const CRYPTO_UNITS = [
        { label: 'mBTC (Milli-bit)', value: 0.001, icon: 'bi-grid-3x3-gap' },
        { label: 'μBTC (Micro-bit)', value: 0.000001, icon: 'bi-grid-1x2' },
        { label: 'Satoshi (Base)', value: 0.00000001, icon: 'bi-dot' }
    ];

    document.getElementById('crypto-form').addEventListener('submit', function (e) {
        e.preventDefault();

        const tx = parseFloat(document.getElementById('tx-amount').value);
        const funds = parseFloat(document.getElementById('funds-provided').value);
        const grid = document.getElementById('denomination-grid');

        if (funds < tx) {
            showError("Insufficient funds provided.");
            return;
        }

        const change = (funds - tx).toFixed(8);
        const sats = Math.round(parseFloat(change) * 100000000);

        document.getElementById('satoshi-change').innerText = `${sats.toLocaleString()} sats`;

        // Breakdown into units for UI
        grid.innerHTML = '';
        let remaining = parseFloat(change);

        CRYPTO_UNITS.forEach(unit => {
            const count = Math.floor((remaining + 0.000000001) / unit.value); // Add small epsilon for float precision
            if (count > 0) {
                remaining = (remaining % unit.value).toFixed(8);

                const card = document.createElement('div');
                card.className = 'ag-denomination ag-animate-up';

                card.innerHTML = `
                    <i class="bi ${unit.icon}" style="font-size: 2rem; color: var(--ag-primary);"></i>
                    <span class="ag-denomination__count">${count.toLocaleString()}</span>
                    <span class="ag-denomination__label">${unit.label}</span>
                `;
                grid.appendChild(card);
            }
        });

        document.getElementById('result-container').classList.remove('d-none');
        document.getElementById('error-alert').classList.add('d-none');
    });

    function showError(msg) {
        document.getElementById('error-message').innerText = msg;
        document.getElementById('error-alert').classList.remove('d-none');
        document.getElementById('result-container').classList.add('d-none');
    }

