/**
     * Updates the UI with the calculation result or error.
     */
    function displayResult(isError, contentHtml) {
        const outputDiv = document.getElementById('solution-output');
        // Ensure result container is visible
        outputDiv.classList.remove('d-none', 'result-error', 'result-card');

        if (isError) {
            outputDiv.classList.add('result-error');
        } else {
            outputDiv.classList.add('result-card');
        }
        outputDiv.innerHTML = contentHtml;
    }

    /**
     * Safely evaluates a user-provided expression string.
     */
    function safeEval(expression) {
        // Allow common math constants and functions
        const cleanedExpression = expression.toUpperCase()
            .replace(/PI/g, 'Math.PI')
            .replace(/E/g, 'Math.E')
            .replace(/ABS/g, 'Math.abs')
            .replace(/SQRT/g, 'Math.sqrt');

        try {
            // Using a constructor function for safe evaluation
            const evaluator = new Function('Math', `
                with (Math) {
                    return (${cleanedExpression});
                }
            `);
            const result = evaluator(Math);

            if (typeof result !== 'number' || isNaN(result) || !isFinite(result)) {
                return NaN;
            }

            return result;
        } catch (error) {
            return NaN;
        }
    }

    /**
     * Handles form submission and triggers the calculation.
     */
    function handleAbsoluteValueCalculation(e) {
        e.preventDefault();

        const inputElement = document.getElementById('x-input');
        const xExpression = inputElement.value.trim();

        // Input Validation (since we removed the default value, this is crucial)
        if (xExpression === '') {
            const htmlContent = `<p class="fw-bold text-center">Empty Input</p><p class="text-center">Please enter a number or expression to calculate its absolute value.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const calculatedValue = safeEval(xExpression);

        if (isNaN(calculatedValue)) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter a valid number or mathematical expression.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const absoluteResult = Math.abs(calculatedValue);

        // Use toFixed(4) for precision, then remove trailing zeros
        const inputDisplay = calculatedValue.toFixed(4).replace(/\.?0+$/, '');
        const resultDisplay = absoluteResult.toFixed(4).replace(/\.?0+$/, '');

        let explanationText;
        if (calculatedValue >= 0) {
            explanationText = `The absolute value of a non-negative number is the number itself.`;
        } else {
            explanationText = `The absolute value converts the negative value to its positive equivalent (the distance from zero).`;
        }

        // Display results clearly using the standard absolute value notation
        let htmlContent = `
            <p class="output-label text-center">Result for |${xExpression}|:</p>
            <div class="output-value text-center mb-2">
                <strong>|${inputDisplay}| = ${resultDisplay}</strong>
            </div>
            <div class="explanation text-center">
                Initial Calculated Value: <strong>${inputDisplay}</strong><br>
                ${explanationText}
            </div>
        `;

        displayResult(false, htmlContent);
    }

    // Attach handler to the form
    document.getElementById('absolute-value-form').addEventListener('submit', handleAbsoluteValueCalculation);

    // FIX: The page now loads with an empty input field and the result area hidden.

