// --- Configuration for High Capacity ---
    const MAX_VARIABLES = 9; // A, B, C, D, E, F, G, H, I -> 2^9 = 512 rows
    // ---------------------------------------

    /**
     * Updates the UI with the calculation result or error.
     */
    function displayResult(isError, contentHtml) {
        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.remove('d-none', 'result-error', 'result-card');

        if (isError) {
            outputDiv.classList.add('result-error');
            outputDiv.classList.remove('result-card');
        } else {
            outputDiv.classList.add('result-card');
            outputDiv.classList.remove('result-error');
            // Trigger MathJax re-render only if content is not an error
            if (window.MathJax) {
                window.MathJax.typesetPromise([outputDiv]);
            }
        }
        outputDiv.innerHTML = contentHtml;
    }

    /**
     * Safely evaluates a logical expression string. 
     */
    function safeEvaluateLogic(expression, variables, values) {
        let jsExpression = expression.toUpperCase();

        jsExpression = jsExpression.replace(/AND|\*/g, '&&');
        jsExpression = jsExpression.replace(/OR|\+/g, '||');
        jsExpression = jsExpression.replace(/NOT|!/g, '!');

        const argNames = variables.join(',');

        try {
            const evaluator = new Function(argNames, `
                return (${jsExpression});
            `);

            // Map true/false to 1/0 for safe evaluation of expressions like 1+0 or !1
            const numericValues = values.map(v => v ? 1 : 0);
            return evaluator(...numericValues);

        } catch (error) {
            return 'ERROR';
        }
    }

    /**
     * Extracts unique uppercase variables (A-Z) from the expression, sorted alphabetically. 
     * Now strictly limited to the first MAX_VARIABLES letters (A-I).
     */
    function extractVariables(expression) {
        const allMatches = expression.match(/[A-I]/g) || []; // Strictly limit to A-I
        const uniqueVars = Array.from(new Set(allMatches)).sort();

        // Use only up to MAX_VARIABLES
        return uniqueVars.slice(0, MAX_VARIABLES);
    }

    /**
     * Generates all 2^n combinations of boolean values.
     */
    function generateCombinations(n) {
        const combinations = [];
        const numRows = 1 << n; 

        for (let i = 0; i < numRows; i++) {
            const row = [];
            for (let j = 0; j < n; j++) {
                // Correct bitwise calculation: read from the most significant bit first (left to right)
                // If n=3, j=0 reads 2^2 (A), j=1 reads 2^1 (B), j=2 reads 2^0 (C)
                const isTrue = ((i >> (n - 1 - j)) & 1) === 1; 
                row.push(isTrue);
            }
            combinations.push(row);
        }
        return combinations;
    }


    /**
     * Handles form submission and triggers the boolean analysis.
     */
    function handleBooleanAnalysis(e) {
        e.preventDefault();

        const expressionInput = document.getElementById('expression-input');
        const userExpression = expressionInput.value.trim();

        // Hide previous results instantly
        document.getElementById('solution-output').classList.add('d-none');

        if (userExpression === '') {
            const htmlContent = `<p class="fw-bold text-center">Empty Input</p><p class="text-center">Please enter a logical expression before analyzing.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const variables = extractVariables(userExpression);
        const numVariables = variables.length;

        if (numVariables === 0) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Expression</p><p class="text-center">Please use at least one uppercase variable (A-I) and supported operators.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        if (numVariables > MAX_VARIABLES) {
            // This case should be mostly prevented by extractVariables, but kept for explicit error
            const htmlContent = `<p class="fw-bold text-center">Too Many Variables</p><p class="text-center">The expression has too many variables. This calculator supports a maximum of ${MAX_VARIABLES} variables (A-${String.fromCharCode(64 + MAX_VARIABLES)}).</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const combinations = generateCombinations(numVariables);
        const numRows = combinations.length;
        let hasError = false;

        const minterms = []; 
        const maxterms = []; 

        // Build Table Header
        let tableHeaderHtml = '<tr><th class="col-minterm">Index ($m_i / M_i$)</th>';
        variables.forEach(v => {
            tableHeaderHtml += `<th class="col-var">${v}</th>`;
        });
        tableHeaderHtml += `<th class="col-minterm">${userExpression} (F)</th></tr>`;


        // Build Table Body and Calculate Canonical Forms
        const rowsArray = [];

        combinations.forEach((values, index) => {
            const result = safeEvaluateLogic(userExpression, variables, values);

            let resultDisplay;
            let rowClass = '';

            if (result === 'ERROR') {
                resultDisplay = 'ERROR';
                rowClass = 'table-danger'; 
                hasError = true;
            } else {
                // Ensure the result is strictly treated as a boolean/numeric 0/1
                const finalOutput = result ? 1 : 0;

                if (finalOutput === 1) {
                    resultDisplay = '1';
                    minterms.push(index);
                } else {
                    resultDisplay = '0';
                    maxterms.push(index);
                }
            }

            let rowHtml = `<tr class="${rowClass}">`;

            // Add Index
            rowHtml += `<td class="fw-bold">${index}</td>`;

            // Add variable values (0/1)
            values.forEach(v => {
                rowHtml += `<td class="col-var">${v ? '1' : '0'}</td>`;
            });

            // Add final expression result
            rowHtml += `<td class="col-minterm">${resultDisplay}</td>`;
            rowHtml += '</tr>';

            rowsArray.push(rowHtml);
        });

        const tableRowsHtml = rowsArray.join('');


        if (hasError) {
             const htmlContent = `<p class="fw-bold text-center">Evaluation Error</p><p class="text-center">The expression appears to have a syntax error or unsupported structure. Please check parentheses and operators (NOT, AND, OR).</p>`;
            displayResult(true, htmlContent);
            return;
        }

        // Display Canonical Forms using MathJax
        const canonicalSOP = `$$\\mathbf{F(${variables.join(', ')}) = \\Sigma (${minterms.join(', ')})}$$`;
        const canonicalPOS = `$$\\mathbf{F(${variables.join(', ')}) = \\Pi (${maxterms.join(', ')})}$$`;

        // Display the final output
        const outputHtml = `
            <h3 class="fs-4 fw-bold text-center text-secondary mb-4">Canonical Forms</h3>
            <div class="row g-4">
                <div class="col-md-6">
                    <p class="text-center fw-semibold text-dark mb-1">Sum-of-Products (SOP / Minterms where $F=1$):</p>
                    <div class="canonical-form">${canonicalSOP}</div>
                    <p class="text-center text-muted small mt-2">
                        Includes minterms $m_i$ for which the function output is 1.
                    </p>
                </div>
                <div class="col-md-6">
                    <p class="text-center fw-semibold text-dark mb-1">Product-of-Sums (POS / Maxterms where $F=0$):</p>
                    <div class="canonical-form">${canonicalPOS}</div>
                    <p class="text-center text-muted small mt-2">
                        Includes maxterms $M_i$ for which the function output is 0.
                    </p>
                </div>
            </div>

            <h3 class="fs-4 fw-bold text-center text-secondary mb-4 mt-5">Truth Table ($2^{${numVariables}} = ${numRows}$ rows)</h3>
            ${numVariables > 6 ? '<p class="text-danger text-center fw-bold">Displaying a large table. Be patient with browser rendering.</p>' : ''}
            <div class="table-container">
                <table class="truth-table table-hover">
                    <thead>
                        ${tableHeaderHtml}
                    </thead>
                    <tbody>
                        ${tableRowsHtml}
                    </tbody>
                </table>
            </div>
        `;

        displayResult(false, outputHtml);
    }

    // Attach handler to the form
    document.getElementById('boolean-form').addEventListener('submit', handleBooleanAnalysis);

