/**
     * Calculates the combination (nCr) using BigInt for maximum precision.
     */
    function calculateCombination(n, r) {
        n = BigInt(n);
        r = BigInt(r);

        if (r === 0n || r === n) return 1n;
        if (r < 0n || r > n) return 0n;

        // Optimization: C(n, r) = C(n, n - r)
        if (r > n / 2n) {
            r = n - r;
        }

        let result = 1n;
        for (let i = 1n; i <= r; i++) {
            result = (result * (n - i + 1n)) / i;
        }
        return result;
    }

