    document.getElementById('complex-calculator-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Get and trim values
        const a1Val = document.getElementById('a1-input').value.trim();
        const b1Val = document.getElementById('b1-input').value.trim();
        const a2Val = document.getElementById('a2-input').value.trim();
        const b2Val = document.getElementById('b2-input').value.trim();

        // Convert to float
        const a1 = parseFloat(a1Val);
        const b1 = parseFloat(b1Val);
        const a2 = parseFloat(a2Val);
        const b2 = parseFloat(b2Val);

        const outputDiv = document.getElementById('solution-output');
        outputDiv.innerHTML = ''; 

        // --- Input Validation ---
        if (a1Val === '' || b1Val === '' || a2Val === '' || b2Val === '' || isNaN(a1) || isNaN(b1) || isNaN(a2) || isNaN(b2)) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter valid numerical values (integers or decimals) for all four parts (a₁, b₁, a₂, b₂).</p>`;
            displayResults(htmlContent, true);
            return;
        }

        // --- Core Calculations ---

        const addA = a1 + a2;
        const addB = b1 + b2;
        const subA = a1 - a2;
        const subB = b1 - b2;
        const multA = (a1 * a2) - (b1 * b2);
        const multB = (a1 * b2) + (b1 * a2);

        const denominator = (a2 * a2) + (b2 * b2);

        if (denominator === 0) {
            const htmlContent = `<p class="fw-bold text-center">Division by Zero Error</p><p class="text-center">Cannot divide, as Complex Number 2 (**Z₂**) is zero (0 + 0i).</p>`;
            displayResults(htmlContent, true);
            return;
        }

        const divA = ((a1 * a2) + (b1 * b2)) / denominator;
        const divB = ((b1 * a2) - (a1 * b2)) / denominator;

        // --- Result Display ---
        let htmlContent = '';

        htmlContent += createResultCard('Addition', [addA, addB], '+');
        htmlContent += createResultCard('Subtraction', [subA, subB], '-');
        htmlContent += createResultCard('Multiplication', [multA, multB], '×'); // Unicode multiplication symbol
        htmlContent += createResultCard('Division', [divA, divB], '÷'); // Unicode division symbol

        displayResults(htmlContent, false);
    });

    // FIX: Removed window.onload function, so the page loads clean and empty.

