/**
     * Calculates the Greatest Common Factor (GCF) of two non-negative integers
     * using the Euclidean Algorithm.
     */
    function gcd(a, b) {
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    /**
     * Updates the results display with appropriate styling and content, and triggers MathJax.
