    document.getElementById('converter-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const inputStr = document.getElementById('decimal-input').value.trim();
        const outputDiv = document.getElementById('solution-output');

        // Hide the result container when a new submission starts
        document.getElementById('result-container').classList.add('d-none');
        outputDiv.className = 'result-box'; 
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (inputStr === '' || isNaN(parseFloat(inputStr))) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter a valid number (e.g., 0.5, -1.25, 4).</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Conversion Logic ---
        const number = parseFloat(inputStr);
        const sign = (number < 0) ? -1 : 1;

        // Use string representation for accurate decimal counting
        // Handle scientific notation if it exists (e.g., 1.2e-5) by converting to fixed
        let absInput;
        if (inputStr.toLowerCase().includes('e')) {
            absInput = Math.abs(number).toFixed(20).replace(/\.?0+$/, "");
        } else {
            absInput = Math.abs(inputStr);
        }

        // Find the fractional part string to count decimal places accurately
        const parts = absInput.toString().split('.');
        // Use an empty string if there's no decimal point
        const decimalPart = parts.length > 1 ? parts[1].replace(/^0+/, '') : ""; 

        const k = decimalPart.length; 

        if (k === 0) {
            // Case 1: Input is an integer (e.g., "5" or "5.0")
            const initialN = Math.abs(number);

            htmlContent += `<p class="detail-text">Input is a whole number: ${inputStr}</p>`;

            // Display simplified whole number using MathJax
            const simplifiedResult = (sign === -1 ? "-" : "") + `$$\\mathbf{${initialN}}$$`;
            htmlContent += `<div class="fraction-display">${simplifiedResult}</div>`;
            htmlContent += `<p class="detail-text">The fraction simplifies to the whole number itself.</p>`;

            resultClass = 'result-success';
            displayResult(resultClass, htmlContent);
            return;
        }

        // Case 2: Input has a decimal part (e.g., "1.25")

        // Construct the numerator and denominator using string parts
        const numeratorStr = (parts[0] || "0") + decimalPart;
        const initialN = parseInt(numeratorStr, 10);
        const initialD = Math.pow(10, k);

        // Calculate GCF for simplification
        const commonDivisor = gcd(initialN, initialD);

        // Calculate the simplified fraction
        const n_simplified = initialN / commonDivisor;
        const d_simplified = initialD / commonDivisor;

        // --- Result Display ---

        // Simplified text: removed $ and used **
        htmlContent += `<p class="detail-text">Unsimplified Fraction (Denominator **10^${k}**): ${initialN}/${initialD}</p>`;
        htmlContent += `<p class="detail-text">Greatest Common Factor (GCF): **${commonDivisor}**</p>`;

        // Display the simplified fraction using MathJax for high-quality rendering
        htmlContent += `<div class="fraction-display">`;
        if (d_simplified === 1) {
             // Display as a whole number
             htmlContent += `$$\\mathbf{${sign * n_simplified}}$$`;
        } else {
             // Display as a simplified fraction
             htmlContent += `$$\\mathbf{${sign === -1 ? "-" : ""}\\frac{${n_simplified}}{${d_simplified}}}$$`;
        }
        htmlContent += `</div>`;

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
    });

    // REMOVED: window.onload function to prevent automatic calculation on page load.

basic_calculator__derivative_calculator:
/**
     * Attempts to find the derivative of a basic function string.
     * NOTE: This is a simplified differentiation engine and has limitations.
     * @param {string} funcStr - The input function string.
     * @returns {string} The derivative string in LaTeX format.
     */
    function calculateDerivative(funcStr) {
        // Clean and normalize the string for easier parsing
        let cleanedStr = funcStr.toLowerCase().replace(/\s+/g, '');
        cleanedStr = cleanedStr.replace(/-/g, '+-'); // Replace subtraction with '+-' for easier splitting

        // Split into terms (handling leading signs)
        const terms = cleanedStr.split('+').filter(term => term.length > 0);

        let derivativeTerms = [];

        for (let term of terms) {
            let sign = term.startsWith('-') ? -1 : 1;
            let currentTerm = term.replace('-', ''); // Remove sign for parsing
            let coeff = 1;
            let derivedTerm = '';

            // --- Case 1: Constant (e.g., 5, -2) ---
            if (!currentTerm.includes('x') && !currentTerm.includes('sin') && !currentTerm.includes('cos') && !currentTerm.includes('ln') && !currentTerm.includes('e')) {
                continue; // Derivative is 0
            }

            // --- Case 2: e^x ---
            if (currentTerm === 'e^x' || currentTerm === 'ex') {
                derivedTerm = 'e^x';
                // Check for coefficient, e.g., 2*e^x
                const coeffMatch = term.match(/(\d+|\d+\.\d+)\*?e[x\^]/);
                if (coeffMatch) {
                    coeff = parseFloat(coeffMatch[1]);
                }
            } 

            // --- Case 3: ln(x) ---
            else if (currentTerm.includes('ln(x)')) {
                derivedTerm = '\\frac{1}{x}';
                // Check for coefficient
                 const coeffMatch = term.match(/(\d+|\d+\.\d+)\*?ln\(x\)/);
                 if (coeffMatch) {
                    coeff = parseFloat(coeffMatch[1]);
                 }
            }

            // --- Case 4: Basic Trigonometry ---
            else if (currentTerm.includes('sin(x)')) {
                derivedTerm = '\\cos(x)';
                 const coeffMatch = term.match(/(\d+|\d+\.\d+)\*?sin\(x\)/);
                 if (coeffMatch) {
                    coeff = parseFloat(coeffMatch[1]);
                 }
            }
            else if (currentTerm.includes('cos(x)')) {
                derivedTerm = '-\\sin(x)';
                 const coeffMatch = term.match(/(\d+|\d+\.\d+)\*?cos\(x\)/);
                 if (coeffMatch) {
                    coeff = parseFloat(coeffMatch[1]);
                 }
            }

            // --- Case 5: Power Rule (c*x^n) ---
            else {
                // Simplified Power Rule parsing
                const parts = currentTerm.split('*');
                let xTerm = parts.find(p => p.includes('x')) || 'x'; // Default to 'x' if coeff is present but x is not explicit
                let cTerm = parts.find(p => !p.includes('x'));

                // Determine the base coefficient
                if (cTerm) {
                    coeff = parseFloat(cTerm);
                } else if (currentTerm.startsWith('x') || currentTerm.startsWith('-x')) {
                    coeff = 1; // e.g., x^2 or -x^2
                }

                let exponent = 1; // Default for x (x^1)

                if (xTerm.includes('^')) {
                    exponent = parseFloat(xTerm.split('^')[1]);
                } else if (xTerm === 'x' && cTerm) {
                    // This handles c*x (e.g., 5*x). derivative is just c.
                    derivedTerm = Math.abs(coeff).toFixed(4).replace(/\.?0+$/, "");
                    exponent = 1; // Reset exponent for calculation logic
                    xTerm = ''; // Mark as handled
                } else if (xTerm === 'x') {
                    // Handles just 'x'. derivative is 1.
                    derivedTerm = '1';
                    exponent = 1; // Reset exponent
                    xTerm = ''; // Mark as handled
                }

                // Apply Power Rule only if it's a true x^n term (not already derived to a constant)
                if (xTerm && exponent !== 0) {
                    // Apply Power Rule: d/dx(c*x^n) = c*n*x^(n-1)
                    let newCoeff = coeff * exponent;
                    let newExp = exponent - 1;

                    // Format the derived term
                    let coeffStr = Math.abs(newCoeff).toFixed(4).replace(/\.?0+$/, ""); 

                    if (newExp === 0) {
                        derivedTerm = coeffStr; // Result is just the constant
                    } else if (newExp === 1) {
                        derivedTerm = `${coeffStr}x`;
                    } else {
                        derivedTerm = `${coeffStr}x^{${newExp}}`;
                    }
                } else if (!xTerm && !derivedTerm) {
                    // This is a constant term that was initially skipped
                    continue;
                }
            }

            // Reapply sign and clean up
            let finalCoeff = sign * coeff;

            if (derivedTerm !== '0') {
                if (finalCoeff < 0) {
                    derivedTerm = '-' + derivedTerm;
                } else if (derivativeTerms.length > 0) {
                    derivedTerm = '+' + derivedTerm;
                }
                derivativeTerms.push(derivedTerm);
            }
        }

        let result = derivativeTerms.join('');

        if (!result) {
            return '0';
        }

        // Final cleanup: remove leading '+' if present
        if (result.startsWith('+')) {
            result = result.substring(1);
        }

        return result;
    }


