    /**
     * Digit Finder Logic (Internal helper function)
     */
    function findEDigit(position) {
        if (position < 1 || !Number.isInteger(position)) {
            return {
                error: true, 
                content: `<p class="fw-bold text-center">Invalid Position</p><p class="text-center">Please enter a positive whole number for the position (1st, 2nd, etc.).</p>`
            };
        }

        if (position > MAX_DIGITS) {
            return {
                error: true, 
                content: `<p class="fw-bold text-center">Position Out of Range</p><p class="text-center">This calculator currently only holds the first **${MAX_DIGITS}** digits of **e** after the decimal point. Please enter a position between 1 and ${MAX_DIGITS}.</p>`
            };
        }

        const digit = E_DIGITS[position - 1];

        // Context Display: Highlight the found digit
        const contextLength = 50; 
        const segmentBefore = E_DIGITS.substring(Math.max(0, position - 1 - contextLength), position - 1);
        const highlightedDigit = E_DIGITS.substring(position - 1, position);
        const segmentAfter = E_DIGITS.substring(position, Math.min(MAX_DIGITS, position + contextLength));

        const displayBefore = (position - 1 > contextLength) ? '... ' : '';
        const displayAfter = (position + contextLength < MAX_DIGITS) ? ' ...' : '';

        let htmlContent = `<p class="output-label">The $\\mathbf{${position}^{th}}$ digit of **e** after the decimal is:</p>`;
        htmlContent += `<div class="output-value">$$\\mathbf{${digit}}$$</div>`;
        htmlContent += `<p class="output-label mt-4 text-base fw-normal">Context:</p>`;
        htmlContent += `<div class="e-display-wrapper">
            $2\\mathbf{.}$ ${displayBefore}${segmentBefore} <span style="color: #dc3545; font-weight: bold; font-size: 1.2em; background-color: #fce7f3; border-radius: 2px;">${highlightedDigit}</span> ${segmentAfter}${displayAfter}
        </div>`;

        return { error: false, content: htmlContent };
    }

    /**
     * e^x Calculator Logic (Internal helper function)
     */
    function calculateEExp(x) {
        if (isNaN(x)) {
            return {
                error: true, 
                content: `<p class="fw-bold text-center">Invalid Exponent</p><p class="text-center">Please enter a valid number for the exponent **x**.</p>`
            };
        }

        const result = Math.exp(x);
        const resultF = result.toFixed(10); 

        let htmlContent = `<p class="output-label">Result of **e** raised to the power of **${x}**:</p>`;
        htmlContent += `<div class="output-value text-3xl">$$\\mathbf{e}^{\\mathbf{${x}}} \\approx \\mathbf{${resultF}}$$</div>`;
        htmlContent += `<p class="text-center small text-muted mt-3 mb-0">Note: Result is shown to 10 decimal places.</p>`;

        return { error: false, content: htmlContent };
    }

    // -------------------------------------------------------------------
    // --- Unified Form Handler ---
    // -------------------------------------------------------------------

    document.getElementById('e-unified-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const inputStr = document.getElementById('input-value').value.trim();
        const outputDiv = document.getElementById('unified-output');
        outputDiv.classList.add('d-none');

        let resultData;

        if (inputStr === '') {
            resultData = {
                error: true, 
                content: `<p class="fw-bold text-center">Empty Input</p><p class="text-center">Please enter a position (whole number) or an exponent (decimal/whole number).</p>`
            };
        } else {
            const num = parseFloat(inputStr);

            // Check if input is a non-negative whole number (for digit finder)
            if (num >= 1 && Number.isInteger(num)) {
                // Treat as Digit Position
                resultData = findEDigit(num);
            } else if (!isNaN(num)) {
                // Treat as Exponent (including 0, negative, and decimal values)
