/**
     * Finds all positive factors (divisors) of a given positive integer N.
     * Uses the square root optimization for efficiency.
     * @param {number} n - The positive integer.
     * @returns {number[]} Array of factors, sorted ascending.
     */
    function findFactors(n) {
        if (n <= 0) return [];
        if (n === 1) return [1];

        const factors = [];
        const limit = Math.sqrt(n);

        for (let i = 1; i <= limit; i++) {
            if (n % i === 0) {
                factors.push(i);

                const complement = n / i;
                if (i !== complement) {
                    factors.push(complement);
                }
            }
        }

        factors.sort((a, b) => a - b);
        return factors;
    }


    document.getElementById('factor-form').addEventListener('submit', function(e) {
