/**
     * Calculates the Greatest Common Factor (GCF) of two non-negative integers
     * using the Euclidean Algorithm.
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The GCF of a and b.
     */
    function gcd(a, b) {
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    document.getElementById('simplifier-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const N_input = document.getElementById('numerator-input').value.trim();
        const D_input = document.getElementById('denominator-input').value.trim();

        const N = parseInt(N_input, 10);
        const D = parseInt(D_input, 10);

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none'); // Hide before new result
        outputDiv.className = 'result-box'; 
        outputDiv.innerHTML = '';

        let htmlContent = '';
