        // --- Input Validation ---
        if (N_input === '' || D_input === '') {
             htmlContent = `<p class="fw-bold text-center">Empty Input</p><p class="text-center">Please enter values for both the numerator and denominator.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
