        }

        if (isNaN(N) || isNaN(D) || !Number.isInteger(N) || !Number.isInteger(D)) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter two whole numbers for the numerator and denominator.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (D === 0) {
            htmlContent = `<p class="fw-bold text-center">Invalid Operation</p><p class="text-center">The denominator (divisor) cannot be zero.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Simplification Calculation ---

        // Use the absolute values for the GCF calculation
        const commonDivisor = gcd(N, D);

        // Determine the sign of the result
        const sign = (N * D < 0) ? '-' : '';

        // Calculate the simplified fraction
        const n_simplified = Math.abs(N) / commonDivisor;
        const d_simplified = Math.abs(D) / commonDivisor;

        // --- Result Display ---

        // Display the original and GCF
        htmlContent += `<p class="fs-5 text-center">Original Fraction: $\\frac{${N}}{${D}}$</p>`;
        htmlContent += `<p class="fs-5 text-center mt-2">Greatest Common Factor (GCF) of ${Math.abs(N)} and ${Math.abs(D)}: $\\mathbf{${commonDivisor}}$</p>`;

        // Display the simplified fraction
        htmlContent += `<div class="fraction-display mt-4">`;
        if (d_simplified === 1) {
             // Display as a whole number
             htmlContent += `$$\\frac{${N}}{${D}} = \\mathbf{${sign}${n_simplified}}$$`;
        } else {
             // Display as a simplified fraction
             htmlContent += `$$\\frac{${N}}{${D}} = \\mathbf{${sign}\\frac{${n_simplified}}{${d_simplified}}}$$`;
        }
        htmlContent += `</div>`;

        if (commonDivisor === 1) {
            htmlContent += `<p class="output-text mt-4">The fraction is already in its lowest terms.</p>`;
        } else {
            htmlContent += `<p class="output-text mt-4">The fraction has been simplified.</p>`;
        }

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
