     * using the Euclidean Algorithm (iterative approach).
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The GCF of a and b.
     */
    function gcd(a, b) {
        // Ensure inputs are positive (Euclidean Algorithm works on non-negative)
        a = Math.abs(a);
        b = Math.abs(b);

        // Handle the case where one number is 0 (GCF is the other number)
        if (a === 0) return b;
        if (b === 0) return a;

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
