document.addEventListener('DOMContentLoaded', () => {
        const canvas = document.getElementById('graph-canvas');
        const ctx = canvas.getContext('2d');
        const form = document.getElementById('graph-form');
        const messageArea = document.getElementById('message-area');

        // Check Math.js
        if (typeof window.math === 'undefined') {
            messageArea.innerHTML = "Error: Math engine failed to load. Check your connection.";
            return;
        }
        const math = window.math;

        // --- Premium Dark Theme Configuration ---
        const THEME = {
            grid: 'rgba(255, 255, 255, 0.12)',  // Subtle frosted grid
            axes: 'rgba(255, 255, 255, 0.45)',  // Clearer axis lines
            text: '#94a3b8',                    // Lighter slate text
            line: '#38bdf8',                    // Vivid Neon Sky Blue for the graph
            glow: 'rgba(56, 189, 248, 0.5)'     // Subtle glow effect
        };

        // Render initial view
        drawAxes(ctx, canvas, { xMin: -10, xMax: 10, yMin: -10, yMax: 10 });

        // Render default equation: sin(x) * x
        try {
            const defaultCompiled = math.compile("sin(x) * x");
            drawGraph(ctx, canvas, defaultCompiled, { xMin: -10, xMax: 10, yMin: -10, yMax: 10 });
        } catch(e) {}

        form.addEventListener('submit', (e) => {
            e.preventDefault();
            messageArea.textContent = '';

            const funcStr = document.getElementById('function-input').value.trim();
            const xMin = parseFloat(document.getElementById('x-min').value);
            const xMax = parseFloat(document.getElementById('x-max').value);
            const yMin = parseFloat(document.getElementById('y-min').value);
            const yMax = parseFloat(document.getElementById('y-max').value);

            if (xMin >= xMax || yMin >= yMax) {
                messageArea.textContent = 'Invalid Graph Domain: Max values must be greater than Min values.';
                return;
            }

            try {
                // Compile the function directly using math.js compiler (much safer/dynamic than new Function)
                const node = math.parse(funcStr);
                const compiled = node.compile();

                // Test an evaluation visually to catch severe syntax (e.g., missing variables) right away
                compiled.evaluate({ x: 1 });

                // Dispatch to draw
                drawGraph(ctx, canvas, compiled, { xMin, xMax, yMin, yMax });

            } catch (error) {
                console.error("Syntax compile error:", error);
                messageArea.textContent = 'Syntax Error: Please check your mathematical expression.';
            }
        });

        function mapToCanvas(x, y, width, height, limits) {
            const xRange = limits.xMax - limits.xMin;
            const yRange = limits.yMax - limits.yMin;
            const px = ((x - limits.xMin) / xRange) * width;
            const py = height - (((y - limits.yMin) / yRange) * height);
            return { px, py };
        }

        function drawAxes(ctx, canvas, limits) {
            const { width, height } = canvas;
            const { xMin, xMax, yMin, yMax } = limits;
            ctx.clearRect(0, 0, width, height);

            const origin = mapToCanvas(0, 0, width, height, limits);
            const xInterval = (xMax - xMin) / 10;
            const yInterval = (yMax - yMin) / 10;
            const xStep = Math.abs(xInterval) || 1;
            const yStep = Math.abs(yInterval) || 1;

            // --- Draw Grid ---
            ctx.strokeStyle = THEME.grid;
            ctx.lineWidth = 1;

            for (let x = xMin; x <= xMax; x += xStep) {
                const { px } = mapToCanvas(x, 0, width, height, limits);
                ctx.beginPath();
                ctx.moveTo(px, 0); ctx.lineTo(px, height); ctx.stroke();
            }
            for (let y = yMin; y <= yMax; y += yStep) {
                const { py } = mapToCanvas(0, y, width, height, limits);
                ctx.beginPath();
                ctx.moveTo(0, py); ctx.lineTo(width, py); ctx.stroke();
            }

            // --- Draw Primary Axes ---
            ctx.strokeStyle = THEME.axes;
            ctx.lineWidth = 2;

            // X-Axis
            if (origin.py >= 0 && origin.py <= height) {
                ctx.beginPath(); ctx.moveTo(0, origin.py); ctx.lineTo(width, origin.py); ctx.stroke();
            }
            // Y-Axis
            if (origin.px >= 0 && origin.px <= width) {
                ctx.beginPath(); ctx.moveTo(origin.px, 0); ctx.lineTo(origin.px, height); ctx.stroke();
            }

            // --- Draw Labels ---
            ctx.fillStyle = THEME.text;
            ctx.font = 'bold 12px "JetBrains Mono"';

            // X labels
            for (let x = xMin; x <= xMax; x += xStep) {
                if (Math.abs(x) < 0.0001) continue;
                const { px } = mapToCanvas(x, 0, width, height, limits);
                ctx.fillText(x.toFixed(1).replace(/\.0$/, ''), px - 12, Math.min(Math.max(origin.py + 18, 18), height - 8));
            }
            // Y labels
            for (let y = yMin; y <= yMax; y += yStep) {
                if (Math.abs(y) < 0.0001) continue;
                const { py } = mapToCanvas(0, y, width, height, limits);
                ctx.fillText(y.toFixed(1).replace(/\.0$/, ''), Math.min(Math.max(origin.px + 8, 8), width - 35), py + 4);
            }
        }

        function drawGraph(ctx, canvas, compiledFunc, limits) {
            drawAxes(ctx, canvas, limits);
            const { width, height } = canvas;
            const { xMin, xMax } = limits;

            // Adjust step fidelity: high res curves based on pixel width mapping
            const step = (xMax - xMin) / (width * 1.5); 

            ctx.beginPath();
            ctx.strokeStyle = THEME.line;
            ctx.lineWidth = 4;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            // Add aesthetic neon glow
            ctx.shadowBlur = 10;
            ctx.shadowColor = THEME.glow;

            let firstPoint = true;
            for (let px = 0; px <= width; px += 0.5) { // subpixel mapping for extra smooth curves
                const x = xMin + px * ((xMax - xMin) / width);
                let y;
                try { 
                    y = compiledFunc.evaluate({ x: x }); 

                    // Complex numbers handling (math.js can output objects for sqrt(-1))
                    if (typeof y === 'object') {
                        continue; // SKIP complex mappings
                    }
                } catch (e) { continue; }

                const { py } = mapToCanvas(x, y, width, height, limits);

                // Keep the curve vertically bounding sensibly inside +/- 10,000 to prevent canvas lag
                const isFinite = Number.isFinite(py) && Math.abs(py) < 10000;

                if (firstPoint && isFinite) {
                    ctx.moveTo(px, py);
                    firstPoint = false;
                } else if (isFinite) {
                    ctx.lineTo(px, py);
                } else {
                    ctx.stroke(); ctx.beginPath(); firstPoint = true;
                }
            }
            ctx.stroke();

            // reset shadow
            ctx.shadowBlur = 0;
        }
    });

