            // --- 2. Numerical (Definite) Integration ---
            if (a !== null && b !== null) {
                if (isNaN(a) || isNaN(b)) {
                     throw new Error("Bounds must be valid numbers for a definite integral.");
                }

                const definiteResult = trapezoidalRule(func, a, b, N_STEPS);

