/**
     * Calculates the Greatest Common Factor (GCF) of two non-negative integers
     * using the Euclidean Algorithm.
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The GCF of a and b.
     */
    function gcd(a, b) {
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    /**
     * Calculates the Least Common Multiple (LCM) of two positive integers.
     * LCM(A, B) = (|A * B|) / GCF(A, B)
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The LCM of a and b.
     */
    function lcm(a, b) {
        if (a === 0 || b === 0) return 0;

        // Calculate GCF first
        const commonDivisor = gcd(a, b);

        // Calculate LCM using the formula: LCM(a, b) = (|a * b|) / GCF(a, b)
        // Using b / commonDivisor first to keep the numbers smaller and avoid overflow
        // for very large integers (though JavaScript's limits still apply).
        return Math.abs(a * (b / commonDivisor));
    }


    document.getElementById('lcm-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const inputA = document.getElementById('number-a').value.trim();
        const inputB = document.getElementById('number-b').value.trim();

        const A = parseInt(inputA, 10);
        const B = parseInt(inputB, 10);

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none'); // Hide before new result
        outputDiv.className = 'result-box'; 
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (inputA === '' || inputB === '') {
             htmlContent = `<p class="fw-bold text-center">Empty Input</p><p class="text-center">Please enter values for both Integer A and Integer B.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (isNaN(A) || isNaN(B) || A < 1 || B < 1 || !Number.isInteger(A) || !Number.isInteger(B)) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter two positive whole numbers (integers $\ge 1$).</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- LCM Calculation ---
        const result = lcm(A, B);
        const commonDivisor = gcd(A, B); // Get GCF for display

        // --- Result Display ---
        htmlContent += `<p class="fs-5 fw-bold text-center">The Least Common Multiple of ${A} and ${B} is:</p>`;
        htmlContent += `<p class="output-text">$$\\mathbf{${result}}$$</p>`;

        // Display GCF calculation used
        htmlContent += `<div class="mt-3 small text-center text-secondary">`;
        htmlContent += `<p>Calculation Method:</p>`;
        htmlContent += `$$ \\text{LCM}(A, B) = \\frac{|A \\times B|}{\\text{GCF}(A, B)} = \\frac{|${A} \\times ${B}|}{${commonDivisor}} = \\mathbf{${result}} $$`;
        htmlContent += `</div>`;

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
    });

    /**
     * Updates the results display with appropriate styling and content.
     */
    function displayResult(className, contentHtml) {
        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.remove('d-none', 'result-error', 'result-success');
        outputDiv.classList.add(className);
