/**
     * Calculates the mean of a data set.
     * @param {number[]} data - The data set.
     * @returns {number} The mean.
     */
    function calculateMean(data) {
        const sum = data.reduce((acc, val) => acc + val, 0);
        return sum / data.length;
    }

    /**
     * Calculates the median of a data set.
     * @param {number[]} sortedData - The data set, must be sorted.
     * @returns {number} The median.
     */
    function calculateMedian(sortedData) {
        const N = sortedData.length;
        if (N % 2 === 1) {
            // Odd number of elements: return the middle element
            return sortedData[Math.floor(N / 2)];
        } else {
            // Even number of elements: return the average of the two middle elements
            const middle1 = sortedData[N / 2 - 1];
            const middle2 = sortedData[N / 2];
            return (middle1 + middle2) / 2;
        }
    }

    /**
     * Calculates the mode(s) of a data set.
     * @param {number[]} data - The data set.
     * @returns {string} The mode(s) as a string.
     */
    function calculateMode(data) {
        const counts = {};
        let maxCount = 0;

        // 1. Count frequencies
        data.forEach(n => {
            // Use string key for accurate counting of distinct values (even with floats)
            const key = n.toString(); 
            counts[key] = (counts[key] || 0) + 1;
            if (counts[key] > maxCount) {
                maxCount = counts[key];
            }
        });

        if (maxCount <= 1) {
            return "N/A (No repetition)";
        }

        // 2. Find all numbers with maxCount (Multimodal)
        const modes = [];
        for (const key in counts) {
            if (counts[key] === maxCount) {
                modes.push(key);
            }
        }

        // Return modes as a comma-separated string
        return modes.join(', ');
    }

    /**
     * Calculates the range of a data set.
     * @param {number[]} sortedData - The data set, must be sorted.
     * @returns {number} The range.
     */
    function calculateRange(sortedData) {
        if (sortedData.length === 0) return 0;
        const min = sortedData[0];
        const max = sortedData[sortedData.length - 1];
        return max - min;
    }

