    /**
     * Implements the correct mathematical modulo operation, ensuring the result
     * has the same sign as the divisor (N), or is zero.
     * @param {number} a - Dividend.
     * @param {number} n - Divisor.
     * @returns {number} - The modulo result R.
     */
    function mathMod(a, n) {
        // Javascript's % is a remainder operator, its result has the sign of the dividend (A).
        const remainder = a % n;

        // Mathematical modulo (result R has the sign of the divisor N, or is zero).
        if (n > 0) {
            // Positive divisor: R must be non-negative (0 <= R < N)
            return (remainder + n) % n;
        } else if (n < 0) {
            // Negative divisor: R must be non-positive (N < R <= 0)
            if (remainder === 0) return 0;
            // The result must be between N and 0 (exclusive of N). 
            // If remainder has opposite sign of N (i.e., positive), add N (which is negative).
            return remainder > 0 ? remainder + n : remainder;
        }
        // Should be caught by input validation, but for completeness:
        return NaN; 
    }


    /**
     * Handles form submission and triggers the modulo calculation.
     */
    function handleModuloCalculation(e) {
        e.preventDefault();

        const inputA = document.getElementById('dividend-a').value.trim();
        const inputN = document.getElementById('divisor-n').value.trim();

        const A = parseInt(inputA, 10);
        const N = parseInt(inputN, 10);

        // Hide output before calculation
        document.getElementById('solution-output').classList.add('d-none');


        if (isNaN(A) || isNaN(N) || !Number.isInteger(A) || !Number.isInteger(N)) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter two valid **integers** for Dividend (A) and Divisor (N).</p>`;
            displayResult(true, htmlContent);
            return;
        }

        if (N === 0) {
            const htmlContent = `<p class="fw-bold text-center">Division by Zero</p><p class="text-center">The divisor ($\mathbf{N}$) cannot be zero. This operation is undefined.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const R = mathMod(A, N);

        // Find the quotient Q: A = Q * N + R => Q = (A - R) / N. This is always an integer if R is correct.
        const Q = (A - R) / N;

        let explanationText;
        if (N > 0) {
             explanationText = `The remainder ($\mathbf{R}$) is always a non-negative number: $0 \\le \\mathbf{R} < \\mathbf{N}$.`;
        } else {
             explanationText = `The remainder ($\mathbf{R}$) has the same sign as the divisor ($\mathbf{N}$): $\\mathbf{N} < \\mathbf{R} \\le 0$.`;
        }

        // Result Display
        let htmlContent = `
            <p class="output-label">Result ($\mathbf{R}$):</p>
            <div class="output-value">
                $$\\mathbf{${A} \\pmod {${N}} = ${R}}$$
            </div>
            <div class="explanation">
                <p class="mb-1">Quotient ($\mathbf{Q}$): $\\mathbf{${Q}}$</p>
                <p class="mb-1">Identity: $\\mathbf{A = QN + R}$</p>
                <p class="mb-0">
                    $\mathbf{${A} = (${Q}) \\times (${N}) + (${R})}$
                </p>
                <hr class="my-2" style="border-top-color: #99f6e4;">
                <p class="mb-0 fst-italic">${explanationText}</p>
            </div>
        `;

        displayResult(false, htmlContent);
    }

    // Attach handler to the form
    document.getElementById('modulo-form').addEventListener('submit', handleModuloCalculation);

    // FIXED: Removed the window.onload to keep input fields empty initially.

