/**
     * Calculates the factorial of a non-negative integer.
     * @param {number} num - The number.
     * @returns {number} The factorial.
     */
    function factorial(num) {
        // Use BigInt for potentially large numbers, though result calculation avoids large factorials
        if (num < 0) return NaN;
        if (num === 0) return 1;
        let result = 1;
        for (let i = 2; i <= num; i++) {
            result *= i;
        }
        return result;
    }

    /**
     * Calculates the permutation (nPr) using the formula n! / (n-r)!.
     * For large numbers, this performs multiplication instead of division to prevent overflow from n!.
     * nPr = n * (n-1) * ... * (n-r+1)
     * @param {number} n - Total items.
     * @param {number} r - Items to choose.
     * @returns {number} The permutation result.
     */
    function calculatePermutation(n, r) {
        if (r === 0) return 1; // nP0 = 1
        // Note: For n > 20, standard JS number precision may fail. Use a library for larger numbers.

        let result = 1;
        // nPr = n * (n-1) * ... * (n - r + 1)
        for (let i = 0; i < r; i++) {
            result *= (n - i);
            // Simple check to warn about large numbers
            if (result === Infinity) return Infinity; 
        }
        return result;
    }

    document.getElementById('permutation-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const n = parseInt(document.getElementById('n-input').value.trim());
        const r = parseInt(document.getElementById('r-input').value.trim());

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none');
        outputDiv.classList.remove('result-error', 'result-success');
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (isNaN(n) || isNaN(r) || !Number.isInteger(n) || !Number.isInteger(r) || n < 0 || r < 0) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter non-negative **integers** for both $\mathbf{n}$ and $\mathbf{r}$.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (r > n) {
