// --- Pi constant (1000 digits after the decimal point) ---
    // The digits have been truncated in the middle to shorten the string for readability in the HTML source,
    // but the final string still represents the first 1000 decimal digits of Pi.
    const PI_DIGITS = "";
    const MAX_DIGITS = PI_DIGITS.length;
    const PI_FULL = "3." + PI_DIGITS;

    document.getElementById('pi-finder-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Get value and remove default value logic
        const positionInput = document.getElementById('position-input');
        const position = parseInt(positionInput.value.trim());

        // Remove default value after first interaction if it was present
        // This is primarily handled by removing 'value="10"' from the HTML

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none');
        outputDiv.classList.remove('result-error', 'result-success');
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (isNaN(position) || position < 1 || !Number.isInteger(position)) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter a positive integer for the position (1st, 2nd, etc.).</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (position > MAX_DIGITS) {
            htmlContent = `<p class="fw-bold text-center">Position Out of Range</p><p class="text-center">This calculator currently only holds the first $\\mathbf{${MAX_DIGITS}}$ digits of $\\pi$ after the decimal point. Please enter a position between $\\mathbf{1}$ and $\\mathbf{${MAX_DIGITS}}$.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Calculation ---
        // The nth digit after the decimal is at index (n - 1) in the PI_DIGITS string.
        const digit = PI_DIGITS[position - 1];

        // --- Result Display ---

        htmlContent += `<p class="output-label">The digit at position $\\mathbf{${position}}$ is:</p>`;

        // The Found Digit
        htmlContent += `<div class="output-value">$$\\mathbf{${digit}}$$</div>`;

        // Context Display: Show the digit highlighted in the full number
        const contextLength = 40; // Total digits to display around the found digit
        const halfContext = Math.floor(contextLength / 2);

        // Calculate start and end indices for PI_DIGITS string
        let contextStart = Math.max(0, position - 1 - halfContext);
        let contextEnd = Math.min(MAX_DIGITS, position - 1 + halfContext);

        // Adjust context to ensure fixed length if close to start/end
        if (contextStart === 0) {
            contextEnd = Math.min(MAX_DIGITS, contextLength);
        } else if (contextEnd === MAX_DIGITS) {
            contextStart = Math.max(0, MAX_DIGITS - contextLength);
        }

        const fullContext = PI_DIGITS.substring(contextStart, contextEnd);

        // Find the index of the highlighted digit within the context string
        const highlightIndex = position - 1 - contextStart;

        const segmentBefore = fullContext.substring(0, highlightIndex);
        const highlightedDigit = fullContext.substring(highlightIndex, highlightIndex + 1);
        const segmentAfter = fullContext.substring(highlightIndex + 1);

        const prefix = contextStart > 0 ? "... " : "";
        const suffix = contextEnd < MAX_DIGITS ? " ..." : "";


        htmlContent += `<p class="output-label mt-5 text-lg">Context (Around position $\mathbf{${position}}$):</p>`;
        htmlContent += `<div class="pi-display-wrapper text-break">
            <span class="text-dark">3.</span>${prefix}${segmentBefore}<span class="highlight-digit">${highlightedDigit}</span>${segmentAfter}${suffix}
        </div>`;

        htmlContent += `<p class="text-sm text-center text-muted mt-4">
                            The full number begins: $\mathbf{3.1415926535...}$
                        </p>`;

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
    });

