function isPrime(n) {
        if (n <= 1) return { isPrime: false, reason: "By definition, prime numbers are greater than 1." };
        if (n === 2) return { isPrime: true, reason: "The smallest and only even prime number." };
        if (n % 2 === 0) return { isPrime: false, reason: "It is an even number greater than 2." };

        // Check for divisibility from 3 up to the square root of n, skipping even numbers
        const limit = Math.sqrt(n);
        for (let i = 3; i <= limit; i += 2) {
            if (n % i === 0) {
                return { isPrime: false, reason: `It is divisible by ${i}.` };
            }
        }

        return { isPrime: true, reason: "No divisors found up to its square root." };
    }


