/**
     * Calculates the Greatest Common Factor (GCF) of two non-negative integers
     * using the Euclidean Algorithm.
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The GCF of a and b.
     */
    function gcd(a, b) {
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    document.getElementById('probability-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const F_input = document.getElementById('favorable-input').value.trim();
        const N_input = document.getElementById('total-input').value.trim();

        const F = parseInt(F_input);
        const N = parseInt(N_input);

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none');
        outputDiv.classList.remove('result-error', 'result-success'); 
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (F_input === '' || N_input === '' || isNaN(F) || isNaN(N) || !Number.isInteger(F) || !Number.isInteger(N) || F < 0 || N <= 0) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter positive whole numbers. Favorable outcomes ($\mathbf{F}$) must be $\\mathbf{\\geq 0}$. Total outcomes ($\mathbf{N}$) must be $\\mathbf{\\geq 1}$.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (F > N) {
            htmlContent = `<p class="fw-bold text-center">Invalid Probability</p><p class="text-center">Favorable outcomes ($\mathbf{F=${F}}$) cannot be greater than Total outcomes ($\mathbf{N=${N}}$).</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Calculation ---

        // 1. Decimal Probability
        const probabilityDecimal = F / N;
        // Check for edge case of 0/N
        const probabilityDecimalF = (N === 0) ? '0.0000' : probabilityDecimal.toFixed(4);

        // 2. Percentage
        const probabilityPercent = probabilityDecimal * 100;
        const probabilityPercentF = probabilityPercent.toFixed(2);

        // 3. Simplified Fraction
        const commonDivisor = gcd(F, N);
        const F_simplified = F / commonDivisor;
        const N_simplified = N / commonDivisor;
        const simplifiedFraction = `$$\\frac{\\mathbf{${F_simplified}}}{\\mathbf{${N_simplified}}}$$`;


        // --- Result Display ---

        htmlContent += `<p class="text-center fs-5 fw-medium mb-4 text-dark">
                            Probability ($P$) Calculation: $\\mathbf{P} = \\frac{\\mathbf{F}}{\\mathbf{N}} = \\frac{${F}}{${N}}$
                        </p>`;

        htmlContent += `<div class="output-grid">
            <div class="output-card">
                <div class="output-label">Simplified Fraction</div>
                <div class="output-value fraction-value">${simplifiedFraction}</div>
            </div>
            <div class="output-card">
                <div class="output-label">Decimal Value</div>
                <div class="output-value">$$\\mathbf{${probabilityDecimalF}}$$</div>
            </div>
            <div class="output-card">
                <div class="output-label">Percentage</div>
                <div class="output-value">$$\\mathbf{${probabilityPercentF}\\%}$$</div>
            </div>
        </div>`;

        resultClass = 'result-success';

