document.getElementById('proportion-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const A_input = document.getElementById('part-a-input').value.trim();
        const B_input = document.getElementById('part-b-input').value.trim();
        const C_input = document.getElementById('part-c-input').value.trim();

        const A = parseFloat(A_input);
        const B = parseFloat(B_input);
        const C = parseFloat(C_input);

        const outputDiv = document.getElementById('solution-output');
        // Clear all custom result classes and ensure it starts as hidden/d-none
        outputDiv.classList.remove('result-error', 'result-success');
        outputDiv.classList.add('d-none'); // Ensure it starts hidden
        outputDiv.innerHTML = '';

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (A_input === '' || B_input === '' || C_input === '' || isNaN(A) || isNaN(B) || isNaN(C)) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter valid numerical values for $\mathbf{A}$, $\mathbf{B}$, and $\mathbf{C}$.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // Check if B is zero (B=0 is impossible for a fraction)
        if (B === 0) {
            htmlContent = `<p class="fw-bold text-center">Math Error: Division by Zero</p><p class="text-center">The denominator ($\mathbf{B}$) cannot be zero.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Calculation (Cross-Multiplication) ---
        // A / B = C / X  => A * X = B * C => X = (B * C) / A

        if (A === 0) {
            // Case: 0/B = C/X => 0 = C/X. This implies C must be 0 or X is undefined.
            if (C === 0) {
                htmlContent = `<p class="fw-bold text-center">Indeterminate Solution</p><p class="text-center">If $\\mathbf{A=0}$ and $\\mathbf{C=0}$, the equation becomes $\\mathbf{0=0}$, and $\\mathbf{X}$ can be any non-zero number.</p>`;
                resultClass = 'result-error';
            } else {
                htmlContent = `<p class="fw-bold text-center">No Solution</p><p class="text-center">The equation $\\mathbf{\\frac{0}{${B}} = \\frac{${C}}{X}}$ has no finite solution for $\\mathbf{X}$ (X would approach $\\mathbf{\\infty}$).</p>`;
                resultClass = 'result-error';
            }
            displayResult(resultClass, htmlContent);
            return;
        }

        const numerator = B * C;
        const result = numerator / A;

        // Format the result to a maximum of 4 decimal places
        const formattedResult = result.toLocaleString('en-US', { maximumFractionDigits: 4 });

        // --- Result Display ---

        htmlContent += `<p class="output-label">Step 1: Cross-Multiplication</p>`;
        htmlContent += `<p class="text-center fs-5 text-secondary">
                           $X = \\frac{B \\cdot C}{A} \\Rightarrow X = \\frac{${B} \\cdot ${C}}{${A}}$
                        </p>`;

        htmlContent += `<p class="output-label mt-4">Step 2: Calculate Result</p>`;
        htmlContent += `<p class="text-center fs-5 text-secondary">
                           $X = \\frac{${numerator.toLocaleString('en-US', { maximumFractionDigits: 4 })}}{${A.toLocaleString('en-US', { maximumFractionDigits: 4 })}} $
                        </p>`;

        htmlContent += `<p class="output-label mt-6">The value of X is:</p>`;
        htmlContent += `<div class="output-value">$$\mathbf{${formattedResult}}$$</div>`;

        htmlContent += `<p class="text-sm text-center text-muted mt-4">
                            The solved proportion is: $\\mathbf{\\frac{${A.toLocaleString('en-US', { maximumFractionDigits: 4 })}}{\\mathbf{${B.toLocaleString('en-US', { maximumFractionDigits: 4 })}}} = \\frac{${C.toLocaleString('en-US', { maximumFractionDigits: 4 })}}{\\mathbf{${formattedResult}}}}}$
                        </p>`;

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
    });

