/**
     * Updates the UI to enable/disable inputs and change labels based on the selected mode.
     */
    function updateInputLabels() {
        const mode = document.getElementById('calculate-mode').value;
        const inputA = document.getElementById('input-a');
        const inputB = document.getElementById('input-b');
        const inputC = document.getElementById('input-c');

        const inputs = [inputA, inputB, inputC];
        const labels = {
            'a': document.getElementById('label-a'),
            'b': document.getElementById('label-b'),
            'c': document.getElementById('label-c')
        };

        // 1. Reset all inputs to be enabled and non-disabled/non-required
        inputs.forEach(input => {
            input.disabled = false;
            input.classList.remove('bg-light'); // Remove disabled background
            input.required = true;
            input.value = ''; // Clear values
            input.placeholder = `Side ${input.id.slice(-1)}`; // Reset placeholder
        });

        // 2. Disable the input corresponding to the mode (the unknown side)
        const unknownInput = document.getElementById(`input-${mode}`);
        unknownInput.disabled = true;
        unknownInput.required = false;
        unknownInput.value = ''; // Ensure it's empty
        unknownInput.placeholder = 'Calculated...';
        unknownInput.classList.add('bg-light');

        // 3. Update labels
        labels['a'].textContent = mode === 'a' ? 'Unknown Leg a' : 'Leg a';
        labels['b'].textContent = mode === 'b' ? 'Unknown Leg b' : 'Leg b';
        labels['c'].textContent = mode === 'c' ? 'Unknown Hypotenuse c' : 'Hypotenuse c';

        // 4. Hide the results container when switching mode
        document.getElementById('solution-output').classList.add('d-none');
    }

    /**
     * Updates the results display with appropriate styling and content.
     */
    function displayResult(isError, contentHtml) {
        const outputDiv = document.getElementById('solution-output');

        // Reset classes
        outputDiv.classList.remove('d-none', 'alert', 'alert-danger', 'card', 'p-3');

        if (isError) {
            outputDiv.classList.add('alert', 'alert-danger'); // Bootstrap error styling
            outputDiv.innerHTML = `<p class="fw-bold mb-1">Calculation Error</p>${contentHtml}`;
        } else {
            outputDiv.classList.add('card', 'p-3'); // Bootstrap card styling
            outputDiv.innerHTML = contentHtml;
        }

        // Trigger MathJax typesetting for the new content
        if (typeof MathJax !== 'undefined') {
             MathJax.typesetPromise([outputDiv]);
        }
    }

    /**
     * Handles form submission and triggers the Pythagorean calculation.
     */
    function handlePythagoreanCalculation(e) {
        e.preventDefault();

        const mode = document.getElementById('calculate-mode').value;
        const inputA = document.getElementById('input-a').value.trim();
        const inputB = document.getElementById('input-b').value.trim();
        const inputC = document.getElementById('input-c').value.trim();

        // Determine known values based on the mode
        let result, known1, known2, formula, calculationSide, calculationText;
        let errorMessage = '';

        // Helper to check if a value is a valid positive number
        const isPositiveNumber = (val) => {
            const num = parseFloat(val);
            return !isNaN(num) && num > 0;
        };

        try {
            if (mode === 'c') {
                // Calculate Hypotenuse c: c = sqrt(a^2 + b^2)
                if (!isPositiveNumber(inputA) || !isPositiveNumber(inputB)) {
                    errorMessage = "Please enter two positive numbers for Leg a and Leg b.";
                }

                known1 = parseFloat(inputA);
                known2 = parseFloat(inputB);
                result = Math.sqrt(known1 * known1 + known2 * known2);
                formula = `c = \\sqrt{a^2 + b^2}`;
                calculationSide = 'c';
                calculationText = `c = \\sqrt{${known1}^2 + ${known2}^2}`;

            } else if (mode === 'a') {
                // Calculate Leg a: a = sqrt(c^2 - b^2)
                if (!isPositiveNumber(inputC) || !isPositiveNumber(inputB)) {
                    errorMessage = "Please enter two positive numbers for Hypotenuse c and Leg b.";
                }

                known1 = parseFloat(inputC); // Hypotenuse c
                known2 = parseFloat(inputB); // Leg b

                if (known2 >= known1) {
                    errorMessage = "Leg (b) cannot be greater than or equal to Hypotenuse (c).";
                }

                result = Math.sqrt(known1 * known1 - known2 * known2);
                formula = `a = \\sqrt{c^2 - b^2}`;
                calculationSide = 'a';
                calculationText = `a = \\sqrt{${known1}^2 - ${known2}^2}`;

            } else if (mode === 'b') {
                // Calculate Leg b: b = sqrt(c^2 - a^2)
                if (!isPositiveNumber(inputC) || !isPositiveNumber(inputA)) {
                    errorMessage = "Please enter two positive numbers for Hypotenuse c and Leg a.";
                }

                known1 = parseFloat(inputC); // Hypotenuse c
                known2 = parseFloat(inputA); // Leg a

                if (known2 >= known1) {
                    errorMessage = "Leg (a) cannot be greater than or equal to Hypotenuse (c).";
                }

                result = Math.sqrt(known1 * known1 - known2 * known2);
                formula = `b = \\sqrt{c^2 - a^2}`;
                calculationSide = 'b';
                calculationText = `b = \\sqrt{${known1}^2 - ${known2}^2}`;
            }

            if (errorMessage) {
                throw new Error(errorMessage);
            }

            // Output Formatting: toFixed(6) for precision, then remove trailing zeros
            const result_f = result.toFixed(6).replace(/\.?0+$/, '');

            // Result Display
            let htmlContent = `
                <p class="output-label text-center fw-bold">Length of Side $\\mathbf{${calculationSide}}$:</p>
                <div class="output-value mb-3">
                    $$\\mathbf{${result_f}}$$
                </div>
                <div class="formula-applied">
                    Applied Formula: $$${formula}$$
                    <br>
                    Calculation: $$${calculationText} \\approx ${result_f}$$
                </div>
            `;

            displayResult(false, htmlContent);

        } catch (error) {
            const htmlContent = `<p class="text-center mb-0">${error.message}</p>`;
            displayResult(true, htmlContent);
        }
    }

    // Attach handler to the form
    document.getElementById('pythagorean-form').addEventListener('submit', handlePythagoreanCalculation);

    // Initial setup on load: Ensure a fresh start by calling updateInputLabels, but do NOT run an initial calculation.
    window.onload = function() {
        updateInputLabels();
    };

