    function simplifyRadicalValue(N) {
        if (N <= 0) return { A: 0, B: N, P: 0 }; 

        let largestPerfectSquare = 1;

        // Only need to check divisors up to the square root of N
        const limit = Math.floor(Math.sqrt(N));

        for (let i = limit; i >= 2; i--) {
            const square = i * i;
            if (N % square === 0) {
                largestPerfectSquare = square;
                break;
            }
        }

        const A = Math.sqrt(largestPerfectSquare); // The number outside the radical
        const B = N / largestPerfectSquare;       // The number remaining inside the radical

        return { A: A, B: B, P: largestPerfectSquare };
    }

    /**
     * Handles form submission and triggers the radical simplification.
     */
    function handleRadicalSimplification(e) {
        e.preventDefault();

        const inputElement = document.getElementById('radicand-n');
        const nStr = inputElement.value.trim();

        // Use standard input validation first
        if (!inputElement.checkValidity()) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please enter a number.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const N = parseInt(nStr, 10);

        if (!Number.isInteger(N) || N <= 0) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please enter a positive whole number (integer) greater than zero.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const { A, B, P } = simplifyRadicalValue(N);

        let resultDisplay;
        let explanationText;

        if (B === 1) {
            // Perfect square case (e.g., sqrt(49) = 7)
            resultDisplay = A.toString();
            explanationText = `The radicand $\\mathbf{${N}}$ is a perfect square ($\\mathbf{${P}}$). The simplified form is an integer.`;
        } else if (A === 1) {
            // Already simplest form (e.g., sqrt(10))
            resultDisplay = `\\sqrt{${B}}`;
            explanationText = `The radicand $\\mathbf{${N}}$ contains no perfect square factors greater than 1, so it is already in its simplest form.`;
        } else {
            // Standard simplified form (e.g., sqrt(72) = 6*sqrt(2))
            resultDisplay = `${A}\\sqrt{${B}}`;
            explanationText = `The largest perfect square factor of $\\mathbf{${N}}$ is $\\mathbf{${P}}$. We simplify: $\\sqrt{${N}} = \\sqrt{${P} \\cdot ${B}} = ${A}\\sqrt{${B}}$.`;
        }

        // Result Display
        let htmlContent = `
            <p class="output-label">Simplified Form of $\\mathbf{\\sqrt{${N}}}$:</p>
            <div class="output-value">
                $$\\mathbf{${resultDisplay}}$$
            </div>
            <div class="explanation">
                ${explanationText}
            </div>
        `;

        displayResult(false, htmlContent);
    }

    // Attach handler to the form
    document.getElementById('radical-form').addEventListener('submit', handleRadicalSimplification);

    // Initial setup on load: Ensure a clean start by hiding the output.
    window.onload = function() {
        // Hiding the output on load ensures a clean, empty start for the visitor.
        document.getElementById('solution-output').classList.add('d-none');
    };

