/**
     * Calculates the Greatest Common Factor (GCF) of two non-negative integers
     * using the Euclidean Algorithm.
     * @param {number} a - First integer.
     * @param {number} b - Second integer.
     * @returns {number} The GCF of a and b.
     */
    function gcd(a, b) {
        // Handle floating point errors due to Math.abs
        a = Math.round(Math.abs(a));
        b = Math.round(Math.abs(b));

        // Euclidean Algorithm
        while (b) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    /**
     * Finds the number of decimal places for accurate multiplication for GCF.
     * @param {number} num - The number to check.
     * @returns {number} The number of decimal places.
     */
    function getDecimalPlaces(num) {
        if (typeof num !== 'number' || isNaN(num)) return 0;
        const str = num.toString();
        if (str.includes('.')) {
            // Check for potential scientific notation
            if (str.includes('e')) {
                const parts = str.split('e');
                // Extremely simple check for exponent, often sufficient
                return parseInt(parts[1], 10) < 0 ? Math.abs(parseInt(parts[1], 10)) : 0;
            }
            return str.split('.')[1].length;
        }
        return 0;
    }

    /**
     * Updates the results display with appropriate styling and content, and triggers MathJax.
     */
    function displayResult(className, contentHtml) {
        const outputDiv = document.getElementById('solution-output');

        // Reset and apply new classes
        outputDiv.classList.remove('d-none', 'result-error', 'result-success');
        outputDiv.classList.add(className);
        outputDiv.innerHTML = contentHtml;

        // Trigger MathJax typesetting for the new content
        if (typeof MathJax !== 'undefined') {
             MathJax.typesetPromise([outputDiv]);
        }
    }

    document.getElementById('ratio-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const A_input = document.getElementById('part-a-input').value.trim();
        const B_input = document.getElementById('part-b-input').value.trim();

        const A = parseFloat(A_input);
        const B = parseFloat(B_input);

        const outputDiv = document.getElementById('solution-output');
        outputDiv.classList.add('d-none'); // Hide output initially

        let htmlContent = '';
        let resultClass = '';

        // --- Input Validation ---
        if (A_input === '' || B_input === '' || isNaN(A) || isNaN(B)) {
            htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center mb-0">Please enter valid numerical values for both parts of the ratio.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        if (B === 0) {
            htmlContent = `<p class="fw-bold text-center">Invalid Ratio</p><p class="text-center mb-0">The second part of the ratio ($B$) cannot be zero.</p>`;
            resultClass = 'result-error';
            displayResult(resultClass, htmlContent);
            return;
        }

        // --- Simplification Logic ---

        // Handle decimals by scaling both parts to integers
        const decimalA = getDecimalPlaces(A);
        const decimalB = getDecimalPlaces(B);
        const maxDecimals = Math.max(decimalA, decimalB);
        // Use 10^(maxDecimals) factor for scaling
        const factor = Math.pow(10, maxDecimals); 

        // Round to handle potential floating-point math issues before rounding
        const N_scaled = Math.round(A * factor);
        const D_scaled = Math.round(B * factor);

        const commonDivisor = gcd(N_scaled, D_scaled);

        // The simplified parts must be integers
        const A_simplified = N_scaled / commonDivisor;
        const B_simplified = D_scaled / commonDivisor;

        // --- Decimal Value Calculation ---
        const decimalValue = A / B;
        const formattedDecimal = decimalValue.toFixed(6).replace(/\.?0+$/, ''); // Max 6 decimals, trim trailing zeros

        // --- Result Display ---

        htmlContent += `<div class="row text-center">`;

        // Simplified Ratio
        htmlContent += `<div class="col-md-6 mb-4 mb-md-0">`;
        htmlContent += `<p class="output-label">Simplified Ratio ($A':B'$)</p>`;
        htmlContent += `<div class="output-value">$$\\mathbf{${A_simplified} : ${B_simplified}}$$</div>`;
        htmlContent += `</div>`;

        // Decimal Value
        htmlContent += `<div class="col-md-6">`;
        htmlContent += `<p class="output-label">Decimal Value ($A / B$)</p>`;
        htmlContent += `<div class="output-value">$$\\mathbf{${formattedDecimal}}$$</div>`;
        htmlContent += `<p class="text-sm text-center text-secondary mt-1">(Ratio value)</p>`;
        htmlContent += `</div>`;

        htmlContent += `</div>`; // end row

        resultClass = 'result-success';

        displayResult(resultClass, htmlContent);
    });

    // Initial setup on load: Ensure a clean start by hiding the output.
    window.onload = function() {
        document.getElementById('solution-output').classList.add('d-none');
    };

