document.addEventListener('DOMContentLoaded', () => {
        // --- Scalable Math.js Engine Initialization ---
        // Ensure Math.js has loaded
        if (typeof window.math === 'undefined') {
            document.getElementById('current-input').innerHTML = "<span style='color:#ef4444;font-size:1.5rem;'>Failed to load math engine.</span>";
            return;
        }

        const math = window.math;

        // Create an alternate math instance specifically for degree overrides
        const mathDeg = math.create(math.all);
        mathDeg.import({
            sin: (x) => math.sin(x * Math.PI / 180),
            cos: (x) => math.cos(x * Math.PI / 180),
            tan: (x) => math.tan(x * Math.PI / 180),
            asin: (x) => math.asin(x) * 180 / Math.PI,
            acos: (x) => math.acos(x) * 180 / Math.PI,
            atan: (x) => math.atan(x) * 180 / Math.PI
        }, { override: true });

        // --- State Management ---
        let tokens = []; // Array of { eval: string, disp: string }
        let degMode = true; // Default to degrees

        // DOM Elements
        const currentInputEl = document.getElementById('current-input');
        const historyEl = document.getElementById('history-display');
        const keypad = document.getElementById('scientific-keypad');
        const degBtn = document.getElementById('deg-btn');
        const radBtn = document.getElementById('rad-btn');

        // --- Core Functions ---
        function updateDisplay() {
            if (tokens.length === 0) {
                currentInputEl.innerHTML = `0<span class="cursor-blink"></span>`;
            } else {
                const displayStr = tokens.map(t => t.disp).join('');
                currentInputEl.innerHTML = `${displayStr}<span class="cursor-blink"></span>`;
            }
        }

        function appendToken(evalStr, dispStr) {
            // clear previous error messages if user types again
            if (currentInputEl.innerText.includes('Error')) {
                historyEl.innerText = '';
                tokens = [];
            }
            tokens.push({ eval: evalStr, disp: dispStr || evalStr });
            updateDisplay();
        }

        function backspace() {
            if (currentInputEl.innerText.includes('Error')) {
                tokens = [];
            } else if (tokens.length > 0) {
                tokens.pop();
            }
            updateDisplay();
        }

        function clearAll() {
            tokens = [];
            historyEl.innerHTML = '';
            updateDisplay();
        }

        function evaluateExpression() {
            if (tokens.length === 0) return;
            const expr = tokens.map(t => t.eval).join('');

            try {
                // Select math engine based on Degree/Radian mode
                const engine = degMode ? mathDeg : math;

                let result = engine.evaluate(expr);

                // Format the result cleanly: e.g. floating point inaccuracies 
                result = math.format(result, { precision: 14 });

                // Set History
                const displayExpr = tokens.map(t => t.disp).join('');
                historyEl.innerHTML = `${displayExpr} =`;

                // Set Current Tokens to result
                tokens = [{ eval: String(result), disp: String(result) }];
                updateDisplay();

            } catch (error) {
                console.error("Math Evaluation Error:", error);
                currentInputEl.innerHTML = `<span style='color:#ef4444;'>Error</span><span class="cursor-blink"></span>`;
                // Keep tokens intact so user can correct syntax
            }
        }

        // --- Event Listeners ---
        degBtn.addEventListener('click', () => {
            degMode = true;
            degBtn.classList.add('active');
            radBtn.classList.remove('active');
        });

        radBtn.addEventListener('click', () => {
            degMode = false;
            radBtn.classList.add('active');
            degBtn.classList.remove('active');
        });

        keypad.addEventListener('click', (e) => {
            const btn = e.target.closest('.btn-calc');
            if (!btn) return;

            const action = btn.dataset.action;
            const evalStr = btn.dataset.eval;
            const dispStr = btn.dataset.disp;

            // Blur to remove focus outline visually allowing keyboard input without accidental re-triggers
            btn.blur(); 

            if (action === 'clear') {
                clearAll();
            } else if (action === 'back') {
                backspace();
            } else if (action === 'evaluate') {
                evaluateExpression();
            } else if (evalStr) {
                appendToken(evalStr, dispStr);
            }
        });

        // --- Keyboard Support ---
        document.addEventListener('keydown', (e) => {
            // Map common keyboard keys to visual displays and evaluations
            const key = e.key;

            if (/[0-9]/.test(key)) {
                e.preventDefault();
                appendToken(key, key);
            } else if (key === '+' || key === '-') {
                e.preventDefault();
                appendToken(key, key);
            } else if (key === '*') {
                e.preventDefault();
                appendToken('*', '×');
            } else if (key === '/') {
                e.preventDefault();
                appendToken('/', '÷');
            } else if (key === '.') {
                e.preventDefault();
                appendToken('.', '.');
            } else if (key === '^') {
                e.preventDefault();
                appendToken('^', '^');
            } else if (key === '(' || key === ')') {
                e.preventDefault();
                appendToken(key, key);
            } else if (key === '%') {
                e.preventDefault();
                appendToken('%', ' mod ');
            } else if (key === 'Enter' || key === '=') {
                e.preventDefault();
                evaluateExpression();
            } else if (key === 'Backspace') {
                e.preventDefault();
                backspace();
            } else if (key === 'Delete' || key === 'Escape') {
                e.preventDefault();
                clearAll();
            }
        });

        // Initial setup
        updateDisplay();
    });

