    /**
     * Converts a Scientific Notation string to a Standard Form string accurately.
     * Handles large/small numbers by string manipulation.
     * Mantissa example: 1.23, Exponent example: 5 or -5
     */
    function scientificToStandardString(mantissaStr, exponent) {
        let isNegative = mantissaStr.startsWith('-');
        if (isNegative) mantissaStr = mantissaStr.substring(1);

        let [integerPart, decimalPart = ''] = mantissaStr.split('.');
        let digits = integerPart + decimalPart;
        let position = integerPart.length;

        // Apply exponent shift
        position += exponent;

        if (position <= 0) {
            // Very small number (e.g., 0.000...)
            let leadingZeros = Math.abs(position);
            // Example: 1.23e-5 -> position = 1 + (-5) = -4. Abs(position) = 4.
            // Result: 0.0000123. 4 leading zeros after decimal.
            let standard = '0.' + '0'.repeat(leadingZeros) + digits;
            // Cleanup: ensure we don't end up with multiple leading zeros if mantissa was 0.x
            standard = standard.replace(/^0\.0+/, '0.').replace(/^0\.0*([1-9])/, '0.' + '0'.repeat(leadingZeros) + '$1');
            return (isNegative ? '-' : '') + standard;

        } else if (position >= digits.length) {
            // Very large number (e.g., 123000...)
            // Example: 1.23e5 -> position = 1 + 5 = 6. digits.length = 3.
            // Result: 123000. 3 trailing zeros.
            let trailingZeros = position - digits.length;
            let standard = digits + '0'.repeat(trailingZeros);
            return (isNegative ? '-' : '') + standard;

        } else {
            // Number with a decimal point in the middle (e.g., 12.3)
            // Example: 1.23e1 -> position = 1 + 1 = 2.
            // Result: 12.3
            let standard = digits.substring(0, position) + '.' + digits.substring(position);
            // Cleanup: remove decimal if it's at the end (e.g., 12.0)
            standard = standard.replace(/\.$/, '');
            return (isNegative ? '-' : '') + standard;
        }
    }

    // -------------------------------------------------------------------
    // --- 1. Standard (Decimal) to Scientific Logic ---
    // -------------------------------------------------------------------
    document.getElementById('standard-to-scientific-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const inputStr = document.getElementById('standard-input').value.trim();
        document.getElementById('scientific-output').classList.add('d-none');

        let processedStr = inputStr.replace(/,/g, '').trim();

        if (processedStr === '' || isNaN(processedStr)) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please enter a valid numeric value.</p>`;
            displayResult('scientific-output', true, htmlContent);
            return;
        }

        if (processedStr === '0' || processedStr === '-0' || processedStr === '+0') {
             const htmlContent = `
                <p class="output-label">Scientific Notation:</p>
                <div class="output-value">
                    $$\\mathbf{0}$$
                </div>
            `;
            displayResult('scientific-output', false, htmlContent);
            return;
        }

        const isNegative = processedStr.startsWith('-');
        if (isNegative) {
            processedStr = processedStr.substring(1);
        }

        // Remove unnecessary signs (+ or -) and use the Number constructor 
        // to simplify the string for better handling of trailing zeros.
        let numString = String(Number(processedStr)); 

        // Get the position of the decimal point
        const decimalIndex = numString.indexOf('.');

        // Remove the decimal point and leading/trailing zeros for the core digits
        let mantissaDigits = numString.replace('.', '');

        // Find the index of the first non-zero digit
        let firstDigitIndex = mantissaDigits.search(/[1-9]/);

        // Sanity check
        if (firstDigitIndex === -1) {
            const htmlContent = `<p class="font-bold text-center">Invalid Number</p><p class="text-center">Could not parse non-zero digits.</p>`;
            displayResult('scientific-output', true, htmlContent);
            return;
        }

        let exponent;

        if (decimalIndex === -1) {
            // Large integer (e.g., "123000")
            // New decimal position is at firstDigitIndex + 1 (i.e., after the first digit)
            // Exponent is the number of digits after the first digit.
            exponent = mantissaDigits.length - (firstDigitIndex + 1);
        } else if (decimalIndex <= firstDigitIndex) {
            // Small number (e.g., "0.000123")
            // We move the decimal right by (firstDigitIndex + 1) - decimalIndex
            exponent = decimalIndex - (firstDigitIndex + 1);
        } else {
            // Large/Mixed number (e.g., "123.45")
            // We move the decimal left by decimalIndex - (firstDigitIndex + 1)
            exponent = decimalIndex - (firstDigitIndex + 1);
        }

        // Final Mantissa calculation
        let cleanedMantissaDigits = mantissaDigits.substring(firstDigitIndex);

        let mantissa;
        if (cleanedMantissaDigits.length === 1) {
            mantissa = cleanedMantissaDigits;
        } else {
            // Format as A.BCDE...
            mantissa = cleanedMantissaDigits.charAt(0) + '.' + cleanedMantissaDigits.substring(1);
        }

        // Clean up mantissa: remove trailing zeros after decimal
        mantissa = mantissa.replace(/(\.\d*?[1-9])0+$/, '$1').replace(/\.$/, '');

        // Add negative sign if necessary
        const mantissaSign = isNegative ? '-' : '';

        // Result Display
        let htmlContent = `
            <p class="output-label">Scientific Notation ($\mathbf{A} \\times 10^{\\mathbf{N}}$):</p>
            <div class="output-value">
                $$\\mathbf{${mantissaSign}${mantissa} \\times 10^{${exponent}}}$$
            </div>
            <p class="result-subtext">
                Mantissa $\\mathbf{A} = ${mantissaSign}${mantissa}$
            </p>
            <p class="result-subtext">
                Exponent $\\mathbf{N} = ${exponent}$
            </p>
        `;

        displayResult('scientific-output', false, htmlContent);
    });

    // -------------------------------------------------------------------
    // --- 2. Scientific to Standard (Decimal) Logic ---
    // -------------------------------------------------------------------
    document.getElementById('scientific-to-standard-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const mantissaStr = document.getElementById('mantissa-input').value.trim();
        const exponentStr = document.getElementById('exponent-input').value.trim();

        document.getElementById('standard-output').classList.add('d-none');

        const mantissa = parseFloat(mantissaStr);
        const exponent = parseInt(exponentStr);

        if (isNaN(mantissa) || isNaN(exponent)) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please enter valid numbers for the Mantissa (A) and Exponent (N).</p>`;
            displayResult('standard-output', true, htmlContent);
            return;
        }

        if (mantissa === 0) {
            const htmlContent = `
                <p class="output-label">Standard Decimal Form:</p>
                <div class="output-value">
                    $$\\mathbf{0}$$
                </div>
            `;
            displayResult('standard-output', false, htmlContent);
            return;
        }

        // Use custom accurate string function
        let standardStr;
        try {
            standardStr = scientificToStandardString(mantissaStr, exponent);
        } catch (error) {
            const htmlContent = `<p class="font-bold text-center">Calculation Error</p><p class="text-center">The resulting number is too large or too small to be accurately displayed in a standard string.</p>`;
            displayResult('standard-output', true, htmlContent);
            return;
        }

        // Result Display
        let htmlContent = `
            <p class="output-label">Standard Decimal Form:</p>
            <div class="output-value">
                $$\\mathbf{${standardStr}}$$
            </div>
            <p class="result-subtext">
                Value: ${standardStr}
            </p>
        `;

        displayResult('standard-output', false, htmlContent);
    });

