        const a_val = document.getElementById('arithmetic-a-input').value.trim();
        const d_val = document.getElementById('arithmetic-d-input').value.trim();
        const n_val = document.getElementById('arithmetic-n-input').value.trim();

        const a = parseFloat(a_val);
        const d = parseFloat(d_val);
        const n = parseInt(n_val);
        const containerId = 'arithmetic-output';

        if (a_val === '' || d_val === '' || n_val === '' || isNaN(a) || isNaN(d) || isNaN(n) || n <= 0 || n !== Math.floor(n)) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please ensure 'a' and 'd' are valid numbers, and 'n' is a positive integer.</p>`;
            displayResult(containerId, true, htmlContent);
            return;
        }

        // Formula: S_n = n/2 * [2a + (n-1)d]
        const sum = (n / 2) * (2 * a + (n - 1) * d);

        const result_f = sum.toFixed(10).replace(/\.?0+$/, ''); // Format result with better precision
        const a_f = a.toFixed(10).replace(/\.?0+$/, '');
        const d_f = d.toFixed(10).replace(/\.?0+$/, '');

        // Result Display
        let htmlContent = `
            <p class="output-label">Sum of $\\mathbf{${n}}$ Terms ($\mathbf{S_{${n}}}$):</p>
            <div class="output-value">
                $$\\mathbf{${result_f}}$$
            </div>
            <div class="formula-display">
                Calculation: $$S_{${n}} = \\frac{${n}}{2} [2(${a_f}) + (${n}-1)(${d_f})]$$
            </div>
        `;

        displayResult(containerId, false, htmlContent);
    }

    /**
     * Calculates the sum of a Geometric Series.
     */
    function calculateGeometricSum(e) {
        e.preventDefault();

        const a_val = document.getElementById('geometric-a-input').value.trim();
        const r_val = document.getElementById('geometric-r-input').value.trim();
        const n_val = document.getElementById('geometric-n-input').value.trim();

        const a = parseFloat(a_val);
        const r = parseFloat(r_val);
        const n = parseInt(n_val);
        const containerId = 'geometric-output';

        if (a_val === '' || r_val === '' || n_val === '' || isNaN(a) || isNaN(r) || isNaN(n) || n <= 0 || n !== Math.floor(n)) {
            const htmlContent = `<p class="font-bold text-center">Invalid Input</p><p class="text-center">Please ensure 'a' and 'r' are valid numbers, and 'n' is a positive integer.</p>`;
            displayResult(containerId, true, htmlContent);
            return;
        }

        let sum;
        let formulaUsed;
        const a_f = a.toFixed(10).replace(/\.?0+$/, '');
        const r_f = r.toFixed(10).replace(/\.?0+$/, '');

        if (r === 1) {
            // Special Case: r = 1 -> S_n = n * a
            sum = n * a;
            formulaUsed = `S_{${n}} = ${n} \\cdot ${a_f}`;
        } else {
            // General Formula: S_n = a * (1 - r^n) / (1 - r)
            sum = a * (1 - Math.pow(r, n)) / (1 - r);
            formulaUsed = `S_{${n}} = ${a_f} \\frac{1 - (${r_f})^{${n}}}{1 - ${r_f}}`;
        }

        const result_f = sum.toFixed(10).replace(/\.?0+$/, ''); // Format result

        // Result Display
        let htmlContent = `
            <p class="output-label">Sum of $\\mathbf{${n}}$ Terms ($\mathbf{S_{${n}}}$):</p>
            <div class="output-value">
                $$\\mathbf{${result_f}}$$
            </div>
            <div class="formula-display">
                Calculation: $$${formulaUsed}$$
            </div>
        `;

        displayResult(containerId, false, htmlContent);
    }

    // Attach handlers to the forms
    document.getElementById('arithmetic-form').addEventListener('submit', calculateArithmeticSum);
    document.getElementById('geometric-form').addEventListener('submit', calculateGeometricSum);

    // FIXED: Removed window.onload auto-calculation to ensure fresh fields on load.

