/**
     * Calculates the determinant of a 2x2 matrix: |A| = ad - bc
     * @param {number} a - Top left coefficient.
     * @param {number} b - Top right coefficient.
     * @param {number} c - Bottom left coefficient.
     * @param {number} d - Bottom right coefficient.
     * @returns {number} The determinant.
     */
    function determinant2x2(a, b, c, d) {
        return a * d - b * c;
    }

    document.getElementById('system-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Use text input and parseFloat to handle empty/non-numeric input gracefully
        const a1 = parseFloat(document.getElementById('a1').value.trim());
        const b1 = parseFloat(document.getElementById('b1').value.trim());
        const c1 = parseFloat(document.getElementById('c1').value.trim());
        const a2 = parseFloat(document.getElementById('a2').value.trim());
        const b2 = parseFloat(document.getElementById('b2').value.trim());
        const c2 = parseFloat(document.getElementById('c2').value.trim());

        const outputDiv = document.getElementById('solution-output');

        // --- Input Validation ---
        if (isNaN(a1) || isNaN(b1) || isNaN(c1) || isNaN(a2) || isNaN(b2) || isNaN(c2)) {
            const htmlContent = `
                <p class="fw-bold mb-1">Invalid Input</p>
                <p class="small mb-0">Please enter a numerical value for all six coefficients ($a_1, b_1, c_1, a_2, b_2, c_2$).</p>
            `;
            displayResult('result-error', htmlContent);
            return;
        }


        // --- 1. Calculate the Main Determinant (D) ---
        // D = | a1 b1 |
        //     | a2 b2 |
        const D = determinant2x2(a1, b1, a2, b2);

        let htmlContent = '';

        // --- 2. Check for Unique Solution ---
        const epsilon = 1e-9; // Tolerance for floating point comparison
        if (Math.abs(D) < epsilon) { 
            // Determinant is close to zero (parallel or same lines)

            // Calculate Dx and Dy to check consistency
            const Dx = determinant2x2(c1, b1, c2, b2);
            const Dy = determinant2x2(a1, c1, a2, c2);

            const a1_f = a1.toFixed(4).replace(/\.?0+$/, '');
            const b1_f = b1.toFixed(4).replace(/\.?0+$/, '');
            const c1_f = c1.toFixed(4).replace(/\.?0+$/, '');

            if (Math.abs(Dx) < epsilon && Math.abs(Dy) < epsilon) {
                // Dx=0 and Dy=0 means the lines are identical (Infinite Solutions)
                htmlContent += `<p class="fs-5 fw-bold mb-2">No Unique Solution (Dependent System)</p>`;
                htmlContent += `<p>The main determinant $\\mathbf{D}$ is zero. The two equations represent the **same line**, meaning there are **infinitely many solutions**.</p>`;
                htmlContent += `<p class="mt-2 fw-semibold">Solution: All points on the line $${a1_f} x + ${b1_f} y = ${c1_f}$</p>`;
            } else {
                // Dx != 0 or Dy != 0 means the lines are parallel (No Solution)
                htmlContent += `<p class="fs-5 fw-bold mb-2">No Solution (Inconsistent System)</p>`;
                htmlContent += `<p>The main determinant $\\mathbf{D}$ is zero. The two equations represent **parallel lines**, meaning they never intersect and there is **no solution**.</p>`;
            }

            displayResult('result-error', htmlContent);
            return;
        }

        // --- 3. Calculate Determinants Dx and Dy (Unique Solution exists) ---
        const Dx = determinant2x2(c1, b1, c2, b2);
        const Dy = determinant2x2(a1, c1, a2, c2);

        // --- 4. Calculate Roots (Cramer's Rule) ---
        const x = Dx / D;
        const y = Dy / D;

        // Displaying results
        htmlContent += `<p class="fs-5 fw-bold mb-3 text-success">Unique Solution Found</p>`;

        htmlContent += `<div class="mb-4">`;
        htmlContent += `<p class="text-base mb-1">Main Determinant ($\\mathbf{D}$): $\\mathbf{${D.toFixed(6).replace(/\.?0+$/, '')}}$</p>`;
        htmlContent += `<p class="text-base mb-1">Determinant $\\mathbf{D_x}$: $\\mathbf{${Dx.toFixed(6).replace(/\.?0+$/, '')}}$</p>`;
        htmlContent += `<p class="text-base mb-1">Determinant $\\mathbf{D_y}$: $\\mathbf{${Dy.toFixed(6).replace(/\.?0+$/, '')}}$</p>`;
        htmlContent += `</div>`;

        htmlContent += `<p class="fs-4 fw-bolder mt-4">`;
        htmlContent += `Solution: $\\mathbf{x} = ${x.toFixed(6).replace(/\.?0+$/, '')}$ and $\\mathbf{y} = ${y.toFixed(6).replace(/\.?0+$/, '')}$`;
        htmlContent += `</p>`;

        displayResult('result-box-success', htmlContent); // Success class
    });

    /**
     * Updates the results display with appropriate styling and content.
     * @param {string} className - Custom class name for styling (e.g., 'result-error', 'result-box-success').
     * @param {string} contentHtml - HTML string containing the calculated results.
     */
    function displayResult(className, contentHtml) {
        const outputDiv = document.getElementById('solution-output');
        // Reset classes and show
        outputDiv.className = '';
        outputDiv.classList.add(className);
        outputDiv.innerHTML = contentHtml;
    }

    // FIXED: No window.onload call to keep fields empty on load.

basic_calculator__trig_identity_verifier:
const TOLERANCE = 1e-9; // Tolerance for floating point comparisons
    const PI = Math.PI;

    // --- Core Safe Evaluation Functions ---

    /**
     * Replaces user-friendly trig functions with Math equivalents and handles power syntax.
     * Also substitutes reciprocal functions using 1/func.
     * @param {string} expression - User input string.
     * @returns {string} - Cleaned expression ready for evaluation.
     */
    function cleanExpression(expression) {
        // 1. Replace constants
        let cleaned = expression.toUpperCase().replace(/PI/g, 'Math.PI');

        // 2. Define safe math functions (only allowed functions)
        cleaned = cleaned.replace(/sin\(/gi, 'Math.sin(');
        cleaned = cleaned.replace(/cos\(/gi, 'Math.cos(');
        cleaned = cleaned.replace(/tan\(/gi, 'Math.tan(');

        // 3. Define reciprocal functions using the quotient identity
        cleaned = cleaned.replace(/csc\((.*?)\)/gi, '(1 / Math.sin($1))');
        cleaned = cleaned.replace(/sec\((.*?)\)/gi, '(1 / Math.cos($1))');
        cleaned = cleaned.replace(/cot\((.*?)\)/gi, '(1 / Math.tan($1))');

        // 4. Handle other common math functions
        cleaned = cleaned.replace(/pow\(/gi, 'Math.pow(');
        cleaned = cleaned.replace(/sqrt\(/gi, 'Math.sqrt(');
        cleaned = cleaned.replace(/abs\(/gi, 'Math.abs(');
        cleaned = cleaned.replace(/log\(/gi, 'Math.log('); // Natural log
        cleaned = cleaned.replace(/log10\(/gi, 'Math.log10(');

        return cleaned;
    }

    /**
     * Safely evaluates a cleaned expression string at a given angle x.
     * @param {string} expression - Cleaned expression string.
     * @param {number} x - Angle value in radians.
     * @returns {number | null} - Result of evaluation or null on error.
     */
    function evalExpression(expression, x) {
        try {
            // Use Function constructor for safe execution context
            const evaluator = new Function('x', 'Math', `
                // Local aliases for Math functions for cleaner expression execution
                const sin = Math.sin;
                const cos = Math.cos;
                const tan = Math.tan;
                const pow = Math.pow;
                const PI = Math.PI;

                return ${expression};
            `);
            return evaluator(x, Math);
        } catch (error) {
            console.error("Evaluation Error:", error.message);
            return NaN;
        }
    }

    // --- Utility Functions ---

    /**
     * Converts degrees to radians.
     */
    const degToRad = (degrees) => degrees * (PI / 180);

    /**
     * Generates a list of test angles (in radians).
     * Includes simple angles (0, PI/2, PI) and random complex angles.
     */
    function generateTestAngles(unit) {
        const angles = [0]; // 0

        // Generate 3 simple angles
        angles.push(PI / 4, PI / 2, PI);

        // Generate 4 random angles between 0 and 2*PI (or 0 and 360)
        for (let i = 0; i < 4; i++) {
            if (unit === 'radians') {
                angles.push(Math.random() * 2 * PI);
            } else {
                angles.push(Math.random() * 360);
            }
        }

        // Convert all angles to radians if they were generated in degrees
        return angles.map(angle => unit === 'degrees' ? degToRad(angle) : angle);
    }

    /**
     * Formats a number for display. Handles very small numbers and Infinity.
     */
    function formatValue(value) {
        if (isNaN(value)) {
            return '<span class="text-danger fw-bold">Undefined (NaN)</span>';
        }
        if (!isFinite(value)) {
            return '<span class="text-danger fw-bold">Infinity</span>';
        }
        if (Math.abs(value) < TOLERANCE) {
            return '0';
        }
        return value.toFixed(8);
    }

    /**
     * Updates the results display with appropriate styling and content.
     */
    function displayResult(isError, statusMessage, detailsHtml) {
        const outputDiv = document.getElementById('solution-output');
        // Reset classes and style
        outputDiv.className = '';
        outputDiv.classList.add('p-4', 'rounded');

        if (isError) {
            outputDiv.classList.add('result-error');
        } else {
            outputDiv.classList.add('result-card');
        }

        outputDiv.innerHTML = `
            <div class="status-text ${isError ? 'status-failure' : 'status-success'}">${statusMessage}</div>
            ${detailsHtml}
        `;
    }

    // --- Main Calculation Handler ---

    function handleIdentityVerification(e) {
        e.preventDefault();

        const lhsExpression = document.getElementById('lhs-input').value.trim();
        const rhsExpression = document.getElementById('rhs-input').value.trim();
        const unit = document.getElementById('unit-selector').value;
        const outputDiv = document.getElementById('solution-output');

        if (lhsExpression === '' || rhsExpression === '') {
            outputDiv.innerHTML = `<div class="p-4 border text-center text-muted rounded">
                Please enter expressions for both the Left Hand Side and Right Hand Side.
            </div>`;
            return;
        }

        // Clean expressions once
        const cleanLHS = cleanExpression(lhsExpression);
        const cleanRHS = cleanExpression(rhsExpression);

        const testAnglesRad = generateTestAngles(unit);
        let allTestsPassed = true;
        let testRows = '';

        for (let i = 0; i < testAnglesRad.length; i++) {
            const angleRad = testAnglesRad[i];

            // Convert angle back to display format (degrees or simplified radians)
            let angleDisplay;
            if (unit === 'degrees') {
                angleDisplay = (angleRad * 180 / PI).toFixed(2) + '°';
            } else {
                // Try to simplify common radian fractions for display
                const simplified = simplifyRadian(angleRad);
                angleDisplay = simplified.isSimple ? simplified.display : angleRad.toFixed(4);
            }

            const lhsResult = evalExpression(cleanLHS, angleRad);
            const rhsResult = evalExpression(cleanRHS, angleRad);

            // Check for NaN or Infinity (Undefined)
            const isUndefined = isNaN(lhsResult) || isNaN(rhsResult) || !isFinite(lhsResult) || !isFinite(rhsResult);

            let passed;

            if (isUndefined) {
                // Check if they are both non-finite/NaN (e.g., both 1/0, both tan(PI/2))
                passed = (isNaN(lhsResult) && isNaN(rhsResult)) || (!isFinite(lhsResult) && !isFinite(rhsResult));

            } else {
                // Standard check: comparison within tolerance
                passed = Math.abs(lhsResult - rhsResult) < TOLERANCE;
            }

            if (!passed) {
                allTestsPassed = false;
            }

            testRows += `
                <tr class="${passed ? '' : 'bg-danger-subtle text-danger fw-semibold'}">
                    <td>${angleDisplay}</td>
                    <td>${formatValue(lhsResult)}</td>
                    <td>${formatValue(rhsResult)}</td>
                    <td>${passed ? 'Match' : 'FAIL'}</td>
                </tr>
            `;
        }

        const detailsHtml = `
            <div class="small text-center text-muted mb-4">
                Tested across **${testAnglesRad.length}** angles (in **${unit}**). Results must match within $\\pm 10^{-9}$ tolerance.
            </div>
            <div class="table-responsive">
                <table class="test-table table table-sm w-100 mb-0">
                    <thead class="bg-light">
                        <tr>
                            <th class="w-25">Angle (x)</th>
                            <th class="w-25">LHS Value</th>
                            <th class="w-25">RHS Value</th>
                            <th class="w-25">Result</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${testRows}
                    </tbody>
                </table>
            </div>
        `;

        let statusMessage;
        let isError;

        if (allTestsPassed) {
            statusMessage = "Identity VERIFIED (Highly Likely)";
            isError = false;
        } else {
            statusMessage = "Identity FAILED Verification (Not Equivalent)";
            isError = true;
        }

        displayResult(isError, statusMessage, detailsHtml);
    }

    /**
     * Attempts to simplify a radian angle for display (e.g., PI/2).
     */
    function simplifyRadian(rad) {
        // Use common denominators for display simplification
        const denominators = [1, 2, 3, 4, 6]; 
        for (const d of denominators) {
            const ratio = rad / (PI / d);
            const nearestInt = Math.round(ratio);
            if (Math.abs(ratio - nearestInt) < TOLERANCE) {
                const numerator = nearestInt;
                let display = '';
                if (numerator === 0) display = '0';
                else if (d === 1) display = `${numerator === 1 ? '' : numerator}\\pi`;
                else if (numerator === 1) display = `\\frac{\\pi}{${d}}`;
                else if (numerator === -1) display = `-\\frac{\\pi}{${d}}`;
                else display = `\\frac{${numerator}\\pi}{${d}}`;
                return { isSimple: true, display: '$' + display + '$' };
            }
        }
        return { isSimple: false, display: '' };
    }

    // Attach handler to the form
    document.getElementById('identity-form').addEventListener('submit', handleIdentityVerification);

