/**
     * Updates the UI with the calculation result or error.
     */
    function displayResult(isError, contentHtml) {
        const outputDiv = document.getElementById('solution-output');
        // Reset classes and style
        outputDiv.className = '';
        outputDiv.classList.add('p-4', 'rounded');

        if (isError) {
            outputDiv.classList.add('result-error');
        } else {
            outputDiv.classList.add('result-card');
        }
        outputDiv.innerHTML = contentHtml;
    }

    /**
     * Safely evaluates a logical expression string.
     * @param {string} expression - Cleaned logical expression string.
     * @param {string[]} variables - Array of variable names (e.g., ['A', 'B']).
     * @param {boolean[]} values - Array of boolean values corresponding to variables.
     * @returns {boolean | string} - Result of evaluation or 'ERROR'.
     */
    function safeEvaluateLogic(expression, variables, values) {
        // 1. Map logical operators to JS operators
        let jsExpression = expression.toUpperCase();

        // Replace custom operators with JS equivalents
        jsExpression = jsExpression.replace(/AND/g, '&&');
        jsExpression = jsExpression.replace(/OR/g, '||');
        jsExpression = jsExpression.replace(/NOT/g, '!');
        jsExpression = jsExpression.replace(/XOR/g, '!='); // A XOR B is equivalent to A != B for booleans

        // 2. Create the function scope for evaluation
        const argNames = variables.join(',');

        try {
            // Use Function constructor for isolated, safe evaluation
            const evaluator = new Function(argNames, `
                // IMPORTANT: All variables (A, B, C...) are passed as booleans (true/false)
                return (${jsExpression});
            `);

            // Pass the boolean values corresponding to the variables
            return evaluator(...values);
        } catch (error) {
            console.error("Evaluation Error:", error.message);
            return 'ERROR';
        }
    }

    /**
     * Extracts unique uppercase variables (A-Z) from the expression, sorted alphabetically.
     * @param {string} expression - User input string.
     * @returns {string[]} - Sorted array of unique variables.
     */
    function extractVariables(expression) {
        const matches = expression.match(/[A-Z]/g) || [];
        const uniqueVars = new Set(matches);
        return Array.from(uniqueVars).sort();
    }

    /**
     * Generates all 2^n combinations of boolean values.
     * @param {number} n - Number of variables.
     * @returns {boolean[][]} - Array of arrays, where inner arrays are combinations.
     */
    function generateCombinations(n) {
        const combinations = [];
        const numRows = 1 << n; // 2^n

        for (let i = 0; i < numRows; i++) {
            const row = [];
            for (let j = 0; j < n; j++) {
                // Determine the value for the j-th variable (from left to right)
                // Use bitwise shift to check the j-th bit
                const isTrue = ((i >> (n - 1 - j)) & 1) === 1;
                row.push(isTrue);
            }
            combinations.push(row);
        }
        return combinations;
    }


    /**
     * Handles form submission and triggers the truth table generation.
     */
    function handleTruthTableGeneration(e) {
        e.preventDefault();

        const expressionInput = document.getElementById('expression-input');
        const userExpression = expressionInput.value.trim();

        const variables = extractVariables(userExpression);
        const numVariables = variables.length;
        const maxVars = 10; // Increased capacity to 10 variables

        if (numVariables === 0) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Expression</p><p class="text-center">Please use at least one uppercase variable (A-Z).</p>`;
            displayResult(true, htmlContent);
            return;
        }

        if (numVariables > maxVars) {
            const numRows = 1 << numVariables;
            const htmlContent = `<p class="fw-bold text-center">Too Many Variables</p><p class="text-center">The expression has ${numVariables} variables, resulting in ${numRows} rows. The current limit is ${maxVars} variables (1024 rows) to prevent slowdowns. Please simplify your expression.</p>`;
            displayResult(true, htmlContent);
            return;
        }

        const combinations = generateCombinations(numVariables);
        let tableRowsHtml = '';
        let hasError = false;
        const numRows = 1 << numVariables;

        // Build Table Header
        let tableHeaderHtml = '<tr>';
        variables.forEach(v => {
            tableHeaderHtml += `<th class="col-var">${v}</th>`;
        });
        tableHeaderHtml += `<th class="col-result">${userExpression}</th></tr>`;


        // Build Table Body
        combinations.forEach(values => {
            const result = safeEvaluateLogic(userExpression, variables, values);

            let resultDisplay;
            let rowClass = '';

            if (result === 'ERROR') {
                resultDisplay = 'ERROR';
                rowClass = 'bg-danger-subtle'; // Bootstrap class for error row
                hasError = true;
            } else {
                resultDisplay = result ? 'T' : 'F';
            }

            let rowHtml = `<tr class="${rowClass}">`;

            // Add variable values (T/F)
            values.forEach(v => {
                rowHtml += `<td class="col-var">${v ? 'T' : 'F'}</td>`;
            });

            // Add final expression result
            rowHtml += `<td class="col-result">${resultDisplay}</td>`;
            rowHtml += '</tr>';

            tableRowsHtml += rowHtml;
        });

        if (hasError) {
             const htmlContent = `<p class="fw-bold text-center">Evaluation Error</p><p class="text-center">The expression appears to have a syntax error or unsupported structure. Please check parentheses and operators.</p>`;
            displayResult(true, htmlContent);
            return;
        }


        // Display the final table
        const outputHtml = `
            <h3 class="fs-5 fw-bold text-center text-dark mb-4">Truth Table ($2^{${numVariables}} = ${numRows}$ rows)</h3>
            <div class="table-container">
                <table class="truth-table table table-bordered table-striped mb-0">
                    <thead>
                        ${tableHeaderHtml}
                    </thead>
                    <tbody>
                        ${tableRowsHtml}
                    </tbody>
                </table>
            </div>
        `;

        displayResult(false, outputHtml);
    }

    // Attach handler to the form
    document.getElementById('truth-table-form').addEventListener('submit', handleTruthTableGeneration);

    // FIXED: Removed the window.onload auto-calculation.

