/**
     * Formats a vector (x, y, z) into a string.
     * @param {number} x - X component.
     * @param {number} y - Y component.
     * @param {number} z - Z component.
     * @returns {string} The formatted LaTeX string.
     */
    function formatVector(x, y, z) {
        // Round to 8 decimal places and remove trailing zeros for clean output
        const cleanNumber = (num) => parseFloat(num.toFixed(8)).toString();

        const x_f = cleanNumber(x);
        const y_f = cleanNumber(y);
        const z_f = cleanNumber(z);

        return `\\mathbf{(${x_f}, ${y_f}, ${z_f})}`;
    }

    /**
     * Generates an HTML card for a single result.
     */
    function createResultCard(title, resultValue, isVector = false) {
        let formattedValue;

        if (isVector) {
            // For Unit Vector result
            formattedValue = formatVector(resultValue[0], resultValue[1], resultValue[2]);
        } else {
            // Scalar result (Magnitude), format to 8 decimal places and clean trailing zeros
            formattedValue = parseFloat(resultValue.toFixed(8)).toString();
        }

        let html = `
            <div class="result-card">
                <p class="output-label">${title}</p>
                <div class="output-value">
                    $$${formattedValue}$$
                </div>
            </div>
        `;
        return html;
    }

    /**
     * Sets the result container back to the initial prompt state.
     */
    function resetOutput() {
        const outputDiv = document.getElementById('solution-output');
        outputDiv.className = 'p-4 border text-center text-muted rounded';
        outputDiv.innerHTML = 'Enter the vector components and click "Calculate Unit Vector".';
    }


    document.getElementById('vector-calculator-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Get inputs for Vector V
        const Vx = parseFloat(document.getElementById('vx-input').value.trim());
        const Vy = parseFloat(document.getElementById('vy-input').value.trim());
        const Vz = parseFloat(document.getElementById('vz-input').value.trim());

        const outputDiv = document.getElementById('solution-output');
        outputDiv.innerHTML = ''; 
        outputDiv.className = 'result-section'; // Reset class for grid layout

        // --- Input Validation ---
        if ([Vx, Vy, Vz].some(isNaN)) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter valid numerical values for all three vector components ($V_x, V_y, V_z$).</p>`;
            outputDiv.innerHTML = htmlContent;
            outputDiv.className = 'result-error'; 
            return;
        }

        // --- Core Calculations ---

        // 1. Magnitude $|\mathbf{V}| = \sqrt{V_x^2 + V_y^2 + V_z^2}$
        const magnitudeV = Math.sqrt((Vx * Vx) + (Vy * Vy) + (Vz * Vz));

        // Check for zero vector (division by zero)
        if (magnitudeV === 0) {
             const htmlContent = `<p class="fw-bold text-center">Zero Vector</p><p class="text-center">The magnitude is zero. A unit vector cannot be defined for the zero vector $\\mathbf{V} = (0, 0, 0)$.</p>`;
            outputDiv.innerHTML = htmlContent;
            outputDiv.className = 'result-error'; 
            return;
        }

        // 2. Unit Vector $\hat{\mathbf{u}} = \mathbf{V} / |\mathbf{V}|$
        const unitVx = Vx / magnitudeV;
        const unitVy = Vy / magnitudeV;
        const unitVz = Vz / magnitudeV;

        const unitVector = [unitVx, unitVy, unitVz];

        // --- Result Display ---

        // Change the result section to a 2-column grid layout for a clean look
        outputDiv.style.gridTemplateColumns = '1fr 1fr'; 

        let htmlContent = '';

        // 1. Magnitude Card
        htmlContent += createResultCard('Magnitude $|\mathbf{V}|$', magnitudeV);

        // 2. Unit Vector Card
        htmlContent += createResultCard('Unit Vector $\\hat{\\mathbf{u}}$', unitVector, true);

        outputDiv.innerHTML = htmlContent;
    });

    // Set initial state of output area
    resetOutput();

