        outputDiv.className = 'p-4 border text-center text-muted rounded';
        outputDiv.innerHTML = 'Enter the components of Vector A and Vector B and click "Calculate Products & Magnitudes".';
    }


    document.getElementById('vector-calculator-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Get inputs for Vector A
        const Ax = parseFloat(document.getElementById('ax-input').value.trim());
        const Ay = parseFloat(document.getElementById('ay-input').value.trim());
        const Az = parseFloat(document.getElementById('az-input').value.trim());

        // Get inputs for Vector B
        const Bx = parseFloat(document.getElementById('bx-input').value.trim());
        const By = parseFloat(document.getElementById('by-input').value.trim());
        const Bz = parseFloat(document.getElementById('bz-input').value.trim());

        const outputDiv = document.getElementById('solution-output');
        outputDiv.innerHTML = ''; 
        // Set class for grid layout
        outputDiv.className = 'result-section'; 

        // --- Input Validation ---
        if ([Ax, Ay, Az, Bx, By, Bz].some(isNaN)) {
            const htmlContent = `<p class="fw-bold text-center">Invalid Input</p><p class="text-center">Please enter valid numerical values for all six vector components.</p>`;
            outputDiv.innerHTML = htmlContent;
            outputDiv.className = 'result-error'; 
            return;
        }

        // --- Core Calculations ---

        // 1. Dot Product (Scalar)
        const dotProduct = (Ax * Bx) + (Ay * By) + (Az * Bz);

        // 2. Cross Product (Vector) $\mathbf{A} \times \mathbf{B}$
        // X component: $A_y B_z - A_z B_y$
        const crossX = (Ay * Bz) - (Az * By);
        // Y component: $A_z B_x - A_x B_z$
        const crossY = (Az * Bx) - (Ax * Bz);
        // Z component: $A_x B_y - A_y B_x$
        const crossZ = (Ax * By) - (Ay * Bx);
        const crossProduct = [crossX, crossY, crossZ];

        // 3. Magnitude of A (Scalar)
        const magnitudeA = Math.sqrt((Ax * Ax) + (Ay * Ay) + (Az * Az));

        // 4. Magnitude of B (Scalar)
        const magnitudeB = Math.sqrt((Bx * Bx) + (By * By) + (Bz * Bz));

        // --- Result Display ---
        let htmlContent = '';

        // 1. Dot Product Card
        htmlContent += createResultCard('Dot Product ($\\mathbf{A} \\cdot \\mathbf{B}$)', dotProduct);

        // 2. Cross Product Card
        htmlContent += createResultCard('Cross Product ($\\mathbf{A} \\times \\mathbf{B}$)', crossProduct, true);

        // 3. Magnitude A Card
        htmlContent += createResultCard('Magnitude $|\mathbf{A}|$', magnitudeA);

        // 4. Magnitude B Card
        htmlContent += createResultCard('Magnitude $|\mathbf{B}|$', magnitudeB);


        outputDiv.innerHTML = htmlContent;
    });

    // Set initial state of output area
    resetOutput();

