        const newRow = assetRowTemplate.content.cloneNode(true).querySelector('tr');

        newRow.querySelector('.asset-name').value = name;
        newRow.querySelector('.asset-value').value = value;
        newRow.querySelector('.asset-target-percent').value = targetPercent;

        newRow.querySelector('.remove-asset-btn').addEventListener('click', function() {
