            // Use parseInt since customers are discrete units
            const start_customers = parseInt(document.getElementById('start_customers').value);
            const lost_customers = parseInt(document.getElementById('lost_customers').value);

            // Check for NaN first
            if (isNaN(start_customers) || isNaN(lost_customers)) {
                displayError("Please enter valid numerical values for both customer counts.");
                return;
            }

            if (start_customers < 0 || lost_customers < 0) {
                displayError("Customer counts must be non-negative.");
                return;
            }

            if (lost_customers > start_customers) {
                displayError("The number of customers lost cannot exceed the number of customers at the start of the period.");
                return;
            }

            let churn_rate = 0;
            let resultMessage = null; // Used for warnings

            // Handle edge case: Division by zero
            if (start_customers === 0) {
                if (lost_customers > 0) {
                    displayError("Cannot calculate Churn Rate: If you started with 0 customers, you shouldn't have lost customers. Please check inputs.");
                    return;
                } else {
                    // 0/0 is 0% churn, but note that the metric is not meaningful.
                    resultMessage = "You had zero starting customers and zero lost customers. Churn is 0%, but the metric is not statistically meaningful for an inactive period.";
                    churn_rate = 0;
                }
            } else {
                // 2. Core Calculation
                // Churn Rate = (Lost Customers / Starting Customers) * 100
                churn_rate = (lost_customers / start_customers) * 100;
            }

            // 3. Update Summary Totals
            document.getElementById('churn_rate').textContent = churn_rate.toFixed(2) + '%';

            // 4. Show Results and Potential Warnings
            document.getElementById('churn-summary').classList.remove('d-none');

