    document.getElementById('cr-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs (Get values as strings first to check for emptiness)
            const assets_val = document.getElementById('current_assets').value;
            const liabilities_val = document.getElementById('current_liabilities').value;

            // Check if fields are empty
            if (!assets_val || !liabilities_val) {
                displayError("Please enter values for both Total Current Assets and Total Current Liabilities.");
                return;
            }

            // Parse inputs
            const current_assets = parseFloat(assets_val);
            const current_liabilities = parseFloat(liabilities_val);

            // Check for NaN after parsing
            if (isNaN(current_assets) || isNaN(current_liabilities)) {
                displayError("Please ensure both inputs are valid numbers.");
                return;
            }

            if (current_assets < 0 || current_liabilities < 0) {
                displayError("Assets and Liabilities must be non-negative values.");
                return;
            }

            let ratio = 0;

            // Handle edge case: Division by zero (zero liabilities)
            if (current_liabilities === 0) {
                if (current_assets > 0) {
                    // Infinite ratio. Treat as excellent but display a special message.
                    const infiniteMessage = "Current Liabilities are zero. The ratio is effectively infinite, indicating extremely high liquidity. Verify data, but this is financially excellent.";
                    document.getElementById('current_ratio').textContent = "∞ : 1";

                    // Show result summary and the special warning
                    document.getElementById('ratio-summary').classList.remove('d-none');
                    updateResultDisplay(100); // Use a very high number to trigger 'healthy' color
                    displayError(infiniteMessage, true); 
                    return;

                } else {
                    // 0/0. Ratio is 0.
                    ratio = 0;
                }
            } else {
                // 2. Core Calculation
                // Current Ratio = Current Assets / Current Liabilities
                ratio = current_assets / current_liabilities;
            }

            // 3. Update Summary Totals and Conditional Display
            const ratioText = ratio.toFixed(2) + ' : 1';
            document.getElementById('current_ratio').textContent = ratioText;
            updateResultDisplay(ratio);

            // 4. Show Results
            document.getElementById('ratio-summary').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation failed:", error);
            displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
        }
    });

