// Function to update the result card's color based on the DSO value
    // We use a hypothetical company credit term of 30 days for generic interpretation
    function updateResultDisplay(dso) {
        const card = document.getElementById('dso-result-card');
        const text = document.getElementById('dso_days');
        const credit_terms = 30; // Hypothethical industry standard / company terms

        // Reset classes
        card.classList.remove('border-low-dso', 'border-moderate-dso', 'border-high-dso');
        text.classList.remove('text-low-dso', 'text-moderate-dso', 'text-high-dso');

        // Handle N/A or special cases
        if (dso === 0 || isNaN(dso)) {
            card.classList.add('border-low-dso');
            text.classList.add('text-low-dso');
            return;
        }

        // Apply new classes based on comparison to credit terms
        if (dso <= credit_terms + 5) { // Collecting near or slightly over terms (Good)
            card.classList.add('border-low-dso');
            text.classList.add('text-low-dso');
        } else if (dso <= credit_terms * 1.5) { // Moderately slow (Acceptable/Warning)
            card.classList.add('border-moderate-dso');
            text.classList.add('text-moderate-dso');
        } else { // Very slow collection (High risk/Poor efficiency)
            card.classList.add('border-high-dso');
            text.classList.add('text-high-dso');
        }
    }

    // Function to display error messages (including warnings/N/A ratio)
    function displayError(message, isWarning = false) {
        const errorDiv = document.getElementById('error-message');
        errorDiv.classList.remove('d-none', 'alert-danger', 'alert-warning');

        if (isWarning) {
            errorDiv.classList.add('alert-warning');
            errorDiv.innerHTML = `<strong>Data Issue:</strong> ${message}`;
        } else {
            errorDiv.classList.add('alert-danger');
            errorDiv.innerHTML = `<strong>Error:</strong> ${message}`;
        }
        document.getElementById('dso-summary').classList.add('d-none');
    }

    // Function to clear errors
    function clearError() {
        document.getElementById('error-message').classList.add('d-none');
    }

    // --- Event Handler and Display Logic ---

    document.getElementById('dso-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs
            const sales_val = document.getElementById('net_credit_sales').value;
            const ar_val = document.getElementById('average_ar').value;
            const days_val = document.getElementById('days_in_period').value;

            // Check for empty fields
            if (!sales_val || !ar_val || !days_val) {
                displayError("All three input fields must be filled with numerical values.");
                return;
            }

            // Parse inputs
            const net_credit_sales = parseFloat(sales_val);
            const average_ar = parseFloat(ar_val);
            const days_in_period = parseInt(days_val, 10); 

            // Check for NaN after parsing
            if (isNaN(net_credit_sales) || isNaN(average_ar) || isNaN(days_in_period)) {
                displayError("Please ensure all inputs are valid numbers.");
                return;
            }

            if (net_credit_sales < 0 || average_ar < 0) {
                displayError("Sales and Accounts Receivable must be non-negative values.");
                return;
            }

            if (days_in_period <= 0) {
                displayError("The number of days in the period must be greater than zero.");
                return;
            }

            let dso_days = 0;

            // Handle edge case: Division by zero (zero credit sales)
            if (net_credit_sales === 0) {
                if (average_ar > 0) {
                    const warningMessage = "Net Credit Sales is zero, but Accounts Receivable is positive. This implies outstanding debt with no new credit sales. The DSO is not meaningful in this calculation.";
                    document.getElementById('dso_days').textContent = 'N/A';
                    updateResultDisplay(1000); // Use a high proxy value to trigger a 'high risk' display color
                    displayError(warningMessage, true);
                    document.getElementById('dso-summary').classList.remove('d-none');
                    return;
                } else {
                    // 0/0. If both are zero, collection is instantaneous.
                    dso_days = 0;
                }
            } else {
                // 2. Core Calculation
                dso_days = (average_ar / net_credit_sales) * days_in_period;
            }

            // 3. Update Summary Totals and Conditional Display
            const resultText = dso_days.toFixed(2) + ' Days';
            document.getElementById('dso_days').textContent = resultText;
            updateResultDisplay(dso_days);

            // 4. Show Results
            document.getElementById('dso-summary').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation failed:", error);
            displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
        }
    });

