    document.getElementById('gpm-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs
            const revenue = parseFloat(document.getElementById('revenue').value);
            const cogs = parseFloat(document.getElementById('cogs').value);

            if (isNaN(revenue) || isNaN(cogs)) {
                displayError("Please enter valid numerical values for Revenue and COGS.");
