                // Allow calculation to proceed to show the negative result
            }

            // 2. Core Calculations
            const gross_profit = revenue - cogs;

            let gross_margin = 0;

            // Formula: Gross Profit Margin = (Gross Profit / Revenue) * 100
            if (revenue > 0) {
                gross_margin = (gross_profit / revenue) * 100;
            }

            // 3. Update Summary Totals
            document.getElementById('gross_profit').textContent = formatter.format(gross_profit);
