// Function to update the result card's color based on the turnover value
    // NOTE: Industry benchmarks vary widely, so we use relative tiers for a generic interpretation.
    function updateResultDisplay(ratio) {
        const card = document.getElementById('itr-result-card');
        const text = document.getElementById('itr_ratio');

        // Reset classes
        card.classList.remove('border-high-turnover', 'border-moderate-turnover', 'border-low-turnover');
        text.classList.remove('text-high-turnover', 'text-moderate-turnover', 'text-low-turnover');

        // Handle special values (Infinite or Negative)
        if (ratio === Infinity) {
            card.classList.add('border-high-turnover');
            text.classList.add('text-high-turnover');
            return;
        } else if (ratio === 0) {
            card.classList.add('border-low-turnover');
            text.classList.add('text-low-turnover');
            return;
        }

        // Apply new classes based on relative tiers (generic interpretation)
        if (ratio >= 5.0) { // High turnover (Efficient/Strong Sales)
            card.classList.add('border-high-turnover');
            text.classList.add('text-high-turnover');
        } else if (ratio >= 2.0) { // Moderate turnover (Acceptable)
            card.classList.add('border-moderate-turnover');
            text.classList.add('text-moderate-turnover');
        } else { // Low turnover (Potential holding costs/obsolescence)
            card.classList.add('border-low-turnover');
            text.classList.add('text-low-turnover');
        }
    }

    // Function to display error messages (including warnings/infinite ratio)
    function displayError(message, isWarning = false) {
        const errorDiv = document.getElementById('error-message');
        errorDiv.classList.remove('d-none', 'alert-danger', 'alert-warning');

        if (isWarning) {
            errorDiv.classList.add('alert-warning');
            errorDiv.innerHTML = `<strong>Extreme Ratio:</strong> ${message}`;
        } else {
            errorDiv.classList.add('alert-danger');
            errorDiv.innerHTML = `<strong>Error:</strong> ${message}`;
        }
        document.getElementById('itr-summary').classList.add('d-none');
    }

    // Function to clear errors
    function clearError() {
        document.getElementById('error-message').classList.add('d-none');
    }

    // --- Event Handler and Display Logic ---

    document.getElementById('itr-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs (Get values as strings first to check for emptiness)
            const cogs_val = document.getElementById('cogs').value;
            const begin_inv_val = document.getElementById('beginning_inventory').value;
            const end_inv_val = document.getElementById('ending_inventory').value;

            // Check for empty fields
            if (!cogs_val || !begin_inv_val || !end_inv_val) {
                displayError("All three input fields must be filled with numerical values.");
                return;
            }

            // Parse inputs
            const cogs = parseFloat(cogs_val);
            const beginning_inventory = parseFloat(begin_inv_val);
            const ending_inventory = parseFloat(end_inv_val);

            // Check for NaN after parsing
            if (isNaN(cogs) || isNaN(beginning_inventory) || isNaN(ending_inventory)) {
                displayError("Please ensure all inputs are valid numbers.");
                return;
            }

            if (cogs < 0 || beginning_inventory < 0 || ending_inventory < 0) {
                displayError("All input values must be non-negative.");
                return;
            }

            // 2. Calculate Average Inventory
            const average_inventory = (beginning_inventory + ending_inventory) / 2;

            let turnover_ratio = 0;

            // Handle edge case: Division by zero (zero average inventory)
            if (average_inventory === 0) {
                if (cogs > 0) {
                    turnover_ratio = Infinity;
                    const infiniteMessage = "Average Inventory is zero, resulting in an infinitely high ratio. This suggests verification of input data is needed.";

                    // Display special warning for infinite ratio
                    document.getElementById('itr_ratio').textContent = 'Infinite (∞) Times';
                    updateResultDisplay(turnover_ratio); // This handles the color coding
                    displayError(infiniteMessage, true); 
                    document.getElementById('itr-summary').classList.remove('d-none');
                    return;

                } else {
                    // 0/0. Use 0.
                    turnover_ratio = 0;
                }
            } else {
                // 3. Core Calculation
                turnover_ratio = cogs / average_inventory;
            }

            // 4. Update Summary Totals and Conditional Display
            const ratioText = turnover_ratio.toFixed(2) + ' Times';
            document.getElementById('itr_ratio').textContent = ratioText;
            updateResultDisplay(turnover_ratio);

            // 5. Show Results
            document.getElementById('itr-summary').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation failed:", error);
            displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
        }
    });

