        clearError();

        try {
            // 1. Get and Validate Inputs
            const revenue = parseFloat(document.getElementById('revenue').value);
            const expenses = parseFloat(document.getElementById('expenses').value);

            if (isNaN(revenue) || isNaN(expenses)) {
                displayError("Please enter valid numerical values for Revenue and Total Expenses.");
                return;
            }

            if (revenue < 0 || expenses < 0) {
                displayError("Revenue and Total Expenses must be non-negative values (zero or greater).");
                return;
            }

            // 2. Core Calculations
            const net_profit = revenue - expenses;

            let net_margin = 0;

            // Avoid division by zero
            if (revenue > 0) {
                net_margin = (net_profit / revenue) * 100; // Result in percentage
            }

            // 3. Update Summary Totals and Conditional Styling

            document.getElementById('net_profit').textContent = formatter.format(net_profit);

