// Function to display error messages
    function displayError(message) {
        const errorDiv = document.getElementById('error-message');
        errorDiv.classList.remove('d-none', 'alert-success', 'alert-info', 'alert-warning');
        errorDiv.classList.add('alert-danger');
        errorDiv.innerHTML = `<strong><i class="bi bi-exclamation-triangle-fill me-2"></i> Error:</strong> ${message}`;
        document.getElementById('rebalance-summary').classList.add('d-none');
    }

    // Function to clear errors
    function clearError() {
        document.getElementById('error-message').classList.add('d-none');
    }

    // Helper function for formatting currency
    const currencyFormatter = (value) => {
        const formatter = new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
        });
        return formatter.format(value);
    };

    // --- Dynamic Asset Row Management ---

    const assetInputBody = document.getElementById('asset-input-body');
    const assetRowTemplate = document.getElementById('asset-row-template');
    const addAssetBtn = document.getElementById('add-asset-btn');

    // Add asset row function
    function addAssetRow(name = '', value = '', targetPercent = '') {
        const newRow = assetRowTemplate.content.cloneNode(true).querySelector('tr');

        newRow.querySelector('.asset-name').value = name;
        newRow.querySelector('.asset-value').value = value;
        newRow.querySelector('.asset-target-percent').value = targetPercent;

        newRow.querySelector('.remove-asset-btn').addEventListener('click', function() {
            if (assetInputBody.querySelectorAll('.asset-row').length > 1) {
                newRow.remove();
                clearError();
            } else {
                displayError("You must have at least one asset in the portfolio.");
            }
        });

        assetInputBody.appendChild(newRow);
    }

    // Default asset rows for initial load
    addAssetRow('US Large Cap Stocks', 65000, 60);
    addAssetRow('International Bonds', 25000, 30);
    addAssetRow('Real Estate (REITs)', 10000, 10);


    addAssetBtn.addEventListener('click', () => addAssetRow());

    // --- Calculation Logic ---

    document.getElementById('rebalancing-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Gather and Validate Inputs
            const assetRows = assetInputBody.querySelectorAll('.asset-row');
            const portfolioData = [];
            let totalPortfolioValue = 0;
            let totalTargetPercent = 0;

            if (assetRows.length === 0) {
                displayError("Please add at least one asset to calculate rebalancing.");
                return;
            }

            assetRows.forEach((row, index) => {
                const name = row.querySelector('.asset-name').value.trim();
                const valueInput = row.querySelector('.asset-value').value;
                const targetPercentInput = row.querySelector('.asset-target-percent').value;

                // Simple check for required fields before parsing
                if (!name || valueInput === "" || targetPercentInput === "") {
                    displayError(`Asset ${index + 1} has missing data.`);
                    throw new Error("Missing input data");
                }

                const value = parseFloat(valueInput);
                const targetPercent = parseFloat(targetPercentInput);

                if (isNaN(value) || value < 0) {
                    displayError(`Current Value for "${name}" must be a non-negative number.`);
                    throw new Error("Invalid asset value");
                }

                if (isNaN(targetPercent) || targetPercent < 0 || targetPercent > 100) {
                    displayError(`Target % for "${name}" must be a number between 0 and 100.`);
                    throw new Error("Invalid target percent");
                }

                totalPortfolioValue += value;
                totalTargetPercent += targetPercent;

                portfolioData.push({ name, value, targetPercent });
            });

            // Final validation: Total Target Percentage must be 100%
            if (Math.abs(totalTargetPercent - 100) > 0.001) { // Use tolerance for float comparison
                displayError(`Total Target Percentage must equal 100%. Current total: ${totalTargetPercent.toFixed(2)}%`);
                return;
            }

            if (totalPortfolioValue <= 0) {
                displayError("Total portfolio value must be greater than zero.");
                return;
            }

            // 2. Core Calculation and Results Formatting
            const resultsBody = document.getElementById('rebalance-results-body');
            resultsBody.innerHTML = ''; // Clear previous results

            let currentPercentTotalCheck = 0; 

            portfolioData.forEach(asset => {
                // Calculate current allocation
                const currentPercent = (asset.value / totalPortfolioValue) * 100;
                currentPercentTotalCheck += currentPercent;

                // Calculate target value and rebalance amount
                // Target Value = Total Portfolio Value * (Target Percent / 100)
                const targetValue = totalPortfolioValue * (asset.targetPercent / 100);

                // Rebalance Amount (Buy if positive, Sell if negative)
                const rebalanceAmount = targetValue - asset.value;

                // Create the result row
                const resultRow = document.createElement('tr');
                resultRow.className = 'result-row';

                let rebalanceText = '<i class="bi bi-dash"></i> No Change';
                let rebalanceClass = 'rebalance-no-change';

                if (Math.abs(rebalanceAmount) > 0.01) { // Apply a small tolerance for display
                    if (rebalanceAmount > 0) {
                        rebalanceText = `<i class="bi bi-cart-plus-fill me-1"></i> BUY ${currencyFormatter(rebalanceAmount)}`;
                        rebalanceClass = 'rebalance-buy';
                    } else {
                        rebalanceText = `<i class="bi bi-cart-x-fill me-1"></i> SELL ${currencyFormatter(Math.abs(rebalanceAmount))}`;
                        rebalanceClass = 'rebalance-sell';
                    }
                }

                // We use the full class name in the innerHTML to style the final column
                resultRow.innerHTML = `
                    <td>${asset.name}</td>
                    <td class="text-center">${currentPercent.toFixed(2)}%</td>
                    <td class="text-center">${asset.targetPercent.toFixed(2)}%</td>
                    <td class="${rebalanceClass}">${rebalanceText}</td>
                `;
                resultsBody.appendChild(resultRow);
            });

            // 3. Update Summary Totals and Display

            document.getElementById('total_portfolio_value').textContent = currencyFormatter(totalPortfolioValue);
            document.getElementById('current_percent_total').textContent = `${currentPercentTotalCheck.toFixed(2)}%`;
            document.getElementById('target_percent_total').textContent = `${totalTargetPercent.toFixed(2)}%`;

            // Rebalancing is a zero-sum game, net transaction is $0.00

            document.getElementById('rebalance-summary').classList.remove('d-none');

        } catch (error) {
            // Catch and display generic error if not a validation error
            if (error.message && !error.message.includes("Missing") && !error.message.includes("Invalid") && !error.message.includes("must")) {
                console.error("Calculation failed:", error);
                displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
            }
        }
    });

