// Function to update the result card's color based on the ratio value
    function updateResultDisplay(ratio) {
        const card = document.getElementById('qr-result-card');
        const text = document.getElementById('quick_ratio');

        // Reset classes
        card.classList.remove('border-healthy', 'border-risky');
        text.classList.remove('text-healthy', 'text-risky', 'text-neutral');

        // Apply new classes based on ratio
        if (ratio >= 1.0) {
            card.classList.add('border-healthy');
            text.classList.add('text-healthy');
        } else if (ratio < 1.0) {
            card.classList.add('border-risky');
            text.classList.add('text-risky');
        } else {
             // Should only happen if ratio is NaN or special value, fall back to danger
            card.classList.add('border-danger');
            text.classList.add('text-danger');
        }
    }

    // Function to display error messages (including warnings/infinite ratio)
    function displayError(message, isWarning = false) {
        const errorDiv = document.getElementById('error-message');
        errorDiv.classList.remove('d-none', 'alert-danger', 'alert-warning');

        if (isWarning) {
            errorDiv.classList.add('alert-warning');
            errorDiv.innerHTML = `<strong>Warning:</strong> ${message}`;
        } else {
            errorDiv.classList.add('alert-danger');
            errorDiv.innerHTML = `<strong>Error:</strong> ${message}`;
        }
        document.getElementById('ratio-summary').classList.add('d-none');
    }

    // Function to clear errors
    function clearError() {
        document.getElementById('error-message').classList.add('d-none');
    }

    // --- Event Handler and Display Logic ---

    document.getElementById('qr-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs (Get values as strings first to check for emptiness)
            const ca_val = document.getElementById('current_assets').value;
            const inv_val = document.getElementById('inventory').value;
            const pp_val = document.getElementById('prepaid_expenses').value;
            const cl_val = document.getElementById('current_liabilities').value;

            // Check if fields are empty
            if (!ca_val || !inv_val || !pp_val || !cl_val) {
                displayError("All four financial input fields must be filled with numerical values.");
                return;
            }

            // Parse inputs
            const current_assets = parseFloat(ca_val);
            const inventory = parseFloat(inv_val);
            const prepaid_expenses = parseFloat(pp_val);
            const current_liabilities = parseFloat(cl_val);

            // Check for NaN after parsing
            if (isNaN(current_assets) || isNaN(inventory) || isNaN(prepaid_expenses) || isNaN(current_liabilities)) {
                displayError("Please ensure all inputs are valid numbers.");
                return;
            }

            if (current_assets < 0 || inventory < 0 || prepaid_expenses < 0 || current_liabilities < 0) {
                displayError("All assets and liabilities must be non-negative values.");
                return;
            }

            // Calculate Quick Assets (Current Assets - Inventory - Prepaid Expenses)
            const quick_assets = current_assets - inventory - prepaid_expenses;

            if (quick_assets < 0) {
                displayError("The sum of Inventory and Prepaid Expenses cannot exceed Total Current Assets, resulting in a negative Quick Assets value.");
                return;
            }

            let ratio = 0;

            // Handle edge case: Division by zero (zero liabilities)
            if (current_liabilities === 0) {
                if (quick_assets > 0) {
                    const infiniteMessage = "Current Liabilities are zero. The Quick Ratio is effectively infinite, indicating extremely high immediate liquidity. Verify data.";
                    document.getElementById('quick_ratio').textContent = "∞ : 1";

                    // Show result summary and the special warning
                    document.getElementById('ratio-summary').classList.remove('d-none');
                    updateResultDisplay(100); // Use a very high number to trigger 'healthy' color
                    displayError(infiniteMessage, true); 
                    return;
                } else {
                    // 0/0. Ratio is 0.
                    ratio = 0;
                }
            } else {
                // 2. Core Calculation
                // Quick Ratio = Quick Assets / Current Liabilities
                ratio = quick_assets / current_liabilities;
            }

            // 3. Update Summary Totals and Conditional Display
            const ratioText = ratio.toFixed(2) + ' : 1';
            document.getElementById('quick_ratio').textContent = ratioText;
            updateResultDisplay(ratio);

            // 4. Show Results
            document.getElementById('ratio-summary').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation failed:", error);
            displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
        }
    });

