// Full Retirement Age (FRA) is fixed at 67 for simplicity in this calculator.
    const FRA = 67;

    // Function to display error messages
    function displayError(message) {
        const errorDiv = document.getElementById('error-message');
        errorDiv.classList.remove('d-none', 'alert-success', 'alert-info', 'alert-warning');
        errorDiv.classList.add('alert-danger');
        errorDiv.innerHTML = `<strong><i class="bi bi-exclamation-triangle-fill me-2"></i> Error:</strong> ${message}`;
        document.getElementById('ssb-summary').classList.add('d-none');
    }

    // Function to clear errors
    function clearError() {
        document.getElementById('error-message').classList.add('d-none');
    }

    // Helper function for formatting currency
    const currencyFormatter = (value) => {
        const formatter = new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
        });
        return formatter.format(Math.max(0, value));
    };

    // --- Core Calculation Logic ---

    /**
     * Calculates the benefit multiplier based on claiming age relative to FRA (67).
     * @param {number} claimingAge - The age the user starts collecting.
     * @returns {number} The multiplier applied to the PIA.
     */
    function calculateBenefitMultiplier(claimingAge) {
        if (claimingAge === FRA) {
            return 1.0;
        }

        const monthsDifference = (claimingAge - FRA) * 12;

        if (monthsDifference > 0) {
            // Delayed Retirement Credit (DRC) - 8% per year (2/3 of 1% per month)
            // 8% per year = 0.08 / 12 = 0.006666... per month
            const drcRate = 0.08 / 12;
            return 1.0 + (monthsDifference * drcRate);
        } else {
            // Early Retirement Penalty
            const reductionMonths = Math.abs(monthsDifference);
            let totalReduction = 0;

            // First 36 months: 5/9 of 1% per month
            const months1 = Math.min(reductionMonths, 36);
            totalReduction += months1 * (5 / 9) * 0.01;

            // Remaining months (over 36): 5/12 of 1% per month
            const months2 = Math.max(0, reductionMonths - 36);
            totalReduction += months2 * (5 / 12) * 0.01;

            return 1.0 - totalReduction;
        }
    }

    /**
     * Projects the total lifetime benefits, applying COLA annually.
     * This uses a simple sum of the annuity for the total benefit.
     * @param {number} initialAnnualBenefit - The benefit in the first year of claiming.
     * @param {number} years - The total projection period (lifespan).
     * @param {number} cola - The annual COLA rate (decimal).
     * @returns {number} The sum of all annual benefits received.
     */
    function calculateTotalBenefits(initialAnnualBenefit, years, cola) {
        let totalBenefits = 0;
        let annualBenefit = initialAnnualBenefit;

        for (let y = 1; y <= years; y++) {
            totalBenefits += annualBenefit;
            // Apply COLA for the next year
            annualBenefit *= (1 + cola);
        }
        return totalBenefits;
    }


    // --- Event Handler and Display Logic ---

    document.getElementById('ssb-form').addEventListener('submit', function (e) {
        e.preventDefault();
        clearError();

        try {
            // 1. Get and Validate Inputs
            // Use || 0 to safely parse empty fields as 0, although required ensures they are filled.
            const PIA = parseFloat(document.getElementById('fra_benefit').value || 0); // Monthly FRA benefit
            const claimingAge = parseInt(document.getElementById('claiming_age').value);
            const lifespanYears = parseInt(document.getElementById('lifespan_years').value);
            const colaRatePct = parseFloat(document.getElementById('cola_rate').value);


            if (isNaN(PIA) || isNaN(claimingAge) || isNaN(lifespanYears) || isNaN(colaRatePct)) {
                displayError("All input fields must be filled with valid numbers.");
                return;
            }

            if (PIA <= 0 || lifespanYears <= 0) {
                displayError("The PIA and Lifespan must be positive values.");
                return;
            }

            if (claimingAge < 62 || claimingAge > 70) {
                displayError("The Claiming Age must be between 62 and 70.");
                return;
            }

            // 2. Prepare Variables
            const colaDecimal = colaRatePct / 100;

            // 3. Core Calculations

            // Calculate the multiplier based on claiming age
            const multiplier = calculateBenefitMultiplier(claimingAge);

            // Initial Monthly Benefit in Year 1 of claiming
            const initialMonthlyBenefit = PIA * multiplier;

            // Initial Annual Benefit for the Lifetime Calculation
            const initialAnnualBenefit = initialMonthlyBenefit * 12;

            // Total Projected Benefits (adjusted for COLA over the lifespan)
            const totalLifetimeBenefits = calculateTotalBenefits(initialAnnualBenefit, lifespanYears, colaDecimal);


            // 4. Update Summary Totals

            document.getElementById('initial_monthly_benefit').textContent = currencyFormatter(initialMonthlyBenefit);
            document.getElementById('total_lifetime_benefits').textContent = currencyFormatter(totalLifetimeBenefits);
            document.getElementById('multiplier_display').textContent = (multiplier * 100).toFixed(2) + '% of FRA Benefit';

            // 5. Show Results
            document.getElementById('ssb-summary').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation failed:", error);
            displayError("An unexpected error occurred during calculation. Please ensure all input values are valid.");
        }
    });

