            let tableRows = `
            <tr><td>Total Volume Required</td><td>**${metrics.finalVolumeYards.toFixed(3)} yd³**</td></tr>
            <tr><td>Total Volume (Cubic Feet)</td><td>${(metrics.finalVolumeYards * CUBIC_FEET_PER_CUBIC_YARD).toFixed(3)} ft³</td></tr>
            <tr><td>Theoretical Minimum Volume (No Waste)</td><td>${metrics.theoreticalVolumeYards.toFixed(3)} yd³</td></tr>
            <tr><td>Waste/Compaction Applied</td><td>${metrics.wastePercentage}%</td></tr>
            <tr><td colspan="2" class="text-center table-active">**Input Summary**</td></tr>
            <tr><td>Slab Diameter (D)</td><td>${metrics.slabDiameter} ft</td></tr>
            <tr><td>Slab Depth (H)</td><td>${metrics.slabDepth} in</td></tr>
            <tr><td>Material Type</td><td>${metrics.materialType.charAt(0).toUpperCase() + metrics.materialType.slice(1)}</td></tr>
            `;

            tableBody.innerHTML = tableRows;
            table.classList.remove('d-none');
            tableTitle.classList.remove('d-none');
        }
    }

    // Main Calculation Logic
    document.getElementById('circular-slab-calculator-form').addEventListener('submit', function (e) {
        e.preventDefault();

        const form = e.target;

        // Input values
        const slabDiameter = parseFloat(form.elements.slabDiameter.value); // D (ft)
        const slabDepth = parseFloat(form.elements.slabDepth.value); // H (in)
        const materialType = form.elements.materialType.value;
        const wastePercentage = parseFloat(form.elements.wastePercentage.value);

        // Basic validation
        if (isNaN(slabDiameter) || slabDiameter <= 0 || isNaN(slabDepth) || slabDepth <= 0 || isNaN(wastePercentage) || wastePercentage < 0 || wastePercentage > 50) {
            displayResult(true, "Please ensure Diameter, Depth, and Waste Percentage are valid positive numbers.");
            return;
        }

        try {
            // --- 1. Calculate Theoretical Volume (V = pi * r^2 * h) ---

            // Radius in feet
            const radiusFt = slabDiameter / 2;

            // Height (Depth) in feet
            const depthFt = slabDepth / INCHES_PER_FOOT;

            // Theoretical Volume in Cubic Feet
            const theoreticalVolumeCuFt = Math.PI * Math.pow(radiusFt, 2) * depthFt;

            // Theoretical Volume in Cubic Yards
            const theoreticalVolumeYards = theoreticalVolumeCuFt / CUBIC_FEET_PER_CUBIC_YARD;

            // --- 2. Apply Waste/Compaction Factor ---
            const wasteFactor = 1 + (wastePercentage / 100);
            const finalVolumeYards = theoreticalVolumeYards * wasteFactor;

            if (finalVolumeYards <= 0) {
                displayResult(true, "Calculated volume is zero or negative. Check inputs.");
                return;
            }

            // 3. Display results
            const metrics = {
                slabDiameter,
                slabDepth,
                materialType,
                wastePercentage,
                theoreticalVolumeYards,
                finalVolumeYards
            };
            displayResult(false, "", metrics);

        } catch (error) {
            console.error("Calculation Error:", error);
            displayResult(true, "An unexpected error occurred during the calculation.");
        }
    });

