document.getElementById('drywall-form').addEventListener('submit', function (e) {
        e.preventDefault();

        const L = parseFloat(this.elements.length.value);
        const W = parseFloat(this.elements.width.value);
        const H = parseFloat(this.elements.height.value);
        const sub = parseFloat(this.elements.subtractArea.value) || 0;
        const sheetArea = parseFloat(this.querySelector('input[name="sheetSize"]:checked').value);
        const surface = this.querySelector('input[name="surface"]:checked').value;

        const resPanel = document.getElementById('results-panel');
        const errAlert = document.getElementById('error-alert');

        if (L > 0 && W > 0 && H > 0) {
            let totalArea = 0;
            const wallArea = (2 * (L + W)) * H;
            const ceilingArea = L * W;

            if (surface === 'walls') totalArea = wallArea;
            else if (surface === 'ceiling') totalArea = ceilingArea;
            else totalArea = wallArea + ceilingArea;

            const netArea = Math.max(0, totalArea - sub);
            const areaWithWaste = netArea * 1.10;
            const sheetsNeeded = Math.ceil(areaWithWaste / sheetArea);

            // Update UI
            document.getElementById('res-sheets').innerText = sheetsNeeded;
            document.getElementById('res-area').innerText = netArea.toLocaleString(undefined, {maximumFractionDigits: 1});
            document.getElementById('res-label').innerText = sheetsNeeded === 1 ? "Sheet" : "Sheets";

            resPanel.style.display = 'block';
            errAlert.classList.add('d-none');
            resPanel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else {
            resPanel.style.display = 'none';
            errAlert.classList.remove('d-none');
        }
    });

