</p>
`;

            // Populate and show the detailed table
            let tableRows = `
            <tr><td>**Total Required Lumens**</td><td>**${numFormatter.format(metrics.requiredLumens)}**</td></tr>
            <tr><td>Room Area (A)</td><td>${metrics.area.toFixed(1)} sq ft</td></tr>
