            const slopeDegrees = angleRadians * RADIANS_TO_DEGREES;

            // 3. Calculate Slope Ratio (1:X)
            // X = Run / Rise
            const slopeRatioRun = run / rise;

            // 4. Display results
            const metrics = {
                rise,
                run,
                gradePercent,
                slopeDegrees,
                slopeRatioRun
            };
            displayResult(false, "", metrics);

        } catch (error) {
            console.error("Calculation Error:", error);
            displayResult(true, "An unexpected error occurred during the calculation.");
        }
    });

    // Run once on load to ensure initial hidden state
    window.onload = function() {
        document.getElementById('slope-result').classList.add('d-none');
        document.getElementById('slope-table').classList.add('d-none');
        document.getElementById('table-title').classList.add('d-none');
    };

