conversion_calculator__acceleration_conv:
// --- CONSTANTS (Relative to m/s²) ---
    const G_TO_MS2_FACTOR = 9.80665; // 1 g = 9.80665 m/s²
    const FTS2_TO_MS2_FACTOR = 0.3048; // 1 ft/s² = 0.3048 m/s²

    // --- Inverse Factors for ease of use ---
    const MS2_TO_FTS2_FACTOR = 1 / FTS2_TO_MS2_FACTOR; // 1 m/s² ≈ 3.28084 ft/s²
    const MS2_TO_G_FACTOR = 1 / G_TO_MS2_FACTOR; // 1 m/s² ≈ 0.10197 g

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the acceleration value from the input unit to all other units.
     */
    function convertAcceleration() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let ms2 = 0; // Base unit: Meters per Second Squared

        // Step 1: Normalize input to MS2
        if (inputUnit === 'MS2') {
            ms2 = value;
        } else if (inputUnit === 'FTS2') {
            // ft/s² to m/s²
            ms2 = value * FTS2_TO_MS2_FACTOR;
        } else if (inputUnit === 'G') {
            // g to m/s²
            ms2 = value * G_TO_MS2_FACTOR;
        }

        // Step 2: Convert normalized MS2 to all target units
        const ft_s2 = ms2 * MS2_TO_FTS2_FACTOR; // m/s² to ft/s²
        const g_force = ms2 * MS2_TO_G_FACTOR; // m/s² to g

        // --- Render Results ---

        const units = [
            { id: 'MS2', name: 'Meters per Second Squared (SI)', symbol: 'm/s²', value: ms2 },
            { id: 'FTS2', name: 'Feet per Second Squared (Imperial)', symbol: 'ft/s²', value: ft_s2 },
            { id: 'G', name: 'Standard Gravity', symbol: 'g', value: g_force }
        ];

        // 1. Render converted values first
        units.filter(u => u.id !== inputUnit).forEach(unit => {
