// --- CONSTANTS ---
    const CONVERSION_FACTOR = 18.0;

    // --- DOM Elements ---
    const calculationMode = document.getElementById('calculationMode');
    const mgdlInputGroup = document.getElementById('mgdlInputGroup');
    const mmolInputGroup = document.getElementById('mmolInputGroup');

    const mgdlValue = document.getElementById('mgdlValue');
    const mmolValue = document.getElementById('mmolValue');
    const resultsList = document.getElementById('resultsList');

    /**
     * Toggles visibility of input groups based on the selected calculation mode.
     */
    function toggleInputs() {
        const mode = calculationMode.value;

        // Reset visibility
        mgdlInputGroup.classList.add('hidden-input');
        mmolInputGroup.classList.add('hidden-input');

        if (mode === 'mgdl') {
            mgdlInputGroup.classList.remove('hidden-input');
        } else if (mode === 'mmol') {
            mmolInputGroup.classList.remove('hidden-input');
        }

        calculateConversion(); // Recalculate immediately
    }

    /**
     * Converts mg/dL to mmol/L.
     * @param {number} mgdl - Value in mg/dL.
     * @returns {number} Value in mmol/L.
     */
    function mgdlToMmol(mgdl) {
        return mgdl / CONVERSION_FACTOR;
    }

    /**
     * Converts mmol/L to mg/dL.
     * @param {number} mmol - Value in mmol/L.
     * @returns {number} Value in mg/dL.
     */
    function mmolToMgdl(mmol) {
        return mmol * CONVERSION_FACTOR;
    }

    /**
     * Renders a single result item.
     */
    function renderResult(name, value, unit, isMainResult) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');

        let borderColor = isMainResult ? '#e91e63' : '#f06292';
        let backgroundColor = isMainResult ? '#e91e63' : '#fce4ec';
        let valueColor = isMainResult ? 'white' : '#c2185b';
        let nameColor = isMainResult ? 'white' : '#455a64';
        let unitColor = isMainResult ? '#ffcdd2' : '#c2185b';

        item.style.borderLeftColor = borderColor;

        let displayValue = (unit === 'mg/dL') ? value.toFixed(0) : value.toFixed(2);

        item.innerHTML = `
            <div class="unit-name" style="color: ${nameColor};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor};">
                ${displayValue} <span style="font-size: 0.7em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    /**
     * Performs the main calculation based on the selected mode.
     */
    function calculateConversion() {
        resultsList.innerHTML = '';
        const mode = calculationMode.value;
        let errors = [];

        if (mode === 'mgdl') {
            // --- Mode 1: mg/dL to mmol/L ---
            const mgdl = parseFloat(mgdlValue.value);

            if (isNaN(mgdl) || mgdl < 0) errors.push("Please enter a valid, non-negative value in mg/dL.");

            if (errors.length === 0) {
                const mmol = mgdlToMmol(mgdl);

                renderResult('Input Value', mgdl, 'mg/dL', false);
                renderResult('Converted Value', mmol, 'mmol/L', true);
            }
        } else if (mode === 'mmol') {
            // --- Mode 2: mmol/L to mg/dL ---
            const mmol = parseFloat(mmolValue.value);

            if (isNaN(mmol) || mmol < 0) errors.push("Please enter a valid, non-negative value in mmol/L.");

            if (errors.length === 0) {
                const mgdl = mmolToMgdl(mmol);

                renderResult('Input Value', mmol, 'mmol/L', false);
                renderResult('Converted Value', mgdl, 'mg/dL', true);
            }
        }

        if (errors.length > 0) {
            resultsList.innerHTML = errors.map(err => `<div class="alert alert-danger">${err}</div>`).join('');
        }
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Attach listeners to all relevant inputs
        document.querySelectorAll('#mgdlValue, #mmolValue, #calculationMode').forEach(input => {
            input.addEventListener('input', calculateConversion);
            input.addEventListener('change', calculateConversion); 
        });

        // Initial setup
        toggleInputs(); 
    }

    window.onload = function() {
        setupListeners();
    };

