// --- GRADE 1 ENGLISH BRAILLE MAP (UNICODE) ---
    // Key: Standard English character
    // Value: Unicode Braille Pattern character (U+2800 + pattern index)
    const BRAILLE_MAP = {
        // Lowercase Letters a-z (Grade 1)
        'a': '⠁', 'b': '⠃', 'c': '⠉', 'd': '⠙', 'e': '⠑', 'f': '⠋', 
        'g': '⠛', 'h': '⠓', 'i': '⠊', 'j': '⠚', 'k': '⠅', 'l': '⠇', 
        'm': '⠍', 'n': '⠝', 'o': '⠕', 'p': '⠏', 'q': '⠟', 'r': '⠗', 
        's': '⠎', 't': '⠞', 'u': '⠥', 'v': '⠧', 'w': '⠺', 'x': '⠭', 
        'y': '⠽', 'z': '⠵',

        // Numbers 0-9 (using the Number Sign ⠼)
        // Standard Braille uses the same patterns as a-j but requires the preceding Number Sign.
        '1': '⠼⠁', '2': '⠼⠃', '3': '⠼⠉', '4': '⠼⠙', '5': '⠼⠑', 
        '6': '⠼⠋', '7': '⠼⠛', '8': '⠼⠓', '9': '⠼⠊', '0': '⠼⠚',

        // Punctuation and Special
        ' ': ' ',      // Space
        '.': '⠲',      // Period
        ',': '⠂',      // Comma
        '?': '⠢',      // Question Mark
        '!': '⠖',      // Exclamation Mark
        '"': '⠶',      // Quotation Mark
        ':': '⠒',      // Colon
        ';': '⠆',      // Semicolon
        '-': '⠤',      // Hyphen/Dash
        '(': '⠣',      // Open Parenthesis
        ')': '⠜',      // Close Parenthesis
        'CAP_SIGN': '⠠', // Capital Sign (precedes a single capitalized letter)
    };

    // Reverse map for Braille to Text conversion
    // We reverse the map, excluding the number sign sequence for simplicity in reverse mapping, 
    // and handle the Capital Sign (CAP_SIGN) logic separately.
    const TEXT_CODE_MAP = {};
    for (const [key, value] of Object.entries(BRAILLE_MAP)) {
        if (key.length === 1 || key === 'CAP_SIGN') {
            TEXT_CODE_MAP[value] = key;
        }
    }

    // Add numbers to reverse map (Braille patterns without the Number Sign)
    // This is necessary because in reverse, we need to handle the two-character sequence.
    const REVERSE_NUM_MAP = {
        '⠁': '1', '⠃': '2', '⠉': '3', '⠙': '4', '⠑': '5',
        '⠋': '6', '⠛': '7', '⠓': '8', '⠊': '9', '⠚': '0',
    };

    // Braille Number Sign
    const NUM_SIGN = '⠼';
    const CAP_SIGN = '⠠';


    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const directionSelect = document.getElementById('directionSelect');
    const convertButton = document.getElementById('convertButton');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts English Text to Grade 1 Braille.
     * @param {string} text - The input English text.
     * @returns {string} The resulting Braille string.
     */
    function textToBraille(text) {
        let braille = '';
        const normalizedText = text.trim();

        for (let i = 0; i < normalizedText.length; i++) {
            let char = normalizedText[i];

            if (char === '\n') {
                braille += '\n'; // Preserve newlines
                continue;
            }

            const isUppercase = char === char.toUpperCase() && char !== char.toLowerCase();
            let charLower = char.toLowerCase();

            // 1. Handle Capital Sign
            if (isUppercase && BRAILLE_MAP[charLower]) {
                braille += BRAILLE_MAP['CAP_SIGN'];
            }

            // 2. Handle known characters (numbers and letters will get the Number Sign if applicable)
            if (BRAILLE_MAP[charLower]) {
                // If it's a number (e.g., '1', '2'), add the full code (Number Sign + Letter equivalent)
                if (charLower >= '0' && charLower <= '9') {
                    braille += BRAILLE_MAP[charLower];
                } else {
                    // It's a letter, space, or punctuation
                    braille += BRAILLE_MAP[charLower];
                }
            } else {
                // Ignore unsupported characters
                // console.warn(`Ignoring unsupported character: ${char}`);
            }
        }
        return braille;
    }

    /**
     * Converts Braille Code to English Text.
     * @param {string} braille - The input Braille string.
     * @returns {string} The resulting English Text string.
     */
    function brailleToText(braille) {
        let text = '';
        let shouldCapitalizeNext = false;

        // Clean up the Braille string: replace unsupported characters with a placeholder space
        const sanitizedBraille = braille.replace(/[^ \n⠁-⠹⠺-⠽⠼⠠]/g, ' '); 
        const chars = Array.from(sanitizedBraille);

        for (let i = 0; i < chars.length; i++) {
            const currentBraille = chars[i];

            if (currentBraille === '\n') {
                text += '\n'; // Preserve newlines
                shouldCapitalizeNext = false; // Reset capitalization state
                continue;
            }

            // 1. Handle Number Sign (⠼)
            if (currentBraille === NUM_SIGN) {
                const nextBraille = chars[i + 1];
                const number = REVERSE_NUM_MAP[nextBraille];

                if (number !== undefined) {
                    text += number;
                    i++; // Skip the next character as it was part of the number sequence
                    continue;
                } else {
                    // Number sign followed by non-number pattern is an error/unsupported
                    text += '?';
                    continue;
                }
            }

            // 2. Handle Capital Sign (⠠)
            if (currentBraille === CAP_SIGN) {
                shouldCapitalizeNext = true;
                continue;
            }

            // 3. Handle standard characters (letters, space, punctuation)
            const standardChar = TEXT_CODE_MAP[currentBraille];

            if (standardChar) {
                let finalChar = standardChar;

                // Apply capitalization if the flag is set
                if (shouldCapitalizeNext && finalChar.length === 1 && finalChar.match(/[a-z]/i)) {
                    finalChar = finalChar.toUpperCase();
                }

                text += finalChar;
                shouldCapitalizeNext = false; // Capitalization only applies to the next character

            } else {
                // Unrecognized Braille cell
                text += '?';
            }
        }
        return text;
    }

    /**
     * Main conversion logic based on selected direction.
     */
    function convert() {
        const input = inputValue.value;
        const direction = directionSelect.value;
        resultsList.innerHTML = '';
        let result = '';
        let inputName = '';
        let outputName = '';
        let outputClass = 'unit-value';

        if (!input.trim()) {
            resultsList.innerHTML = `<div class="alert alert-warning">Please enter a message.</div>`;
            return;
        }

        if (direction === 'textToBraille') {
            result = textToBraille(input);
            inputName = 'English Text Input';
            outputName = 'Braille Output (Grade 1)';
            outputClass += ' braille-output';
        } else if (direction === 'brailleToText') {
            result = brailleToText(input);
            inputName = 'Braille Input';
            outputName = 'English Text Output';
        }

        // Display Result
        if (!result.trim()) {
             resultsList.innerHTML = `<div class="alert alert-danger">The input resulted in no valid conversion.</div>`;
             return;
        }

        // Input Echo
        resultsList.innerHTML += `
            <div class="list-group-item">
                <span class="unit-name">${inputName}</span>
                <span class="unit-value">${input}</span>
            </div>
        `;

        // Conversion Result
        resultsList.innerHTML += `
            <div class="list-group-item highlight-item">
                <span class="unit-name">${outputName}</span>
                <span class="${outputClass}">${result}</span>
            </div>
        `;
    }

    // --- Event Listeners and Initialization ---

    function setupListeners() {
        // Use 'input' event for real-time responsiveness
        inputValue.addEventListener('input', convert);
        // Use 'change' event for dropdown changes
        directionSelect.addEventListener('change', convert);
        convertButton.addEventListener('click', convert);
    }

