// --- CONSTANTS ---
    // 1 Katal to Enzyme Units (60 seconds/minute * 1,000,000 micromoles/mole)
    const KATAL_TO_UNIT_FACTOR = 60000000; 
    const UNIT_TO_KATAL_FACTOR = 1 / KATAL_TO_UNIT_FACTOR; // Inverse of the above

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const directionSelect = document.getElementById('directionSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the catalytic activity value based on the selected direction.
     */
    function convertCatalyticActivity() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const direction = directionSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let result = 0;
        let inputUnitSymbol = '';
        let outputUnitSymbol = '';
        let outputFormat = 4; // Default precision

        if (direction === 'UtoKat') {
            // Enzyme Units (U) to Katal (kat): kat = U / 60,000,000
            result = value * UNIT_TO_KATAL_FACTOR;
            inputUnitSymbol = 'U';
            outputUnitSymbol = 'kat';
            outputFormat = 15; // High precision for small kat values
        } else if (direction === 'KattoU') {
            // Katal (kat) to Enzyme Units (U): U = kat * 60,000,000
            result = value * KATAL_TO_UNIT_FACTOR;
            inputUnitSymbol = 'kat';
            outputUnitSymbol = 'U';
            outputFormat = 4;
        }

        // --- Render Results ---

        // 1. Input Echo
        renderResult(`Input Value (${inputUnitSymbol})`, value.toPrecision(7), inputUnitSymbol, '343a40', true);

        // 2. Converted Output
        renderResult(`Converted Value (${outputUnitSymbol})`, result.toPrecision(outputFormat), outputUnitSymbol, '009688', false);
    }

    /**
     * Renders a single result item.
     * @param {string} name - The name of the result/unit.
     * @param {string} value - The numerical value (string).
     * @param {string} unit - The unit abbreviation.
     * @param {string} borderColor - The color for the left border (HEX).
     * @param {boolean} isInput - If true, styles the item as the input echo.
     */
    function renderResult(name, value, unit, borderColor, isInput) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');
        item.style.borderLeftColor = `#${borderColor}`;

        let valueColor = isInput ? '#f5f5f5' : '#ff5722';
        let backgroundColor = isInput ? '#343a40' : '#343a40';
        let unitColor = isInput ? '#009688' : '#e0f2f1';

        item.innerHTML = `
            <div class="unit-name" style="color: ${isInput ? '#343a40' : '#2c3e50'};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor}; font-size: 1.3rem;">
                ${value} <span style="font-size: 0.8em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Use 'input' event for live updates on value change
        inputValue.addEventListener('input', convertCatalyticActivity);
        // Use 'change' event for direction switch
        directionSelect.addEventListener('change', convertCatalyticActivity);
    }

