    // The chart keys are mapped to their column indices.
    // Base unit is the body measurement (in CM) for the primary fitting point.

    const SIZING_TABLES = {
        // Base measurement: Chest Circumference (cm)
        mens_tops: {
            base_unit: 'Chest (cm)',
            units: [
