// Base unit: Bytes (B)
    // Using SI decimal standard: 1000^N
    const BASE = 1000;

    const UNIT_FACTORS = {
        'B': { name: 'Bytes', factor: 1, abbr: 'B' },
        'kB': { name: 'Kilobytes', factor: BASE, abbr: 'kB' }, // 10^3
        'MB': { name: 'Megabytes', factor: Math.pow(BASE, 2), abbr: 'MB' }, // 10^6
        'GB': { name: 'Gigabytes', factor: Math.pow(BASE, 3), abbr: 'GB' }, // 10^9
        'TB': { name: 'Terabytes', factor: Math.pow(BASE, 4), abbr: 'TB' }, // 10^12
        'PB': { name: 'Petabytes', factor: Math.pow(BASE, 5), abbr: 'PB' }  // 10^15
    };

    let activeUnit = 'GB'; // Default unit
    const inputField = document.getElementById('inputValue');
    const unitDropdown = document.getElementById('unitDropdown');
    const resultsList = document.getElementById('resultsList');
    const initialMessage = document.getElementById('initialMessage');

    // Function to update the dropdown button text
    function updateDropdownButton(unitKey) {
        const { name, abbr } = UNIT_FACTORS[unitKey];
        unitDropdown.textContent = `${name} (${abbr})`;
    }

    // Function to perform the conversion and update the UI
    function convertData() {
        const inputValue = parseFloat(inputField.value);

        // Clear previous results
        resultsList.innerHTML = '';
        initialMessage.style.display = 'none';

        if (isNaN(inputValue) || inputValue < 0) {
            resultsList.innerHTML = `<div class="alert alert-warning">Please enter a valid, non-negative number.</div>`;
            return;
        }

        const fromFactor = UNIT_FACTORS[activeUnit].factor;

        // 1. Convert the input value to the Base Unit (Bytes)
        const baseValueBytes = inputValue * fromFactor;

        // 2. Calculate and display all conversions
        const allUnits = Object.keys(UNIT_FACTORS);

        allUnits.forEach(toUnitKey => {
            const { name, abbr, factor: toFactor } = UNIT_FACTORS[toUnitKey];

            // Convert from Base Unit (Bytes) to the Target Unit
            const convertedValue = baseValueBytes / toFactor;

            const li = document.createElement('div');
            li.classList.add('list-group-item');

            // Highlight the active input unit
            if (activeUnit === toUnitKey) {
                li.classList.add('highlight-item');
            }

            // Ensure proper display formatting
            let displayValue;
            // Use precise formatting for smaller units (B, kB)
            if (toUnitKey === 'B') {
                 // For bytes, use round or floor for whole numbers
                displayValue = Math.round(convertedValue).toLocaleString('en-US');
            } else if (Math.abs(convertedValue) > 10000 || Math.abs(convertedValue) < 1e-4) {
                 // Use exponential notation for very large/small numbers
                displayValue = convertedValue.toExponential(4);
            } else {
                // Default fixed precision for common units
                displayValue = convertedValue.toFixed(4);
            }

            li.innerHTML = `
                <span class="unit-name">${name} (${abbr})</span>
                <span class="unit-value">${displayValue}</span>
            `;

            resultsList.appendChild(li);
        });
    }

    // Event listener for input changes (real-time conversion)
    inputField.addEventListener('input', convertData);

    // Event listener for dropdown unit selection
    document.querySelectorAll('.dropdown-item').forEach(item => {
        item.addEventListener('click', function(e) {
            e.preventDefault();
            const newUnit = this.getAttribute('data-unit');
            activeUnit = newUnit;
            updateDropdownButton(activeUnit);
            convertData(); // Recalculate with the new unit
        });
    });

    // Set 'GB' as the initial unit in the button text
    updateDropdownButton(activeUnit);
    resultsList.appendChild(initialMessage);

