// --- CONSTANTS (Based on the kg/m³ SI unit) ---
    const GCM3_TO_KGM3 = 1000; // 1 g/cm³ = 1000 kg/m³
    const LBFT3_TO_KGM3 = 16.018463; // 1 lb/ft³ ≈ 16.018463 kg/m³

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the density value from the input unit to all other units.
     */
    function convertDensity() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let kgm3 = 0; // Base unit: Kilograms per Cubic Meter

        // Step 1: Normalize input to KGM3
        if (inputUnit === 'KGM3') {
            kgm3 = value;
        } else if (inputUnit === 'GCM3') {
            // g/cm³ to kg/m³
            kgm3 = value * GCM3_TO_KGM3;
        } else if (inputUnit === 'LBFT3') {
            // lb/ft³ to kg/m³
            kgm3 = value * LBFT3_TO_KGM3;
        }

        // Step 2: Convert normalized KGM3 to all target units
        const gcm3 = kgm3 / GCM3_TO_KGM3; // kg/m³ to g/cm³
        const lbft3 = kgm3 / LBFT3_TO_KGM3; // kg/m³ to lb/ft³

        // --- Render Results ---

        const units = [
            { id: 'KGM3', name: 'Kilograms per Cubic Meter (SI)', symbol: 'kg/m³', value: kgm3 },
            { id: 'GCM3', name: 'Grams per Cubic Centimeter (CGS)', symbol: 'g/cm³', value: gcm3 },
            { id: 'LBFT3', name: 'Pounds per Cubic Foot (Imperial)', symbol: 'lb/ft³', value: lbft3 }
        ];

        // 1. Highlight the input value
        const inputUnitData = units.find(u => u.id === inputUnit);
        renderResult(`Input Value (${inputUnitData.symbol})`, value.toFixed(4), inputUnitData.symbol, '343a40', true);


