            outputUnit = 'Ampere-Hours (Ah)';
        } else if (direction === 'AhtoC') {
            // Ampere-Hours (Ah) to Coulombs (C): C = Ah * 3600
            result = value * SECONDS_PER_HOUR;
            inputUnit = 'Ampere-Hours (Ah)';
            outputUnit = 'Coulombs (C)';
        }

        // --- Render Results ---

        // 1. Input Echo
        renderResult(`Input Value (${inputUnit})`, value.toFixed(4), inputUnit, '343a40');

