// --- CONVERSION CONSTANTS (Based on US Gallon) ---
    // 1 US Gallon = 3.78541 Liters
    // 1 Minute = 60 Seconds
    // 1 Hour = 3600 Seconds

    // GPM (Gallons/Minute) to LPS (Liters/Second)
    const GPM_TO_LPS_FACTOR = 3.78541 / 60; // 0.063090166...

    // LPS (Liters/Second) to CMH (Cubic Meters/Hour)
    // 1 L/s = 0.001 m³/s
    // 1 m³/s = 3600 m³/h
    // 1 L/s = 3.6 m³/h
    const LPS_TO_CMH_FACTOR = 3.6;

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the flow rate value from the input unit to all other units.
     */
    function convertFlowRate() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let gpm = 0;
        let lps = 0;
        let cmh = 0;

        // Step 1: Normalize input to GPM (Gallons per Minute)
        if (inputUnit === 'GPM') {
            gpm = value;
        } else if (inputUnit === 'LPS') {
            // LPS to GPM: GPM = LPS / GPM_TO_LPS_FACTOR
            gpm = value / GPM_TO_LPS_FACTOR;
        } else if (inputUnit === 'CMH') {
            // CMH to LPS: LPS = CMH / LPS_TO_CMH_FACTOR
            lps = value / LPS_TO_CMH_FACTOR;
            // LPS to GPM
            gpm = lps / GPM_TO_LPS_FACTOR;
        }

        // Step 2: Convert normalized GPM to other target units
        lps = gpm * GPM_TO_LPS_FACTOR;
        cmh = lps * LPS_TO_CMH_FACTOR;

        // --- Render Results ---

        const units = [
            { id: 'GPM', name: 'Gallons per Minute', symbol: 'GPM', value: gpm },
            { id: 'LPS', name: 'Liters per Second', symbol: 'L/s', value: lps },
            { id: 'CMH', name: 'Cubic Meters per Hour', symbol: 'm³/h', value: cmh }
        ];

        // Highlight the input value
        renderResult(`Input Value (${units.find(u => u.id === inputUnit).symbol})`, value.toFixed(4), units.find(u => u.id === inputUnit).symbol, '343a40', true);


        units.filter(u => u.id !== inputUnit).forEach(unit => {
            renderResult(unit.name, unit.value.toFixed(6), unit.symbol, '3498db', false);
        });
    }

    /**
     * Renders a single result item.
     * @param {string} name - The name of the result/unit.
     * @param {string} value - The numerical value.
     * @param {string} unit - The unit abbreviation.
     * @param {string} borderColor - The color for the left border (HEX).
     * @param {boolean} isInput - If true, styles the item as the input echo.
     */
    function renderResult(name, value, unit, borderColor, isInput) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');
        item.style.borderLeftColor = `#${borderColor}`;

        let valueColor = isInput ? '#343a40' : '#e74c3c';
        let backgroundColor = isInput ? '#fcfcfc' : '#ecf0f1';
        let fontSize = isInput ? '1.1rem' : '1.3rem';

        item.innerHTML = `
            <div class="unit-name">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor}; font-size: ${fontSize};">
                ${value} <span style="font-size: 0.8em; font-weight: normal; color: #3498db;">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Use 'input' event for live updates on value change
        inputValue.addEventListener('input', convertFlowRate);
        // Use 'change' event for unit switch
        inputUnitSelect.addEventListener('change', convertFlowRate);
    }

