    // 1 Pound-force (lbf) to Newton (N)
    const LBF_TO_N_FACTOR = 4.448222; 
    // 1 Newton (N) to Pound-force (lbf)
    const N_TO_LBF_FACTOR = 1 / LBF_TO_N_FACTOR; 

    // --- DOM Elements ---
