// Base unit: Meters (m)
    const UNIT_FACTORS = {
        'm': { name: 'Meters', factor: 1, abbr: 'm' },
        'km': { name: 'Kilometers', factor: 1000, abbr: 'km' },
        'cm': { name: 'Centimeters', factor: 0.01, abbr: 'cm' },
        'mi': { name: 'Miles', factor: 1609.344, abbr: 'mi' }, // 1 mile = 1609.344 meters
        'ft': { name: 'Feet', factor: 0.3048, abbr: 'ft' }, // 1 foot = 0.3048 meters
        'in': { name: 'Inches', factor: 0.0254, abbr: 'in' } // 1 inch = 0.0254 meters
    };

    let activeUnit = 'm'; // Default unit
    const inputField = document.getElementById('inputValue');
    const unitDropdown = document.getElementById('unitDropdown');
    const resultsList = document.getElementById('resultsList');
    const initialMessage = document.getElementById('initialMessage');

    // Function to update the dropdown button text
    function updateDropdownButton(unitKey) {
        const { name, abbr } = UNIT_FACTORS[unitKey];
        unitDropdown.textContent = `${name} (${abbr})`;
    }

    // Function to perform the conversion and update the UI
    function convertLength() {
        const inputValue = parseFloat(inputField.value);

        // Clear previous results
        resultsList.innerHTML = '';
        initialMessage.style.display = 'none';

        if (isNaN(inputValue) || inputValue <= 0) {
            resultsList.innerHTML = `<div class="alert alert-warning">Please enter a valid, positive number.</div>`;
            return;
        }

        const fromFactor = UNIT_FACTORS[activeUnit].factor;

        // 1. Convert the input value to the Base Unit (Meters)
        const baseValueMeters = inputValue * fromFactor;

        // 2. Calculate and display all conversions
        const allUnits = Object.keys(UNIT_FACTORS);

        allUnits.forEach(toUnitKey => {
            const { name, abbr, factor: toFactor } = UNIT_FACTORS[toUnitKey];

            // Convert from Base Unit (Meters) to the Target Unit
            const convertedValue = baseValueMeters / toFactor;

            const li = document.createElement('div');
            li.classList.add('list-group-item');

            // Highlight the active input unit
            if (activeUnit === toUnitKey) {
                li.classList.add('highlight-item');
            }

            li.innerHTML = `
                <span class="unit-name">${name} (${abbr})</span>
                <span class="unit-value">${convertedValue.toFixed(4)}</span>
            `;

            resultsList.appendChild(li);
        });
    }

    // Event listener for input changes (real-time conversion)
    inputField.addEventListener('input', convertLength);

    // Event listener for dropdown unit selection
    document.querySelectorAll('.dropdown-item').forEach(item => {
        item.addEventListener('click', function(e) {
            e.preventDefault();
            const newUnit = this.getAttribute('data-unit');
            activeUnit = newUnit;
            updateDropdownButton(activeUnit);
            convertLength(); // Recalculate with the new unit
        });
    });

    // Initial setup: Set default unit and prompt user
    updateDropdownButton(activeUnit);
    initialMessage.style.display = 'block';
    resultsList.appendChild(initialMessage);

