// --- CONSTANTS ---
    // Conversion factors to a base unit (meters for distance, unitless for scale)
    const UNIT_FACTORS_TO_METER = {
        'mm': 0.001,
        'cm': 0.01,
        'm': 1,
        'km': 1000,
    };

    // Output units for easy reading
    const OUTPUT_UNITS_GROUND = {
        'm': 1,
        'km': 1000
    };
    const OUTPUT_UNITS_MAP = {
        'mm': 0.001,
        'cm': 0.01
    };


    // --- DOM Elements ---
    const calculationMode = document.getElementById('calculationMode');
    const mapDistanceInputGroup = document.getElementById('mapDistanceInputGroup');
    const groundDistanceInputGroup = document.getElementById('groundDistanceInputGroup');
    const scaleFactorInputGroup = document.getElementById('scaleFactorInputGroup');

    const mapDistanceValue = document.getElementById('mapDistanceValue');
    const mapDistanceUnit = document.getElementById('mapDistanceUnit');
    const groundDistanceValue = document.getElementById('groundDistanceValue');
    const groundDistanceUnit = document.getElementById('groundDistanceUnit');
    const scaleY = document.getElementById('scaleY');
    const resultsList = document.getElementById('resultsList');

    /**
     * Toggles visibility of input groups based on the selected calculation mode.
     */
    function toggleInputs() {
        const mode = calculationMode.value;

        // Reset visibility
        mapDistanceInputGroup.classList.remove('hidden-input');
        groundDistanceInputGroup.classList.remove('hidden-input');
        scaleFactorInputGroup.classList.remove('hidden-input');

        // Hide the input we are calculating
        if (mode === 'scale') {
            scaleFactorInputGroup.classList.add('hidden-input');
        } else if (mode === 'ground') {
            groundDistanceInputGroup.classList.add('hidden-input');
        } else if (mode === 'map') {
            mapDistanceInputGroup.classList.add('hidden-input');
        }

        calculateScale(); // Recalculate immediately
    }


    function autoFormatDistance(meters, unitMap) {
        if (meters >= 1000 && unitMap === OUTPUT_UNITS_GROUND) {
            return { value: meters / 1000, unit: 'km' };
        } 
        if (meters < 1 && unitMap === OUTPUT_UNITS_MAP) {
            // Check for cm
            if (meters / 0.01 >= 1) { 
                return { value: meters / 0.01, unit: 'cm' };
            }
            // Check for mm
            if (meters / 0.001 >= 1) {
                return { value: meters / 0.001, unit: 'mm' };
            }
        }
        return { value: meters, unit: 'm' }; // Default to meters
    }

    /**
     * Renders a single result item.
     */
    function renderResult(name, value, unit, isMainResult) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');

        let borderColor = isMainResult ? '#4caf50' : '#81c784';
        let backgroundColor = isMainResult ? '#388e3c' : '#e8f5e9';
        let valueColor = isMainResult ? 'white' : '#388e3c';
        let nameColor = isMainResult ? 'white' : '#455a64';
        let unitColor = isMainResult ? '#c8e6c9' : '#455a64';

        item.style.borderLeftColor = borderColor;

        let displayValue = (typeof value === 'number') ? value.toFixed(3) : value;

        item.innerHTML = `
            <div class="unit-name" style="color: ${nameColor};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor};">
                ${displayValue} <span style="font-size: 0.7em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    /**
     * Performs the main calculation based on the selected mode.
     */
    function calculateScale() {
        resultsList.innerHTML = '';
        const mode = calculationMode.value;

        // Fetch inputs
        const mapDistVal = parseFloat(mapDistanceValue.value);
        const mapDistUnit = mapDistanceUnit.value;
        const groundDistVal = parseFloat(groundDistanceValue.value);
        const groundDistUnit = groundDistanceUnit.value;
        const scaleFactorY = parseFloat(scaleY.value);

        let errors = [];

        // Normalize distance values to meters (the base unit)
        const mapDistMeters = mapDistVal * (UNIT_FACTORS_TO_METER[mapDistUnit] || 0);
        const groundDistMeters = groundDistVal * (UNIT_FACTORS_TO_METER[groundDistUnit] || 0);

        // --- Validation ---
        if (mode !== 'scale' && (isNaN(scaleFactorY) || scaleFactorY < 1)) errors.push("Please enter a valid, positive Scale Factor (Y).");
        if (mode !== 'map' && (isNaN(mapDistVal) || mapDistVal <= 0)) errors.push("Please enter a valid, positive Map Distance.");
        if (mode !== 'ground' && (isNaN(groundDistVal) || groundDistVal <= 0)) errors.push("Please enter a valid, positive Ground Distance.");

        if (errors.length > 0) {
            resultsList.innerHTML = errors.map(err => `<div class="alert alert-danger">${err}</div>`).join('');
            return;
        }

        let result = null;

        if (mode === 'scale') {
            // --- Mode 1: Calculate Scale Factor (1:X) ---
            // Scale Factor (unitless) = Ground Distance (e.g., in cm) / Map Distance (in the *same unit*, e.g., cm)

            // To ensure 1:X format, we normalize both to the map distance unit (cm is usually easiest)
            // Scale X = Ground Distance (cm) / Map Distance (cm)

            const mapDistBase = mapDistVal * (UNIT_FACTORS_TO_METER[mapDistUnit] / UNIT_FACTORS_TO_METER['cm']); // Map distance in cm
            const groundDistBase = groundDistMeters / UNIT_FACTORS_TO_METER['cm']; // Ground distance in cm

            const scaleX = groundDistBase / mapDistBase;

            if (scaleX < 1) {
                 errors.push("Scale factor (X) must be 1 or greater. Check your inputs.");
            } else {
                 result = Math.round(scaleX); // Scale is typically rounded to nearest whole number
            }

            if (errors.length > 0) {
                 resultsList.innerHTML = errors.map(err => `<div class="alert alert-danger">${err}</div>`).join('');
                 return;
            }

            renderResult('Calculated Scale Factor', `1:${result.toLocaleString()}`, 'unitless', true);
            renderResult('Input Map Distance', `${mapDistVal.toFixed(2)} ${mapDistUnit}`, '', false);
            renderResult('Input Ground Distance', `${groundDistVal.toFixed(2)} ${groundDistUnit}`, '', false);

        } else if (mode === 'ground') {
            // --- Mode 2: Calculate Ground Distance ---
            // Ground Distance (m) = Map Distance (m) * Scale Factor (X)
            const groundDistM = mapDistMeters * scaleFactorY;

            // Auto-format for display (m or km)
            const formatted = autoFormatDistance(groundDistM, OUTPUT_UNITS_GROUND);

            renderResult('Calculated Ground Distance', formatted.value, formatted.unit, true);
            renderResult('Input Map Distance', `${mapDistVal.toFixed(2)} ${mapDistUnit}`, '', false);
            renderResult('Input Scale Factor', `1:${scaleFactorY.toLocaleString()}`, '', false);

        } else if (mode === 'map') {
            // --- Mode 3: Calculate Map Distance ---
            // Map Distance (m) = Ground Distance (m) / Scale Factor (X)
            const mapDistM = groundDistMeters / scaleFactorY;

            // Auto-format for display (mm or cm)
            const formatted = autoFormatDistance(mapDistM, OUTPUT_UNITS_MAP);

            renderResult('Calculated Map Distance', formatted.value, formatted.unit, true);
            renderResult('Input Ground Distance', `${groundDistVal.toFixed(2)} ${groundDistUnit}`, '', false);
            renderResult('Input Scale Factor', `1:${scaleFactorY.toLocaleString()}`, '', false);
        }
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Attach listeners to all inputs that change the result
        document.querySelectorAll('.input-field').forEach(input => {
            input.addEventListener('input', calculateScale);
            input.addEventListener('change', calculateScale); // For select elements
        });

        // Initial setup
        toggleInputs(); 
    }

    window.onload = function() {
        setupListeners();
    };

conversion_calculator__metric_prefix_con:
// Define all prefixes relative to the Base Unit (factor is 10^X)
    const PREFIX_FACTORS = {
        'BASE': 1e0,   // Base Unit (U)
        'K': 1e3,      // Kilo (kU)
        'M': 1e6,      // Mega (MU)
        'G': 1e9,      // Giga (GU)
        'T': 1e12     // Tera (TU)
    };

    const PREFIX_NAMES = {
        'BASE': 'Base Unit',
        'K': 'Kilo',
        'M': 'Mega',
        'G': 'Giga',
        'T': 'Tera'
    };

    const PREFIX_SYMBOLS = {
        'BASE': 'U',
        'K': 'kU',
        'M': 'MU',
        'G': 'GU',
        'T': 'TU'
    };

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Helper function to format large/small numbers in scientific notation if necessary.
     * @param {number} num - The number to format.
     * @returns {string} The formatted string, using toFixed or toExponential based on magnitude.
     */
    function formatOutput(num) {
        if (num === 0) return '0';
        const absNum = Math.abs(num);

        // Use standard notation if within a comfortable range
        if (absNum >= 0.00001 && absNum < 10000000) {
            return num.toFixed(6).replace(/\.?0+$/, ""); // Remove trailing zeros
        }

        // Use scientific notation for very large or very small numbers
        let expStr = num.toExponential(4);

        // Reformat 'e+XX' to 'x 10^XX' for better visual math display
        const [mantissa, exponent] = expStr.split('e');
        if (exponent) {
            const sign = exponent.startsWith('-') ? '' : '+';
            const expValue = exponent.replace('+', '');
            return `${parseFloat(mantissa).toFixed(4)} \times 10<span class="result-exponent">${sign}${expValue}</span>`;
        }
        return num.toString();
    }


    /**
     * Converts the value from the input prefix to all other prefixes.
     */
    function convertPrefix() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputPrefix = inputUnitSelect.value;

        if (isNaN(value)) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid number.</div>`;
            return;
        }

        // 1. Normalize input value to the Base Unit (U)
        const baseFactor = PREFIX_FACTORS[inputPrefix];
        const baseValue = value * baseFactor; 

        // 2. Convert baseValue to all target prefixes
        const units = [];
        for (const [prefix, factor] of Object.entries(PREFIX_FACTORS)) {
            const convertedValue = baseValue / factor;
            units.push({
                id: prefix,
                name: PREFIX_NAMES[prefix],
                symbol: PREFIX_SYMBOLS[prefix],
                value: convertedValue
            });
        }

        // --- Render Results ---

        // Find and render the input value first
        const inputUnitData = units.find(u => u.id === inputPrefix);
        if (inputUnitData) {
            renderResult(`Input Value (${inputUnitData.name})`, value.toString(), inputUnitData.symbol, '343a40', true);
        }


        // Render all other converted values
        units.filter(u => u.id !== inputPrefix).forEach(unit => {
            // Use formatter for the output
            renderResult(unit.name, formatOutput(unit.value), unit.symbol, '00bcd4', false);
        });
    }

    /**
     * Renders a single result item.
     * @param {string} name - The name of the result/unit.
     * @param {string} value - The numerical value (string, potentially formatted with exponents).
     * @param {string} unit - The unit abbreviation.
     * @param {string} borderColor - The color for the left border (HEX).
     * @param {boolean} isInput - If true, styles the item as the input echo.
     */
    function renderResult(name, value, unit, borderColor, isInput) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');
        item.style.borderLeftColor = `#${borderColor}`;

        let valueColor = isInput ? '#343a40' : '#e91e63';
        let backgroundColor = isInput ? '#e0f7fa' : '#fce4ec';
        let unitColor = isInput ? '#00838f' : '#00838f';
        let fontSize = isInput ? '1.1rem' : '1.3rem';


        item.innerHTML = `
            <div class="unit-name" style="color: ${isInput ? '#343a40' : '#2c3e50'};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor}; font-size: ${fontSize};">
                ${value} <span style="font-size: 0.8em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Use 'input' event for live updates on value change
        inputValue.addEventListener('input', convertPrefix);
        // Use 'change' event for unit switch
        inputUnitSelect.addEventListener('change', convertPrefix);
    }

