// --- CONSTANTS (Relative to kg⋅m²) ---
    // kg⋅m² to g⋅cm²: 1000 g/kg * 10000 cm²/m² = 10,000,000
    const KGM2_TO_GCM2_FACTOR = 1e7; 

    // kg⋅m² to lbm⋅ft²: 1 kg ≈ 2.20462 lbm, 1 m² ≈ 10.7639 ft². (2.20462 * 10.7639)
    const KGM2_TO_LBMFT2_FACTOR = 23.73036; 

    // --- Inverse Factors ---
    const GCM2_TO_KGM2_FACTOR = 1 / KGM2_TO_GCM2_FACTOR; // 1e-7
    const LBMFT2_TO_KGM2_FACTOR = 1 / KGM2_TO_LBMFT2_FACTOR; // 0.04214011

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the moment of inertia value from the input unit to all other units.
     */
    function convertInertia() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let kgm2 = 0; // Base unit: Kilogram meter squared

        // Step 1: Normalize input to KGM2
        if (inputUnit === 'KGM2') {
            kgm2 = value;
        } else if (inputUnit === 'GCM2') {
            // g⋅cm² to kg⋅m²
            kgm2 = value * GCM2_TO_KGM2_FACTOR;
        } else if (inputUnit === 'LBMFT2') {
            // lbm⋅ft² to kg⋅m²
            kgm2 = value * LBMFT2_TO_KGM2_FACTOR;
        }

        // Step 2: Convert normalized KGM2 to all target units
        const g_cm2 = kgm2 * KGM2_TO_GCM2_FACTOR; // kg⋅m² to g⋅cm²
        const lbm_ft2 = kgm2 * KGM2_TO_LBMFT2_FACTOR; // kg⋅m² to lbm⋅ft²

        // --- Render Results ---

        const units = [
            { id: 'KGM2', name: 'Kilogram meter squared (SI)', symbol: 'kg⋅m²', value: kgm2 },
            { id: 'GCM2', name: 'Gram centimeter squared (CGS)', symbol: 'g⋅cm²', value: g_cm2 },
            { id: 'LBMFT2', name: 'Pound-mass foot squared (Imperial)', symbol: 'lbm⋅ft²', value: lbm_ft2 }
        ];

        // 1. Render converted values first
        units.filter(u => u.id !== inputUnit).forEach(unit => {
            // Use different precision for CGS due to large numbers
            const precision = unit.id === 'GCM2' ? 0 : 6;
            renderResult(unit.name, unit.value.toFixed(precision), unit.symbol, '673ab7', false);
        });

        // 2. Highlight the input value
        const inputUnitData = units.find(u => u.id === inputUnit);
        // Display input value as entered, maybe with some formatting
