// Base unit: Watts (W)
    const UNIT_FACTORS = {
        'W': { name: 'Watts', factor: 1, abbr: 'W' },
        'kW': { name: 'Kilowatts', factor: 1000, abbr: 'kW' }, // 1 kW = 1000 W

        // Imperial Horsepower (550 ft·lbf/s)
        'hp_i': { name: 'Horsepower (Imp)', factor: 745.699872, abbr: 'hp' }, 

        // Metric Horsepower (PS - Pferdestärke)
        'hp_m': { name: 'Horsepower (Metric)', factor: 735.49875, abbr: 'PS' }, 

        // Foot-Pounds per Second (1 ft·lbf/s = 1.355817948 W)
        'ft_lbs': { name: 'Foot-Pounds/Second', factor: 1.355817948, abbr: 'ft·lb/s' }, 

        // Kilocalories per Second (1 kcal/s = 4184 W)
        'kCal_s': { name: 'Kilocalories per Second', factor: 4184, abbr: 'kcal/s' } 
    };

    let activeUnit = 'W'; // Default unit
    const inputField = document.getElementById('inputValue');
    const unitDropdown = document.getElementById('unitDropdown');
    const resultsList = document.getElementById('resultsList');
    const initialMessage = document.getElementById('initialMessage');

    // Function to update the dropdown button text
    function updateDropdownButton(unitKey) {
        const { name, abbr } = UNIT_FACTORS[unitKey];
        unitDropdown.textContent = `${name} (${abbr})`;
    }

    // Function to perform the conversion and update the UI
    function convertPower() {
        const inputValue = parseFloat(inputField.value);

        // Clear previous results
        resultsList.innerHTML = '';
        initialMessage.style.display = 'none';

        if (isNaN(inputValue) || inputValue < 0) {
            resultsList.innerHTML = `<div class="alert alert-warning">Please enter a valid, non-negative number.</div>`;
            return;
        }

        const fromFactor = UNIT_FACTORS[activeUnit].factor;

        // 1. Convert the input value to the Base Unit (Watts)
