    // 1 Newton/Meter to Dyne/Centimeter
    const NM_TO_DYNECM_FACTOR = 1000; 

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const directionSelect = document.getElementById('directionSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the surface tension value based on the selected direction.
     */
    function convertSurfaceTension() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const direction = directionSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let result = 0;
        let inputUnitSymbol = '';
        let outputUnitSymbol = '';
        let inputUnitName = '';
        let outputUnitName = '';

        if (direction === 'NmtoDyneCm') {
            // N/m to dyne/cm: dyne/cm = N/m * 1000
            result = value * NM_TO_DYNECM_FACTOR;
            inputUnitSymbol = 'N/m';
            outputUnitSymbol = 'dyne/cm';
            inputUnitName = 'Newton per Meter (SI)';
            outputUnitName = 'Dyne per Centimeter (CGS)';
        } else if (direction === 'DyneCmtoNm') {
            // dyne/cm to N/m: N/m = dyne/cm / 1000
            result = value / NM_TO_DYNECM_FACTOR;
            inputUnitSymbol = 'dyne/cm';
            outputUnitSymbol = 'N/m';
            inputUnitName = 'Dyne per Centimeter (CGS)';
            outputUnitName = 'Newton per Meter (SI)';
        }

        // --- Render Results ---

        // 1. Input Echo
        renderResult(`Input Value (${inputUnitName})`, value.toFixed(6), inputUnitSymbol, '343a40', true);

        // 2. Converted Output
        renderResult(`Converted Value (${outputUnitName})`, result.toFixed(8), outputUnitSymbol, '3f51b5', false);
    }

