// Define the units and their names/abbreviations
    const UNITS = {
        'celsius': { name: 'Celsius', abbr: '°C' },
        'fahrenheit': { name: 'Fahrenheit', abbr: '°F' },
        'kelvin': { name: 'Kelvin', abbr: 'K' }
    };

    let activeUnit = 'celsius'; // Default unit
    const inputField = document.getElementById('inputValue');
    const unitDropdown = document.getElementById('unitDropdown');
    const resultsList = document.getElementById('resultsList');
    const initialMessage = document.getElementById('initialMessage');

    // Function to update the dropdown button text
    function updateDropdownButton(unitKey) {
        const { name, abbr } = UNITS[unitKey];
        unitDropdown.innerHTML = `${name} (${abbr})`;
    }

    /**
     * Converts a temperature value from a source unit to a target unit.
     * Conversion uses Celsius (°C) as the intermediary base.
     */
    function convertTemperature(value, fromUnit, toUnit) {
        let celsiusValue;

        // 1. Convert input value to Celsius (Base Unit)
        if (fromUnit === 'celsius') {
            celsiusValue = value;
        } else if (fromUnit === 'fahrenheit') {
            // C = (F - 32) * 5/9
            celsiusValue = (value - 32) * (5 / 9);
        } else if (fromUnit === 'kelvin') {
            // C = K - 273.15
            celsiusValue = value - 273.15;
        } else {
            return NaN;
        }

        // 2. Convert from Celsius to the target unit
        if (toUnit === 'celsius') {
            return celsiusValue;
        } else if (toUnit === 'fahrenheit') {
            // F = C * 9/5 + 32
            return (celsiusValue * (9 / 5)) + 32;
        } else if (toUnit === 'kelvin') {
            // K = C + 273.15
            return celsiusValue + 273.15;
        } else {
            return NaN;
        }
    }

    // Function to handle UI updates and validation
    function executeConversion() {
        const inputValue = parseFloat(inputField.value);

        // Clear previous results
        resultsList.innerHTML = '';
        initialMessage.style.display = 'none';

        if (isNaN(inputValue)) {
            resultsList.innerHTML = `<div class="alert alert-warning">Please enter a valid number.</div>`;
            return;
        }

        // Check for physical impossibility (below absolute zero: 0 K or -273.15 °C)
        // Convert input to Kelvin to check.
        const kelvinCheck = convertTemperature(inputValue, activeUnit, 'kelvin');
        if (kelvinCheck < 0 && activeUnit !== 'kelvin') { // Kelvin must be 0 or above
            resultsList.innerHTML = `<div class="alert alert-danger">Temperature cannot be below Absolute Zero (0 K).</div>`;
            return;
        }
        if (activeUnit === 'kelvin' && inputValue < 0) {
             resultsList.innerHTML = `<div class="alert alert-danger">Temperature cannot be below Absolute Zero (0 K).</div>`;
            return;
        }


        // Calculate and display all conversions
        const allUnits = Object.keys(UNITS);

        allUnits.forEach(toUnitKey => {
            const { name, abbr } = UNITS[toUnitKey];

            // Perform the conversion
            const convertedValue = convertTemperature(inputValue, activeUnit, toUnitKey);

            const li = document.createElement('div');
            li.classList.add('list-group-item');

            // Highlight the active input unit
            if (activeUnit === toUnitKey) {
                li.classList.add('highlight-item');
            }

            li.innerHTML = `
                <span class="unit-name">${name} (${abbr})</span>
                <span class="unit-value">${convertedValue.toFixed(2)} ${abbr}</span>
            `;

            resultsList.appendChild(li);
        });
    }

    // Event listener for input changes (real-time conversion)
    inputField.addEventListener('input', executeConversion);

    // Event listener for dropdown unit selection
    document.querySelectorAll('.dropdown-item').forEach(item => {
        item.addEventListener('click', function(e) {
            e.preventDefault();
            const newUnit = this.getAttribute('data-unit');
            activeUnit = newUnit;
            updateDropdownButton(activeUnit);
            executeConversion(); // Recalculate with the new unit
        });
    });

    // Initial setup: Set default unit and prompt user
    updateDropdownButton(activeUnit);
    resultsList.appendChild(initialMessage);

