// --- CONSTANTS ---
    // 1 Newton-Meter to Foot-Pound (high precision)
    const NM_TO_FTLB_FACTOR = 0.737562149; 
    // 1 Foot-Pound to Newton-Meter (inverse)
    const FTLB_TO_NM_FACTOR = 1 / NM_TO_FTLB_FACTOR; // 1.35581794833...

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const directionSelect = document.getElementById('directionSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the torque value based on the selected direction.
     */
    function convertTorque() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const direction = directionSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let result = 0;
        let inputUnitSymbol = '';
        let outputUnitSymbol = '';

        if (direction === 'NmtoFtLb') {
            // N·m to ft·lb: ft·lb = N·m * FACTOR
            result = value * NM_TO_FTLB_FACTOR;
            inputUnitSymbol = 'N·m';
            outputUnitSymbol = 'ft·lb';
        } else if (direction === 'FtLbtoNm') {
            // ft·lb to N·m: N·m = ft·lb * INVERSE FACTOR
            result = value * FTLB_TO_NM_FACTOR;
            inputUnitSymbol = 'ft·lb';
            outputUnitSymbol = 'N·m';
        }

        // --- Render Results ---

        // 1. Input Echo
        renderResult(`Input Value (${inputUnitSymbol})`, value.toFixed(4), inputUnitSymbol, '343a40');

        // 2. Converted Output
        // Use higher precision for the converted value
        renderResult(`Converted Value (${outputUnitSymbol})`, result.toFixed(6), outputUnitSymbol, 'e67e22');
    }

