conversion_calculator__typography_unit_c:
// --- CONSTANTS ---
    // Standard CSS/Web assumption: 1 point = 1.333... pixels (72/96 ratio)
    const PT_TO_PX_FACTOR = 96 / 72; // 1.33333333
    const PX_TO_PT_FACTOR = 72 / 96; // 0.75

    // --- DOM Elements ---
    const baseFontSize = document.getElementById('baseFontSize');
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the typography value from the input unit to all other units.
     */
    function convertTypography() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const basePx = parseFloat(baseFontSize.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative value for the conversion.</div>`;
            return;
        }

        if (isNaN(basePx) || basePx <= 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid, positive Base Font Size (e.g., 16).</div>`;
            return;
        }

        let px = 0; // Base unit: Pixels

        // Step 1: Normalize input to PX
        if (inputUnit === 'PX') {
            px = value;
        } else if (inputUnit === 'PT') {
            // pt to px: px = pt * (96/72)
            px = value * PT_TO_PX_FACTOR;
        } else if (inputUnit === 'EM') {
            // em to px: px = em * basePx
            px = value * basePx;
        }

        // Step 2: Convert normalized PX to all target units
        const pt = px * PX_TO_PT_FACTOR; // px to pt
        const em = px / basePx; // px to em

        // --- Render Results ---

        const units = [
            { id: 'PX', name: 'Pixels (Web Standard)', symbol: 'px', value: px },
            { id: 'PT', name: 'Points (Print Standard)', symbol: 'pt', value: pt },
            { id: 'EM', name: 'Ems (Relative Unit)', symbol: 'em', value: em }
        ];

        const inputUnitData = units.find(u => u.id === inputUnit);

        // 1. Render input value (always first)
        renderResult(`Input Value (${inputUnitData.name})`, value.toFixed(4), inputUnitData.symbol, '343a40', true);


        // 2. Render converted values
        units.filter(u => u.id !== inputUnit).forEach(unit => {
            renderResult(`Converted to ${unit.name}`, unit.value.toFixed(4), unit.symbol, '009688', false);
        });

        // 3. Show Base Size Info
        renderResult(`Base Size Used`, basePx.toFixed(0), 'px', '512da8', true);
    }

    /**
     * Renders a single result item.
     * @param {string} name - The name of the result/unit.
     * @param {string} value - The numerical value (string).
     * @param {string} unit - The unit abbreviation.
     * @param {string} borderColor - The color for the left border (HEX).
     * @param {boolean} isInput - If true, styles the item as the input echo/info.
     */
    function renderResult(name, value, unit, borderColor, isInput) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');
        item.style.borderLeftColor = `#${borderColor}`;

        let valueColor = isInput ? '#343a40' : 'white';
        let backgroundColor = isInput ? '#e0f2f1' : '#00695c';
        let unitColor = isInput ? '#00695c' : '#fdd835';
        let nameColor = isInput ? '#00695c' : '#e0f2f1';


        item.innerHTML = `
            <div class="unit-name" style="color: ${nameColor};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor}; font-size: 1.3rem;">
                ${value} <span style="font-size: 0.8em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Use 'input' event for live updates on value change
        inputValue.addEventListener('input', convertTypography);
        inputUnitSelect.addEventListener('change', convertTypography);
        // Base font size is critical, also listen to its changes
        baseFontSize.addEventListener('input', convertTypography);
    }

conversion_calculator__video_file_size_c:
// --- CONSTANTS ---
    const BITS_PER_BYTE = 8;
    const KILO_TO_MEGA_FACTOR = 1000;

    // The total factor to convert (kbps * seconds) into MB:
    // (kbps * s) / (8 bits/byte * 1000 kb/Mb) = MB
    const KBPS_SECONDS_TO_MB_FACTOR = 1 / (BITS_PER_BYTE * KILO_TO_MEGA_FACTOR); // 0.000125

    // --- DOM Elements ---
    const videoBitrateValue = document.getElementById('videoBitrateValue');
    const audioBitrateValue = document.getElementById('audioBitrateValue');
    const durationH = document.getElementById('durationH');
    const durationM = document.getElementById('durationM');
    const durationS = document.getElementById('durationS');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts hours, minutes, and seconds input into total seconds.
     * @returns {number} Total duration in seconds.
     */
    function durationToSeconds() {
        const h = parseFloat(durationH.value) || 0;
        const m = parseFloat(durationM.value) || 0;
        const s = parseFloat(durationS.value) || 0;
        return (h * 3600) + (m * 60) + s;
    }

    /**
     * Performs the main calculation for total file size.
     */
    function calculateFileSize() {
        resultsList.innerHTML = '';
        const videoBitrate = parseFloat(videoBitrateValue.value);
        const audioBitrate = parseFloat(audioBitrateValue.value);
        const durationSec = durationToSeconds();

        const errors = [];

        // --- Validation ---
        if (isNaN(videoBitrate) || videoBitrate < 1) errors.push("Please enter a valid, positive Video Bitrate (kbps).");
        if (isNaN(audioBitrate) || audioBitrate < 0) errors.push("Please enter a valid, non-negative Audio Bitrate (kbps).");
        if (durationSec <= 0) errors.push("Please enter a positive Duration (h:m:s).");

        if (errors.length > 0) {
            resultsList.innerHTML = errors.map(err => `<div class="alert alert-danger">${err}</div>`).join('');
            return;
        }

        // --- Calculation ---
        const totalBitrate = videoBitrate + audioBitrate; // Total kbps

        // Total Size (MB) = Total Bitrate (kbps) * Duration (s) * Conversion Factor
        const totalSizeMB = totalBitrate * durationSec * KBPS_SECONDS_TO_MB_FACTOR;

        // --- Calculate individual stream sizes for breakdown ---
        const videoSizeMB = videoBitrate * durationSec * KBPS_SECONDS_TO_MB_FACTOR;
        const audioSizeMB = audioBitrate * durationSec * KBPS_SECONDS_TO_MB_FACTOR;

        // --- Render Results ---

        // 1. Total Result
        renderResult('Total Estimated File Size', totalSizeMB, 'MB', 'e91e63', 'white', '#c2185b');

        // 2. Breakdown and Inputs Echo
        renderResult('Video Stream Size', videoSizeMB, 'MB', '607d8b', '#343a40', '#eceff1');
        renderResult('Audio Stream Size', audioSizeMB, 'MB', '607d8b', '#343a40', '#eceff1');
        renderResult('Total Duration Input', secondsToHMS(durationSec), 'h:m:s', '607d8b', '#343a40', '#eceff1');
    }

    /**
     * Converts total seconds into H:M:S format string.
     */
    function secondsToHMS(totalSeconds) {
        if (totalSeconds < 0 || isNaN(totalSeconds)) return "00h : 00m : 00s";

        const h = Math.floor(totalSeconds / 3600);
        const m = Math.floor((totalSeconds % 3600) / 60);
        const s = Math.round(totalSeconds % 60);

        const pad = (num) => String(num).padStart(2, '0');
        return `${pad(h)}h : ${pad(m)}m : ${pad(s)}s`;
    }

    /**
     * Renders a single result item.
     */
    function renderResult(name, value, unit, borderColor, valueColor, backgroundColor) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');
        item.style.borderLeftColor = `#${borderColor}`;

        let displayValue = (typeof value === 'number') ? value.toFixed(3) : value;
        let unitColor = valueColor === 'white' ? '#fdd835' : '#e91e63';
        let nameColor = valueColor === 'white' ? 'white' : '#455a64';


        item.innerHTML = `
            <div class="unit-name" style="color: ${nameColor};">${name}</div>
            <div class="unit-value" style="background-color: ${backgroundColor}; color: ${valueColor}; font-size: 1.3rem;">
                ${displayValue} <span style="font-size: 0.8em; font-weight: normal; color: ${unitColor};">${unit}</span>
            </div>
        `;
        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Recalculate on any input change
        document.querySelectorAll('.input-field').forEach(input => {
            input.addEventListener('input', calculateFileSize);
            input.addEventListener('change', calculateFileSize);
        });

        calculateFileSize(); // Initial calculation
    }

    window.onload = function() {
        setupListeners();
    };

conversion_calculator__viscosity_convert:
// --- CONSTANTS ---
    // Dynamic Viscosity: Pa·s to cP
    const PaS_TO_CP_FACTOR = 1000; // 1 Pa·s = 1000 cP
    // Kinematic Viscosity: m²/s to cSt
    const M2S_TO_CST_FACTOR = 1000000; // 1 m²/s = 1,000,000 cSt

    // --- DOM Elements ---
    const inputValue = document.getElementById('inputValue');
    const inputUnitSelect = document.getElementById('inputUnitSelect');
    const resultsList = document.getElementById('resultsList');

    /**
     * Converts the viscosity value based on the selected unit.
     */
    function convertViscosity() {
        resultsList.innerHTML = '';
        const value = parseFloat(inputValue.value);
        const inputUnit = inputUnitSelect.value;

        if (isNaN(value) || value < 0) {
            resultsList.innerHTML = `<div class="alert alert-danger">Please enter a valid non-negative number.</div>`;
            return;
        }

        let results = [];

        // --- DYNAMIC VISCOSITY CONVERSIONS (Pa·s and cP) ---
        if (inputUnit === 'PaS' || inputUnit === 'cP') {
            let PaS_value;

            if (inputUnit === 'PaS') {
                PaS_value = value;
                results.push({ name: 'Input', unit: 'Pa·s', value: value.toFixed(6) });
            } else { // cP
                PaS_value = value / PaS_TO_CP_FACTOR;
                results.push({ name: 'Input', unit: 'cP', value: value.toFixed(6) });
            }

            // Output in Pa·s
            if (inputUnit !== 'PaS') {
                results.push({ name: 'Pascal-seconds (SI)', unit: 'Pa·s', value: PaS_value.toFixed(10) });
            }

            // Output in cP
            const cP_value = PaS_value * PaS_TO_CP_FACTOR;
            if (inputUnit !== 'cP') {
                results.push({ name: 'Centipoise (cgs)', unit: 'cP', value: cP_value.toFixed(6) });
            }

            // Note on Kinematic
            results.push({ 
                name: 'Kinematic Viscosity Note', 
                unit: '', 
                value: 'Requires density to convert to kinematic units ($\text{m}^2/\text{s}$, $\text{cSt}$).', 
                isNote: true 
            });


        // --- KINEMATIC VISCOSITY CONVERSIONS (m²/s and cSt) ---
        } else if (inputUnit === 'm2S' || inputUnit === 'cSt') {
            let m2S_value;

            if (inputUnit === 'm2S') {
                m2S_value = value;
                results.push({ name: 'Input', unit: '$\text{m}^2/\text{s}$', value: value.toFixed(8) });
            } else { // cSt
                m2S_value = value / M2S_TO_CST_FACTOR;
                results.push({ name: 'Input', unit: 'cSt', value: value.toFixed(6) });
            }

            // Output in m²/s
            if (inputUnit !== 'm2S') {
                results.push({ name: 'Square meters/second (SI)', unit: '$\text{m}^2/\text{s}$', value: m2S_value.toFixed(12) });
            }

            // Output in cSt
            const cSt_value = m2S_value * M2S_TO_CST_FACTOR;
            if (inputUnit !== 'cSt') {
                results.push({ name: 'Centistokes (cgs)', unit: 'cSt', value: cSt_value.toFixed(6) });
            }

             // Note on Dynamic
            results.push({ 
                name: 'Dynamic Viscosity Note', 
                unit: '', 
                value: 'Requires density to convert to dynamic units ($\text{Pa} \cdot \text{s}$, $\text{cP}$).', 
                isNote: true 
            });
        }

        // --- Render Results ---
        results.forEach(res => {
            renderResult(res.name, res.value, res.unit, res.isNote);
        });
    }

    /**
     * Renders a single result item.
     * @param {string} name - The name of the result/unit.
     * @param {string} value - The numerical value.
     * @param {string} unit - The unit abbreviation.
     * @param {boolean} isNote - If true, style as a note/alert.
     */
    function renderResult(name, value, unit, isNote = false) {
        const item = document.createElement('div');
        item.classList.add('list-group-item');

        if (isNote) {
             item.style.borderLeftColor = '#3498db'; /* Blue for info */
             item.style.backgroundColor = '#eef7ff';
             item.innerHTML = `
                <div class="unit-name" style="color:#3498db">${name}</div>
                <div style="font-size: 0.9rem; color: #34495e; font-style: italic; margin-top: 5px;">${value}</div>
             `;
        } else {
             item.innerHTML = `
                <div class="unit-name">${name}</div>
                <div class="unit-value">
                    ${value} <span style="font-size: 0.8em; font-weight: normal; color: #f39c12;">${unit}</span>
                </div>
            `;
        }

        resultsList.appendChild(item);
    }

    // --- Initialization & Event Listeners ---

    function setupListeners() {
        // Use 'input' event for live updates on value change
        inputValue.addEventListener('input', convertViscosity);
        // Use 'change' event for unit switch
        inputUnitSelect.addEventListener('change', convertViscosity);
    }

