        document.getElementById('table-title').classList.add('d-none');
        document.getElementById('bd-table').classList.add('d-none');
    }

    function parseHolidays(holidayText) {
        const holidaySet = new Set();
        const lines = holidayText.split('\n');

        lines.forEach(line => {
            const dateStr = line.trim();
            if (dateStr) {
                // Check format YYYY-MM-DD (or similar)
                if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
                    // Create a Date object to validate if it's a real date
                    const date = new Date(dateStr);
                    // Check if date object is valid and the date components match the string (for strict validation)
                    if (!isNaN(date.getTime())) {
                        holidaySet.add(dateStr);
                    }
                }
            }
        });
        return holidaySet;
    }

    document.getElementById('business-days-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const startDateStr = document.getElementById('start-date').value;
        const endDateStr = document.getElementById('end-date').value;
        const holidayText = document.getElementById('holidays-input').value;

        // Standardize dates to start of day UTC to avoid local timezone issues
        const start = new Date(startDateStr);
        const end = new Date(endDateStr);

        const startDate = new Date(Date.UTC(start.getFullYear(), start.getMonth(), start.getDate()));
        const endDate = new Date(Date.UTC(end.getFullYear(), end.getMonth(), end.getDate()));

        // 2. Validation
        if (startDate.getTime() > endDate.getTime()) {
            displayError("The **Start Date** must be before or the same as the **End Date**.");
            return;
        }

        // 3. Process Holidays
        const holidaySet = parseHolidays(holidayText);

        let businessDays = 0;
        let weekendDays = 0;
        let holidayDays = 0;
        let totalDays = 0;

        // 4. Iterate through dates (inclusive of end date)
        let currentDate = new Date(startDate.getTime());

        while (currentDate.getTime() <= endDate.getTime()) {
            totalDays++;
            const dayOfWeek = currentDate.getUTCDay(); // 0 = Sunday, 6 = Saturday

            // Format current date for holiday lookup (YYYY-MM-DD)
            const currentYear = currentDate.getUTCFullYear();
            const currentMonth = String(currentDate.getUTCMonth() + 1).padStart(2, '0');
            const currentDay = String(currentDate.getUTCDate()).padStart(2, '0');
            const currentDateStr = `${currentYear}-${currentMonth}-${currentDay}`;

            const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);
            const isHoliday = holidaySet.has(currentDateStr);

            if (isWeekend) {
                weekendDays++;
            } else if (isHoliday) {
                holidayDays++;
            } else {
                businessDays++;
            }

            // Move to the next day
            currentDate.setUTCDate(currentDate.getUTCDate() + 1);
        }

        // 5. Update Result Display (Main)
        const res = document.getElementById('bd-result');
        res.classList.remove('d-none', 'alert-danger');
        res.classList.add('alert-success');

        res.innerHTML = `
**Total Calculated Business Days:**
<span class="days-highlight">${businessDays.toLocaleString()} days</span>
`;

        // 6. Update Summary Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('bd-table').classList.remove('d-none');
        const tableBody = document.getElementById('bd-body');

        tableBody.innerHTML = `
            <tr><td>Start Date</td><td>${startDateStr}</td></tr>
            <tr><td>End Date</td><td>${endDateStr}</td></tr>
            <tr><td>Total Days in Range</td><td>${totalDays.toLocaleString()} days</td></tr>
            <tr><td style="font-weight: bold;">Business Days (M-F, not holiday)</td><td style="font-weight: bold; color: #198754;">${businessDays.toLocaleString()} days</td></tr>
            <tr><td>Weekend Days Excluded</td><td>${weekendDays.toLocaleString()} days</td></tr>
            <tr><td>Holiday Days Excluded</td><td>${holidayDays.toLocaleString()} days</td></tr>
        `;
    });

date_time__chronological_age_calculator:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper to get the number of days in a given month/year
    function daysInMonth(month, year) {
        // month is 1-based (1 for January, 12 for December)
        return new Date(year, month, 0).getDate();
    }

    // Helper to format date strings for display
    function formatReadableDate(dateStr) {
        const date = new Date(dateStr + 'T00:00:00');
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }


    function calculateChronologicalAge(dobStr, calcDateStr) {
        const dob = new Date(dobStr + 'T00:00:00');
        const calcDate = new Date(calcDateStr + 'T00:00:00');

        if (dob > calcDate) {
            throw new Error("Date of Birth cannot be later than the Calculation Date.");
        }

        let ageY = calcDate.getFullYear() - dob.getFullYear();
        let ageM = calcDate.getMonth() - dob.getMonth();
        let ageD = calcDate.getDate() - dob.getDate();

        // 1. Adjust Days
        if (ageD < 0) {
            ageM--;
            // Find the number of days in the month *before* the current calculation date month
            // Note: getMonth() returns 0-11. We pass the month number to daysInMonth function, 
            // which handles the year change if calcDate.getMonth() is 0 (January).
            const daysLastMonth = daysInMonth(calcDate.getMonth(), calcDate.getFullYear());
            ageD += daysLastMonth;
        }

        // 2. Adjust Months
        if (ageM < 0) {
            ageY--;
            ageM += 12;
        }

        return { years: ageY, months: ageM, days: ageD };
    }

    // --- Event Handler ---

    document.getElementById('age-calculator-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const dobStr = document.getElementById('dob').value;
        const calcDateStr = document.getElementById('calc-date').value;

        if (!dobStr || !calcDateStr) {
            displayStatus("Please select both the Date of Birth and the Calculation Date.", true);
            return;
        }

        try {
            // 1. Perform Calculation
            const age = calculateChronologicalAge(dobStr, calcDateStr);

            // 2. Display Results
            const totalYearsStr = `${age.years} year${age.years !== 1 ? 's' : ''}`;
            const totalMonthsStr = `${age.months} month${age.months !== 1 ? 's' : ''}`;
            const totalDaysStr = `${age.days} day${age.days !== 1 ? 's' : ''}`;

            document.getElementById('age-summary').innerText = totalYearsStr;
            document.getElementById('age-years').innerText = totalYearsStr;
            document.getElementById('age-months').innerText = totalMonthsStr;
            document.getElementById('age-days').innerText = totalDaysStr;

            document.getElementById('dob-display').innerText = formatReadableDate(dobStr);
            document.getElementById('calc-date-display').innerText = formatReadableDate(calcDateStr);

            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation Error:", error);
            displayStatus(error.message, true);
        }
    });

    // Set default dates
    document.addEventListener('DOMContentLoaded', () => {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        const todayStr = `${yyyy}-${mm}-${dd}`;

        // Default Calculation Date to Today
        document.getElementById('calc-date').value = todayStr;

        // Default DOB to 30 years ago (a reasonable default)
        const defaultDOB = new Date();
        defaultDOB.setFullYear(today.getFullYear() - 30);
        const dobY = defaultDOB.getFullYear();
        const dobM = String(defaultDOB.getMonth() + 1).padStart(2, '0');
        const dobD = String(defaultDOB.getDate()).padStart(2, '0');
        document.getElementById('dob').value = `${dobY}-${dobM}-${dobD}`;
    });

