function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    /**
     * Toggles the visibility of the relevant input groups based on the selected rule.
     */
    function toggleInputGroups() {
        const workType = document.getElementById('work-type').value;
        const groupLife = document.getElementById('group-life-plus-70');
        const groupWork = document.getElementById('group-work-for-hire');

        // Hide all first
        groupLife.style.display = 'none';
        groupWork.style.display = 'none';

        // Set input fields to not required when hidden
        document.getElementById('death-year').required = false;
        document.getElementById('publication-year').required = false;
        document.getElementById('creation-year').required = false;

        // Show and set required for the selected group
        if (workType === 'life_plus_70') {
            groupLife.style.display = 'block';
            document.getElementById('death-year').required = true;
        } else if (workType === 'work_for_hire') {
            groupWork.style.display = 'block';
            document.getElementById('publication-year').required = true;
            document.getElementById('creation-year').required = true;
        }
    }

    // --- Core Calculation Logic ---
    document.getElementById('copyright-calculator-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const workType = document.getElementById('work-type').value;
        let finalExpirationYear = null;
        let ruleSummary = '';
        let calculationDetail = '';

        if (!workType) {
            displayStatus("Please select a Type of Copyrighted Work.", true);
            return;
        }

        try {
            if (workType === 'life_plus_70') {
                const deathYear = parseInt(document.getElementById('death-year').value, 10);
                if (isNaN(deathYear)) {
                    throw new Error("Please enter a valid Year of Author's Death.");
                }

                finalExpirationYear = deathYear + 70;
                ruleSummary = "Individual Author (Life + 70 Years)";
                calculationDetail = `${deathYear} + 70 = ${finalExpirationYear}`;

            } else if (workType === 'work_for_hire') {
                const pubYear = parseInt(document.getElementById('publication-year').value, 10);
                const creationYear = parseInt(document.getElementById('creation-year').value, 10);

                if (isNaN(pubYear) || isNaN(creationYear)) {
                    throw new Error("Please enter valid years for both Publication and Creation.");
                }

                // Rule 1: 95 years from publication
                const yearPub95 = pubYear + 95;
                const detailPub = `${pubYear} + 95 = ${yearPub95}`;

                // Rule 2: 120 years from creation
                const yearCreate120 = creationYear + 120;
                const detailCreate = `${creationYear} + 120 = ${yearCreate120}`;

                // Work for Hire uses the shorter of the two terms
                finalExpirationYear = Math.min(yearPub95, yearCreate120);
                ruleSummary = "Corporate / Anonymous (Shorter of 95/120 Years)";
                calculationDetail = `Shorter of (${detailPub}) and (${detailCreate}) = ${finalExpirationYear}`;

            }

            if (finalExpirationYear === null) {
                throw new Error("Calculation failed. Check all input fields.");
            }

            // 1. Calculate Expiration Date (always December 31st of the final year)
            // Use local time zone (YYYY, M-1, D)
            const expirationDate = new Date(finalExpirationYear, 11, 31); // Month 11 is December

            // 2. Format and Display Results
            const formattedDate = expirationDate.toLocaleDateString('en-US', { 
                weekday: 'long', 
                year: 'numeric', 
                month: 'long', 
                day: 'numeric' 
            });

            document.getElementById('final-expiration-date').innerText = formattedDate;
            document.getElementById('expiration-year-summary').innerText = `The work enters the Public Domain on January 1, ${finalExpirationYear + 1}`;
            document.getElementById('rule-used-summary').innerText = ruleSummary;
            document.getElementById('final-year-summary').innerText = `${finalExpirationYear} (Calculated from: ${calculationDetail})`;


            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Copyright Calculation Error:", error);
            displayStatus(`Calculation error: ${error.message}. Please check your inputs.`, true);
        }
    });

    // --- Initialization ---
    document.addEventListener('DOMContentLoaded', () => {
        // Set maximum year to the current year
        const currentYear = new Date().getFullYear();
        document.getElementById('death-year').max = currentYear;
        document.getElementById('publication-year').max = currentYear;
        document.getElementById('creation-year').max = currentYear;

        // Initial setup for input groups
        toggleInputGroups();
    });

date_time__countdown_to_specific_event:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Global variable to hold the countdown interval
    let countdownInterval;

    // Helper function to pad numbers with a leading zero
    function pad(num) {
        return num.toString().padStart(2, '0');
    }

    function updateCountdown(targetDateTime, eventName) {
        const now = new Date().getTime();
        const distance = targetDateTime.getTime() - now;

        const daysElement = document.getElementById('countdown-days');
        const hoursElement = document.getElementById('countdown-hours');
        const minutesElement = document.getElementById('countdown-minutes');
        const secondsElement = document.getElementById('countdown-seconds');
        const messageElement = document.getElementById('event-message');

        // Check if the countdown is over
        if (distance < 0) {
            clearInterval(countdownInterval);
            daysElement.innerText = '00';
            hoursElement.innerText = '00';
            minutesElement.innerText = '00';
            secondsElement.innerText = '00';
            messageElement.innerHTML = `🎉 **${eventName} is happening NOW!**`;
            return;
        }

        // Time calculations
        const oneSecond = 1000;
        const oneMinute = oneSecond * 60;
        const oneHour = oneMinute * 60;
        const oneDay = oneHour * 24;

        const days = Math.floor(distance / oneDay);
        const hours = Math.floor((distance % oneDay) / oneHour);
        const minutes = Math.floor((distance % oneHour) / oneMinute);
        const seconds = Math.floor((distance % oneMinute) / oneSecond);

        // Display the result
        daysElement.innerText = pad(days);
        hoursElement.innerText = pad(hours);
        minutesElement.innerText = pad(minutes);
        secondsElement.innerText = pad(seconds);

        messageElement.innerHTML = `Counting down to: ${targetDateTime.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })} at ${targetDateTime.toLocaleTimeString('en-US')}`;
    }

    // --- Event Handler ---

    document.getElementById('countdown-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // Clear any existing timer
        if (countdownInterval) {
            clearInterval(countdownInterval);
        }

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const eventName = document.getElementById('event-name').value;
        const targetDateStr = document.getElementById('target-date').value;
        const targetTimeStr = document.getElementById('target-time').value;

        if (!eventName || !targetDateStr || !targetTimeStr) {
            displayStatus("Please fill in all event details (Name, Date, and Time).", true);
            return;
        }

        try {
            // Combine date and time strings into a single valid format (Local Time)
            const targetDateTimeString = `${targetDateStr}T${targetTimeStr}:00`;
            const targetDateTime = new Date(targetDateTimeString);

            // Validation check (if Date object is invalid or in the past)
            if (isNaN(targetDateTime.getTime())) {
                throw new Error("Invalid date or time format.");
            }
            if (targetDateTime.getTime() <= new Date().getTime()) {
                displayStatus("The target date/time must be in the future.", true);
                return;
            }

            // 1. Prepare Results Display
            document.getElementById('countdown-event-title').innerText = `Countdown to ${eventName}`;
            document.getElementById('results-container').classList.remove('d-none');

            // 2. Start Live Countdown
            // Run once immediately to avoid a 1-second delay
            updateCountdown(targetDateTime, eventName); 
            // Set up the interval to run every second (1000ms)
            countdownInterval = setInterval(() => updateCountdown(targetDateTime, eventName), 1000);

        } catch (error) {
            console.error("Countdown Initialization Error:", error);
            displayStatus(`Failed to start countdown: ${error.message}`, true);
        }
    });

    // Set default target date/time (e.g., next New Year)
    document.addEventListener('DOMContentLoaded', () => {
        const today = new Date();
        const nextYear = today.getFullYear() + 1;

        // Target: January 1st, next year, 00:00
        const defaultTargetDateStr = `${nextYear}-01-01`;

        document.getElementById('target-date').value = defaultTargetDateStr;
        document.getElementById('target-time').value = '00:00';
    });

date_time__court_filing_deadline_calcula:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // --- Federal Holidays for 2025 (YYYY-MM-DD format) ---
    // NOTE: These must be manually updated for future years.
    const HOLIDAYS = [
        { date: '2025-01-01', name: 'New Year\'s Day' },
        { date: '2025-01-20', name: 'M.L. King, Jr.\'s Birthday' },
        { date: '2025-02-17', name: 'Washington\'s Birthday' },
        { date: '2025-05-26', name: 'Memorial Day' },
        { date: '2025-06-19', name: 'Juneteenth' },
        { date: '2025-07-04', name: 'Independence Day' },
        { date: '2025-09-01', name: 'Labor Day' },
        { date: '2025-10-13', name: 'Columbus Day' },
        { date: '2025-11-11', name: 'Veterans Day' },
        { date: '2025-11-27', name: 'Thanksgiving Day' },
        { date: '2025-12-25', name: 'Christmas Day' },
    ];

    /**
     * Checks if a given Date object falls on a weekend or a defined holiday.
     * @param {Date} date The date to check.
     * @returns {boolean} True if the date is a non-business day.
     */
    function isNonBusinessDay(date) {
        const dayOfWeek = date.getDay(); // 0 (Sunday) to 6 (Saturday)

        // 1. Check for Weekend
        if (dayOfWeek === 0 || dayOfWeek === 6) {
            return true; // Sunday or Saturday
        }

        // 2. Check for Holiday
        const dateString = date.toISOString().slice(0, 10); // YYYY-MM-DD
        const isHoliday = HOLIDAYS.some(holiday => holiday.date === dateString);

        return isHoliday;
    }


    function calculateDeadline(startDate, businessDays) {
        let currentDate = new Date(startDate.getTime());
        let daysToCount = businessDays;
        let rollForwardNote = '';

        // Advance to the day *after* the trigger date to begin counting
        currentDate.setDate(currentDate.getDate()); 

        while (daysToCount > 0) {
            currentDate.setDate(currentDate.getDate() + 1); // Move to the next calendar day

            // Skip the current day if it's a non-business day, but don't count it down
            if (!isNonBusinessDay(currentDate)) {
                daysToCount--; // Only decrement if it's a business day
            }
        }

        // 3. Final Roll-Forward Check: If the calculated deadline is a non-business day, roll forward.
        if (isNonBusinessDay(currentDate)) {
            rollForwardNote = 'The calculated deadline initially fell on a non-business day. It has been rolled forward to the next business day.';
            let rolledDays = 0;
            while (isNonBusinessDay(currentDate)) {
                currentDate.setDate(currentDate.getDate() + 1);
                rolledDays++;
            }
            if (rolledDays > 0) {
                rollForwardNote = `(Rolled forward ${rolledDays} day${rolledDays > 1 ? 's' : ''} to the next business day)`;
            }
        }

        return {
            deadlineDate: currentDate,
            rollForwardNote: rollForwardNote
        };
    }

    // Helper to format a Date object into a readable string
    function formatDate(date) {
        return date.toLocaleDateString('en-US', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });
    }

    // --- Initialization and Setup ---
    function initialize() {
        // Set default trigger date to today
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');

        document.getElementById('trigger-date').value = `${yyyy}-${mm}-${dd}`;

        // Populate holiday list
        const holidayListDiv = document.getElementById('holiday-list');
        holidayListDiv.innerHTML = HOLIDAYS.map(h => 
            `<li><strong>${h.name}</strong>: ${new Date(h.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</li>`
        ).join('');
    }


    // --- Event Handler ---
    document.getElementById('deadline-calculator-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const triggerDateStr = document.getElementById('trigger-date').value;
        const ruleDaysStr = document.getElementById('rule-days').value;

        const triggerDate = new Date(triggerDateStr);
        const ruleDays = parseInt(ruleDaysStr, 10);

        if (isNaN(triggerDate.getTime()) || !triggerDateStr) {
            displayStatus("Please select a valid Trigger Date.", true);
            return;
        }
        if (isNaN(ruleDays) || ruleDays < 1) {
            displayStatus("Please enter a valid number of Rule Days (must be 1 or more).", true);
            return;
        }

        try {
            // 1. Calculate the Deadline
            const result = calculateDeadline(triggerDate, ruleDays);

            // 2. Format and Display Results
            const formattedDeadlineDate = formatDate(result.deadlineDate);

            document.getElementById('final-deadline-date').innerText = formattedDeadlineDate;
            document.getElementById('trigger-date-summary').innerText = formatDate(triggerDate);
            document.getElementById('rule-days-summary').innerText = ruleDays;

            const notesElement = document.getElementById('deadline-notes');
            notesElement.innerText = result.rollForwardNote || "Filing date falls on a standard business day.";
            notesElement.style.color = result.rollForwardNote ? '#dc143c' : '#555';


            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Deadline Calculation Error:", error);
            displayStatus(`An error occurred during calculation: ${error.message}`, true);
        }
    });

    // Run initialization
    document.addEventListener('DOMContentLoaded', initialize);

date_time__credit_card_payment_due_date_:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper function to format a Date object into a readable string
    function formatReadableDate(date) {
        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }

    /**
     * Calculates the payment due date by adding the grace period to the statement closing date.
     * @param {string} closingDateStr The statement closing date string (YYYY-MM-DD).
     * @param {number} gracePeriodDays The number of days in the grace period.
     * @returns {Date} The calculated payment due date.
     */
    function calculateDueDate(closingDateStr, gracePeriodDays) {
        // Create a copy of the closing date
        const closingDate = new Date(closingDateStr + 'T00:00:00');

        // Add the grace period to the closing date
        const dueDate = new Date(closingDate);
        dueDate.setDate(closingDate.getDate() + gracePeriodDays);

        return dueDate;
    }

    // --- Event Handler ---

    document.getElementById('due-date-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const closingDateStr = document.getElementById('closing-date').value;
        const gracePeriodStr = document.getElementById('grace-period').value;
        const gracePeriodDays = parseInt(gracePeriodStr, 10);

        if (!closingDateStr || isNaN(gracePeriodDays) || gracePeriodDays < 15) {
            displayStatus("Please enter a valid closing date and a grace period of 15 days or more.", true);
            return;
        }

        try {
            // 1. Perform Calculation
            const dueDate = calculateDueDate(closingDateStr, gracePeriodDays);

            // 2. Display Results
            const dateReadable = formatReadableDate(dueDate);
            const closingDateReadable = formatReadableDate(new Date(closingDateStr + 'T00:00:00'));

            document.getElementById('result-title').innerText = `Payment Due Date`;
            document.getElementById('calculated-due-date').innerText = dateReadable;
