date_time__custom_countdown_timer:
const MS_PER_SECOND = 1000;
    const MS_PER_MINUTE = 60 * MS_PER_SECOND;
    const MS_PER_HOUR = 60 * MS_PER_MINUTE;
    const MS_PER_DAY = 24 * MS_PER_HOUR;

    let countdownInterval;

    function displayError(message) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-info');
        statusDiv.classList.add('alert-danger');
        statusDiv.innerHTML = `**Error:** ${message}`;
        document.getElementById('timer-display').classList.add('d-none');
        document.getElementById('timer-title').classList.add('d-none');
    }

    function updateTimer(targetTime) {
        const now = new Date().getTime();
        const distance = targetTime - now;

        const statusDiv = document.getElementById('status-message');
        const timerDisplay = document.getElementById('timer-display');

        if (distance < 0) {
            clearInterval(countdownInterval);

            // Display final 00:00:00
            document.getElementById('days').innerText = '00';
            document.getElementById('hours').innerText = '00';
            document.getElementById('minutes').innerText = '00';
            document.getElementById('seconds').innerText = '00';

            // Show completion message
            statusDiv.classList.remove('d-none', 'alert-danger', 'alert-info');
            statusDiv.classList.add('alert-success');
            statusDiv.innerHTML = '🎉 **COUNTDOWN COMPLETE!** The target time has been reached.';

            document.getElementById('start-button').classList.remove('d-none');
            document.getElementById('stop-button').classList.add('d-none');
            return;
        }

        // Calculation time units
        const days = Math.floor(distance / MS_PER_DAY);
        const hours = Math.floor((distance % MS_PER_DAY) / MS_PER_HOUR);
        const minutes = Math.floor((distance % MS_PER_HOUR) / MS_PER_MINUTE);
        const seconds = Math.floor((distance % MS_PER_MINUTE) / MS_PER_SECOND);

        // Display results
        const pad = (num) => String(num).padStart(2, '0');
        document.getElementById('days').innerText = pad(days);
        document.getElementById('hours').innerText = pad(hours);
        document.getElementById('minutes').innerText = pad(minutes);
        document.getElementById('seconds').innerText = pad(seconds);

        timerDisplay.classList.remove('d-none');
        document.getElementById('timer-title').classList.remove('d-none');
        statusDiv.classList.add('d-none');
    }

    function startCountdown() {
        // Clear any existing interval
        if (countdownInterval) {
            clearInterval(countdownInterval);
        }

        const dateStr = document.getElementById('target-date').value;
        const timeStr = document.getElementById('target-time').value;

        if (!dateStr || !timeStr) {
            displayError("Please set both a target date and time.");
            return;
        }

        // Create the target timestamp in milliseconds (local time)
        const targetDateTime = new Date(`${dateStr}T${timeStr}:00`);
        const targetTime = targetDateTime.getTime();

        if (isNaN(targetTime)) {
             displayError("Invalid date or time format.");
            return;
        }

        const now = new Date().getTime();
        if (targetTime <= now) {
            displayError("The target time must be in the future.");
            return;
        }

        // Initial update
        updateTimer(targetTime);

        // Start the continuous update
        countdownInterval = setInterval(() => updateTimer(targetTime), 1000);

        // Update button visibility
        document.getElementById('start-button').classList.add('d-none');
        document.getElementById('stop-button').classList.remove('d-none');
    }

    function stopCountdown() {
        if (countdownInterval) {
            clearInterval(countdownInterval);
            countdownInterval = null;
        }

        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger');
        statusDiv.classList.add('alert-info');
        statusDiv.innerHTML = '⏸️ **Countdown Paused.** Click Start Countdown to resume.';

        document.getElementById('start-button').classList.remove('d-none');
        document.getElementById('stop-button').classList.add('d-none');
    }

    // Attach event listeners
    document.getElementById('countdown-form').addEventListener('submit', function (e) {
        e.preventDefault();
        startCountdown();
    });

    document.getElementById('stop-button').addEventListener('click', stopCountdown);

    // Set today's date + 1 day as default
    document.addEventListener('DOMContentLoaded', () => {
        const now = new Date();
        now.setDate(now.getDate() + 1); // Tomorrow
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        const dd = String(now.getDate()).padStart(2, '0');
        document.getElementById('target-date').value = `${yyyy}-${mm}-${dd}`;
    });

date_time__date_addition_and_subtraction:
function displayError(message) {
        const res = document.getElementById('date-math-result');
        res.classList.remove('d-none', 'alert-success');
        res.classList.add('alert-danger');
        res.innerHTML = `**Calculation Error:** ${message}`;
        document.getElementById('table-title').classList.add('d-none');
        document.getElementById('date-math-table').classList.add('d-none');
    }

    document.getElementById('date-math-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const startDateStr = document.getElementById('start-date').value;
        const operation = document.querySelector('input[name="operation"]:checked').value;
        const value = parseInt(document.getElementById('value-input').value, 10);
        const unit = document.getElementById('unit-select').value;

        // Ensure value is positive for calculation
        if (value <= 0 || isNaN(value)) {
            displayError("Duration value must be a positive number.");
            return;
        }

        // Use a mutable copy of the start date
        let currentDate = new Date(startDateStr);

        // Convert start date string to a proper Date object, setting time to midnight UTC to avoid timezone issues with date inputs
        const startYear = currentDate.getUTCFullYear();
        const startMonth = currentDate.getUTCMonth();
        const startDay = currentDate.getUTCDate();

        let resultDate = new Date(Date.UTC(startYear, startMonth, startDay));
        const originalDate = new Date(resultDate.getTime()); // Keep original for display summary

        // Determine multiplier (1 for Add, -1 for Subtract)
        const multiplier = operation === 'add' ? 1 : -1;
        const calculatedValue = value * multiplier;
        let totalDaysCalculated = 0;

        // 2. Perform Calculation
        try {
            switch (unit) {
                case 'day':
                    resultDate.setUTCDate(resultDate.getUTCDate() + calculatedValue);
                    totalDaysCalculated = Math.abs(calculatedValue);
                    break;
                case 'week':
                    // 7 days in a week
                    resultDate.setUTCDate(resultDate.getUTCDate() + (calculatedValue * 7));
                    totalDaysCalculated = Math.abs(calculatedValue * 7);
                    break;
                case 'month':
                    // setUTCMonth handles month/year rollovers correctly
                    resultDate.setUTCMonth(resultDate.getUTCMonth() + calculatedValue);
                    break;
                case 'year':
                    // setUTCFullYear handles rollovers correctly
                    resultDate.setUTCFullYear(resultDate.getUTCFullYear() + calculatedValue);
                    break;
            }
        } catch (e) {
            console.error("Date calculation error:", e);
            displayError("An unexpected error occurred during date calculation.");
            return;
        }

        // 3. Format Result Date
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        const formattedResultDate = resultDate.toLocaleDateString('en-US', options);
        const formattedStart = originalDate.toLocaleDateString('en-US', options);

        // Calculate Total Days (only if unit wasn't day/week, or to confirm accuracy)
        if (unit === 'month' || unit === 'year') {
            const diffTime = Math.abs(resultDate.getTime() - originalDate.getTime());
            totalDaysCalculated = Math.floor(diffTime / (1000 * 60 * 60 * 24));
        }

        // 4. Update Result Display
        const res = document.getElementById('date-math-result');
        res.classList.remove('d-none', 'alert-danger');
        res.classList.add('alert-success');

        const operationText = operation === 'add' ? 'Added' : 'Subtracted';

        res.innerHTML = `
**Starting Date:** ${formattedStart}
**Operation:** ${operationText} ${value} ${unit}${value !== 1 ? 's' : ''}
---
**Resulting Date:** <span style="font-size:1.5rem; color:#0d6efd;">${formattedResultDate}</span>
`;

        // 5. Update Summary Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('date-math-table').classList.remove('d-none');
        const tableBody = document.getElementById('date-math-body');

        tableBody.innerHTML = `
            <tr><td>Start Date</td><td>${formattedStart}</td></tr>
            <tr><td>Duration</td><td>${value} ${unit}${value !== 1 ? 's' : ''}</td></tr>
            <tr><td>Operation Performed</td><td>${operationText}</td></tr>
            <tr><td>Total Days Elapsed/Reversed</td><td>${totalDaysCalculated.toLocaleString()} days</td></tr>
            <tr><td>**Final Date**</td><td>**${formattedResultDate}**</td></tr>
        `;
    });

date_time__date_difference_calculator:
function calculateYMDDifference(startDate, endDate) {
        let years = endDate.getFullYear() - startDate.getFullYear();
        let months = endDate.getMonth() - startDate.getMonth();
        let days = endDate.getDate() - startDate.getDate();

        // Adjust for negative months/days
        if (days < 0) {
            months--;
            // Get the number of days in the previous month of the end date
            const lastMonth = new Date(endDate.getFullYear(), endDate.getMonth(), 0);
            days += lastMonth.getDate();
        }

        if (months < 0) {
            years--;
            months += 12;
        }

        return { years, months, days };
    }

    function displayError(message) {
        const res = document.getElementById('date-diff-result');
        res.classList.remove('d-none', 'alert-success');
        res.classList.add('alert-danger');
        res.innerHTML = `**Calculation Error:** ${message}`;
        document.getElementById('table-title').classList.add('d-none');
        document.getElementById('date-diff-table').classList.add('d-none');
    }

    document.getElementById('date-diff-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const startDateStr = document.getElementById('start-date').value;
        const endDateStr = document.getElementById('end-date').value;
        const includeEndDate = document.getElementById('include-end-date').checked;

        const startDate = new Date(startDateStr);
        const endDate = new Date(endDateStr);

        // 2. Validate Date Order
        if (startDate > endDate) {
            displayError("The **Start Date** must be before or the same as the **End Date**.");
            return;
        }

        // 3. Main Calculation (in milliseconds)
        let diffTime = endDate.getTime() - startDate.getTime();

        // Adjust for "Include End Date"
        if (includeEndDate) {
            diffTime += (1000 * 60 * 60 * 24); // Add 1 day (in milliseconds)
        }

        // 4. Calculate Time Components
        const oneDay = 1000 * 60 * 60 * 24;
        const totalDays = Math.round(diffTime / oneDay);
        const totalWeeks = (totalDays / 7).toFixed(1);
        const totalHours = totalDays * 24;
        const totalMinutes = totalHours * 60;

        // Calculate Years, Months, Days (YMD format)
        let ymdDiff;
        if (includeEndDate) {
            // Need a special handling for YMD when including the end date
            // Add one day to the end date for the YMD calculation
            const adjustedEndDate = new Date(endDate.getTime() + oneDay);
            ymdDiff = calculateYMDDifference(startDate, adjustedEndDate);
        } else {
            ymdDiff = calculateYMDDifference(startDate, endDate);
        }

        // 5. Update Result Display
        const res = document.getElementById('date-diff-result');
        res.classList.remove('d-none', 'alert-danger');
        res.classList.add('alert-success');

        const ymdText = ymdDiff.years > 0 ? `${ymdDiff.years} Year${ymdDiff.years !== 1 ? 's' : ''}, ` : '';
        const mdText = `${ymdDiff.months} Month${ymdDiff.months !== 1 ? 's' : ''}, and ${ymdDiff.days} Day${ymdDiff.days !== 1 ? 's' : ''}`;

        res.innerHTML = `
**Total Duration:** <span style="font-size:1.5rem;">${ymdText}${mdText}</span>
---
**Total Days:** ${totalDays.toLocaleString()} days
`;

        // 6. Update Table Breakdown
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('date-diff-table').classList.remove('d-none');
        const tableBody = document.getElementById('date-diff-body');

        tableBody.innerHTML = `
            <tr><td>Total Years (approx)</td><td>${(totalDays / 365.25).toFixed(2)} years</td></tr>
            <tr><td>Total Months (approx)</td><td>${(totalDays / 30.4375).toFixed(2)} months</td></tr>
            <tr><td>**Total Weeks**</td><td>**${totalWeeks} weeks**</td></tr>
            <tr><td>**Total Days**</td><td>**${totalDays.toLocaleString()} days**</td></tr>
            <tr><td>Total Hours</td><td>${totalHours.toLocaleString()} hours</td></tr>
            <tr><td>Total Minutes</td><td>${totalMinutes.toLocaleString()} minutes</td></tr>
        `;
    });

