date_time__day_of_year_calculator:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    /**
     * Checks if a year is a leap year.
     * @param {number} year The year number.
     * @returns {boolean} True if it is a leap year, false otherwise.
     */
    function isLeapYear(year) {
        // A year is a leap year if it is divisible by 4,
        // except for years divisible by 100 but not by 400.
        return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    }

    /**
     * Calculates the Day of the Year (Ordinal Date).
     * @param {Date} date The input Date object (local time).
     * @returns {number} The day number (1 to 366).
     */
    function calculateDayOfYear(date) {
        // 1. Create a new Date object for January 1st of the same year
        const startOfYear = new Date(date.getFullYear(), 0, 1);

        // 2. Calculate the difference in milliseconds
        // We use Math.floor to ensure we account for any time difference 
        // within the day itself, calculating based on 00:00 to 00:00 boundaries.
        const timeDiff = date.getTime() - startOfYear.getTime();

        // 3. Convert difference to days and add 1 (since the count starts at 1, not 0)
        const dayCount = Math.floor(timeDiff / (1000 * 60 * 60 * 24)) + 1;

        return dayCount;
    }

    // --- Event Handler ---

    document.getElementById('day-of-year-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const dateStr = document.getElementById('target-date').value;

        if (!dateStr) {
            displayStatus("Please select a valid calendar date.", true);
            return;
        }

        // 1. Prepare Date
        // Create Date object in local time for display and calculation
        const targetDate = new Date(dateStr); 

        // 2. Perform Calculation
        const dayOfYear = calculateDayOfYear(targetDate);
        const year = targetDate.getFullYear();
        const isLeap = isLeapYear(year);
        const totalDaysInYear = isLeap ? 366 : 365;
        const daysRemaining = totalDaysInYear - dayOfYear;

        const dateReadable = targetDate.toLocaleDateString('en-US', { 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });

        // 3. Display Results
        document.getElementById('result-date-display').innerText = `Day of Year for ${dateReadable}`;
        document.getElementById('day-of-year-value').innerText = dayOfYear;

        document.getElementById('total-days').innerText = totalDaysInYear;
        document.getElementById('days-remaining').innerText = daysRemaining;
        document.getElementById('year-type').innerText = isLeap ? "Leap Year" : "Standard Year";

        const summary = `
The date ${dateReadable} is the ${dayOfYear}th day of the year ${year}.
There are ${daysRemaining} days remaining until December 31st.
        `;
        document.getElementById('calculation-summary').innerText = summary.trim();

        document.getElementById('results-container').classList.remove('d-none');
    });

    // Set default date to today
    document.addEventListener('DOMContentLoaded', () => {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        document.getElementById('target-date').value = `${yyyy}-${mm}-${dd}`;
    });

date_time__digital_stopwatch:
// State variables
    let startTime; 
    let elapsedTime = 0;
    let timerInterval;
    let isRunning = false;
    let lapCounter = 0;
    let lastLapTime = 0; // The total time of the previous lap measurement

    // DOM references
    const displayMin = document.getElementById('display-min');
    const displaySec = document.getElementById('display-sec');
    const displayMs = document.getElementById('display-ms');
    const startButton = document.getElementById('start-button');
    const pauseButton = document.getElementById('pause-button');
    const lapButton = document.getElementById('lap-button');
    const resetButton = document.getElementById('reset-button');
    const lapList = document.getElementById('lap-list');
    const noLapsMessage = document.getElementById('no-laps-message');

    // Constants
    const MS_PER_SEC = 1000;
    const MS_PER_MIN = 60 * MS_PER_SEC;

    /**
     * Converts milliseconds into formatted time string (MM:SS.MS).
     * @param {number} ms - Total milliseconds elapsed.
     * @returns {string} Formatted time string.
     * @returns {object} Object with formatted components.
     */
    function formatTime(ms) {
        const totalSeconds = Math.floor(ms / MS_PER_SEC);
        const minutes = Math.floor(totalSeconds / 60);
        const seconds = totalSeconds % 60;
        const milliseconds = ms % MS_PER_SEC;

        const pad = (num, length = 2) => String(num).padStart(length, '0');

        return {
            minutes: pad(minutes),
            seconds: pad(seconds),
            milliseconds: pad(milliseconds, 3)
        };
    }

    /**
     * Updates the stopwatch display and handles continuous counting.
     */
    function updateDisplay() {
        elapsedTime = Date.now() - startTime;
        const time = formatTime(elapsedTime);

        displayMin.textContent = time.minutes;
        displaySec.textContent = time.seconds;
        displayMs.textContent = time.milliseconds;
    }

    // --- Control Functions ---

    function startStopwatch() {
        if (!isRunning) {
            // Adjust startTime by subtracting the previous elapsedTime, so it continues from where it paused.
            startTime = Date.now() - elapsedTime;
            timerInterval = setInterval(updateDisplay, 10); // Update every 10ms for smooth milliseconds

            isRunning = true;

            // Update buttons
            startButton.classList.add('d-none');
            pauseButton.classList.remove('d-none');
            lapButton.disabled = false;
            resetButton.disabled = false;
        }
    }

    function pauseStopwatch() {
        if (isRunning) {
            clearInterval(timerInterval);
            isRunning = false;

            // Update buttons
            pauseButton.classList.add('d-none');
            startButton.classList.remove('d-none');
            // Allow lap to be pressed if the user wants to record the final time
            lapButton.disabled = false; 
        }
    }

    function resetStopwatch() {
        clearInterval(timerInterval);
        isRunning = false;
        elapsedTime = 0;
        lapCounter = 0;
        lastLapTime = 0;

        // Reset display
        displayMin.textContent = '00';
        displaySec.textContent = '00';
        displayMs.textContent = '000';

        // Clear laps
        lapList.innerHTML = '';
        noLapsMessage.classList.remove('d-none');

        // Update buttons
        startButton.classList.remove('d-none');
        pauseButton.classList.add('d-none');
        lapButton.disabled = true;
        resetButton.disabled = true;
    }

    function recordLap() {
        if (elapsedTime === 0) return; // Don't record lap if stopped at zero

        lapCounter++;
        const currentLapTime = elapsedTime - lastLapTime;
        lastLapTime = elapsedTime; // Update reference for the next lap

        const totalFormatted = formatTime(elapsedTime);
        const lapFormatted = formatTime(currentLapTime);

        // Build the lap time string (MM:SS.MS)
        const totalTimeStr = `${totalFormatted.minutes}:${totalFormatted.seconds}.${totalFormatted.milliseconds}`;
        const lapTimeStr = `${lapFormatted.minutes}:${lapFormatted.seconds}.${lapFormatted.milliseconds}`;

        const lapItem = document.createElement('div');
        lapItem.className = 'lap-item';

        // Insert the new lap at the top of the list (most recent first)
        lapItem.innerHTML = `
            <span class="lap-number">Lap ${lapCounter}</span>
            <span class="lap-total">${totalTimeStr}</span>
            <span class="lap-time">${lapTimeStr}</span>
        `;

        // Prepend the new lap
        lapList.prepend(lapItem);
        noLapsMessage.classList.add('d-none');
    }

    // --- Event Listeners ---

    startButton.addEventListener('click', startStopwatch);
    pauseButton.addEventListener('click', pauseStopwatch);
    lapButton.addEventListener('click', recordLap);
    resetButton.addEventListener('click', resetStopwatch);

date_time__floating_holiday_date_calcula:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper function to format a Date object into a readable string
    function formatReadableDate(date) {
        return date.toLocaleDateString('en-US', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });
    }

    /**
     * Calculates the date of Easter Sunday using the Meeus/Butcher's algorithm.
     * @param {number} Y The year (Gregorian Calendar).
     * @returns {Date} Date object for Easter Sunday at midnight local time.
     */
    function calculateEaster(Y) {
        // Meeus/Butcher's Algorithm for Gregorian Calendar
        const a = Y % 19;
        const b = Y % 4;
        const c = Y % 7;
        const k = Math.floor(Y / 100);
        const p = Math.floor((13 + 8 * k) / 25);
        const q = Math.floor(k / 4);

        // Lunar Correction (M)
        const M = (15 - p + k - q) % 30;

        // Solar Correction (N)
        const N = (4 + k - q) % 7;

        const d = (19 * a + M) % 30;
        const e = (2 * b + 4 * c + 6 * d + N) % 7;

        // The day of the month (March 22 to April 25)
        const dayOfMonth = 22 + d + e;

        let month;
        let day;

        if (dayOfMonth > 31) {
            // Falls in April
            month = 3; // April (0-indexed month)
            day = dayOfMonth - 31;
        } else {
            // Falls in March
            month = 2; // March (0-indexed month)
            day = dayOfMonth;
        }

        // Return Date object (local time)
        return new Date(Y, month, day);
    }

    /**
     * Finds the Nth day of the week (DOW) in a specific month of a year.
     * @param {number} Y Year.
     * @param {number} M Month (0-11).
     * @param {number} DOW Target Day of Week (0=Sun, 1=Mon... 6=Sat).
     * @param {number} N Which occurrence (1st, 2nd, 3rd, 4th, or -1 for Last).
     * @returns {Date} Date object.
     */
    function findNthWeekday(Y, M, DOW, N) {
        const firstOfMonth = new Date(Y, M, 1);
        let currentDay = new Date(firstOfMonth);

        if (N === -1) {
            // Find Last Weekday: Start at the 1st of the next month and go back one day, then search backward.
            const lastOfMonth = new Date(Y, M + 1, 0); // Day 0 of M+1 is the last day of M
            currentDay = lastOfMonth;

            while (currentDay.getDay() !== DOW) {
                currentDay.setDate(currentDay.getDate() - 1);
            }
            return currentDay;
        } else {
            // Find Nth Weekday: Search forward
            let count = 0;

            while (currentDay.getMonth() === M) {
                if (currentDay.getDay() === DOW) {
                    count++;
                    if (count === N) {
                        return currentDay;
                    }
                }
                currentDay.setDate(currentDay.getDate() + 1);
            }
        }
        return null; // Should not happen for standard Nth weekdays
    }

    // --- Event Handler ---

    document.getElementById('holiday-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const yearStr = document.getElementById('target-year').value;
        const holidayName = document.getElementById('holiday-name').value;
        const Y = parseInt(yearStr, 10);

        if (isNaN(Y) || Y < 1583) {
            displayStatus("Please enter a valid year (1583 or later for Gregorian Calendar accuracy).", true);
            return;
        }

        let calculatedDate = null;
        let summaryText = "";

        switch (holidayName) {
            case 'Easter':
                calculatedDate = calculateEaster(Y);
                summaryText = "Calculated using the Meeus/Butcher's Algorithm, which determines the date based on the Paschal Full Moon.";
                break;

            case 'Thanksgiving':
                // 4th Thursday (DOW 4) in November (Month 10)
                calculatedDate = findNthWeekday(Y, 10, 4, 4);
                summaryText = "US Thanksgiving is observed on the **fourth Thursday** of November.";
                break;

            case 'Memorial Day':
                // Last Monday (DOW 1) in May (Month 4)
                calculatedDate = findNthWeekday(Y, 4, 1, -1); // -1 signifies the last occurrence
                summaryText = "US Memorial Day is observed on the **last Monday** of May.";
                break;

            case 'Labor Day':
                // 1st Monday (DOW 1) in September (Month 8)
                calculatedDate = findNthWeekday(Y, 8, 1, 1);
                summaryText = "US Labor Day is observed on the **first Monday** of September.";
                break;
        }

        if (calculatedDate) {
            const dateReadable = formatReadableDate(calculatedDate);

            document.getElementById('result-holiday-display').innerText = `${holidayName} ${Y}`;
            document.getElementById('calculated-date').innerText = dateReadable;
            document.getElementById('calculation-summary').innerText = summaryText;
            document.getElementById('results-container').classList.remove('d-none');
        } else {
            displayStatus(`Could not calculate the date for ${holidayName} in ${Y}.`, true);
        }
    });

    // Set default year to next year (2026)
    document.addEventListener('DOMContentLoaded', () => {
        document.getElementById('target-year').value = new Date().getFullYear() + 1;
    });

date_time__galactic_time_converter:
function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper function to pad numbers with a leading zero (base 100 system)
    function pad(num) {
        return num.toString().padStart(2, '0');
    }

    /**
     * Converts Earth Time components into a total number of Earth Seconds.
     */
    function totalEarthSeconds(days, hours, minutes, seconds) {
        return (days * 86400) + (hours * 3600) + (minutes * 60) + seconds;
    }



    function convertToGalacticTime(totalEarthSeconds) {
        // --- Galactic Constants ---
        const SECONDS_PER_GD = 30 * 3600; // 108,000 Earth Seconds
        const DAYS_PER_SC = 30;
        const DAYS_PER_GC = 600;

        let remainingEarthSeconds = totalEarthSeconds;

        // --- 1. Calculate Galactic Days (Total) ---
        const totalGalacticDays = remainingEarthSeconds / SECONDS_PER_GD;

        // Use floor for integer days, and the remainder for the sub-day units
        const galacticDaysInteger = Math.floor(totalGalacticDays);
        const subDayFraction = totalGalacticDays - galacticDaysInteger;

        let remainingGD = galacticDaysInteger;

        // --- 2. Calculate GC, SC, and GD ---
        const gc = Math.floor(remainingGD / DAYS_PER_GC);
        remainingGD %= DAYS_PER_GC;

        const sc = Math.floor(remainingGD / DAYS_PER_SC);
        const gd = remainingGD % DAYS_PER_SC;

        // --- 3. Calculate Galactic Hours, Minutes, Seconds (Base 100 system) ---
        // 1 Galactic Day = 1,000,000 Galactic Seconds (GS)
        // Galactic Sub-Day Seconds (Total Galactic Seconds in the fraction)
        const totalGalacticSubDaySeconds = Math.floor(subDayFraction * 1000000); 

        let gsRemaining = totalGalacticSubDaySeconds;

        const gh = Math.floor(gsRemaining / 10000); // 100 GH * 100 GM = 10,000 GS per GH
        gsRemaining %= 10000;

        const gm = Math.floor(gsRemaining / 100); // 100 GS per GM
        const gs = gsRemaining % 100;

        return { gc, sc, gd, gh, gm, gs };
    }

    // --- Event Handler ---

    document.getElementById('galactic-converter-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const earthDays = parseInt(document.getElementById('earth-days').value, 10);
        const earthHours = parseInt(document.getElementById('earth-hours').value, 10);
        const earthMinutes = parseInt(document.getElementById('earth-minutes').value, 10);
        const earthSeconds = parseInt(document.getElementById('earth-seconds').value, 10);

        if (isNaN(earthDays) || isNaN(earthHours) || isNaN(earthMinutes) || isNaN(earthSeconds) || 
            earthDays < 0 || earthHours < 0 || earthMinutes < 0 || earthSeconds < 0) {
            displayStatus("Please enter valid, non-negative numbers for all Earth time fields.", true);
            return;
        }

        try {
            // 1. Calculate Total Earth Seconds
            const totalSec = totalEarthSeconds(earthDays, earthHours, earthMinutes, earthSeconds);

            // 2. Perform Galactic Conversion
            const galacticTime = convertToGalacticTime(totalSec);

            // 3. Format and Display Results

            // Format 1: GC:SC:GD - GH:GM:GS
            const formattedTime = `${pad(galacticTime.gc)}:${pad(galacticTime.sc)}:${pad(galacticTime.gd)} - ${pad(galacticTime.gh)}:${pad(galacticTime.gm)}:${pad(galacticTime.gs)}`;

            document.getElementById('converted-galactic-time').innerText = formattedTime;

            // Breakdown table update
            document.getElementById('breakdown-gc').innerText = galacticTime.gc.toLocaleString();
            document.getElementById('breakdown-sc').innerText = galacticTime.sc.toLocaleString();
            document.getElementById('breakdown-gd').innerText = galacticTime.gd.toLocaleString();
            document.getElementById('breakdown-gh').innerText = galacticTime.gh.toLocaleString();
            document.getElementById('breakdown-gm').innerText = galacticTime.gm.toLocaleString();
            document.getElementById('breakdown-gs').innerText = galacticTime.gs.toLocaleString();

            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Galactic Conversion Error:", error);
            displayStatus("An error occurred during galactic conversion. Please check your input.", true);
        }
    });

