        const dd = String(today.getDate()).padStart(2, '0');
        document.getElementById('start-date').value = `${yyyy}-${mm}-${dd}`;
        document.getElementById('lease-months').value = 12;
    });

date_time__moon_phase_calendar_calculato:
// --- Constants ---
    const SYNODIC_MONTH = 29.530588853; // Average length of a lunation (in days)
    const JULIAN_DAY_2000 = 2451549.5; // Julian Day of a known New Moon (Jan 6, 2000, 18:14 UT)
    const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24;

    function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper function to format a Date object into a readable string
    function formatReadableDate(date) {
        return date.toLocaleDateString('en-US', { 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });
    }

    function dateToJulianDay(date) {
        // Convert local date to milliseconds since Epoch, accounting for local timezone offset
        // We calculate JD at 00:00 UT on the target day.
        const timeInMs = date.getTime() - date.getTimezoneOffset() * 60000;

        // Days since JD Epoch (Jan 1, 4713 BC) at noon.
        // Convert to JD at 00:00 UT
        return (timeInMs / MILLISECONDS_PER_DAY) + 2440587.5;
    }


    function calculateMoonPhase(JD) {
        // 1. Calculate the number of days since the known New Moon (JD_2000)
        const daysSince2000 = JD - JULIAN_DAY_2000;

        // 2. Calculate the number of full lunation cycles passed (N)
        const N = daysSince2000 / SYNODIC_MONTH;

        // 3. Calculate the fraction of the current cycle (F)
        const F = N - Math.floor(N);

        // 4. Moon Age in days (0 to ~29.53)
        const moonAge = F * SYNODIC_MONTH;

        // 5. Calculate Illumination (Approximation based on cosine of phase angle)
        const phaseAngle = 2 * Math.PI * F;
        const illumination = ((1 - Math.cos(phaseAngle)) / 2) * 100;

        // 6. Determine Phase Name based on age (in days)
        let phaseName;
        if (moonAge < 1.84) {
            phaseName = 'New Moon';
        } else if (moonAge < 5.53) {
            phaseName = 'Waxing Crescent';
        } else if (moonAge < 9.23) {
            phaseName = 'First Quarter';
        } else if (moonAge < 12.93) {
            phaseName = 'Waxing Gibbous';
        } else if (moonAge < 16.63) {
            phaseName = 'Full Moon';
        } else if (moonAge < 20.33) {
            phaseName = 'Waning Gibbous';
        } else if (moonAge < 24.03) {
            phaseName = 'Last Quarter';
        } else if (moonAge < 27.73) {
            phaseName = 'Waning Crescent';
        } else {
            phaseName = 'New Moon';
        }

        return {
            age: moonAge,
            illumination: Math.round(illumination * 10) / 10, // Round to one decimal place
            phaseName: phaseName
        };
    }

    /**
     * Calculates the date of the next major moon phase (New or Full).
     * @param {number} JD - Starting Julian Day.
     * @param {string} targetPhase - 'New' (age 0) or 'Full' (age 14.76).
     * @param {number} count - Number of future dates to find.
     * @returns {Array<Date>} Array of target phase dates.
     */
    function calculateNextMajorPhaseDates(JD, targetPhase, count) {
        const dates = [];
        let currentJD = JD;
        let targetFraction; // Target fraction of the cycle (0 for New, 0.5 for Full)

        switch (targetPhase) {
            case 'New':
                targetFraction = 0.0;
                break;
            case 'Full':
                targetFraction = 0.5;
                break;
            default:
                return [];
        }

        // Calculate current fractional position in the cycle
        let N = (currentJD - JULIAN_DAY_2000) / SYNODIC_MONTH;
        let F = N - Math.floor(N);

        // Calculate the days remaining until the target fraction is reached.
        let daysUntilTarget;
        if (targetFraction >= F) {
            // Target is later in the current cycle
            daysUntilTarget = (targetFraction - F) * SYNODIC_MONTH;
        } else {
            // Target is in the next cycle
            daysUntilTarget = (1 + targetFraction - F) * SYNODIC_MONTH;
        }

        currentJD += daysUntilTarget;

        for (let i = 0; i < count; i++) {
            // Convert Julian Day (UT) back to a local Date object (at 00:00 local time)
            // JD at 00:00 UT = days since 2440587.5.
            const dateInMs = (currentJD - 2440587.5) * MILLISECONDS_PER_DAY;

            // Create a Date object in the local timezone
            const nextDate = new Date(dateInMs);

            dates.push(nextDate);

            // Advance to the next cycle
            currentJD += SYNODIC_MONTH;
        }

        return dates;
    }


    // --- Event Handler ---

    document.getElementById('moon-phase-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const dateStr = document.getElementById('target-date').value;

        if (!dateStr) {
            displayStatus("Please select a valid date.", true);
            return;
        }

        // 1. Prepare Date
        const [y, m, d] = dateStr.split('-').map(Number);
        // Date object in local time for display purposes
        const targetDate = new Date(y, m - 1, d); 

        // 2. Convert to Julian Day (JD at 00:00 UT)
        const JD = dateToJulianDay(targetDate);

        // 3. Perform Moon Phase Calculation
        const { age, illumination, phaseName } = calculateMoonPhase(JD);

        // 4. Project Future Phases
        const nextFullMoons = calculateNextMajorPhaseDates(JD, 'Full', 3);
        const nextNewMoons = calculateNextMajorPhaseDates(JD, 'New', 3);

        // 5. Display Results
        document.getElementById('result-date-display').innerText = `Moon Phase for ${formatReadableDate(targetDate)}`;
        document.getElementById('illumination-value').innerText = `${illumination}%`;
        document.getElementById('current-phase').innerText = phaseName;
        document.getElementById('moon-age-days').innerText = `${age.toFixed(2)}`;

        // Populate Full Moon List
        const fullMoonList = document.getElementById('full-moon-list');
        fullMoonList.innerHTML = nextFullMoons.map(date => `<li>${formatReadableDate(date)}</li>`).join('');

        // Populate New Moon List
        const newMoonList = document.getElementById('new-moon-list');
        newMoonList.innerHTML = nextNewMoons.map(date => `<li>${formatReadableDate(date)}</li>`).join('');

        const summary = `
The moon's age is approximately ${age.toFixed(2)} days into the ${SYNODIC_MONTH.toFixed(4)}-day synodic cycle.
Illumination: ${illumination}% of the Moon's face visible from Earth.
        `;
        document.getElementById('calculation-summary').innerText = summary;

        document.getElementById('results-container').classList.remove('d-none');
    });

    // Set default date to today
    document.addEventListener('DOMContentLoaded', () => {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        document.getElementById('target-date').value = `${yyyy}-${mm}-${dd}`;
    });

date_time__overtime_hours_pay_calculator:
const MINUTES_PER_HOUR = 60;
    const MINUTES_PER_DAY = 24 * MINUTES_PER_HOUR;
    let shiftCounter = 0;

    const DEFAULT_DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];

    // Helper function to convert HH:MM string to total minutes from midnight
    function timeToMinutes(timeStr) {
        if (!timeStr) return 0;
        const [hours, minutes] = timeStr.split(':').map(Number);
        return (hours * MINUTES_PER_HOUR) + minutes;
    }

    // Helper function to format total minutes into H:MM string
    function formatMinutesToHours(totalMinutes) {
        if (totalMinutes < 0) return '0:00';
        const hours = Math.floor(totalMinutes / MINUTES_PER_HOUR);
        const minutes = totalMinutes % MINUTES_PER_HOUR;
        const pad = (num) => String(num).padStart(2, '0');
        return `${hours}:${pad(minutes)}`;
    }

    function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    /**
     * Calculates the net work minutes for a single shift.
     */
    function calculateShiftNetMinutes(startStr, endStr, breakMin) {
        if (!startStr || !endStr) return 0;

        const startMin = timeToMinutes(startStr);
        const endMin = timeToMinutes(endStr);
        let grossMin;

        if (endMin < startMin) {
            // Shift crosses midnight
            grossMin = (endMin + MINUTES_PER_DAY) - startMin;
        } else {
            // Standard shift
            grossMin = endMin - startMin;
        }

        const netMin = grossMin - breakMin;
        return Math.max(0, netMin);
    }

    /**
     * Updates the calculated Net Hours for a specific row.
     */
    function updateRowCalculation(rowId) {
        const row = document.getElementById(rowId);
        if (!row) return;

        const startTime = row.querySelector('.start-time').value;
        const endTime = row.querySelector('.end-time').value;
        const breakTime = parseInt(row.querySelector('.break-minutes').value || 0, 10);
        const netHoursCell = row.querySelector('.net-hours-cell');

        const netMinutes = calculateShiftNetMinutes(startTime, endTime, breakTime);
        const formattedNetHours = formatMinutesToHours(netMinutes);

        netHoursCell.innerText = formattedNetHours;
        // The net minutes is stored on the element for easy retrieval when summing the total
        netHoursCell.dataset.netMinutes = netMinutes; 
    }

    /**
     * Creates a new row for the timesheet table.
     */
    function createTimesheetRow(dayLabel, defaultStart = '', defaultEnd = '', defaultBreak = 0) {
        shiftCounter++;
        const rowId = `shift-row-${shiftCounter}`;
        const row = document.createElement('tr');
        row.id = rowId;

        // Define common update function for all input changes
        const updateFunc = `updateRowCalculation('${rowId}')`;

        row.innerHTML = `
            <td>${dayLabel}</td>
            <td><input type="time" class="form-control form-control-sm start-time" value="${defaultStart}" onchange="${updateFunc}" required></td>
            <td><input type="time" class="form-control form-control-sm end-time" value="${defaultEnd}" onchange="${updateFunc}" required></td>
            <td><input type="number" class="form-control form-control-sm break-minutes" min="0" value="${defaultBreak}" onchange="${updateFunc}" required></td>
            <td class="net-hours-cell" data-net-minutes="0">0:00</td>
        `;

        document.getElementById('timesheet-body').appendChild(row);
        updateRowCalculation(rowId);
    }

    // --- Main Submission Logic ---

    document.getElementById('overtime-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const thresholdHours = parseInt(document.getElementById('weekly-threshold').value, 10);
        const regularWage = parseFloat(document.getElementById('regular-wage').value);
        const multiplier = parseFloat(document.getElementById('overtime-rate-multiplier').value);

        if (isNaN(thresholdHours) || thresholdHours <= 0 || isNaN(regularWage) || regularWage < 0 || isNaN(multiplier) || multiplier < 1) {
            displayStatus("Please ensure OT threshold is > 0, Regular Wage is >= 0, and OT Multiplier is >= 1.", true);
            return;
        }

        let totalNetMinutes = 0;
        let totalBreakMinutes = 0;
        let totalGrossMinutes = 0;
        let hasInputError = false;

        const allRows = document.querySelectorAll('#timesheet-body tr');

        // 1. Sum up all net minutes and check for input errors
        allRows.forEach(row => {
            const startStr = row.querySelector('.start-time').value;
            const endStr = row.querySelector('.end-time').value;
            const breakMinInput = row.querySelector('.break-minutes').value;
            const breakMin = parseInt(breakMinInput || 0, 10);

            if (!startStr || !endStr || isNaN(breakMin) || breakMin < 0) {
                 hasInputError = true;
            }

            // Recalculate net minutes for accuracy on submission
            const netMinutes = calculateShiftNetMinutes(startStr, endStr, breakMin);
            const grossMinutes = calculateShiftNetMinutes(startStr, endStr, 0); 

            totalNetMinutes += netMinutes;
            totalBreakMinutes += breakMin;
            totalGrossMinutes += grossMinutes;

            // Update the display for the final time
            row.querySelector('.net-hours-cell').innerText = formatMinutesToHours(netMinutes);
        });

        if (hasInputError) {
            displayStatus("Please ensure all fields are correctly filled for every shift.", true);
            return;
        }

        // 2. Calculate Regular and Overtime Hours
        const thresholdMinutes = thresholdHours * MINUTES_PER_HOUR;

        let regularMinutes = 0;
        let overtimeMinutes = 0;

        if (totalNetMinutes > thresholdMinutes) {
            regularMinutes = thresholdMinutes;
            overtimeMinutes = totalNetMinutes - thresholdMinutes;
        } else {
            regularMinutes = totalNetMinutes;
            overtimeMinutes = 0;
        }

        const regularHours = regularMinutes / MINUTES_PER_HOUR;
        const overtimeHours = overtimeMinutes / MINUTES_PER_HOUR;

        // 3. Calculate Pay
        const overtimeWage = regularWage * multiplier;
        const regularPay = regularHours * regularWage;
        const overtimePay = overtimeHours * overtimeWage;
        const totalGrossPay = regularPay + overtimePay;

        // 4. Display Results
        document.getElementById('total-net-hours').innerText = formatMinutesToHours(totalNetMinutes);
        document.getElementById('total-regular-pay').innerText = `$${regularPay.toFixed(2)}`;
        document.getElementById('total-overtime-pay').innerText = `$${overtimePay.toFixed(2)}`;
        document.getElementById('total-gross-pay').innerText = `$${totalGrossPay.toFixed(2)}`;

        const summary = `
Total Net Work Time: ${formatMinutesToHours(totalNetMinutes)}
Regular Hours: ${regularHours.toFixed(2)} hrs @ $${regularWage.toFixed(2)}/hr
Overtime Hours: ${overtimeHours.toFixed(2)} hrs @ $${overtimeWage.toFixed(2)}/hr (Total Break: ${totalBreakMinutes} min)
        `;
        document.getElementById('calculation-summary').innerText = summary;
        document.getElementById('results-container').classList.remove('d-none');
    });

    // --- Initialization and Event Handlers ---

    // Initial population of default rows
    document.addEventListener('DOMContentLoaded', () => {
        // Create 5 default rows (e.g., a standard work week)
        DEFAULT_DAYS.forEach(day => {
            createTimesheetRow(day, '09:00', '17:00', 30);
        });
    });

    // Add row functionality
    document.getElementById('add-row-button').addEventListener('click', () => {
        const rowCount = document.getElementById('timesheet-body').children.length;
        createTimesheetRow(`Shift ${rowCount + 1}`, '', '', 0);
    });

date_time__pay_period_date_calculator:
const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24;

    // Helper function to format a Date object into a readable string
    function formatReadableDate(date) {
        return date.toLocaleDateString('en-US', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });
    }

    function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    /**
     * Calculates the next N pay dates based on the last pay date and frequency.
     * Uses Date.UTC methods for reliable date arithmetic.
     * @param {Date} lastPayDate - The date of the last payment (UTC midnight).
     * @param {string} frequency - weekly, bi-weekly, semi-monthly, or monthly.
     * @param {number} count - The number of future dates to calculate.
     * @returns {Array<Date>} An array of the next pay dates.
     */
    function calculateNextPayDates(lastPayDate, frequency, count) {
        let dates = [];
        let currentDate = new Date(lastPayDate.getTime());
        const targetDay = lastPayDate.getUTCDate(); // Used for monthly pay

        // Helper to move to the next day
        const getNextDay = (date) => new Date(date.getTime() + MILLISECONDS_PER_DAY);

        for (let i = 0; i < count; i++) {
            let nextDate;

            switch (frequency) {
                case 'weekly':
                    // Add 7 days
                    currentDate.setTime(currentDate.getTime() + (7 * MILLISECONDS_PER_DAY));
                    nextDate = new Date(currentDate.getTime());
                    break;

                case 'bi-weekly':
                    // Add 14 days
                    currentDate.setTime(currentDate.getTime() + (14 * MILLISECONDS_PER_DAY));
                    nextDate = new Date(currentDate.getTime());
                    break;

                case 'monthly':
                    // Add one month, maintaining the day of the month
                    let currentMonth = currentDate.getUTCMonth();
                    currentDate.setUTCMonth(currentMonth + 1);
                    // Handle cases where the target day doesn't exist in the next month (e.g., Mar 31 -> Apr 30)
                    if (currentDate.getUTCDate() !== targetDay) {
                        currentDate.setUTCDate(0); // Move to the last day of the current month
                    }
                    nextDate = new Date(currentDate.getTime());
                    break;

                case 'semi-monthly':
                    // Paydays are the 1st and the 15th of the month.
                    let currentDay = currentDate.getUTCDate();
                    let currentMonthSM = currentDate.getUTCMonth();
                    let currentYearSM = currentDate.getUTCFullYear();

                    if (currentDay < 15) {
                        // If it's before the 15th, the next payday is the 15th of the current month
                        currentDate.setUTCDate(15);
                    } else {
                        // If it's on or after the 15th, the next payday is the 1st of the next month
                        currentDate.setUTCMonth(currentMonthSM + 1);
                        currentDate.setUTCDate(1);
                    }
                    nextDate = new Date(currentDate.getTime());
                    break;

                default:
                    // Should not happen if select is correctly constrained
                    return dates;
            }

            // For Semi-Monthly, we must ensure the calculated date is *after* the last known date.
            // All other frequencies naturally result in a later date.
            if (frequency === 'semi-monthly' && nextDate.getTime() <= lastPayDate.getTime() && dates.length === 0) {
                // If the first calculated semi-monthly date is not later than the anchor,
                // we calculate again (effectively skipping the first payday of the cycle).
                i--; // Decrement counter to repeat calculation for the *next* date
                currentDate = new Date(nextDate.getTime()); // Use this date as the new start for the next iteration
                continue;
            }

            dates.push(nextDate);
            // Set currentDate for the next loop iteration (except for semi-monthly where it's handled above)
            if (frequency !== 'semi-monthly') {
                 currentDate = nextDate;
            } else {
                 // For semi-monthly, use the calculated next date as the start for the *following* date calculation
                 lastPayDate = nextDate;
                 currentDate = nextDate;
            }
        }

        return dates;
    }


