    }

    // Helper function to pad numbers with a leading zero (e.g., 5 -> 05)
    function pad(num) {
        return num.toString().padStart(2, '0');
    }


    function convertSeconds(totalSeconds) {
        // Constants for conversion
        const SECONDS_IN_MINUTE = 60;
        const SECONDS_IN_HOUR = 60 * SECONDS_IN_MINUTE; // 3600
        const SECONDS_IN_DAY = 24 * SECONDS_IN_HOUR;    // 86400

        // Calculate components
        let remainingSeconds = totalSeconds;

        const days = Math.floor(remainingSeconds / SECONDS_IN_DAY);
        remainingSeconds %= SECONDS_IN_DAY;

        const hours = Math.floor(remainingSeconds / SECONDS_IN_HOUR);
        remainingSeconds %= SECONDS_IN_HOUR;

        const minutes = Math.floor(remainingSeconds / SECONDS_IN_MINUTE);
        remainingSeconds %= SECONDS_IN_MINUTE;

        const seconds = remainingSeconds;

        return { days, hours, minutes, seconds };
    }

    // --- Event Handler ---

    document.getElementById('seconds-converter-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

