            displayStatus("Please enter a non-negative number for total seconds.", true);
            return;
        }

        try {
            // 1. Perform Conversion
            const { days, hours, minutes, seconds } = convertSeconds(totalSeconds);

            // 2. Format and Display Results
            const formattedTime = `${pad(days)}:${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;

            document.getElementById('converted-time-dhm').innerText = formattedTime;

