        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    document.getElementById('term-calculator-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const startDateStr = document.getElementById('start-date').value;
        const durationType = document.getElementById('duration-type').value;
        const durationValueStr = document.getElementById('duration-value').value;
        const durationValue = parseInt(durationValueStr, 10);

        if (!startDateStr || isNaN(durationValue) || durationValue <= 0) {
            displayStatus("Please ensure all fields are filled correctly and the duration is a positive number.", true);
            return;
        }

        // 1. Calculate Total Days to Add
        let daysToAdd = 0;
        let summaryText = "";

        if (durationType === 'weeks') {
            daysToAdd = durationValue * DAYS_PER_WEEK;
            summaryText = `Based on a **${durationValue}-week** duration, which is equal to **${daysToAdd} days**.`;
        } else { // 'days'
            daysToAdd = durationValue;
            summaryText = `Based on a **${durationValue}-day** duration.`;
        }

        // 2. Determine the End Date
        // We parse the date string. It's crucial to treat the input date as the start day.
        // We use UTC parsing to prevent local timezone offsets from shifting the day boundary.
        const [y, m, d] = startDateStr.split('-').map(Number);
        const startDate = new Date(Date.UTC(y, m - 1, d)); // Month is 0-indexed (m-1)

        // The term *ends* after the duration has passed.
        // If a term starts on Day 1 and lasts for 7 days, it ends on Day 7.
        // If a term starts today, and lasts for 1 day, it ends today.
        // We add daysToAdd - 1 to get the last day of the term (inclusive).

        const endDayOffset = daysToAdd > 0 ? daysToAdd - 1 : 0;

        // Calculate the milliseconds for the end date
        const endDateMs = startDate.getTime() + (endDayOffset * MILLISECONDS_PER_DAY);
        const endDate = new Date(endDateMs);

        // 3. Display Results
        document.getElementById('final-end-date').innerText = formatReadableDate(endDate);
        document.getElementById('calculation-summary').innerHTML = `Your term starts on ${formatReadableDate(startDate)}, and ends after ${daysToAdd} day(s). ${summaryText}`;
        document.getElementById('results-container').classList.remove('d-none');
    });

    // Set a default start date (e.g., today)
    document.addEventListener('DOMContentLoaded', () => {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        document.getElementById('start-date').value = `${yyyy}-${mm}-${dd}`;
    });

