    }

    // Transit times are in BUSINESS DAYS (Mon-Fri)
    const SHIPPING_TRANSIT_TIMES = {
        'EXPRESS': 2,
        'STANDARD': 5,
        'ECONOMY': 10
    };

    // Helper to format a Date object into a readable string
    function formatDate(date) {
        return date.toLocaleDateString('en-US', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
        });
    }


    function calculateDeliveryDate(startDate, businessDays) {
        let currentDate = new Date(startDate.getTime());
        let daysToCount = businessDays;
        let totalCalendarDays = 0;

        // Skip the initial day if it is a weekend, but DON'T count it as a transit day
        while (currentDate.getDay() === 0 || currentDate.getDay() === 6) {
            currentDate.setDate(currentDate.getDate() + 1);
        }

        while (daysToCount > 0) {
            // Move to the next day
            currentDate.setDate(currentDate.getDate() + 1);
            totalCalendarDays++;

            const dayOfWeek = currentDate.getDay(); // 0 (Sunday) to 6 (Saturday)

            // If it's not a weekend (Mon=1 to Fri=5), count it as a business day
            if (dayOfWeek >= 1 && dayOfWeek <= 5) {
                daysToCount--;
            }
        }

        // Final check: if the calculated delivery day is a weekend, delivery happens on the next Monday
        while (currentDate.getDay() === 0 || currentDate.getDay() === 6) {
             currentDate.setDate(currentDate.getDate() + 1);
             totalCalendarDays++;
        }

        return {
            deliveryDate: currentDate,
            totalCalendarDays: totalCalendarDays
        };
    }


