        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }

    /**
     * Calculates the subscription renewal date.
     * Handles month-end rollovers (e.g., Jan 31st renews on Feb 28th/29th).
     * @param {string} startDateStr The start date string (YYYY-MM-DD).
     * @param {number} monthsPerCycle The number of months in one cycle (e.g., 1 for monthly).
     * @param {number} cycles The number of cycles to project ahead.
     * @returns {Date} The calculated renewal date.
     */
    function calculateRenewalDate(startDateStr, monthsPerCycle, cycles) {
        // 1. Create a copy of the start date
        const startDate = new Date(startDateStr);
        const startDay = startDate.getDate();
        const startMonth = startDate.getMonth();

        // 2. Calculate total months to advance
        const totalMonths = monthsPerCycle * cycles;

        // 3. Create the renewal date object and set the month
        const renewalDate = new Date(startDate);
        renewalDate.setMonth(startMonth + totalMonths);

        // 4. CRUCIAL LOGIC: Handle month-end overflow (e.g., Jan 31st + 1 month attempts to land on Feb 31st, 
        // which JavaScript resolves to Mar 3rd, but the actual renewal should be Feb 28th/29th).
        // If the day in the new month is less than the original day, it means it overflowed.
        if (renewalDate.getDate() < startDay) {
            // Setting the day to 0 of the current month effectively sets it to the last day 
            // of the previous month (the intended renewal month).
            renewalDate.setDate(0); 
        }

        return renewalDate;
    }

    // --- Event Handler ---

    document.getElementById('renewal-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
