            displayStatus("Please ensure a valid start date and positive values for cycles.", true);
            return;
        }

        try {
            // 1. Perform Calculation
            const renewalDate = calculateRenewalDate(startDateStr, monthsPerCycle, cycles);

            // 2. Display Results
            const dateReadable = formatReadableDate(renewalDate);
            const frequencyText = document.getElementById('renewal-frequency').options[document.getElementById('renewal-frequency').selectedIndex].text;

            document.getElementById('result-title').innerText = `Renewal Date (After ${cycles} Cycles)`;
            document.getElementById('calculated-renewal-date').innerText = dateReadable;

            const summaryText = `
Your subscription, set to renew ${frequencyText}, will renew on **${dateReadable}** after ${cycles} cycle(s). 
If the renewal date is the 29th, 30th, or 31st, it shifts to the last day of a shorter month (e.g., February).
            `;
            document.getElementById('calculation-summary').innerText = summaryText.trim();

            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation Error:", error);
            displayStatus("An error occurred during calculation. Please check your inputs.", true);
