    }

    // Helper function to format a Date object into a readable string
    function formatReadableDate(date) {
        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }

    /**
     * Calculates the warranty expiry date.
     * The expiry date is the purchase date + term, minus one day (as coverage ends the day before the renewal date).
     * @param {string} purchaseDateStr The purchase date string (YYYY-MM-DD).
     * @param {number} termValue The term length value.
     * @param {string} termUnit The unit of the term ('Years', 'Months', 'Days').
     * @returns {Date} The calculated expiry date.
     */
    function calculateExpiryDate(purchaseDateStr, termValue, termUnit) {
        // Create a copy of the purchase date to manipulate
        const purchaseDate = new Date(purchaseDateStr);
        // Important: Use the date object's methods to handle month/year rollovers correctly.
        const effectiveEndDate = new Date(purchaseDate);

        if (termUnit === 'Years') {
            effectiveEndDate.setFullYear(effectiveEndDate.getFullYear() + termValue);
        } else if (termUnit === 'Months') {
            effectiveEndDate.setMonth(effectiveEndDate.getMonth() + termValue);
        } else if (termUnit === 'Days') {
            // Add termValue days to the effective end date
            effectiveEndDate.setDate(effectiveEndDate.getDate() + termValue);
        }

        // The warranty typically covers the *entire* last day. 
        // Example: 1-year warranty starting Jan 1st 2025. It should expire Dec 31st 2025.
        // My previous logic for Lease (start + term months - 1 day) is the most accurate way 
        // to handle the end of a fixed period where the period is inclusive of the start day.

        // Therefore, the date we calculated (effectiveEndDate) is the *first day* the warranty is *expired*.
        // We subtract one day to get the *last day* the warranty is *active*.
        effectiveEndDate.setDate(effectiveEndDate.getDate() - 1);

        return effectiveEndDate;
    }

    // --- Event Handler ---

    document.getElementById('warranty-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

