        const termValueStr = document.getElementById('term-value').value;
        const termUnit = document.getElementById('term-unit').value;

        const termValue = parseInt(termValueStr, 10);

        if (!purchaseDateStr || isNaN(termValue) || termValue < 0) {
            displayStatus("Please ensure a valid purchase date and a non-negative warranty term.", true);
            return;
        }

        try {
            // 1. Perform Calculation
            const expiryDate = calculateExpiryDate(purchaseDateStr, termValue, termUnit);

            // 2. Display Results
            const dateReadable = formatReadableDate(expiryDate);
            const purchaseDateReadable = formatReadableDate(new Date(purchaseDateStr));

            document.getElementById('result-title').innerText = `Warranty Expiry Date (${termValue} ${termUnit})`;
            document.getElementById('calculated-expiry-date').innerText = dateReadable;

            const summaryText = `
Your warranty, which started on **${purchaseDateReadable}** with a term of **${termValue} ${termUnit}**, 
provides coverage up to and including **${dateReadable}**. 
It officially expires at the end of that day.
            `;
            document.getElementById('calculation-summary').innerText = summaryText.trim();

            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation Error:", error);
            displayStatus("An error occurred during calculation. Please check your inputs.", true);
        }
    });

