        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        document.getElementById('purchase-date').value = `${yyyy}-${mm}-${dd}`;
        document.getElementById('term-value').value = 1;
        document.getElementById('term-unit').value = 'Years';
    });

date_time__week_number_calculator:
const MS_PER_DAY = 1000 * 60 * 60 * 24;

    function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }


    function getISOWeekDate(date) {
        // 1. Create a copy of the date object
        const d = new Date(date.valueOf());

        // 2. Set the date to the nearest Thursday. 
        // This Thursday's year will be the ISO year.

        // d.getDay() returns 0 for Sunday, 1 for Monday... 6 for Saturday.
        // Convert Sunday (0) to 7 for easier week calculation (Monday=1...Sunday=7)
        let dayNum = d.getDay(); 
        if (dayNum === 0) dayNum = 7; 

        // Move the date to the Thursday of the current week (dayNum 4)
        // d.getDate() + (4 - dayNum) calculates the offset to Thursday
        d.setDate(d.getDate() + (4 - dayNum));

        // 3. Get the ISO Year (the year of the Thursday)
        const isoYear = d.getFullYear();

        // 4. Calculate the start of the ISO year (Jan 1st of the ISO Year)
        const yearStart = new Date(isoYear, 0, 1);

        // 5. Calculate the difference in days between the Thursday and the start of the year
        // Add 1 to include the starting day itself.
        const days = Math.floor((d.getTime() - yearStart.getTime()) / MS_PER_DAY) + 1;

        // 6. Calculate the week number (1-53)
        // Math.ceil((days / 7)) gives the correct week number (Week 1 = days 1-7)
        const weekNo = Math.ceil(days / 7);

        return { week: weekNo, year: isoYear };
    }

    // --- Event Handler ---

    document.getElementById('week-number-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

