function displayStatus(message, isError) {
        const statusDiv = document.getElementById('status-message');
        statusDiv.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-info');
        statusDiv.classList.add(isError ? 'alert-danger' : 'alert-info');
        statusDiv.innerHTML = isError ? `❌ **Error:** ${message}` : `ℹ️ ${message}`;
    }

    // Helper function to format time as HH:MM AM/PM
    function formatTime(date) {
        return date.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    }


    function formatDuration(hours, minutes) {
        let parts = [];
        if (hours > 0) {
            parts.push(`${hours} hour${hours !== 1 ? 's' : ''}`);
        }
        if (minutes > 0) {
            parts.push(`${minutes} minute${minutes !== 1 ? 's' : ''}`);
        }
        return parts.join(' and ');
    }


    function calculateEndTime(startTimeStr, scheduledHours, breakMinutes) {
        // 1. Parse Start Time
        const [hour, minute] = startTimeStr.split(':').map(Number);

        // We need a specific date reference to use Date object addition, 
        // but we only care about the time calculation. Use today's date.
        const today = new Date();
        const startDate = new Date(today.getFullYear(), today.getMonth(), today.getDate(), hour, minute, 0);

        // 2. Calculate Total Time to Add (Scheduled Work + Unpaid Breaks) in minutes
        const scheduledMinutes = scheduledHours * 60;
        const totalMinutesToAdd = scheduledMinutes + breakMinutes;

        // 3. Calculate End Time
        const endTime = new Date(startDate.getTime());
        endTime.setMinutes(startDate.getMinutes() + totalMinutesToAdd);

        return { endTime, totalShiftMinutes: totalMinutesToAdd };
    }

    // --- Event Handler ---

    document.getElementById('workday-form').addEventListener('submit', function (e) {
        e.preventDefault();

        document.getElementById('results-container').classList.add('d-none');
        document.getElementById('status-message').classList.add('d-none');

        const startTimeStr = document.getElementById('start-time').value;
        const scheduledHours = parseFloat(document.getElementById('scheduled-hours').value);
        const breakMinutes = parseInt(document.getElementById('break-minutes').value, 10);

        if (!startTimeStr || isNaN(scheduledHours) || isNaN(breakMinutes) || scheduledHours <= 0) {
            displayStatus("Please ensure a valid start time, positive scheduled hours, and a valid break duration.", true);
            return;
        }

        try {
            // 1. Perform Calculation
            const { endTime, totalShiftMinutes } = calculateEndTime(startTimeStr, scheduledHours, breakMinutes);

            // 2. Format Durations for Display
            const totalShiftHours = Math.floor(totalShiftMinutes / 60);
            const totalShiftRemainingMinutes = totalShiftMinutes % 60;
            const totalShiftDurationReadable = formatDuration(totalShiftHours, totalShiftRemainingMinutes);

            // 3. Display Results
            document.getElementById('calculated-end-time').innerText = formatTime(endTime);
            document.getElementById('start-time-display').innerText = formatTime(new Date(`2000/01/01 ${startTimeStr}`));
            document.getElementById('total-shift-duration-display').innerText = totalShiftDurationReadable;
            document.getElementById('net-working-hours-display').innerText = `${scheduledHours} hours`;

            document.getElementById('results-container').classList.remove('d-none');

        } catch (error) {
            console.error("Calculation Error:", error);
            displayStatus("An error occurred during calculation. Please check your inputs.", true);
        }
    });

    // Set default values (e.g., 9:00 AM start, 8 hours, 30 min break)
    document.addEventListener('DOMContentLoaded', () => {
        document.getElementById('start-time').value = '09:00';
        document.getElementById('scheduled-hours').value = 8;
        document.getElementById('break-minutes').value = 30;
    });

