    const concordanceTable = {
        1600: 36, 1590: 36, 1580: 36, 1570: 36, 1560: 35, 1550: 35, 1540: 34, 1530: 34, 1520: 34, 1510: 33,
        1500: 33, 1490: 33, 1480: 33, 1470: 32, 1460: 32, 1450: 32, 1440: 32, 1430: 31, 1420: 31, 1410: 31,
