            { id: 'author_last', label: 'Last Name', placeholder: 'e.g. Orwell', required: true },
            { id: 'author_first', label: 'First Name', placeholder: 'e.g. George', required: true },
            { id: 'year', label: 'Year', placeholder: '1949', required: true, type: 'number' },
            { id: 'title', label: 'Book Title', placeholder: '1984', required: true },
            { id: 'publisher', label: 'Publisher', placeholder: 'Secker & Warburg', required: true },
        ]
    };

    const dynamicInputsEl = document.getElementById('dynamic-inputs');
    const styleSelect = document.getElementById('citation_style');
    const typeSelect = document.getElementById('source_type');
    const generateBtn = document.getElementById('generate-btn');
    const outputBox = document.getElementById('output-box');
    const resultContainer = document.getElementById('result-container');
    const placeholder = document.getElementById('output-placeholder');

    function renderInputs() {
        const fields = sourceFields[typeSelect.value];
        dynamicInputsEl.innerHTML = fields.map(f => `
            <div class="mb-3">
                <div class="input-group">
                    <span class="input-group-text small">${f.label}${f.required ? '*' : ''}</span>
                    <input type="${f.type || 'text'}" class="form-control" id="${f.id}" placeholder="${f.placeholder}">
                </div>
            </div>
        `).join('');
    }

    function capitalize(str) {
        return str ? str.charAt(0).toUpperCase() + str.slice(1) : '';
    }

    function generate() {
        const type = typeSelect.value;
        const style = styleSelect.value;
        const data = {};

        sourceFields[type].forEach(f => {
            data[f.id] = document.getElementById(f.id).value.trim();
        });

        // Validation Check
        const missing = sourceFields[type].filter(f => f.required && !data[f.id]);
        if (missing.length > 0) {
            alert('Please fill in the required fields marked with (*)');
            return;
        }

        let reference = '';
        let intext = '';

        if (style === 'APA') {
            const author = data.author_last ? `${data.author_last}, ${data.author_first.charAt(0)}.` : data.site_name;
            const date = data.year ? `(${data.year}${data.month ? ', ' + data.month : ''}${data.day ? ' ' + data.day : ''})` : '(n.d.)';

            intext = `(${data.author_last || data.site_name}, ${data.year || 'n.d.'})`;

            if (type === 'Website') {
                reference = `${author} ${date}. <i>${data.title}</i>. ${data.site_name}. ${data.url}`;
            } else {
                reference = `${author} (${data.year}). <i>${data.title}</i>. ${data.publisher}.`;
            }
        } else { // MLA
            const author = data.author_last ? `${data.author_last}, ${data.author_first}.` : `${data.site_name}.`;
            intext = `(${data.author_last || data.site_name})`;

            if (type === 'Website') {
                const date = data.day ? `${data.day} ${data.month} ${data.year}` : data.year;
                reference = `${author} "${data.title}." <i>${data.site_name}</i>, ${date}, ${data.url}.`;
            } else {
                reference = `${author} <i>${data.title}</i>, ${data.publisher}, ${data.year}.`;
            }
        }

        // Display results
        placeholder.style.display = 'none';
        resultContainer.style.display = 'block';
        resultContainer.classList.add('animate-result');
        outputBox.classList.add('has-content');
        document.getElementById('generated-citation').innerHTML = reference;
        document.getElementById('intext-citation').innerText = intext;
    }

    function copyToClipboard() {
        const text = document.getElementById('generated-citation').textContent;
        navigator.clipboard.writeText(text).then(() => {
            const btn = document.getElementById('copy-btn');
            btn.innerHTML = '<i class="bi bi-check2"></i> Copied!';
            setTimeout(() => btn.innerHTML = '<i class="bi bi-clipboard"></i> Copy Citation', 2000);
        });
    }

    // Init
    typeSelect.addEventListener('change', renderInputs);
    styleSelect.addEventListener('change', () => { if(resultContainer.style.display === 'block') generate(); });
    generateBtn.addEventListener('click', generate);
    document.getElementById('copy-btn').addEventListener('click', copyToClipboard);

    window.onload = renderInputs;

education__class_curve_grade_calculator:
// --- Statistical Logic ---
    const calculateMean = scores => scores.length ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;
    const calculateStandardDeviation = (scores, mean) => {
        if (scores.length <= 1) return 0;
        return Math.sqrt(scores.map(s => Math.pow(s - mean, 2)).reduce((a, b) => a + b) / scores.length);
    };

    function toggleCurveParameters() {
        const method = document.getElementById('curve-method').value;
        const paramsDiv = document.getElementById('curve-params');
        paramsDiv.innerHTML = '';

        const config = {
            add_points: `<label class="small fw-bold">Points to Add</label><input type="number" id="param-points" class="form-control" oninput="calculateCurve()">`,
            percentage: `<label class="small fw-bold">Percentage Increase (%)</label><input type="number" id="param-percent" class="form-control" oninput="calculateCurve()">`,
            standard_dev: `
                <div class="mb-2"><label class="small fw-bold text-muted">Target Mean</label><input type="number" id="param-target-mean" class="form-control" oninput="calculateCurve()"></div>
                <div><label class="small fw-bold text-muted">Target Std Dev</label><input type="number" id="param-target-stdev" class="form-control" oninput="calculateCurve()"></div>`,
            set_max: `<div class="small text-primary"><i class="bi bi-info-circle me-1"></i> Scales best score to 100%</div>`
        };

        paramsDiv.innerHTML = config[method] || `<div class="small text-muted">No parameters needed</div>`;
    }

    function calculateCurve() {
        const rawInput = document.getElementById('raw-scores').value.trim();
        const resultsView = document.getElementById('results-view');
        const emptyView = document.getElementById('empty-view');

        if (!rawInput) {
            resultsView.classList.add('d-none');
            emptyView.classList.remove('d-none');
            return;
        }

        const rawScores = rawInput.split(/,|\n/).map(s => parseFloat(s.trim())).filter(n => !isNaN(n));
        if (rawScores.length === 0) return;

        resultsView.classList.remove('d-none');
        emptyView.classList.add('d-none');

        const rawMean = calculateMean(rawScores);
        const rawStDev = calculateStandardDeviation(rawScores, rawMean);
        const maxRaw = Math.max(...rawScores);
        const method = document.getElementById('curve-method').value;

        const curvedData = rawScores.map(score => {
            let curved = score;
            let adj = "0";

            if (method === 'add_points') {
                const p = parseFloat(document.getElementById('param-points')?.value || 0);
                curved = Math.min(100, score + p);
                adj = `+${p}`;
            } else if (method === 'percentage') {
                const p = parseFloat(document.getElementById('param-percent')?.value || 0);
                curved = Math.min(100, score * (1 + p/100));
                adj = `+${p}%`;
            } else if (method === 'set_max') {
                curved = (score / maxRaw) * 100;
                adj = `x${(100/maxRaw).toFixed(2)}`;
            } else if (method === 'standard_dev') {
                const tm = parseFloat(document.getElementById('param-target-mean')?.value || 80);
                const ts = parseFloat(document.getElementById('param-target-stdev')?.value || 10);
                const z = rawStDev === 0 ? 0 : (score - rawMean) / rawStDev;
                curved = Math.min(100, Math.max(0, tm + (z * ts)));
                adj = (curved - score) >= 0 ? `+${(curved-score).toFixed(1)}` : (curved-score).toFixed(1);
            }

            return { raw: score, curved, adj };
        });

        const finalCurvedScores = curvedData.map(d => d.curved);

        // Update UI Stats
        document.getElementById('raw-average').innerText = rawMean.toFixed(1);
        document.getElementById('raw-stdev').innerText = rawStDev.toFixed(1);
        document.getElementById('curved-average').innerText = calculateMean(finalCurvedScores).toFixed(1);
        document.getElementById('curved-stdev').innerText = calculateStandardDeviation(finalCurvedScores, calculateMean(finalCurvedScores)).toFixed(1);

        // Update Table
        const output = document.getElementById('score-output');
        output.innerHTML = curvedData.map((d, i) => `
            <tr>
                <td class="ps-3 text-muted">Student ${i+1}</td>
                <td class="text-center">${d.raw.toFixed(1)}</td>
                <td class="text-center"><span class="badge bg-light text-dark border">${d.adj}</span></td>
                <td class="text-end pe-3 fw-bold text-success">${d.curved.toFixed(1)}%</td>
            </tr>
        `).join('');
    }

    window.onload = () => {
        document.getElementById('raw-scores').addEventListener('input', calculateCurve);
        toggleCurveParameters();
    };

education__class_schedule_conflict_check:
let courseCounter = 0;
    const daysArr = ['M', 'T', 'W', 'Th', 'F'];

    const courseListEl = document.getElementById('course-list');
    const addCourseBtn = document.getElementById('add-course-btn');
    const statusBar = document.getElementById('conflict-status-bar');
    const emptyMsg = document.getElementById('empty-msg');

    function timeToMinutes(timeStr) {
        if (!timeStr) return 0;
        const [hours, minutes] = timeStr.split(':').map(Number);
        return hours * 60 + minutes;
    }

    function checkConflicts() {
        const rows = document.querySelectorAll('.course-card');
        const courses = [];

        // Clear all conflict states first
        rows.forEach(row => row.classList.remove('conflict'));

        rows.forEach(row => {
            const id = row.id;
            const name = row.querySelector('.course-name').value;
            const start = timeToMinutes(row.querySelector('.start-time').value);
            const end = timeToMinutes(row.querySelector('.end-time').value);
            const days = Array.from(row.querySelectorAll('.day-check:checked')).map(cb => cb.value);

            if (name && days.length > 0 && start < end) {
                courses.push({ id, name, start, end, days });
            }
        });

        if (courses.length < 2) {
            statusBar.style.display = 'none';
            return;
        }

        let conflictsFound = false;
        const conflictingIds = new Set();

        for (let i = 0; i < courses.length; i++) {
            for (let j = i + 1; j < courses.length; j++) {
                const a = courses[i];
                const b = courses[j];

                const sharedDays = a.days.filter(d => b.days.includes(d));
                if (sharedDays.length > 0) {
                    const overlap = (a.start < b.end) && (b.start < a.end);
                    if (overlap) {
                        conflictsFound = true;
                        conflictingIds.add(a.id);
                        conflictingIds.add(b.id);
                    }
                }
            }
        }

        statusBar.style.display = 'block';
        if (conflictsFound) {
            conflictingIds.forEach(id => document.getElementById(id).classList.add('conflict'));
            statusBar.className = 'alert alert-danger p-3 mb-4 text-center shadow-sm';
            statusBar.innerHTML = '<i class="bi bi-exclamation-triangle-fill me-2"></i> Conflict Detected! Some classes overlap in time.';
        } else {
            statusBar.className = 'alert alert-success p-3 mb-4 text-center shadow-sm';
            statusBar.innerHTML = '<i class="bi bi-check-circle-fill me-2"></i> Your schedule looks clean! No overlaps found.';
        }
    }

    function addCourse() {
        if (emptyMsg) emptyMsg.style.display = 'none';

        courseCounter++;
        const rowId = `course-${courseCounter}`;
        const card = document.createElement('div');
        card.className = 'course-card';
        card.id = rowId;

        let dayCheckboxes = daysArr.map(day => `
            <input type="checkbox" class="btn-check day-check" id="day-${day}-${rowId}" value="${day}" autocomplete="off" onchange="checkConflicts()">
            <label class="btn btn-outline-primary" for="day-${day}-${rowId}">${day}</label>
        `).join('');

        card.innerHTML = `
            <div class="row g-3 align-items-center">
                <div class="col-lg-3">
                    <label class="small fw-bold text-muted">Course Name</label>
                    <input type="text" class="form-control course-name" placeholder="e.g., Biology 101" oninput="checkConflicts()">
                </div>
                <div class="col-md-6 col-lg-3">
                    <label class="small fw-bold text-muted">Time Period</label>
                    <div class="input-group">
                        <input type="time" class="form-control start-time" value="09:00" oninput="checkConflicts()">
                        <span class="input-group-text">to</span>
                        <input type="time" class="form-control end-time" value="10:00" oninput="checkConflicts()">
                    </div>
                </div>
                <div class="col-md-6 col-lg-4">
                    <label class="small fw-bold text-muted d-block">Meeting Days</label>
                    <div class="day-selector d-flex">${dayCheckboxes}</div>
                </div>
                <div class="col-lg-2 text-end">
                    <button class="btn btn-outline-danger w-100 mt-lg-3" onclick="removeCourse('${rowId}')">
                        <i class="bi bi-trash"></i>
                    </button>
                </div>
            </div>
        `;

        courseListEl.appendChild(card);
        checkConflicts();
    }

    function removeCourse(id) {
        document.getElementById(id).remove();
        if (document.querySelectorAll('.course-card').length === 0) {
            emptyMsg.style.display = 'block';
            statusBar.style.display = 'none';
        } else {
            checkConflicts();
        }
    }

    function resetAll() {
        if (confirm("Clear your entire schedule?")) {
            courseListEl.innerHTML = '';
            courseListEl.appendChild(emptyMsg);
            statusBar.style.display = 'none';
            emptyMsg.style.display = 'block';
        }
    }

    addCourseBtn.addEventListener('click', addCourse);

    window.onload = () => {
        // Start with clean slate for visitor use
    };

education__college_gpa_calculator:
const GRADE_POINTS = {
        'A+': 4.0, 'A': 4.0, 'A-': 3.7,
        'B+': 3.3, 'B': 3.0, 'B-': 2.7,
        'C+': 2.3, 'C': 2.0, 'C-': 1.7,
        'D+': 1.3, 'D': 1.0, 'D-': 0.7,
        'F': 0.0
    };

    function createCourseRow(name = '', grade = 'A', credits = '') {
        const row = document.createElement('div');
        row.className = 'course-row';
        row.innerHTML = `
            <div class="col-md-6 col-12">
                <input type="text" class="form-control" placeholder="Course Name (Optional)" value="${name}">
            </div>
            <div class="col-md-3 col-5">
                <select class="form-select course-grade">
                    ${Object.keys(GRADE_POINTS).map(g => `<option value="${g}" ${g === grade ? 'selected' : ''}>${g}</option>`).join('')}
                    <option value="P">Pass (P)</option>
                    <option value="NP">No Pass (NP)</option>
                </select>
            </div>
            <div class="col-md-2 col-4">
                <input type="number" class="form-control course-credits" placeholder="Credits" step="0.5" min="0" value="${credits}">
            </div>
            <div class="col-md-1 col-2 text-end">
                <button type="button" class="btn btn-outline-danger remove-btn">&times;</button>
            </div>
        `;

        row.querySelector('.remove-btn').addEventListener('click', () => {
            row.remove();
            // Don't auto-calculate here to keep it clean, or uncomment below to auto-update
            // if(document.querySelectorAll('.course-row').length > 0) calculateGPA();
        });

        return row;
    }

    function calculateGPA(e) {
        if (e) e.preventDefault();

        const rows = document.querySelectorAll('#course-list .course-row');
        let semCredits = 0;
        let semGradePoints = 0;

        rows.forEach(row => {
            const credits = parseFloat(row.querySelector('.course-credits').value) || 0;
            const grade = row.querySelector('.course-grade').value;
            const points = GRADE_POINTS[grade];

            // Only count grades that exist in our 4.0 mapping
            if (points !== undefined) {
                semCredits += credits;
                semGradePoints += (points * credits);
            }
        });

        if (semCredits === 0) {
            alert("Please enter credit hours for at least one course.");
            return;
        }

        const semGPA = semGradePoints / semCredits;

        // Cumulative Calculation
        const prevGPA = parseFloat(document.getElementById('prev_gpa').value) || 0;
        const prevCredits = parseFloat(document.getElementById('prev_credits').value) || 0;

        let cumGPA = 0;
        let totalCredits = semCredits;
        let hasCumulative = prevCredits > 0;

        if (hasCumulative) {
            totalCredits = prevCredits + semCredits;
            cumGPA = ((prevGPA * prevCredits) + semGradePoints) / totalCredits;
        }

        // Update UI
        document.getElementById('results-container').classList.remove('d-none');
        document.getElementById('sem-gpa-val').innerText = semGPA.toFixed(3);

        const cumCard = document.getElementById('cum-gpa-card');
        if (hasCumulative) {
            cumCard.style.display = 'block';
            document.getElementById('cum-gpa-val').innerText = cumGPA.toFixed(3);
        } else {
            cumCard.style.display = 'none';
        }

        updateTable(semGPA, semCredits, semGradePoints, cumGPA, totalCredits, hasCumulative);
    }

    function updateTable(semGPA, semCr, semPts, cumGPA, totCr, hasCum) {
        let html = `
            <tr><td>Semester Credits Attempted</td><td class="text-end fw-bold">${semCr.toFixed(1)}</td></tr>
            <tr><td>Semester Total Grade Points</td><td class="text-end fw-bold">${semPts.toFixed(2)}</td></tr>
            <tr class="table-success"><td><strong>Semester GPA</strong></td><td class="text-end fw-bold">${semGPA.toFixed(3)}</td></tr>
        `;

        if (hasCum) {
            html += `
                <tr class="table-light"><td colspan="2" class="py-1"></td></tr>
                <tr><td>Total Cumulative Credits</td><td class="text-end fw-bold">${totCr.toFixed(1)}</td></tr>
                <tr class="table-primary"><td><strong>New Cumulative GPA</strong></td><td class="text-end fw-bold">${cumGPA.toFixed(3)}</td></tr>
            `;
        }

        document.getElementById('gpa-body').innerHTML = html;
        window.scrollTo({ top: document.getElementById('results-container').offsetTop - 20, behavior: 'smooth' });
    }

    // Event Listeners
    document.getElementById('add-course-btn').addEventListener('click', () => {
        document.getElementById('course-list').appendChild(createCourseRow());
    });

    document.getElementById('reset-btn').addEventListener('click', () => {
        if(confirm("Are you sure you want to clear all inputs?")) {
            document.getElementById('course-list').innerHTML = '';
            for(let i=0; i<4; i++) document.getElementById('course-list').appendChild(createCourseRow());
            document.getElementById('college-gpa-form').reset();
            document.getElementById('results-container').classList.add('d-none');
        }
    });

    document.getElementById('college-gpa-form').addEventListener('submit', calculateGPA);

    // Initial load: 4 empty rows
    window.addEventListener('load', () => {
        const list = document.getElementById('course-list');
        for(let i=0; i<4; i++) {
            list.appendChild(createCourseRow());
        }
    });

education__college_savings_plan_calculat:
let comparisonChart = null;

    function formatCurrency(amount) {
        return new Intl.NumberFormat('en-US', {
            style: 'currency', currency: 'USD',
            minimumFractionDigits: 0, maximumFractionDigits: 0,
        }).format(amount);
    }

    function calculateSavings(e) {
        if (e) e.preventDefault();

        const P = parseFloat(document.getElementById('initial_deposit').value) || 0;
        const PMT = parseFloat(document.getElementById('monthly_contribution').value) || 0;
        const Y_until = parseFloat(document.getElementById('years_until_enrollment').value);
        const D_duration = parseFloat(document.getElementById('college_duration').value);
        const R_return = parseFloat(document.getElementById('rate_of_return').value) / 100;
        const I_inflation = parseFloat(document.getElementById('inflation_rate').value) / 100;
        const C_current = parseFloat(document.getElementById('current_annual_cost').value);

        if (Y_until < 1 || C_current < 1) return;

        // Calculate Savings
        const R_monthly = R_return / 12;
        const M_total = Y_until * 12;
        const fvInitial = P * Math.pow(1 + R_return, Y_until);
        const fvContributions = R_monthly === 0 ? PMT * M_total : PMT * (Math.pow(1 + R_monthly, M_total) - 1) / R_monthly;

        const totalSaved = fvInitial + fvContributions;
        const totalPrincipal = P + (PMT * M_total);
        const totalInterest = totalSaved - totalPrincipal;

        // Calculate College Cost
        let totalCost = 0;
        for (let k = 0; k < D_duration; k++) {
            totalCost += C_current * Math.pow(1 + I_inflation, Y_until + k);
        }

        const netDifference = totalSaved - totalCost;

        // Update UI
        document.getElementById('results-container').classList.remove('d-none');
        document.getElementById('total-saved').textContent = formatCurrency(totalSaved);
        document.getElementById('total-cost').textContent = formatCurrency(totalCost);
        document.getElementById('total-interest').textContent = formatCurrency(totalInterest);

        const summaryEl = document.getElementById('summary-message');
        summaryEl.classList.remove('alert-success', 'alert-danger', 'alert-warning');

        if (netDifference >= 0) {
            summaryEl.classList.add('alert-success');
            summaryEl.innerHTML = `<strong>Congratulations!</strong> You are on track to have a surplus of <span class="fw-bold">${formatCurrency(netDifference)}</span>.`;
        } else {
            summaryEl.classList.add('alert-warning');
            summaryEl.innerHTML = `<strong>Planning Tip:</strong> You may face a shortfall of <span class="fw-bold">${formatCurrency(Math.abs(netDifference))}</span>. Consider increasing monthly contributions or seeking additional aid.`;
        }

        updateChart(totalSaved, totalCost);
        window.scrollTo({ top: document.getElementById('results-container').offsetTop - 50, behavior: 'smooth' });
    }

    function updateChart(totalSaved, totalCost) {
        const ctx = document.getElementById('comparison-chart').getContext('2d');
        if (comparisonChart) comparisonChart.destroy();

        comparisonChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: ['Projected Totals'],
                datasets: [
                    { label: 'Total 529 Savings', data: [totalSaved], backgroundColor: '#007bff' },
                    { label: 'Projected College Cost', data: [totalCost], backgroundColor: '#dc3545' }
                ]
            },
            options: {
                indexAxis: 'y',
                responsive: true,
                maintainAspectRatio: false,
                scales: { 
                    x: { beginAtZero: true, ticks: { callback: v => formatCurrency(v) } } 
                },
                plugins: { legend: { position: 'bottom' } }
            }
        });
    }

    document.getElementById('savings-calculator-form').addEventListener('submit', calculateSavings);

    document.getElementById('reset-btn').addEventListener('click', () => {
        document.getElementById('savings-calculator-form').reset();
        document.getElementById('results-container').classList.add('d-none');
        if (comparisonChart) comparisonChart.destroy();
    });

education__course_load_difficulty_calcul:
const courseListEl = document.getElementById('course-list');
    const addCourseBtn = document.getElementById('add-course-btn');
    const emptyMsg = document.getElementById('empty-msg');

    const totalCreditsEl = document.getElementById('total-credits');
    const weightedDifficultyIndexEl = document.getElementById('weighted-difficulty-index');
    const estimatedWeeklyHoursEl = document.getElementById('estimated-weekly-hours');

    let courseCounter = 0;

    function calculateLoad() {
        let totalCredits = 0;
        let totalWeightedDiff = 0;
        let totalWeeklyHours = 0;

        const rows = document.querySelectorAll('.course-card');

        rows.forEach(row => {
            const credits = parseFloat(row.querySelector('.input-credits').value) || 0;
            const difficulty = parseFloat(row.querySelector('.input-difficulty').value) || 0;

            // Study multiplier calculation
            const studyMultiplier = 1 + (difficulty / 5) * 3; 
            const weeklyHours = Math.round(credits * studyMultiplier);

            row.querySelector('.display-weekly-hours').textContent = weeklyHours;

            totalCredits += credits;
            totalWeightedDiff += (credits * difficulty);
            totalWeeklyHours += weeklyHours;
        });

        totalCreditsEl.textContent = totalCredits.toFixed(0);
        weightedDifficultyIndexEl.textContent = totalWeightedDiff.toFixed(1);
        estimatedWeeklyHoursEl.textContent = totalWeeklyHours.toFixed(0);
    }

    function addCourse() {
        if (emptyMsg) emptyMsg.style.display = 'none';

        courseCounter++;
        const rowId = `course-${courseCounter}`;

        const div = document.createElement('div');
        div.className = 'course-card shadow-sm animate__animated animate__fadeIn';
        div.id = rowId;
        div.innerHTML = `
            <div class="row g-3 align-items-center">
                <div class="col-lg-4 col-md-12">
                    <label class="form-label small fw-bold">Course Title</label>
                    <input type="text" class="form-control" placeholder="e.g. Organic Chemistry" oninput="calculateLoad()">
                </div>
