function resetCalculator() {
        if(confirm("Are you sure you want to clear your data?")) {
            document.querySelectorAll('input').forEach(i => i.value = '');
            calculateTimeImpact();
        }
    }

    function calculateTimeImpact() {
        // --- Inputs ---
        const completed = parseFloat(document.getElementById('credits-completed').value);
        const primaryTotal = parseFloat(document.getElementById('credits-primary-total').value);
        const secondaryTotal = parseFloat(document.getElementById('credits-secondary-total').value);
        const overlap = parseFloat(document.getElementById('credits-overlap').value) || 0;
        const creditsPerSem = parseFloat(document.getElementById('credits-per-semester').value) || 15;

        const placeholder = document.getElementById('placeholder-ui');
        const results = document.getElementById('results-ui');

        // Logic: Only show results if primary total and completed are entered
        if (isNaN(completed) || isNaN(primaryTotal) || isNaN(secondaryTotal)) {
            placeholder.classList.remove('d-none');
            results.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        results.classList.remove('d-none');

        // --- Calculations ---
        const safeOverlap = Math.min(overlap, secondaryTotal);
        const uniqueSecondary = Math.max(0, secondaryTotal - safeOverlap);
        const totalProgramCredits = primaryTotal + uniqueSecondary;

        const remainingPrimary = Math.max(0, primaryTotal - completed);
        const remainingCombined = Math.max(0, totalProgramCredits - completed);

        const sPrimary = remainingPrimary / creditsPerSem;
        const sCombined = remainingCombined / creditsPerSem;
        const extension = Math.max(0, sCombined - sPrimary);

        // --- UI Updates ---
        document.getElementById('semesters-primary').textContent = sPrimary.toFixed(1);
        document.getElementById('semesters-combined').textContent = sCombined.toFixed(1);
        document.getElementById('time-extension').textContent = extension.toFixed(1);

        document.getElementById('unique-secondary-credits').textContent = uniqueSecondary;
        document.getElementById('total-unique-credits').textContent = totalProgramCredits;
        document.getElementById('combined-remaining-credits').textContent = remainingCombined;
    }

    window.onload = function() {
        document.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', calculateTimeImpact);
        });
    };

