                    <span class="input-group-text">%</span>
                </div>
            </div>
            <div class="col-3">
                <div class="input-group">
                    <input type="number" class="form-control assignment-weight" placeholder="Weight" min="0" max="100" step="0.1" value="${weight}">
                    <span class="input-group-text">%</span>
                </div>
            </div>
            <div class="col-1 text-end">
                <button type="button" class="btn btn-outline-danger remove-btn" title="Remove">&times;</button>
            </div>
        `;

        row.querySelector('.remove-btn').addEventListener('click', () => {
            row.remove();
            autoCalculate();
        });

        row.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', autoCalculate);
        });

        return row;
    }

    /**
     * Helper to trigger calculation automatically on input
     */
    function autoCalculate() {
        const finalWeight = document.getElementById('final_weight').value;
        const targetGrade = document.getElementById('target_grade').value;

        // Only trigger if essential goal data is present
        if (finalWeight && targetGrade) {
            calculateFinalGrade();
        }
    }

    /**
     * Primary Logic
     */
    function calculateFinalGrade(e) {
        if (e) e.preventDefault();

        const resultDiv = document.getElementById('grade-result');
        const summarySection = document.getElementById('summary-section');
        const finalWeight = parseFloat(document.getElementById('final_weight').value);
        const targetGrade = parseFloat(document.getElementById('target_grade').value);

        // Validation gatekeeper
        if (isNaN(finalWeight) || isNaN(targetGrade)) {
            hideResults();
            return;
        }

        const gradeRows = document.querySelectorAll('#grade-list .grade-row');
        let currentTotalWeight = 0;
        let currentEarnedPoints = 0;
        let errors = [];

        gradeRows.forEach((row, index) => {
            const s = parseFloat(row.querySelector('.assignment-score').value);
            const w = parseFloat(row.querySelector('.assignment-weight').value);

            if (!isNaN(s) && !isNaN(w)) {
                currentEarnedPoints += (s / 100) * w;
                currentTotalWeight += w;
            }
        });

        const totalWeight = currentTotalWeight + finalWeight;

        if (totalWeight > 100.001) {
            displayError(`Total weight (${totalWeight.toFixed(1)}%) exceeds 100%. Please adjust.`);
            return;
        }

        // Calculation: (Target - Earned) / FinalWeight * 100
        const pointsNeeded = targetGrade - currentEarnedPoints;
        const requiredGrade = (pointsNeeded / finalWeight) * 100;

        displayResults(requiredGrade, targetGrade, currentEarnedPoints, finalWeight, currentTotalWeight, totalWeight);
    }

    function displayResults(required, target, earned, fWeight, cWeight, tWeight) {
        const resultDiv = document.getElementById('grade-result');
        const summarySection = document.getElementById('summary-section');

        resultDiv.classList.remove('d-none', 'alert-danger', 'alert-success', 'alert-primary');
        summarySection.classList.remove('d-none');

        let msg = '';
        let colorClass = '';

        if (required <= 0) {
            msg = `Great news! You already reached your goal. You need a **0%** on the final.`;
            colorClass = 'alert-success';
        } else if (required > 100) {
            msg = `A target of ${target}% is mathematically impossible with this final's weight. Max possible: ${(earned + fWeight).toFixed(2)}%`;
            colorClass = 'alert-danger';
        } else {
            msg = `To finish with **${target}%**, you need a minimum score of:`;
            colorClass = 'alert-primary';
        }

        resultDiv.classList.add(colorClass);
        resultDiv.innerHTML = `
            ${msg}
            <div id="required-grade">${required > 100 ? 'N/A' : Math.max(0, required).toFixed(2) + '%'}</div>
            <p class="mb-0 small opacity-75">Final Exam constitutes ${fWeight}% of your grade.</p>
        `;

        updateTableAndChart(cWeight, fWeight, tWeight);
    }

    function updateTableAndChart(cWeight, fWeight, tWeight) {
        const tableBody = document.getElementById('grade-body');
        tableBody.innerHTML = `
            <tr><td>Completed Weight</td><td class="text-end">${cWeight.toFixed(1)}%</td></tr>
            <tr><td>Final Exam Weight</td><td class="text-end">${fWeight.toFixed(1)}%</td></tr>
            <tr class="table-light fw-bold"><td>Total Accounted For</td><td class="text-end">${tWeight.toFixed(1)}%</td></tr>
        `;

        const ctx = document.getElementById('grade-chart').getContext('2d');
        if (gradeChart) gradeChart.destroy();

        gradeChart = new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: ['Completed', 'Final Exam', 'Remaining'],
                datasets: [{
                    data: [cWeight, fWeight, Math.max(0, 100 - tWeight)],
                    backgroundColor: ['#0d6efd', '#ffc107', '#e9ecef']
                }]
            },
            options: { maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } } }
        });
    }

    function displayError(message) {
        const res = document.getElementById('grade-result');
        res.classList.remove('d-none', 'alert-success', 'alert-primary');
        res.classList.add('alert-danger');
        res.innerHTML = `<strong>Error:</strong> ${message}`;
        document.getElementById('summary-section').classList.add('d-none');
    }

    function hideResults() {
        document.getElementById('grade-result').classList.add('d-none');
        document.getElementById('summary-section').classList.add('d-none');
    }

    // --- Initialization ---

    document.getElementById('add-grade-btn').addEventListener('click', () => {
        document.getElementById('grade-list').appendChild(createGradeRow());
    });

    document.getElementById('reset-btn').addEventListener('click', () => {
        if(confirm("Clear all entries?")) {
            document.getElementById('grade-list').innerHTML = '';
            document.getElementById('grade-list').appendChild(createGradeRow());
            document.getElementById('final-grade-form').reset();
            hideResults();
        }
    });

    document.getElementById('final_weight').addEventListener('input', autoCalculate);
    document.getElementById('target_grade').addEventListener('input', autoCalculate);
    document.getElementById('final-grade-form').addEventListener('submit', calculateFinalGrade);

    window.addEventListener('load', () => {
        // Professional empty start with 2 clean rows
        const list = document.getElementById('grade-list');
        list.appendChild(createGradeRow());
        list.appendChild(createGradeRow());
    });

education__gpa_calculator:
// --- 4.0 Grading Scale Conversion ---
    const GRADE_POINTS = {
        'A+': 4.00, 'A': 4.00, 'A-': 3.70,
        'B+': 3.30, 'B': 3.00, 'B-': 2.70,
        'C+': 2.30, 'C': 2.00, 'C-': 1.70,
        'D+': 1.30, 'D': 1.00, 'F': 0.00,
        'W': 0.00, 'P': 0.00, 'I': 0.00 // Non-GPA calculating grades (W=Withdraw, P=Pass, I=Incomplete)
    };

    /**
     * Function to create a new course input row.
     */
    function createCourseRow(courseName = '', credits = 3, grade = 'A') {
        const row = document.createElement('div');
        row.className = 'course-row';

        row.innerHTML = `
            <input type="text" class="form-control course-name" placeholder="Course Name (e.g., Calculus I)" value="${courseName}">
            <select class="form-select course-credits">
                ${[...Array(11).keys()].slice(1).map(c => 
                    `<option value="${c}" ${c == credits ? 'selected' : ''}>${c} cr</option>`
                ).join('')}
            </select>
            <select class="form-select course-grade">
                ${Object.keys(GRADE_POINTS).map(g => 
                    `<option value="${g}" ${g === grade ? 'selected' : ''}>${g}</option>`
                ).join('')}
            </select>
            <button type="button" class="btn btn-danger remove-btn" title="Remove Course">&times;</button>
        `;

        // Attach event listener for removal
        row.querySelector('.remove-btn').addEventListener('click', () => {
            row.remove();
            calculateGPA(); // Recalculate immediately on course removal
        });

        // Attach event listeners for immediate recalculation
        row.querySelectorAll('input, select').forEach(input => {
            input.addEventListener('change', calculateGPA);
        });

        return row;
    }

    /**
     * Main calculation logic.
     */
    function calculateGPA() {
        const courseRows = document.querySelectorAll('#course-list .course-row');
        if (courseRows.length === 0) {
            displayError("Please add at least one course.");
            return;
        }

        // --- Semester Data ---
        let semesterTotalCredits = 0;
        let semesterTotalGradePoints = 0;
        let semesterCoursesCount = 0;

        courseRows.forEach(row => {
            const credits = parseFloat(row.querySelector('.course-credits').value);
            const grade = row.querySelector('.course-grade').value;
            const points = GRADE_POINTS[grade];

            if (points > 0 || grade === 'F') { // Only count credit hours for graded courses (A+ to F)
                semesterTotalCredits += credits;
                semesterTotalGradePoints += points * credits;
            }
            // Count all rows, even if they are 'W', 'P', 'I' etc.
            semesterCoursesCount++;
        });

        // --- Prior Data ---
        const priorGpa = parseFloat(document.getElementById('prior_gpa').value) || 0;
        const priorCredits = parseInt(document.getElementById('prior_credits').value) || 0;

        const priorTotalGradePoints = priorGpa * priorCredits;

        // --- Results Calculation ---
        const semesterGPA = semesterTotalCredits > 0 
            ? semesterTotalGradePoints / semesterTotalCredits 
            : 0;

        const cumulativeTotalCredits = priorCredits + semesterTotalCredits;
        const cumulativeTotalGradePoints = priorTotalGradePoints + semesterTotalGradePoints;

        const cumulativeGPA = cumulativeTotalCredits > 0
            ? cumulativeTotalGradePoints / cumulativeTotalCredits
            : semesterGPA; // If no prior credits, cumulative is the same as semester

        // --- Display Results ---
        displayResults(semesterGPA, cumulativeGPA, priorCredits, semesterTotalCredits, cumulativeTotalCredits, semesterCoursesCount);
    }

    /**
     * Function to handle results display.
     */
    function displayResults(semGPA, cumGPA, priorCredits, semCredits, cumCredits, numCourses) {
        const semGPARounded = semGPA.toFixed(3);
        const cumGPARounded = cumGPA.toFixed(3);

        const resultDiv = document.getElementById('gpa-result');
        resultDiv.classList.remove('d-none', 'alert-danger');
        resultDiv.classList.add('alert-success');
        resultDiv.innerHTML = `
            **Semester GPA:** <span class="highlight">${semGPARounded}</span>
            <br>
            **Cumulative GPA:** <span class="highlight">${cumGPARounded}</span>
        `;

        // Update Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('gpa-table').classList.remove('d-none');
        const tableBody = document.getElementById('gpa-body');
        tableBody.innerHTML = `
            <tr><td>Current Courses Attempted</td><td>${numCourses}</td></tr>
            <tr><td>Semester Credits Earned</td><td>${semCredits}</td></tr>
            <tr><td>**Semester GPA**</td><td class="highlight">${semGPARounded}</td></tr>
            <tr><td colspan="2"><hr class="my-0"></td></tr>
            <tr><td>Prior Attempted Credits</td><td>${priorCredits}</td></tr>
            <tr><td>Total Cumulative Credits</td><td>${cumCredits}</td></tr>
            <tr><td>**Cumulative GPA**</td><td class="highlight">${cumGPARounded}</td></tr>
        `;
    }

    /**
     * Function to display calculation errors.
     */
    function displayError(message) {
        const resultDiv = document.getElementById('gpa-result');
        resultDiv.classList.remove('d-none', 'alert-success');
        resultDiv.classList.add('alert-danger');
        resultDiv.innerHTML = `**Calculation Error:** ${message}`;
        document.getElementById('gpa-table').classList.add('d-none');
        document.getElementById('table-title').classList.add('d-none');
    }

    // --- Event Listeners and Initial Setup ---

    // Add event listeners for the prior data fields
    document.getElementById('prior_gpa').addEventListener('change', calculateGPA);
    document.getElementById('prior_credits').addEventListener('change', calculateGPA);

    // Add Course button logic
    document.getElementById('add-course-btn').addEventListener('click', () => {
        document.getElementById('course-list').appendChild(createCourseRow());
    });

    // Form submission (just calls the main function)
    document.getElementById('gpa-form').addEventListener('submit', function (e) {
        e.preventDefault();
        calculateGPA();
    });

    // Initial setup: Add one empty row
    window.addEventListener('load', () => {
        const courseList = document.getElementById('course-list');
        courseList.appendChild(createCourseRow('', 3, 'A'));
    });

