function resetCalc() {
        if(confirm("Clear all academic inputs?")) {
            document.querySelectorAll('input').forEach(i => i.value = '');
            calculateImpact();
        }
    }

    function calculateImpact() {
        const completed = parseFloat(document.getElementById('credits-completed').value);
        const originalTotal = parseFloat(document.getElementById('credits-original-major').value);
        const newTotal = parseFloat(document.getElementById('credits-new-major').value);
        const overlap = parseFloat(document.getElementById('credits-overlap').value) || 0;
        const creditsPerSem = parseFloat(document.getElementById('credits-per-semester').value) || 15;
        const costPerCredit = parseFloat(document.getElementById('cost-per-credit').value) || 0;

        const placeholder = document.getElementById('placeholder-ui');
        const results = document.getElementById('results-ui');

        // Professional Check: Hide results if core data is missing
        if (isNaN(completed) || isNaN(originalTotal) || isNaN(newTotal)) {
            placeholder.classList.remove('d-none');
            results.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        results.classList.remove('d-none');

        // Logic
        const safeOverlap = Math.min(overlap, completed);
        const remainingOld = Math.max(0, originalTotal - completed);
        const remainingNew = Math.max(0, newTotal - safeOverlap);
        const extraCredits = Math.max(0, remainingNew - remainingOld);

        const semesterExtension = extraCredits / (creditsPerSem || 1);
        const totalSemestersRequired = (completed + remainingNew) / (creditsPerSem || 1);
        const additionalCost = extraCredits * costPerCredit;

        // UI Updates
        document.getElementById('semester-extension').textContent = semesterExtension.toFixed(1);
        document.getElementById('cost-extension').textContent = '$' + additionalCost.toLocaleString();

        document.getElementById('required-new').textContent = newTotal;
        document.getElementById('remaining-new').textContent = remainingNew;
        document.getElementById('net-credit-diff').textContent = `+${extraCredits}`;
        document.getElementById('total-semesters-new').textContent = totalSemestersRequired.toFixed(1);
    }

    window.onload = function() {
        document.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', calculateImpact);
        });
    };

