function calculateTime() {
        const numCards = parseFloat(document.getElementById('num-cards').value);
        const learningRate = parseFloat(document.getElementById('learning-rate').value);
        const reviewFactor = parseFloat(document.getElementById('review-factor').value);
        const dailyHours = parseFloat(document.getElementById('daily-hours').value);

        const placeholder = document.getElementById('placeholder-ui');
        const results = document.getElementById('results-ui');

        // Professional "Clean State" Check
        if (!numCards || !learningRate || !dailyHours) {
            placeholder.classList.remove('d-none');
            results.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        results.classList.remove('d-none');

        // Calculations
        const initialTime = numCards / learningRate;
        const reviewTime = initialTime * reviewFactor;
        const totalTime = initialTime + reviewTime;
        const totalDays = Math.ceil(totalTime / dailyHours);
