function calculate() {
        const target = parseFloat(document.getElementById('target-word-count').value);

        const t = parseFloat(document.getElementById('t-words').value) || 0;
        const e = parseFloat(document.getElementById('e-words').value) || 0;
        const a = parseFloat(document.getElementById('a-words').value) || 0;
        const l = parseFloat(document.getElementById('l-words').value) || 0;

        const emptyState = document.getElementById('empty-state');
        const plannerContent = document.getElementById('planner-content');
        const totalDisplay = document.getElementById('total-words-display');
        const badge = document.getElementById('status-badge');

        if (!target || target <= 0) {
            emptyState.style.display = 'block';
            plannerContent.style.display = 'none';
            totalDisplay.textContent = '0';
            return;
        }

        emptyState.style.display = 'none';
        plannerContent.style.display = 'block';

        const total = t + e + a + l;
        totalDisplay.textContent = total;

        // Visual Progress Bar Logic
        const barT = document.getElementById('bar-t');
        const barE = document.getElementById('bar-e');
        const barA = document.getElementById('bar-a');
        const barL = document.getElementById('bar-l');

        const pT = (t / total) * 100;
        const pE = (e / total) * 100;
        const pA = (a / total) * 100;
        const pL = (l / total) * 100;

        barT.style.width = pT + '%';
        barE.style.width = pE + '%';
        barA.style.width = pA + '%';
        barL.style.width = pL + '%';

        barT.textContent = pT > 5 ? 'T' : '';
        barE.textContent = pE > 5 ? 'E' : '';
        barA.textContent = pA > 5 ? 'A' : '';
        barL.textContent = pL > 5 ? 'L' : '';

        // Status Feedback
        const diff = total - target;
        if (Math.abs(diff) <= 10) {
            badge.innerHTML = '<span class="badge bg-success">Perfect Length</span>';
        } else if (diff > 0) {
            badge.innerHTML = `<span class="badge bg-danger">${diff} Words Over</span>`;
        } else {
            badge.innerHTML = `<span class="badge bg-warning text-dark">${Math.abs(diff)} Words Short</span>`;
        }
    }

