function updatePaceTip(pace) {
        const tipEl = document.getElementById('pace-tip');
        let text = "";
        if (pace <= 0.5) text = "<strong>Rapid Style:</strong> Focus on one image per slide and very little text. Perfect for high-energy pitches.";
        else if (pace <= 1.0) text = "<strong>Dynamic Style:</strong> TED-style pacing. Keep slides clean and move quickly to maintain engagement.";
        else if (pace <= 1.5) text = "<strong>Standard Style:</strong> A balanced pace allowing for short bullet points and brief chart explanations.";
        else if (pace <= 2.5) text = "<strong>Detailed Style:</strong> Best for technical or academic talks where data needs to be parsed by the audience.";
        else text = "<strong>Interactive Style:</strong> Slides act as background anchors while you engage in discussion or workshops.";

        tipEl.innerHTML = `<i class="bi bi-lightbulb-fill text-warning me-1"></i> ${text}`;
    }

    function calculateSlides() {
        const totalMins = parseFloat(document.getElementById('total-minutes').value);
        const qnaMins = parseFloat(document.getElementById('qna-minutes').value) || 0;
        const pace = parseFloat(document.getElementById('pres-style').value);

        const placeholder = document.getElementById('placeholder-ui');
        const results = document.getElementById('results-ui');

        if (isNaN(totalMins) || isNaN(pace)) {
            placeholder.classList.remove('d-none');
            results.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        results.classList.remove('d-none');
        updatePaceTip(pace);

        const netTime = Math.max(0, totalMins - qnaMins);
        let totalSlides = Math.round(netTime / pace);
        if (totalSlides < 1 && netTime > 0) totalSlides = 1;

        // Breakdown Logic
        let intro = Math.max(1, Math.round(totalSlides * 0.15));
        let conc = Math.max(1, Math.round(totalSlides * 0.15));
        if (totalSlides <= 2) { intro = 1; conc = totalSlides === 2 ? 1 : 0; }
        let body = Math.max(0, totalSlides - intro - conc);

        // UI Updates
