let holidayCount = 0;

    function createHolidayRow() {
        holidayCount++;
        const row = document.createElement('div');
        row.className = 'holiday-row d-flex align-items-center gap-2';
        row.id = `h-row-${holidayCount}`;
        row.innerHTML = `
            <input type="date" class="form-control form-control-sm border-0 holiday-date-input" oninput="calculateDeadline()">
            <button class="btn btn-link btn-sm text-danger p-0" onclick="removeHoliday(${holidayCount})"><i class="bi bi-x-circle-fill"></i></button>
        `;
        document.getElementById('holidays-list').appendChild(row);
    }

    function removeHoliday(id) {
        document.getElementById(`h-row-${id}`).remove();
        calculateDeadline();
    }

    function calculateDeadline() {
        const effort = parseFloat(document.getElementById('total-effort-hours').value);
        const dailyHrs = parseFloat(document.getElementById('daily-hours').value);
        const startStr = document.getElementById('start-date').value;

        const placeholder = document.getElementById('placeholder-ui');
        const results = document.getElementById('results-ui');

        if (!effort || !dailyHrs || !startStr) {
            placeholder.classList.remove('d-none');
            results.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        results.classList.remove('d-none');

        const totalWorkDays = Math.ceil(effort / dailyHrs);
        const workingDaysSet = new Set();
        document.querySelectorAll('.day-checkbox').forEach(cb => {
            if (cb.checked) workingDaysSet.add(parseInt(cb.dataset.day));
        });

        const holidaysSet = new Set();
        document.querySelectorAll('.holiday-date-input').forEach(input => {
            if (input.value) holidaysSet.add(input.value);
        });

        let currentDate = new Date(startStr + 'T00:00:00');
        let daysFound = 0;
        let calendarDays = 0;

        while (daysFound < totalWorkDays) {
            const dayOfWeek = currentDate.getDay();
            const dateStr = currentDate.toISOString().split('T')[0];

            if (workingDaysSet.has(dayOfWeek) && !holidaysSet.has(dateStr)) {
                daysFound++;
            }

            if (daysFound < totalWorkDays) {
                currentDate.setDate(currentDate.getDate() + 1);
            }
            calendarDays++;
        }

        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        document.getElementById('deadline-date').textContent = currentDate.toLocaleDateString('en-US', options);
        document.getElementById('work-days-count').textContent = totalWorkDays;
        document.getElementById('calendar-days-count').textContent = calendarDays + " Days";
    }

    window.onload = () => {
        // Set default start date to today
        document.getElementById('start-date').value = new Date().toISOString().split('T')[0];

        document.getElementById('add-holiday-btn').addEventListener('click', createHolidayRow);
        document.querySelectorAll('input, select').forEach(el => {
            el.addEventListener('input', calculateDeadline);
        });
    }

