const MS_PER_DAY = 1000 * 60 * 60 * 24;
    const DAYS_PER_WEEK = 7;

    function resetCalculator() {
        document.getElementById('start-date').value = '';
        document.getElementById('end-date').value = '';
        document.getElementById('total-weeks').value = 15;
        calculateCountdown();
    }

    function calculateCountdown() {
        const startDateStr = document.getElementById('start-date').value;
        const endDateStr = document.getElementById('end-date').value;
        const totalWeeks = parseFloat(document.getElementById('total-weeks').value);
        const currentDate = new Date();
        currentDate.setHours(0,0,0,0);

        const emptyState = document.getElementById('empty-state');
        const resultsDashboard = document.getElementById('results-dashboard');
        const statusMessageEl = document.getElementById('status-message');
        const progressBarEl = document.getElementById('progress-bar');
        const weekLabel = document.getElementById('current-week-label');

        // Professional State Handling: Hide dashboard if inputs are missing
        if (!startDateStr || !endDateStr) {
            emptyState.classList.remove('d-none');
            resultsDashboard.classList.add('d-none');
            return;
        }

        emptyState.classList.add('d-none');
        resultsDashboard.classList.remove('d-none');

        const startDate = new Date(startDateStr);
        const endDate = new Date(endDateStr);

        // Validation
        if (startDate >= endDate) {
            statusMessageEl.innerHTML = "<strong>Error:</strong> The start date must occur before the end date.";
            updateValues(0, totalWeeks, 0);
            return;
        }

        const totalScheduledDays = totalWeeks * DAYS_PER_WEEK;
        let elapsedWeeks = 0;
        let completionPercentage = 0;
        let message = "";

        if (currentDate < startDate) {
            const diffTime = Math.abs(startDate - currentDate);
            const daysToStart = Math.ceil(diffTime / MS_PER_DAY);
            message = `The semester hasn't started yet. Classes begin in <strong>${daysToStart} days</strong>.`;
            elapsedWeeks = 0;
            completionPercentage = 0;
            weekLabel.innerText = "Pre-Semester";
        } else if (currentDate > endDate) {
            message = "Congratulations! The semester has officially concluded.";
            elapsedWeeks = totalWeeks;
            completionPercentage = 100;
            weekLabel.innerText = "Term Finished";
        } else {
            const diffTime = Math.abs(currentDate - startDate);
            const elapsedDays = Math.floor(diffTime / MS_PER_DAY) + 1;

            elapsedWeeks = elapsedDays / DAYS_PER_WEEK;
            completionPercentage = Math.min(100, (elapsedDays / totalScheduledDays) * 100);

            const currentWeek = Math.ceil(elapsedWeeks);
            weekLabel.innerText = `Currently in Week ${currentWeek}`;
            message = `You are performing well! There are <strong>${(totalWeeks - elapsedWeeks).toFixed(1)} weeks</strong> remaining until the end of the term.`;
        }

        updateValues(elapsedWeeks, totalWeeks - elapsedWeeks, completionPercentage);
        statusMessageEl.innerHTML = message;
    }

    function updateValues(elapsed, remaining, percent) {
        document.getElementById('elapsed-weeks').innerText = elapsed.toFixed(1);
        document.getElementById('remaining-weeks').innerText = Math.max(0, remaining).toFixed(1);
        document.getElementById('completion-percentage').innerText = percent.toFixed(1) + '%';

        const bar = document.getElementById('progress-bar');
        bar.style.width = percent + '%';
        bar.innerText = percent >= 10 ? percent.toFixed(1) + '%' : '';
    }

