        style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0
    });

    /**
     * Amortization Formula for monthly payments
     */
    function calculateMonthlyPayment(P, R, T) {
        if (P <= 0 || T <= 0) return 0;
        const i = R / 12;
        const n = T * 12;
        if (i === 0) return P / n;
        return P * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
    }

    function calculateDTI() {
        const totalDebt = parseFloat(document.getElementById('total-debt').value) || 0;
        const annualSalary = parseFloat(document.getElementById('annual-salary').value) || 0;
        const interestRate = parseFloat(document.getElementById('interest-rate').value) / 100 || 0;
        const repaymentTerm = parseFloat(document.getElementById('repayment-term').value) || 0;

        const initialState = document.getElementById('initial-state');
        const resultState = document.getElementById('result-state');

        // Professional Clean Slate Logic: Show results only when main data is present
        if (totalDebt <= 0 || annualSalary <= 0) {
            initialState.classList.remove('d-none');
            resultState.classList.add('d-none');
            return;
        }

        initialState.classList.add('d-none');
        resultState.classList.remove('d-none');

        const monthlyPayment = calculateMonthlyPayment(totalDebt, interestRate, repaymentTerm);
        const monthlyIncome = annualSalary / 12;
        const dtiRatio = (monthlyPayment / monthlyIncome) * 100;

        // UI Updates
        document.getElementById('monthly-payment').textContent = currencyFormatter.format(monthlyPayment);
        document.getElementById('monthly-income').textContent = currencyFormatter.format(monthlyIncome);
        document.getElementById('dti-ratio').textContent = dtiRatio.toFixed(1) + "%";

        // Risk Assessment
        const dtiCard = document.getElementById('dti-card');
        const riskBadge = document.getElementById('risk-badge');

        dtiCard.classList.remove('risk-low', 'risk-medium', 'risk-high');

        if (dtiRatio < 10) {
            dtiCard.classList.add('risk-low');
            riskBadge.textContent = "Low Risk: Sustainable";
        } else if (dtiRatio <= 20) {
            dtiCard.classList.add('risk-medium');
            riskBadge.textContent = "Moderate Risk: Manageable";
        } else {
            dtiCard.classList.add('risk-high');
            riskBadge.textContent = "High Risk: Action Recommended";
        }
    }

    window.onload = function() {
        document.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', calculateDTI);
        });
    };

education__student_loan_forgiveness_elig:
const loanTypeEl = document.getElementById('loan-type');
    const repaymentPlanEl = document.getElementById('repayment-plan');
    const employmentEl = document.getElementById('qualifying-employment');
    const pslfSlider = document.getElementById('payments-made-pslf');
    const idrSlider = document.getElementById('years-completed-idr');

    const emptyState = document.getElementById('empty-state');
    const calcState = document.getElementById('calculation-state');
    const resultBox = document.getElementById('result-box');
    const statusText = document.getElementById('forgiveness-status');
    const timelineDetails = document.getElementById('timeline-details');
    const resultMsg = document.getElementById('result-message');

    function calculateEligibility() {
        const loan = loanTypeEl.value;
        if (!loan) return;

        // Sync displays
        document.getElementById('pslf-payments-display').textContent = pslfSlider.value;
        document.getElementById('idr-years-display').textContent = idrSlider.value;

        emptyState.style.display = 'none';
        calcState.style.display = 'block';

        const pslfMade = parseInt(pslfSlider.value);
        const idrYears = parseInt(idrSlider.value);
        const onIdr = repaymentPlanEl.value === 'idr';
        const inPublic = employmentEl.value === 'yes';

        // 1. Private Loan Logic
        if (loan === 'private') {
            showResult('ineligible', 'INELIGIBLE: PRIVATE LOANS', 
                `<div class="timeline-stat text-danger fw-bold">No Federal Path Available</div>
                 <p class="mt-2 small">Private student loans are not eligible for federal forgiveness programs like PSLF or IDR.</p>`,
                'Action: Consult your lender for private refinancing or hardship deferment options.');
            return;
        }

        // 2. PSLF Path Logic
        if (loan === 'direct' && inPublic && (onIdr || repaymentPlanEl.value === 'standard')) {
            const rem = 120 - pslfMade;
            if (rem <= 0) {
                showResult('eligible', 'PSLF ELIGIBLE!', 
                    `<div class="timeline-stat text-success"><i class="bi bi-patch-check-fill me-2"></i><strong>120/120 Payments Made</strong></div>`,
                    'Action: Submit your PSLF Forgiveness Application through the StudentAid.gov PSLF Help Tool immediately.');
            } else {
                showResult('partial', 'ON TRACK FOR PSLF', 
                    `<div class="timeline-stat">
                        <div class="d-flex justify-content-between"><span>Remaining:</span> <strong>${rem} Payments</strong></div>
                        <div class="d-flex justify-content-between"><span>Est. Date:</span> <strong>${Math.ceil(rem/12)} Years</strong></div>
                    </div>`,
                    'Keep certifying your employment annually to lock in these payment counts.');
            }
            return;
        }

        // 3. IDR Path Logic
        if (onIdr) {
            const target = 20; // simplified undergraduate target
            const rem = target - idrYears;
            if (rem <= 0) {
                showResult('eligible', 'IDR FORGIVENESS READY', 
                    `<div class="timeline-stat text-success"><strong>${idrYears}+ Years Completed</strong></div>`,
                    'Contact your servicer to verify your IDR account adjustment count.');
            } else {
                showResult('partial', 'IDR FORGIVENESS PATH', 
                    `<div class="timeline-stat">
                        <div class="d-flex justify-content-between"><span>Years Remaining:</span> <strong>${rem} Years</strong></div>
                    </div>`,
                    'Ensure you recertify your income every year to remain on this path.');
            }
            return;
        }

        // 4. Default / Consolidation Guidance
        if (loan === 'ffel-perkins') {
            showResult('ineligible', 'CONSOLIDATION REQUIRED', 
                `<p class="small">Your FFEL/Perkins loans are federal, but they must be converted to a <strong>Direct Consolidation Loan</strong> to qualify.</p>`,
                'Action: Visit StudentAid.gov to consolidate your loans into the Direct Loan program.');
        } else {
            showResult('ineligible', 'NO ACTIVE PATH', 
                `<p class="small">Currently, your plan or employment does not align with federal forgiveness requirements.</p>`,
                'Action: Switch to an Income-Driven Repayment (IDR) plan to begin accruing credit toward eventual forgiveness.');
        }
    }

    function showResult(type, title, html, msg) {
        resultBox.className = `result-display-area ${type}-border`;
        statusText.className = `result-status text-${type === 'partial' ? 'warning' : (type === 'eligible' ? 'success' : 'danger')}`;
        statusText.textContent = title;
        timelineDetails.innerHTML = html;
        resultMsg.textContent = msg;
    }

education__student_loan_refinance_saving:
let comparisonChart = null;

    function formatCurrency(amount) {
        return new Intl.NumberFormat('en-US', {
            style: 'currency', currency: 'USD'
        }).format(amount);
    }

    function calculateLoanDetails(principal, annualRate, termYears) {
        const i = (annualRate / 100) / 12;
        const n = termYears * 12;

        const monthlyPayment = i === 0 ? principal / n : principal * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
        const totalCost = monthlyPayment * n;
        const totalInterest = totalCost - principal;

        return { payment: monthlyPayment, totalInterest: totalInterest, totalCost: totalCost };
    }

    function calculateRefinance(e) {
        if (e) e.preventDefault();

        const principal = parseFloat(document.getElementById('current_principal').value);
        const currRate = parseFloat(document.getElementById('current_rate').value);
        const currTerm = parseFloat(document.getElementById('current_term').value);
        const newRate = parseFloat(document.getElementById('new_rate').value);
        const newTerm = parseFloat(document.getElementById('new_term').value);

        if (!principal || !currRate || !currTerm || !newRate || !newTerm) return;

        const currentLoan = calculateLoanDetails(principal, currRate, currTerm);
        const newLoan = calculateLoanDetails(principal, newRate, newTerm);

        const monthlySavings = currentLoan.payment - newLoan.payment;
        const interestSavings = currentLoan.totalInterest - newLoan.totalInterest;

        // UI Updates
        document.getElementById('results-container').classList.remove('d-none');
        document.getElementById('current-payment').textContent = formatCurrency(currentLoan.payment);
        document.getElementById('new-payment').textContent = formatCurrency(newLoan.payment);
        document.getElementById('current-interest').textContent = formatCurrency(currentLoan.totalInterest);
        document.getElementById('new-interest').textContent = formatCurrency(newLoan.totalInterest);

        const msgEl = document.getElementById('savings-message');
        msgEl.className = interestSavings >= 0 ? 'savings-result shadow-sm' : 'loss-result shadow-sm';
        msgEl.innerHTML = interestSavings >= 0 
            ? `🎉 Total Savings: ${formatCurrency(interestSavings)}`
            : `⚠️ Total Extra Cost: ${formatCurrency(Math.abs(interestSavings))}`;

        document.getElementById('monthly-difference').innerHTML = monthlySavings >= 0 
            ? `<span class="text-success">Save ${formatCurrency(monthlySavings)}/mo</span>`
            : `<span class="text-danger">Extra ${formatCurrency(Math.abs(monthlySavings))}/mo</span>`;

        document.getElementById('total-interest-savings').innerHTML = interestSavings >= 0
            ? `<span class="text-success">Save ${formatCurrency(interestSavings)} total</span>`
            : `<span class="text-danger">Pay ${formatCurrency(Math.abs(interestSavings))} extra</span>`;

        updateChart(principal, currentLoan.totalInterest, newLoan.totalInterest);
        window.scrollTo({ top: document.getElementById('results-container').offsetTop - 50, behavior: 'smooth' });
    }

    function updateChart(principal, curInt, newInt) {
        const ctx = document.getElementById('comparison-chart').getContext('2d');
        if (comparisonChart) comparisonChart.destroy();

        comparisonChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: ['Current Loan', 'Refinanced Loan'],
                datasets: [
                    { label: 'Principal', data: [principal, principal], backgroundColor: '#90caf9' },
                    { label: 'Total Interest', data: [curInt, newInt], backgroundColor: '#ef9a9a' }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: { x: { stacked: true }, y: { stacked: true, beginAtZero: true } },
                plugins: { legend: { position: 'bottom' } }
            }
        });
    }

    document.getElementById('refinance-calculator-form').addEventListener('submit', calculateRefinance);

    document.getElementById('current_principal').addEventListener('input', (e) => {
        const val = e.target.value;
        document.getElementById('new_principal_display').value = val ? formatCurrency(val) : '';
    });

    document.getElementById('reset-btn').addEventListener('click', () => {
        document.getElementById('refinance-calculator-form').reset();
        document.getElementById('results-container').classList.add('d-none');
        if (comparisonChart) comparisonChart.destroy();
    });

