        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic: Liability ($100 base + scale)
        let liability = 0;
        if (guests > 0) {
            liability = 125 + (Math.floor(guests / 100) * 35);
        }

        // Logic: Liquor Liability
        let liquor = 0;
        if (liquorType === 'host') liquor = 50 + (guests * 0.40);
        else if (liquorType === 'retail') liquor = 75 + (guests * 0.60);

        // Logic: Cancellation (Approx 1% - 1.5% of budget)
        let cancel = budget * 0.012;

        const total = liability + liquor + cancel;

        // Display
        document.getElementById('cost-liability').textContent = '$' + liability.toFixed(0);
        document.getElementById('cost-liquor').textContent = '$' + liquor.toFixed(0);
        document.getElementById('cost-cancel').textContent = '$' + cancel.toFixed(0);
        document.getElementById('total-premium').textContent = '$' + total.toFixed(0);

        const riskEl = document.getElementById('risk-rating');
        if (liquorType !== 'none' && guests > 200) {
            riskEl.textContent = "Risk Level: Moderate";
            riskEl.className = "mb-0 small fw-bold text-warning";
