function calculateNetworking() {
        const guests = parseFloat(document.getElementById('net-guests').value) || 0;
        const type = document.getElementById('net-type').value;
        const goals = parseFloat(document.getElementById('net-goals').value);
        const hasBuffer = document.getElementById('add-buffer').checked;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (guests <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic
        // Minutes per conversation based on intensity
        let minsPerConvo = 5; 
        if (type === 'low') minsPerConvo = 12; // Natural conversations take longer
        if (type === 'med') minsPerConvo = 7;
        if (type === 'high') minsPerConvo = 4; // Rapid switches

        let baseTime = goals * minsPerConvo;

        // Scale time slightly for larger groups to account for "cross-room travel"
        if (guests > 100) baseTime *= 1.2;

        const buffer = hasBuffer ? 15 : 0;
        const totalDuration = Math.ceil(baseTime + buffer);

        // Potential unique pairs in the room
        const potentialPairs = (guests * (guests - 1)) / 2;

        document.getElementById('total-time').textContent = totalDuration;
        document.getElementById('stat-potential').textContent = potentialPairs.toLocaleString() + " pairs";
        document.getElementById('stat-per-guest').textContent = (totalDuration / guests).toFixed(1);
    }

    window.onload = () => {
        document.querySelectorAll('.net-input, #net-guests').forEach(el => {
            el.addEventListener('input', calculateNetworking);
        });
    };

