function calculatePower() {
        const v = parseFloat(document.getElementById('voltage-input').value);

        // Load Inputs
        const avWatt = parseFloat(document.getElementById('watt-av').value) || 0;
        const avQty = parseFloat(document.getElementById('qty-av').value) || 0;

        const lightWatt = parseFloat(document.getElementById('watt-light').value) || 0;
        const lightQty = parseFloat(document.getElementById('qty-light').value) || 0;

        const cateringWatt = parseFloat(document.getElementById('watt-catering').value) || 0;
        const cateringQty = parseFloat(document.getElementById('qty-catering').value) || 0;

        // Sum Category Watts
        const totalWatts = (avWatt * avQty) + (lightWatt * lightQty) + (cateringWatt * cateringQty);

        // Ohms Law: Amps = Watts / Volts
        const totalAmps = totalWatts / v;

        // Generator Sizing: (Watts / 1000) / 0.8 (Power Factor) = kVA
        const kva = (totalWatts / 1000) / 0.8;

        // Update UI
        document.getElementById('total-watts').textContent = totalWatts.toLocaleString() + 'W';
        document.getElementById('total-amps').textContent = totalAmps.toFixed(1) + ' A';
        document.getElementById('gen-kva').textContent = kva.toFixed(1) + ' kVA';

        // High load warning (> 40A typically requires heavy 3-phase or spider boxes)
        const warning = document.getElementById('safety-warning');
        if (totalAmps > 40) {
            warning.classList.remove('d-none');
        } else {
            warning.classList.add('d-none');
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        document.querySelectorAll('.pwr-input, #voltage-input').forEach(el => {
            el.addEventListener('input', calculatePower);
        });

        // Initial calculation to set 0 values
        calculatePower();
    });

