function calculateFees() {
        const base = parseFloat(document.getElementById('base-price').value) || 0;
        const feePct = (parseFloat(document.getElementById('fee-percent').value) || 0) / 100;
        const feeFlat = parseFloat(document.getElementById('fee-flat').value) || 0;
        const taxPct = (parseFloat(document.getElementById('tax-percent').value) || 0) / 100;
        const strategy = document.getElementById('fee-strategy').value;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (base <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        let attendeePrice, netProfit;
        const totalFees = (base * feePct) + feeFlat;
        const totalTax = base * taxPct;

        if (strategy === 'pass') {
            // Attendee pays base + fees + tax
            attendeePrice = base + totalFees + totalTax;
            netProfit = base;
        } else {
            // Attendee pays base, you cover fees and tax
            attendeePrice = base;
            netProfit = base - totalFees - totalTax;
        }

        document.getElementById('total-attendee-price').textContent = '$' + attendeePrice.toFixed(2);
        document.getElementById('net-profit-per-ticket').textContent = '$' + netProfit.toFixed(2);
    }

    window.onload = () => {
        document.querySelectorAll('.reg-input, #fee-strategy').forEach(el => {
            el.addEventListener('input', calculateFees);
        });
    };

