        const revTickets = parseFloat(document.getElementById('rev-tickets').value) || 0;
        const revSponsors = parseFloat(document.getElementById('rev-sponsors').value) || 0;
        const expHard = parseFloat(document.getElementById('exp-hard').value) || 0;
