            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic
        // Base SqFt = People * style preference
        let totalSqft = people * styleSqft;
        if (hasFurniture) totalSqft *= 1.2;

        // Determine common stage deck sizes (Assuming 4x8 or 4x4 decks)
        // This is a simplified calculation for a standard 3:2 or 2:1 aspect ratio stage
        let depth = 8;
        if (totalSqft > 120) depth = 12;
        if (totalSqft > 300) depth = 16;

        let width = Math.ceil(totalSqft / depth);
        // Round up to nearest 4ft increment (Standard stage deck size)
        width = Math.ceil(width / 4) * 4;

        const finalSqft = width * depth;
        const finalBackdropWidth = width + (overhang * 2);

        document.getElementById('total-dimensions').textContent = width + "' x " + depth + "'";
        document.getElementById('total-sqft').textContent = finalSqft + " sq. ft.";
        document.getElementById('backdrop-width').textContent = finalBackdropWidth + " ft.";
    }

