function calculateLogistics() {
        const guests = parseFloat(document.getElementById('transp-guests').value) || 0;
        const shuttleCap = parseFloat(document.getElementById('shuttle-type').value);
        const shuttleRate = parseFloat(document.getElementById('cost-shuttle').value) || 0;
        const parkingRate = parseFloat(document.getElementById('cost-parking').value) || 0;
        const valetRate = parseFloat(document.getElementById('cost-valet').value) || 0;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (guests <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Shuttles needed (1 shuttle can do multiple loops, but this estimates total vehicles for a single window)
        const numShuttles = Math.ceil(guests / shuttleCap);
        const parkingSpots = Math.ceil(guests / 2.5);

        // Total Cost
        const totalCost = (numShuttles * shuttleRate) + parkingRate + valetRate;

        // Display
        document.getElementById('total-transp-cost').textContent = '$' + totalCost.toLocaleString();
        document.getElementById('req-shuttles').textContent = numShuttles;
        document.getElementById('req-parking').textContent = parkingSpots;
    }

    window.onload = () => {
        document.querySelectorAll('.transp-input, #transp-guests').forEach(el => {
            el.addEventListener('input', calculateLogistics);
        });
    };

