function calculateTravel() {
        const count = parseFloat(document.getElementById('vip-count').value) || 0;
        const airfare = parseFloat(document.getElementById('air-class').value);
        const nightlyRate = parseFloat(document.getElementById('hotel-rate').value) || 0;
        const nights = parseFloat(document.getElementById('hotel-nights').value);
        const hasStipend = document.getElementById('add-stipend').checked;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (count <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic
        const totalAir = count * airfare;
        const totalHotel = count * (nightlyRate * nights);
        const stipendPerDay = 125;
        // Total days = Nights + 1 (Travel day)
        const totalMisc = hasStipend ? (count * (nights + 1) * stipendPerDay) : 0;

        const grandTotal = totalAir + totalHotel + totalMisc;
        const perPerson = grandTotal / count;

        document.getElementById('total-travel-cost').textContent = '$' + grandTotal.toLocaleString();
        document.getElementById('per-person-cost').textContent = '$' + perPerson.toLocaleString() + " per person";
        document.getElementById('stat-airfare').textContent = '$' + totalAir.toLocaleString();
        document.getElementById('stat-lodging').textContent = '$' + totalHotel.toLocaleString();
        document.getElementById('stat-misc').textContent = '$' + totalMisc.toLocaleString();
    }

    window.onload = () => {
        document.querySelectorAll('.travel-input, #vip-count').forEach(el => {
            el.addEventListener('input', calculateTravel);
        });
    };

