function calculateWaste() {
        const guests = parseFloat(document.getElementById('waste-guests').value) || 0;
        const hours = parseFloat(document.getElementById('waste-hours').value) || 0;
        const perGuestLoad = parseFloat(document.getElementById('waste-style').value);

        const hasRecycle = document.getElementById('has-recycle').checked;
        const hasCompost = document.getElementById('has-compost').checked;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (guests <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic: Total lbs = Guests * lbs per guest + a slight factor for duration
        const totalLbs = Math.round(guests * (perGuestLoad + (hours * 0.05)));

        // Bin Stations: 1 station per 100 guests for small events, 1 per 150 for massive ones
        const stationsNeeded = Math.ceil(guests / 100);

        // Diversion Rate Estimate
        let diversion = 10; // Base landfill diversion (e.g. pallets/packaging)
        if (hasRecycle) diversion += 30;
        if (hasCompost) diversion += 35;

        document.getElementById('total-weight').textContent = totalLbs.toLocaleString();
        document.getElementById('total-stations').textContent = stationsNeeded;
        document.getElementById('diversion-rate').textContent = diversion + '%';
    }

    window.onload = () => {
        document.querySelectorAll('.waste-input, #waste-guests, #waste-hours').forEach(el => {
            el.addEventListener('input', calculateWaste);
        });
    };

