function calculateBandwidth() {
        const guests = parseFloat(document.getElementById('net-guests').value) || 0;
        const density = parseFloat(document.getElementById('net-density').value);
        const intensity = parseFloat(document.getElementById('net-intensity').value);
        const stream = parseFloat(document.getElementById('net-stream').value);
        const ops = document.getElementById('net-ops-check').checked ? 5 : 0;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (guests <= 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic
        const totalDevices = guests * density;

        // Base guest bandwidth = (Devices * Intensity per device) * Concurrency Factor (0.35)
        const guestMbps = (totalDevices * intensity) * 0.35;

        // Total = Guest Load + Streaming Buffer + Ops Buffer
        const totalMbps = Math.ceil(guestMbps + stream + ops);

        document.getElementById('total-mbps').textContent = totalMbps;
        document.getElementById('total-devices').textContent = Math.round(totalDevices).toLocaleString();
    }

    window.onload = () => {
        document.querySelectorAll('.net-input, #net-guests, #net-density').forEach(el => {
            el.addEventListener('input', calculateBandwidth);
        });
    };

