function calculatePricing() {
        const guests = parseFloat(document.getElementById('calc-guests').value) || 0;
        const fixed = parseFloat(document.getElementById('cost-fixed').value) || 0;
        const variable = parseFloat(document.getElementById('cost-variable').value) || 0;
        const profit = parseFloat(document.getElementById('target-profit').value) || 0;

        const placeholder = document.getElementById('placeholder-ui');
        const planner = document.getElementById('planner-ui');
        const summary = document.getElementById('summary-section');

        if (guests <= 0 && fixed === 0) {
            placeholder.classList.remove('d-none');
            planner.classList.add('d-none');
            summary.classList.add('d-none');
            return;
        }

        placeholder.classList.add('d-none');
        planner.classList.remove('d-none');
        summary.classList.remove('d-none');

        // Logic
        const totalVariable = guests * variable;
        const totalExpenses = fixed + totalVariable;

        // Break-even price = Total Fixed / Guests + Variable Cost
        const bePrice = (guests > 0) ? (fixed / guests) + variable : 0;

        // Recommended price (with profit)
        const recPrice = (guests > 0) ? ((fixed + profit) / guests) + variable : 0;

        // Display
        document.getElementById('be-price').textContent = '$' + bePrice.toFixed(2);
        document.getElementById('total-expenses-summary').textContent = '$' + totalExpenses.toLocaleString();
        document.getElementById('target-profit-summary').textContent = '$' + profit.toLocaleString();
        document.getElementById('recommended-price').textContent = '$' + recPrice.toFixed(2);
    }

    window.onload = () => {
        document.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', calculatePricing);
        });
    };

