function makeRow(){ const d=document.createElement('div'); d.className='cat-row'; d.innerHTML=`
  <input class="form-control pir-name" placeholder="Category (e.g., Groceries)">
  <input class="form-control pir-last" type="number" placeholder="Last Year Spend (annual)" min="0" step="0.01">
  <input class="form-control pir-this" type="number" placeholder="This Year Spend (annual)" min="0" step="0.01">
  <button class="btn btn-outline-danger btn-sm remove-cat" type="button">−</button>`; return d;
}
document.getElementById('pir-add').addEventListener('click', ()=>document.getElementById('pir-list').appendChild(makeRow()));
document.addEventListener('click', e=>{ if(e.target.classList.contains('remove-cat')) e.target.parentElement.remove(); });

let pirChart = null;
document.getElementById('pir-form').addEventListener('submit', function(e){
  e.preventDefault();
  const names = Array.from(document.querySelectorAll('.pir-name')).map(n=>n.value||'Category');
  const last = Array.from(document.querySelectorAll('.pir-last')).map(n=>parseFloat(n.value)||0);
  const nowA = Array.from(document.querySelectorAll('.pir-this')).map(n=>parseFloat(n.value)||0);

  const totalLast = last.reduce((s,v)=>s+v,0);
  // If totalLast is 0, compute simple percent change average
  let weightedChange = 0;
  if(totalLast === 0){
    // Avoid divide by zero: compute average % change across categories with last>0
    let deltas = [];
    for(let i=0;i<names.length;i++){
      if(last[i] > 0) deltas.push( ((nowA[i] - last[i]) / last[i]) );
    }
    weightedChange = deltas.length ? (deltas.reduce((a,b)=>a+b,0)/deltas.length)*100 : 0;
  } else {
    for(let i=0;i<names.length;i++){
      const weight = last[i] / totalLast;
      const change = last[i] === 0 ? 0 : ( (nowA[i] - last[i]) / last[i] ); // fractional change per category
      weightedChange += weight * change * 100;
    }
  }

  // Build chart: category % change
  const pctChanges = names.map((_,i)=> last[i] === 0 ? 0 : ((nowA[i]-last[i]) / last[i])*100 );
  const ctx = document.getElementById('pir-chart').getContext('2d');
  if(pirChart) pirChart.destroy();
  pirChart = new Chart(ctx, {
    type: 'bar',
    data: { labels: names, datasets: [{ label: 'Category % Change', data: pctChanges, borderWidth:1 }] },
    options: { scales: { y: { beginAtZero:true } } }
  });

  document.getElementById('pir-rate').textContent = weightedChange.toFixed(2);
  document.getElementById('pir-result').classList.remove('d-none');

  // Deep analysis
  let analysis = `Weighted personal inflation: ${weightedChange.toFixed(2)}% (this is how your annual spending changed overall).\n\n`;
  analysis += `Interpretation:\n- Positive value indicates your personal cost-of-living rose; negative means you spent less overall.\n`;
  // highlight top movers
  const combined = names.map((n,i)=>({name:n, last:last[i], now:nowA[i], pct: pctChanges[i]})).sort((a,b)=>Math.abs(b.pct)-Math.abs(a.pct));
  analysis += `\nTop category movers:\n` + combined.slice(0,5).map(c=>`- ${c.name}: ${c.pct.toFixed(1)}% (${c.last===0 ? 'no prior spend' : '$'+c.last.toFixed(2) + ' → $' + c.now.toFixed(2)})`).join('\n');
  analysis += `\n\nRecommendations:\n- If essential categories (housing, healthcare) rose sharply, plan to increase income or cut discretionary items.\n- If discretionary categories drove most of the rise, set targets to reduce those by 10–20% to offset inflation.\n- Revisit yearly and track to spot trends; consider subscription review, meal planning, and cheaper transport options.`;

  document.getElementById('pir-analysis').textContent = analysis;
});

document.getElementById('pir-reset').addEventListener('click', function(){
  document.getElementById('pir-list').innerHTML = '';
  document.getElementById('pir-list').appendChild(makeRow());
  document.getElementById('pir-result').classList.add('d-none');
});
// initialize one row
document.getElementById('pir-list').innerHTML = ''; document.getElementById('pir-list').appendChild(makeRow());

finance__personal_loan_comparison_calcul:
// Helper: monthly payment formula
function monthlyPayment(principal, annualRate, years){
  const r = annualRate/100/12;
  const n = years*12;
  if(r === 0) return principal / n;
  return (principal * r) / (1 - Math.pow(1+r, -n));
}

function makeLoanRow(){
  const d=document.createElement('div'); d.className='loan-row';
  d.innerHTML = `
    <input class="form-control loan-name" placeholder="Lender name">
    <input class="form-control loan-amount" type="number" placeholder="Loan amount ($)" min="0" step="0.01">
    <input class="form-control loan-rate" type="number" placeholder="Annual rate (%)" min="0" step="0.01">
    <input class="form-control loan-term" type="number" placeholder="Term (years)" min="0" step="1">
    <input class="form-control loan-fees" type="number" placeholder="Upfront fees ($)" min="0" step="0.01">
    <button class="btn btn-outline-danger btn-sm remove-loan" type="button">−</button>
  `;
  return d;
}
document.getElementById('loan-add').addEventListener('click', ()=>document.getElementById('loan-list').appendChild(makeLoanRow()));
document.addEventListener('click', e=>{ if(e.target.classList.contains('remove-loan')) e.target.parentElement.remove(); });

let loanChart=null;
document.getElementById('loan-form').addEventListener('submit', function(e){
  e.preventDefault();
  const offers = Array.from(document.querySelectorAll('.loan-name')).map((el,i)=>({
    name: el.value || `Offer ${i+1}`,
    principal: parseFloat(document.querySelectorAll('.loan-amount')[i].value) || 0,
    rate: parseFloat(document.querySelectorAll('.loan-rate')[i].value) || 0,
    term: parseFloat(document.querySelectorAll('.loan-term')[i].value) || 0,
    fees: parseFloat(document.querySelectorAll('.loan-fees')[i].value) || 0
  })).filter(o=>o.principal>0 && o.term>0);

  if(offers.length === 0){ alert('Add at least one valid loan offer (principal & term).'); return; }

  const comparisons = offers.map(o=>{
    const monthly = monthlyPayment(o.principal, o.rate, o.term);
    const totalPaid = monthly * o.term * 12 + o.fees;
    const totalInterest = totalPaid - o.principal - o.fees;
    return {...o, monthly, totalPaid, totalInterest};
  });

  // Prepare summary
  const summaryDiv = document.getElementById('loan-summary'); summaryDiv.innerHTML='';
  comparisons.forEach(c=>{
    const div=document.createElement('div');
    div.innerHTML = `<strong>${c.name}:</strong> Monthly $${c.monthly.toFixed(2)} | Total paid $${c.totalPaid.toFixed(2)} | Interest $${c.totalInterest.toFixed(2)} | Fees $${c.fees.toFixed(2)}`;
    summaryDiv.appendChild(div);
  });

  // Chart: totalPaid comparison
  const ctx = document.getElementById('loan-chart').getContext('2d');
  if(loanChart) loanChart.destroy();
  loanChart = new Chart(ctx, {
    type: 'bar',
    data: { labels: comparisons.map(c=>c.name), datasets:[{ label:'Total Paid ($)', data: comparisons.map(c=>c.totalPaid) }, { label:'Principal ($)', data: comparisons.map(c=>c.principal) }] },
    options:{scales:{y:{beginAtZero:true}}}
  });

  document.getElementById('loan-result').classList.remove('d-none');

  // Deep analysis
  let analysis = `Comparison summary for ${comparisons.length} offers:\n\n`;
  // find best by totalPaid
  const bestTotal = comparisons.reduce((a,b)=> a.totalPaid<b.totalPaid?a:b);
  const bestMonthly = comparisons.reduce((a,b)=> a.monthly<b.monthly?a:b);
  analysis += `- Lowest total cost: ${bestTotal.name} (Total $${bestTotal.totalPaid.toFixed(2)})\n`;
  analysis += `- Lowest monthly payment: ${bestMonthly.name} ($${bestMonthly.monthly.toFixed(2)} / month)\n\n`;
  analysis += `Advice:\n- If you prioritize cashflow choose lower monthly payment even if total cost is higher.\n- If minimizing cost, pick the lowest total paid (watch for higher fees).\n- Consider prepayment penalties and flexibility (payoff options) which are not in this simple model.\n- Use APR from lender for more precise comparison if available (includes fees amortized).`;

  document.getElementById('loan-analysis').textContent = analysis;
});

// init
document.getElementById('loan-list').innerHTML=''; document.getElementById('loan-list').appendChild(makeLoanRow());
document.getElementById('loan-reset').addEventListener('click', function(){
  document.getElementById('loan-list').innerHTML=''; document.getElementById('loan-list').appendChild(makeLoanRow());
  document.getElementById('loan-result').classList.add('d-none');
});

