const LB_PER_KG = 2.20462;
    const BASAL_PERCENT_MIN = 0.40; // 40% of TDD for basal
    const BASAL_PERCENT_MAX = 0.50; // 50% of TDD for basal

    document.getElementById('basal-dose-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const weightInput = parseFloat(document.getElementById('weight_input').value);
        const weightUnit = document.getElementById('weight_unit').value;
        const tddFactorMin = parseFloat(document.getElementById('tdd_factor_min').value);
        const tddFactorMax = parseFloat(document.getElementById('tdd_factor_max').value);

        // 2. Validation
        if (weightInput <= 0 || isNaN(weightInput) || isNaN(tddFactorMin) || isNaN(tddFactorMax) || tddFactorMin <= 0 || tddFactorMax <= 0) {
            displayError("Please enter valid, positive values for Weight and TDD Factors.");
            return;
        }
        if (tddFactorMin > tddFactorMax) {
            displayError("The Minimum TDD Factor cannot be greater than the Maximum TDD Factor.");
            return;
        }

        // 3. Normalize Weight to Kilograms
        const weightKg = weightUnit === 'lb' ? weightInput / LB_PER_KG : weightInput;

        // 4. Calculation Logic

        // Step 1: Calculate TDD Range
        const tddMin = weightKg * tddFactorMin;
        const tddMax = weightKg * tddFactorMax;

        // Step 2: Calculate Basal Dose Range (40-50% of TDD)
        const basalMin = tddMin * BASAL_PERCENT_MIN;
        const basalMax = tddMax * BASAL_PERCENT_MAX;

        // 5. Update Result Display (Round to the nearest whole unit, or 0.5 unit for precision)
        document.getElementById('tdd_range_min').textContent = Math.round(tddMin);
        document.getElementById('tdd_range_max').textContent = Math.round(tddMax);

        document.getElementById('basal_range_min').textContent = roundToNearestHalf(basalMin);
        document.getElementById('basal_range_max').textContent = roundToNearestHalf(basalMax);

        // 6. Update Visibility
        document.getElementById('result-title').classList.remove('d-none');
        document.getElementById('results-container').classList.remove('d-none');
        document.getElementById('error-message').classList.add('d-none');
    });

    /** Rounds a number to the nearest 0.5 (half unit). */
    function roundToNearestHalf(num) {
        return Math.round(num * 2) / 2;
    }

    function displayError(message) {
        document.getElementById('error-message').classList.remove('d-none');
        document.getElementById('error-message').textContent = `Calculation Error: ${message}`;
        document.getElementById('result-title').classList.add('d-none');
        document.getElementById('results-container').classList.add('d-none');
    }

health__basal_metabolic_rate_calculator:
let bmrChart = null;

    const activityMultipliers = {
        '1.2': 'Sedentary',
        '1.375': 'Lightly Active',
        '1.55': 'Moderately Active',
        '1.725': 'Very Active',
        '1.9': 'Extra Active'
    };

    document.getElementById('bmr-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs and Convert Units (Imperial to Metric)
        const age = parseFloat(document.getElementById('age').value);
        const weight_lb = parseFloat(document.getElementById('weight_lb').value);
        const height_ft = parseFloat(document.getElementById('height_ft').value);
        const height_in = parseFloat(document.getElementById('height_in').value);
        const gender = document.querySelector('input[name="gender"]:checked').value;
        const selected_multiplier = parseFloat(document.getElementById('activity_level').value);

        // Unit Conversions:
        // 1 lb = 0.453592 kg
        // 1 ft = 30.48 cm
        // 1 in = 2.54 cm

        const weight_kg = weight_lb * 0.453592;
        const height_cm = (height_ft * 30.48) + (height_in * 2.54);

        let BMR;
        // 2. Calculate BMR (Mifflin-St Jeor Equation)
        // Men: BMR = 10 * weight(kg) + 6.25 * height(cm) - 5 * age(years) + 5
        // Women: BMR = 10 * weight(kg) + 6.25 * height(cm) - 5 * age(years) - 161
        if (gender === 'male') {
            BMR = (10 * weight_kg) + (6.25 * height_cm) - (5 * age) + 5;
        } else { // female
            BMR = (10 * weight_kg) + (6.25 * height_cm) - (5 * age) - 161;
        }

        const BMR_rounded = BMR.toFixed(0);

        // 3. Calculate TDEE for selected activity level
        const TDEE_selected = BMR * selected_multiplier;
        const TDEE_selected_rounded = TDEE_selected.toFixed(0);

        // 4. Update Result Text Display
        const res = document.getElementById('bmr-result');
        res.classList.remove('d-none');
        res.innerHTML = `
**Your Basal Metabolic Rate (BMR):** **${BMR_rounded} calories/day**
(This is the minimum energy required to keep you alive at rest.)

---

**Selected Activity Level ( ${activityMultipliers[selected_multiplier]} ):**
**Your Estimated Total Daily Energy Expenditure (TDEE):** **${TDEE_selected_rounded} calories/day**
(This is the estimated number of calories you burn daily, including activity.)
`;

        // 5. Update TDEE Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('bmr-table').classList.remove('d-none');
        const tableBody = document.getElementById('bmr-body');
        tableBody.innerHTML = ''; // Clear previous results

        const chartLabels = ['BMR'];
        const chartData = [BMR_rounded];

        // Calculate and populate TDEE for all levels
        for (const multiplier in activityMultipliers) {
            const TDEE_level = BMR * parseFloat(multiplier);
            const levelName = activityMultipliers[multiplier];
            const isSelected = parseFloat(multiplier) === selected_multiplier;

            tableBody.innerHTML += `
            <tr class="${isSelected ? 'table-primary' : ''}">
                <td>${levelName} ${isSelected ? '**(Selected)**' : ''}</td>
                <td>${TDEE_level.toFixed(0)}</td>
            </tr>
            `;
            chartLabels.push(levelName);
            chartData.push(TDEE_level.toFixed(0));
        }

        // 6. Update Chart
        const ctx = document.getElementById('bmr-chart').getContext('2d');
        document.getElementById('bmr-chart').classList.remove('d-none');
        if (bmrChart) bmrChart.destroy();

        bmrChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: chartLabels,
                datasets: [{
                    label: 'Calories (kcal/day)',
                    data: chartData,
                    backgroundColor: [
                        '#4bc0c0', // BMR color
                        '#ff9f40', '#ff9f40', '#ff9f40', '#ff9f40', '#ff9f40' // TDEE colors
                    ],
                    borderColor: [
                        '#4bc0c0',
                        '#ff9f40', '#ff9f40', '#ff9f40', '#ff9f40', '#ff9f40'
                    ],
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: { display: true, text: 'Energy Expenditure Breakdown (TDEE = BMR x Activity Multiplier)' },
                    legend: { display: false }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Calories (kcal/day)' }
                    }
                }
            }
        });
    });

health__blood_alcohol_content_calculator:
// Standard Constants for Simplified Widmark's Formula (US Units)
    // Formula: BAC = ( (A * 5.14) / (W * r) ) - (B * T)
    const ALCOHOL_OZ_PER_DRINK = 0.6; // Ounces of pure alcohol per standard drink
    const WIDMARK_MALE = 0.68;
    const WIDMARK_FEMALE = 0.55;
    const ELIMINATION_RATE = 0.015; // % BAC eliminated per hour (Beta)
    const CONSTANT_FACTOR = 5.14; 

    // BAC Risk Categories (Generalized)
    const BAC_CATEGORIES = [
        { max: 0.02, label: 'Minimal Impairment', color: 'bg-success', text: 'You may feel relaxed. Effects are negligible.' },
        { max: 0.05, label: 'Judgment Impairment', color: 'bg-info', text: 'Relaxation, warmth, altered judgment, reduced coordination.' },
        { max: 0.08, label: 'Driving Limit (Typical)', color: 'bg-warning', text: 'Clear impairment of balance, speech, vision, and reaction time. **Illegal to drive in most regions.**' },
        { max: 0.15, label: 'Major Impairment', color: 'bg-danger', text: 'Significant loss of muscle control and judgment. Vomiting may occur.' },
        { max: 0.25, label: 'Severe Impairment', color: 'bg-dark', text: 'Stupor, loss of understanding, possible blackout. Seek immediate attention.' },
        { max: 1.00, label: 'High Risk / Emergency', color: 'bg-dark', text: 'Severe risk of coma and death. **Medical Emergency.**' },
    ];

    function getCategory(bac) {
        for (const cat of BAC_CATEGORIES) {
            if (bac <= cat.max) {
                return cat;
            }
        }
        return BAC_CATEGORIES[BAC_CATEGORIES.length - 1]; // Fallback for very high BAC
    }

    document.getElementById('bac-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const gender = document.querySelector('input[name="gender"]:checked').value;
        const weight_lb = parseFloat(document.getElementById('weight_lb').value);
        const standard_drinks = parseFloat(document.getElementById('standard_drinks').value);
        const time_h = parseFloat(document.getElementById('time_h').value);

        // 2. Set Constants
        const r = (gender === 'male') ? WIDMARK_MALE : WIDMARK_FEMALE;

        // 3. Calculate Total Alcohol Consumed (A)
        const alcohol_consumed_oz = standard_drinks * ALCOHOL_OZ_PER_DRINK;

        // 4. Calculate Theoretical BAC before metabolism (BAC_peak)
        const BAC_peak = (alcohol_consumed_oz * CONSTANT_FACTOR) / (weight_lb * r);

        // 5. Calculate BAC adjusted for metabolism
        const metabolized_alcohol = ELIMINATION_RATE * time_h;
        let BAC_final = BAC_peak - metabolized_alcohol;

        // Ensure BAC is not negative
        BAC_final = Math.max(0, BAC_final); 

        const BAC_rounded = BAC_final.toFixed(3);
        const category = getCategory(BAC_final);

        // 6. Update Result Display
        const res = document.getElementById('bac-result');
        res.classList.remove('d-none', 'alert-success', 'alert-danger', 'alert-warning', 'alert-info');
        res.classList.add(`alert-${category.color.split('-')[1]}`); // Use Bootstrap colors

        res.innerHTML = `
**Estimated BAC:** <span class="bac-output">${BAC_rounded}%</span>
**Classification:** ${category.label}
---
**Expected Effects:** ${category.text}
**Time to Zero BAC:** ${(BAC_final / ELIMINATION_RATE).toFixed(1)} hours (approx.) from now.
`;

    });

