health__one_rep_max_calculator:
let trainingChart = null;

    // Formulas adapted from Wikipedia/common sources
    const formulas = {
        'Epley': (w, r) => w * (1 + (r / 30)),
        'Brzycki': (w, r) => w * (36 / (37 - r)),
        'Lander': (w, r) => w * (100 / (101.3 - 2.6713 * r)),
        'Lombardi': (w, r) => w * Math.pow(r, 0.10), // Note: Often yields high results
        'O\'Conner': (w, r) => w * (1 + (r * 0.025))
    };

    document.getElementById('1rm-form').addEventListener('submit', function (e) {
        e.preventDefault();

        const weight = parseFloat(document.getElementById('weight_lifted').value);
        const reps = parseInt(document.getElementById('repetitions').value);

        if (reps < 1 || reps > 12) {
            displayError("Please enter between 2 and 12 successful repetitions for an accurate 1RM estimate.");
            return;
        }

        // 1. Calculate 1RM using all formulas
        const estimates = [];
        let total1RM = 0;
        let count = 0;

        for (const [name, func] of Object.entries(formulas)) {
            const max = func(weight, reps);
            if (!isNaN(max) && isFinite(max)) {
                estimates.push({ name: name, value: max });
                total1RM += max;
                count++;
            }
        }

        // 2. Determine Average and Best Estimate
        const average1RM = count > 0 ? total1RM / count : 0;
        const bestEstimate = estimates.find(e => e.name === 'Epley') || estimates[0]; // Prefer Epley as a standard
        const best1RM = bestEstimate ? bestEstimate.value : 0;

        if (best1RM === 0) {
            displayError("Calculation failed. Please check your input values.");
            return;
        }

        // 3. Update Result Display
        const res = document.getElementById('1rm-result');
        res.classList.remove('d-none', 'alert-danger');
        res.classList.add('alert-primary');
        res.innerHTML = `
**Lifting Data:** ${weight} x ${reps} reps
---
**Estimated One-Rep Max (1RM):** <span class="best-1rm">${best1RM.toFixed(1)}</span> (using the Epley formula)
<br>Your theoretical maximum lift is **${best1RM.toFixed(1)}** units.
`;

        // 4. Update Estimates Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('1rm-table').classList.remove('d-none');
        const tableBody = document.getElementById('1rm-body');
        tableBody.innerHTML = ''; // Clear previous results

        estimates.forEach(est => {
            let rowClass = est.name === 'Epley' ? 'table-primary' : '';
            tableBody.innerHTML += `
            <tr class="${rowClass}">
                <td>${est.name}</td>
                <td>${est.value.toFixed(1)}</td>
            </tr>
            `;
        });

        // 5. Generate Training Percentages (Based on the best 1RM)
        const percentages = [
            { pct: 100, label: '100% (1 Rep Max)', reps: 1, color: '#ff6384' },
            { pct: 95, label: '95% (2-3 Reps)', reps: 3, color: '#ff9f40' },
            { pct: 90, label: '90% (3-4 Reps)', reps: 4, color: '#4bc0c0' },
            { pct: 85, label: '85% (5-6 Reps)', reps: 6, color: '#36a2eb' },
            { pct: 80, label: '80% (6-8 Reps)', reps: 8, color: '#9966ff' },
            { pct: 75, label: '75% (8-10 Reps)', reps: 10, color: '#ffcd56' },
            { pct: 70, label: '70% (10-12+ Reps)', reps: 12, color: '#cc65fe' }
        ];

        const tableHeadRow = document.querySelector('#1rm-table thead tr');
        if (tableHeadRow.cells.length < 3) {
             tableHeadRow.innerHTML += '<th>Reps @ % of 1RM</th>';
        }

        tableBody.innerHTML += '<tr><td colspan="3" class="table-dark">Training Max Estimates</td></tr>';

        percentages.forEach(p => {
            const trainingWeight = (best1RM * (p.pct / 100)).toFixed(1);
            tableBody.innerHTML += `
            <tr class="${p.pct === 100 ? 'table-success' : ''}">
                <td>${p.label}</td>
                <td>${trainingWeight}</td>
                <td>${p.reps}</td>
            </tr>
            `;
        });


        // 6. Update Chart
        const ctx = document.getElementById('1rm-chart').getContext('2d');
        document.getElementById('1rm-chart').classList.remove('d-none');
        if (trainingChart) trainingChart.destroy();

        trainingChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: percentages.map(p => `${p.pct}% - ${p.reps} Reps`),
                datasets: [{
                    label: 'Training Weight',
                    data: percentages.map(p => (best1RM * (p.pct / 100)).toFixed(1)),
                    backgroundColor: percentages.map(p => p.color),
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: { display: true, text: `Training Weights Based on ${best1RM.toFixed(1)} 1RM` },
                    legend: { display: false }
                },
                scales: {
                    y: {
                        beginAtZero: false,
                        title: { display: true, text: 'Weight (Units)' }
                    },
                    x: {
                        title: { display: true, text: 'Intensity & Rep Range' }
                    }
                }
            }
        });
    });

    function displayError(message) {
        const res = document.getElementById('1rm-result');
        res.classList.remove('d-none', 'alert-primary');
        res.classList.add('alert-danger');
        res.innerHTML = `**Calculation Error:** ${message}`;
        document.getElementById('table-title').classList.add('d-none');
        document.getElementById('1rm-table').classList.add('d-none');
        document.getElementById('1rm-chart').classList.add('d-none');
    }

health__pregnancy_weight_gain_calculator:
const KG_PER_LB = 0.453592;
    const METERS_PER_INCH = 0.0254;

    // IOM Guidelines (Weight Gain in Lbs)
    const IOM_GUIDELINES = {
        underweight: {
            bmi_range: '< 18.5', 
            total_min: 28, total_max: 40,
            weekly_rate: 1.0, // lbs/week in 2nd/3rd trimester
            category: 'Underweight'
        },
        normal: {
            bmi_range: '18.5 - 24.9', 
            total_min: 25, total_max: 35,
            weekly_rate: 1.0,
            category: 'Normal Weight'
        },
        overweight: {
            bmi_range: '25.0 - 29.9', 
            total_min: 15, total_max: 25,
            weekly_rate: 0.6,
            category: 'Overweight'
        },
        obese: {
            bmi_range: '≥ 30.0', 
            total_min: 11, total_max: 20,
            weekly_rate: 0.5,
            category: 'Obese'
        }
    };

    function calculateBMI(weight_lb, height_ft, height_in) {
        const total_height_in = (height_ft * 12) + height_in;
        const total_height_m = total_height_in * METERS_PER_INCH;
        const weight_kg = weight_lb * KG_PER_LB;

        return weight_kg / (total_height_m * total_height_m);
    }

    function getBMICategory(bmi) {
        if (bmi < 18.5) return IOM_GUIDELINES.underweight;
        if (bmi < 25.0) return IOM_GUIDELINES.normal;
        if (bmi < 30.0) return IOM_GUIDELINES.overweight;
        return IOM_GUIDELINES.obese;
    }

    document.getElementById('weight-gain-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const weight_lb = parseFloat(document.getElementById('pre_pregnancy_weight_lb').value);
        const height_ft = parseFloat(document.getElementById('height_ft').value);
        const height_in = parseFloat(document.getElementById('height_in').value);
        const current_week = parseInt(document.getElementById('current_week').value);

        // 2. Calculate Pre-Pregnancy BMI
        const bmi = calculateBMI(weight_lb, height_ft, height_in);
        const category = getBMICategory(bmi);

        // 3. Calculate Recommended Target Gain
        const total_min_gain = category.total_min;
        const total_max_gain = category.total_max;

        // 4. Calculate Current Recommended Gain (Approximate)
        // Gain is usually minimal in the first trimester (Weeks 1-13).
        const first_trimester_weeks = 13;
        const second_trimester_start = 14;
        const weeks_gained_since_T2 = Math.max(0, current_week - second_trimester_start);

        // The minimal recommended gain in T1 is usually 1-4 lbs, we use 3 lbs average for calculation
        const t1_gain_avg = 3; 

        let recommended_current_gain_approx;

        if (current_week <= first_trimester_weeks) {
            // First trimester gain is highly variable, use general T1 min-max
            recommended_current_gain_approx = `Approx. ${t1_gain_avg} lbs`; // Simple representation
        } else {
            // After T1, calculate T1 gain + weekly rate * weeks since T2 started
            const current_min_gain = t1_gain_avg + (weeks_gained_since_T2 * category.weekly_rate * 0.7); // *0.7 to skew toward lower estimate
            const current_max_gain = 5 + (weeks_gained_since_T2 * category.weekly_rate * 1.3); // *1.3 to skew toward higher estimate

            recommended_current_gain_approx = `${current_min_gain.toFixed(1)} - ${current_max_gain.toFixed(1)} lbs`;
        }

        // 5. Update Result Display
        const bmi_rounded = bmi.toFixed(1);

        const res = document.getElementById('gain-result');
        res.classList.remove('d-none', 'alert-danger');
        res.classList.add('alert-info');
        res.innerHTML = `
**Pre-Pregnancy BMI:** <span class="bmi-info">${bmi_rounded} (${category.category})</span>
**Current Gestational Week:** ${current_week} weeks
---

**Total Recommended Weight Gain Range (by Week 40):** <span class="weight-output">${total_min_gain} - ${total_max_gain} <span class="unit-label">lbs</span></span>

*Recommended Current Gain (${current_week} Weeks): ${recommended_current_gain_approx}*
`;

        // 6. Update Guideline Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('guideline-table').classList.remove('d-none');

        const tableBody = document.getElementById('guideline-body');
        tableBody.innerHTML = `
        <tr class="table-primary">
            <td>**Your BMI Category**</td>
            <td>**${category.category}**</td>
        </tr>
        <tr>
            <td>BMI Range for Category</td>
            <td>${category.bmi_range}</td>
        </tr>
        <tr>
            <td>Total Gain Goal (lbs)</td>
            <td>${total_min_gain} - ${total_max_gain}</td>
        </tr>
        <tr>
            <td>Recommended Weekly Gain (T2 & T3)</td>
            <td>${category.weekly_rate.toFixed(1)} lbs/week</td>
        </tr>
        `;
    });

    function displayError(message) {
        const res = document.getElementById('gain-result');
        res.classList.remove('d-none', 'alert-info');
        res.classList.add('alert-danger');
        res.innerHTML = `**Calculation Error:** ${message}`;
        document.getElementById('table-title').classList.add('d-none');
        document.getElementById('guideline-table').classList.add('d-none');
    }

health__protein_intake_calculator:
const KG_TO_LB = 2.20462;

    // Protein requirements (g per unit of body weight)
    // Values are given as { min_g_per_lb, max_g_per_lb }
    const PROTEIN_MULTIPLIERS = {
        sedentary: { min: 0.36, max: 0.45, name: "Maintenance / Sedentary" }, // 0.8-1.0 g/kg
        endurance: { min: 0.55, max: 0.64, name: "Endurance Training" },     // 1.2-1.4 g/kg
        strength:  { min: 0.73, max: 1.00, name: "Strength Training" },     // 1.6-2.2 g/kg
        weightloss: { min: 0.82, max: 1.14, name: "Weight Loss / Deficit" } // 1.8-2.5 g/kg
    };

    document.getElementById('protein-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs
        const weight_input = parseFloat(document.getElementById('weight_input').value);
        const unit = document.getElementById('weight_unit').value;
        const goal = document.getElementById('goal_level').value;

        // Simple validation
        if (weight_input <= 0) {
            displayError("Weight must be greater than zero.");
            return;
        }
        if (!PROTEIN_MULTIPLIERS[goal]) {
            displayError("Please select a fitness goal.");
            return;
        }

        // 2. Normalize Weight to Pounds (Lbs)
        let weight_lb;
        if (unit === 'kg') {
            weight_lb = weight_input * KG_TO_LB;
        } else { // lb
            weight_lb = weight_input;
        }

        // 3. Calculation
        const multipliers = PROTEIN_MULTIPLIERS[goal];

        const min_protein_g = weight_lb * multipliers.min;
        const max_protein_g = weight_lb * multipliers.max;

        // 4. Update Result Display
        const min_g_rounded = min_protein_g.toFixed(0);
