let tdeeChart = null;

    const activityMultipliers = {
        '1.2': 'Sedentary',
        '1.375': 'Lightly Active',
        '1.55': 'Moderately Active',
        '1.725': 'Very Active',
        '1.9': 'Extra Active'
    };

    document.getElementById('tdee-form').addEventListener('submit', function (e) {
        e.preventDefault();

        // 1. Get Inputs and Convert Units (Imperial to Metric)
        const age = parseFloat(document.getElementById('age').value);
        const weight_lb = parseFloat(document.getElementById('weight_lb').value);
        const height_ft = parseFloat(document.getElementById('height_ft').value);
        const height_in = parseFloat(document.getElementById('height_in').value);
        const gender = document.querySelector('input[name="gender"]:checked').value;
        const selected_multiplier = parseFloat(document.getElementById('activity_level').value);
        const selected_level_name = activityMultipliers[selected_multiplier.toString()];

        // Conversion Factors
        const weight_kg = weight_lb * 0.453592;
        const height_cm = (height_ft * 30.48) + (height_in * 2.54);

        let BMR;
        // 2. Calculate BMR (Mifflin-St Jeor Equation)
        // Men: BMR = 10 * weight(kg) + 6.25 * height(cm) - 5 * age(years) + 5
        // Women: BMR = 10 * weight(kg) + 6.25 * height(cm) - 5 * age(years) - 161
        if (gender === 'male') {
            BMR = (10 * weight_kg) + (6.25 * height_cm) - (5 * age) + 5;
        } else { // female
            BMR = (10 * weight_kg) + (6.25 * height_cm) - (5 * age) - 161;
        }

        const BMR_rounded = BMR.toFixed(0);

        // 3. Calculate TDEE
        const TDEE = BMR * selected_multiplier;
        const TDEE_rounded = TDEE.toFixed(0);

        // 4. Calculate Calorie Goals (General estimates)
        const goal_maintain = TDEE;
        const goal_moderate_loss = TDEE - 500; // ~1 lb/week
        const goal_fast_loss = TDEE - 1000; // ~2 lb/week
        const goal_gain = TDEE + 500;

        // 5. Update Result Text Display
        const res = document.getElementById('tdee-result');
        res.classList.remove('d-none');
        res.innerHTML = `
**Your Calculated BMR:** ${BMR_rounded} calories/day
**Your Selected Activity Level:** ${selected_level_name} (x${selected_multiplier})
---
**Your Estimated Total Daily Energy Expenditure (TDEE):** **${TDEE_rounded} calories/day**
<span style="font-weight:bold;color:green;">✅ This is your estimated daily calorie burn for maintaining your current weight.</span>
`;

        // 6. Update Calorie Goals Table
        document.getElementById('table-title').classList.remove('d-none');
        document.getElementById('tdee-table').classList.remove('d-none');
        const tableBody = document.getElementById('tdee-body');
        tableBody.innerHTML = ''; // Clear previous results

        const goalData = [
            { name: '**Maintenance (TDEE)**', value: goal_maintain.toFixed(0), style: 'table-success' },
            { name: 'Moderate Weight Loss (1 lb/week)', value: goal_moderate_loss.toFixed(0), style: 'table-warning' },
            { name: 'Aggressive Weight Loss (2 lb/week)', value: goal_fast_loss.toFixed(0), style: 'table-danger' },
            { name: 'Weight Gain (Muscle/Bulk)', value: goal_gain.toFixed(0), style: 'table-info' }
        ];

        goalData.forEach(goal => {
            tableBody.innerHTML += `
            <tr class="${goal.style}">
                <td>${goal.name}</td>
                <td>${goal.value}</td>
            </tr>
            `;
        });

        // 7. Update Chart
        const ctx = document.getElementById('tdee-chart').getContext('2d');
        document.getElementById('tdee-chart').classList.remove('d-none');
        if (tdeeChart) tdeeChart.destroy();

        tdeeChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: goalData.map(g => g.name.replace(/\*\*/g, '').replace(' (TDEE)', '')),
                datasets: [{
                    label: 'Calories (kcal/day)',
                    data: goalData.map(g => g.value),
                    backgroundColor: ['#4bc0c0', '#ff9f40', '#ff6384', '#36a2eb'],
                    borderColor: ['#4bc0c0', '#ff9f40', '#ff6384', '#36a2eb'],
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: { display: true, text: 'Estimated Daily Calorie Needs by Goal' },
                    legend: { display: false }
                },
                scales: {
                    y: {
                        beginAtZero: false,
                        title: { display: true, text: 'Calories (kcal/day)' }
                    }
                }
            }
        });
    });

