    let currentInput = '0';
    let history = '';
    let firstOperand = null;
    let operator = null;
    let waitingForSecondOperand = false;
    let lastAns = '0';
    let memory = 0;

    const currentDisplay = document.getElementById('current-input');
    const historyDisplay = document.getElementById('history-display');

    function updateDisplay() {
        // Simple scaling for long numbers
        if (currentInput.length > 12) {
            currentDisplay.style.fontSize = '2rem';
        } else if (currentInput.length > 8) {
            currentDisplay.style.fontSize = '2.4rem';
        } else {
            currentDisplay.style.fontSize = '3rem';
        }
        currentDisplay.textContent = currentInput;
        historyDisplay.textContent = history;
    }

    /* 🧮 Advanced Calculation IT Calculator Engine v2.5 */
    const MAX_DIGITS = 12;

    function inputDigit(digit) {
        if (waitingForSecondOperand) {
            currentInput = digit;
            waitingForSecondOperand = false;
        } else {
            if (currentInput.replace('.', '').length >= MAX_DIGITS) return;
            currentInput = currentInput === '0' ? digit : currentInput + digit;
        }
        updateDisplay();
    }

    function inputDecimal() {
        if (waitingForSecondOperand) {
            currentInput = '0.';
            waitingForSecondOperand = false;
            updateDisplay();
            return;
        }
        if (currentInput.replace('.', '').length >= MAX_DIGITS) return;
        if (!currentInput.includes('.')) {
            currentInput += '.';
        }
        updateDisplay();
    }

    function handleOperator(nextOperator) {
        const inputValue = parseFloat(currentInput);

        if (operator && waitingForSecondOperand) {
            operator = nextOperator;
            history = `${firstOperand} ${operator}`;
            updateDisplay();
            return;
        }

        if (firstOperand === null && !isNaN(inputValue)) {
            firstOperand = inputValue;
        } else if (operator) {
            const result = calculate(firstOperand, inputValue, operator);
            currentInput = `${parseFloat(result.toFixed(7))}`;
            firstOperand = result;
        }

        waitingForSecondOperand = true;
        operator = nextOperator;
        history = `${firstOperand} ${operator}`;
        updateDisplay();
    }

    function calculate(first, second, op) {
        if (op === '+') return first + second;
        if (op === '-') return first - second;
        if (op === '*') return first * second;
        if (op === '/') return second === 0 ? 'Error' : first / second;
        return second;
    }

    function handleEquals() {
        if (operator === null || waitingForSecondOperand) return;
        const secondOperand = parseFloat(currentInput);
        const result = calculate(firstOperand, secondOperand, operator);

        if (result === 'Error') {
            currentInput = 'Error';
            history = '';
        } else {
            history = `${firstOperand} ${operator} ${secondOperand} =`;
            currentInput = `${parseFloat(result.toFixed(7))}`;
            lastAns = currentInput;
        }

        firstOperand = null;
        operator = null;
        waitingForSecondOperand = true;
        updateDisplay();
    }

    function clearCalculator() {
        currentInput = '0';
        history = '';
        firstOperand = null;
        operator = null;
        waitingForSecondOperand = false;
        updateDisplay();
    }

    function backspace() {
        if (waitingForSecondOperand) return;
        currentInput = currentInput.length > 1 ? currentInput.slice(0, -1) : '0';
        updateDisplay();
    }

    function memoryAdd() { memory += parseFloat(currentInput) || 0; }
    function memorySub() { memory -= parseFloat(currentInput) || 0; }
    function memoryRecall() { currentInput = String(memory); waitingForSecondOperand = false; updateDisplay(); }
    function useAns() { currentInput = lastAns; waitingForSecondOperand = false; updateDisplay(); }
    function generateRandom() { currentInput = Math.random().toFixed(4); waitingForSecondOperand = false; updateDisplay(); }
    function toggleSign() { currentInput = (parseFloat(currentInput) * -1).toString(); updateDisplay(); }
    function appendExp() { if (!currentInput.includes('e')) currentInput += 'e+'; updateDisplay(); }

    /* ⌨️ Keyboard Support */
    document.addEventListener('keydown', (event) => {
        const key = event.key;
        if (key >= '0' && key <= '9') inputDigit(key);
        if (key === '.') inputDecimal();
        if (key === '+') handleOperator('+');
        if (key === '-') handleOperator('-');
        if (key === '*') handleOperator('*');
        if (key === '/') { event.preventDefault(); handleOperator('/'); }
        if (key === 'Enter' || key === '=') { event.preventDefault(); handleEquals(); }
        if (key === 'Escape') clearCalculator();
        if (key === 'Backspace') backspace();
    });

