    function calcPI(P, R, Y) {
        const i = (R / 100) / 12;
        const n = Y * 12;
        if (i === 0) return P / n;
        return P * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
    }

    function calcRemaining(P, R, Y_total, Y_passed) {
        const i = (R / 100) / 12;
        const n = Y_total * 12;
