        errorUi.classList.add('d-none');
        capAlert.classList.add('d-none');

        if ([p0, rInit, yFixed, rIdx, rMargin].some(isNaN) || yFixed >= yTotal) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please ensure all values are positive and the fixed term is shorter than the 30-year total term.";
            return;
        }

        // 1. Initial Phase
        const initPayment = calcPI(p0, rInit, yTotal);
        const remPrincipal = calcRemaining(p0, rInit, yTotal, yFixed);

        // 2. Adjustment Phase
        const fullyIndexed = rIdx + rMargin;
        const periodicMax = rInit + cPeriodic;
        const lifetimeMax = rInit + cLife;

        let rAdjusted = fullyIndexed;
        let isCapped = false;

        if (rAdjusted > periodicMax) {
            rAdjusted = periodicMax;
            isCapped = true;
            document.getElementById('cap-alert-text').innerText = "Initial Periodic Cap triggered: Rate limited to " + periodicMax.toFixed(2) + "%.";
        }
        if (rAdjusted > lifetimeMax) {
            rAdjusted = lifetimeMax;
            isCapped = true;
            document.getElementById('cap-alert-text').innerText = "Lifetime Cap triggered: Rate limited to " + lifetimeMax.toFixed(2) + "%.";
        }

        const adjPayment = calcPI(remPrincipal, rAdjusted, yTotal - yFixed);

        // 3. UI Update
        resultsUi.classList.remove('d-none');
        if (isCapped) capAlert.classList.remove('d-none');

        document.getElementById('initial-payment-display').textContent = currency.format(initPayment);
        document.getElementById('adjusted-payment-display').textContent = currency.format(adjPayment);
        document.getElementById('fixed-term-label').textContent = `Fixed for the first ${yFixed} years`;
        document.getElementById('adjusted-rate-label').textContent = `At an adjusted rate of ${rAdjusted.toFixed(2)}%`;
        document.getElementById('indexed-rate-display').textContent = `${fullyIndexed.toFixed(2)}%`;
        document.getElementById('remaining-principal-display').textContent = currency.format(remPrincipal).split('.')[0];
        document.getElementById('max-lifetime-rate-display').textContent = `${lifetimeMax.toFixed(2)}%`;
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

