    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const amount = parseFloat(document.getElementById('loan-amount').value);
        const rate = parseFloat(document.getElementById('interest-rate').value);
        const amortY = parseInt(document.getElementById('amort-years').value);
        const balloonY = parseInt(document.getElementById('balloon-years').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (balloonY >= amortY) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "The Balloon Year must be sooner than the Amortization Term.";
            return;
        }

        if (isNaN(amount) || amount <= 0 || isNaN(rate) || rate < 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide a valid loan amount and interest rate.";
            return;
        }

        // Logic
        const i = (rate / 100) / 12;
        const nAmort = amortY * 12;
        const nBalloon = balloonY * 12;

        // Monthly Payment (P&I)
        const monthlyPI = amount * (i * Math.pow(1 + i, nAmort)) / (Math.pow(1 + i, nAmort) - 1);

        // Remaining Balance (Balloon)
        const balloonAmount = amount * (Math.pow(1 + i, nAmort) - Math.pow(1 + i, nBalloon)) / (Math.pow(1 + i, nAmort) - 1);

        const equity = amount - balloonAmount;

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('balloon-display').textContent = currency.format(balloonAmount);
        document.getElementById('balloon-date-text').textContent = `Due at the end of Year ${balloonY}`;
        document.getElementById('monthly-pi-display').textContent = currency.format(monthlyPI);
        document.getElementById('equity-display').textContent = currency.format(equity);
