const form = document.getElementById('bi-weekly-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: 2,
    });

    function formatTerm(totalMonths) {
        const years = Math.floor(totalMonths / 12);
        const months = Math.round(totalMonths % 12);
        if (years === 0) return `${months} months`;
        return `${years} yrs, ${months} mos`;
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const P = parseFloat(document.getElementById('principal-input').value);
        const R = parseFloat(document.getElementById('rate-input').value);
        const N = parseFloat(document.getElementById('term-input').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(P) || isNaN(R) || isNaN(N) || P <= 0 || R <= 0 || N <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide valid positive numbers for all fields.";
            return;
        }

        const monthlyR = (R / 100) / 12;
        const totalLoanMonths = N * 12;
        const baseMonthlyPI = P * (monthlyR * Math.pow(1 + monthlyR, totalLoanMonths)) / (Math.pow(1 + monthlyR, totalLoanMonths) - 1);

        // 1. Baseline Monthly
        let monthlyInterest = 0;
        let mBal = P;
        for (let m = 1; m <= totalLoanMonths; m++) {
            let int = mBal * monthlyR;
            monthlyInterest += int;
            mBal -= (baseMonthlyPI - int);
        }

        // 2. Bi-Weekly Simulation
        // Standard model: Payment is half the monthly, made 26 times a year.
        const biWeeklyPay = baseMonthlyPI / 2;
        const biWeeklyR = (R / 100) / 26;
        let biWeeklyInterest = 0;
        let bBal = P;
        let totalBiWeeklyPayments = 0;

        for (let b = 1; bBal > 0 && b < 2000; b++) {
            let int = bBal * (monthlyR / 2); // Interest accrued over 2 weeks
            biWeeklyInterest += int;
            let principalP = biWeeklyPay - int;

            if (principalP >= bBal) {
                bBal = 0;
            } else {
                bBal -= principalP;
            }
            totalBiWeeklyPayments = b;
        }

        const newTermInMonths = (totalBiWeeklyPayments / 26) * 12;
        const monthsSaved = totalLoanMonths - newTermInMonths;

        // UI Injection
        resultsUi.classList.remove('d-none');
        document.getElementById('total-interest-saved').textContent = formatter.format(monthlyInterest - biWeeklyInterest);
        document.getElementById('term-reduction-display').textContent = formatTerm(monthsSaved);
        document.getElementById('time-saved-label').textContent = `Pay off ${formatTerm(monthsSaved)} earlier`;
        document.getElementById('bi-weekly-payment-display').textContent = formatter.format(biWeeklyPay);

        // Table
        document.getElementById('monthly-payment-cell').textContent = formatter.format(baseMonthlyPI);
        document.getElementById('monthly-interest-cell').textContent = formatter.format(monthlyInterest);
        document.getElementById('bi-weekly-payment-cell').textContent = formatter.format(biWeeklyPay);
        document.getElementById('bi-weekly-interest-cell').textContent = formatter.format(biWeeklyInterest);
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

