const form = document.getElementById('tax-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });

    // 2024 LTCG Brackets (approximate)
    const BRACKETS = {
        single: { zero: 47025, fifteen: 518900 },
        married: { zero: 94050, fifteen: 583750 }
    };

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // 1. Inputs
        const price = parseFloat(document.getElementById('sale-price').value);
        const purchase = parseFloat(document.getElementById('purchase-price').value);
        const improve = parseFloat(document.getElementById('improvements').value) || 0;
        const selling = parseFloat(document.getElementById('selling-costs').value) || 0;
        const months = parseInt(document.getElementById('months-owned').value) || 0;
        const agi = parseFloat(document.getElementById('agi').value) || 0;
        const status = document.getElementById('filing-status').value;

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (price <= 0 || purchase < 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide valid sale and purchase prices.";
            return;
        }

        // 2. Calculations
        const adjustedBasis = purchase + improve;
        const netSale = price - selling;
        const realizedGain = netSale - adjustedBasis;

        // Primary Residence Exclusion (Simplified Sec 121)
        const maxExclusion = status === 'married' ? 500000 : 250000;
        const actualExclusion = realizedGain > 0 ? Math.min(realizedGain, maxExclusion) : 0;
        const taxableGain = Math.max(0, realizedGain - actualExclusion);

        // Tax Rate Determination
        let rate = 0;
        let statusLabel = "No Taxable Gain";

        if (taxableGain > 0) {
            if (months <= 12) {
                rate = 24; // Placeholder for ordinary income
                statusLabel = "Short-Term Gain (Ordinary Rate)";
            } else {
                const totalIncome = agi + taxableGain;
                const limit = BRACKETS[status];
                if (totalIncome <= limit.zero) rate = 0;
                else if (totalIncome <= limit.fifteen) rate = 15;
                else rate = 20;
                statusLabel = `Long-Term Gain (${rate}%)`;
            }
        }

        const totalTax = taxableGain * (rate / 100);

        // 3. UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('tax-display').textContent = currency.format(totalTax);
        document.getElementById('basis-display').textContent = currency.format(adjustedBasis);
        document.getElementById('taxable-gain-display').textContent = currency.format(taxableGain);
        document.getElementById('realized-gain-display').textContent = currency.format(realizedGain);
        document.getElementById('exclusion-display').textContent = `-${currency.format(actualExclusion)}`;
        document.getElementById('tax-rate-display').textContent = `${rate}%`;

        document.getElementById('status-badge-container').innerHTML = 
            `<span class="badge-ltcg">${statusLabel}</span>`;
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

