const form = document.getElementById('depreciation-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const cost = parseFloat(document.getElementById('asset-cost').value);
        const salvage = parseFloat(document.getElementById('salvage-value').value);
        const life = parseInt(document.getElementById('useful-life').value);
        const factor = parseFloat(document.getElementById('db-factor').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (salvage >= cost) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Salvage value must be less than original cost.";
            return;
        }

        // 1. Logic Helpers
        const depreciableBase = cost - salvage;
        document.getElementById('dep-base-display').textContent = currency.format(depreciableBase);
        document.getElementById('sl-rate-display').textContent = (100 / life).toFixed(1) + "%";
        document.getElementById('final-val-display').textContent = currency.format(salvage);
        document.getElementById('db-header-text').textContent = factor === 2 ? 'Double Declining' : '150% Declining';

        // 2. Calculations & Table Generation
        renderTable('sl-table-container', calculateSL(cost, salvage, life));
        renderTable('syd-table-container', calculateSYD(cost, salvage, life));
        renderTable('db-table-container', calculateDB(cost, salvage, life, factor));

        resultsUi.classList.remove('d-none');
    });

    function calculateSL(cost, salvage, life) {
        const annual = (cost - salvage) / life;
        let schedule = [];
        for (let i = 1; i <= life; i++) {
            schedule.push({ year: i, dep: annual, book: cost - (annual * i) });
        }
        return schedule;
    }

    function calculateSYD(cost, salvage, life) {
        const base = cost - salvage;
        const sumOfDigits = (life * (life + 1)) / 2;
        let schedule = [];
        let accDep = 0;
        for (let i = 1; i <= life; i++) {
            let dep = base * ((life - i + 1) / sumOfDigits);
            accDep += dep;
            schedule.push({ year: i, dep: dep, book: cost - accDep });
        }
        return schedule;
    }

    function calculateDB(cost, salvage, life, factor) {
        const rate = factor / life;
        let schedule = [];
        let currentBook = cost;
        for (let i = 1; i <= life; i++) {
            let dep = currentBook * rate;
            if (currentBook - dep < salvage) dep = currentBook - salvage;
            currentBook -= dep;
            schedule.push({ year: i, dep: dep, book: currentBook });
        }
        return schedule;
    }

    function renderTable(containerId, data) {
        let html = `<table class="table table-sm table-depreciation border shadow-sm">
            <thead><tr><th>Yr</th><th>Exp</th><th>Book</th></tr></thead><tbody>`;
        data.forEach(row => {
            html += `<tr><td class="text-center text-muted fw-bold">${row.year}</td>
                <td class="text-success">${currency.format(row.dep)}</td>
                <td class="fw-bold">${currency.format(row.book)}</td></tr>`;
        });
        html += `</tbody></table>`;
        document.getElementById(containerId).innerHTML = html;
    }

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

