    }

    function getDetailedAnalysis(front, back) {
        if (back > 43) return "Your Back-End DTI is high. Lenders typically view 43% as the maximum for 'Qualified Mortgages.' You may need to pay down debt or increase income to qualify for better rates.";
        if (front > 31) return "Your housing ratio is higher than standard guidelines. While you might qualify for an FHA loan, you may find your monthly budget tight.";
        if (back <= 36 && front <= 28) return "Congratulations! Your ratios are within the 'Gold Standard' range. You should qualify for most conventional loan programs with the best available rates.";
        return "Your ratios are within acceptable limits for most government-backed and conventional loans.";
    }

