const form = document.getElementById('exchange-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const salePrice = parseFloat(document.getElementById('sale-price').value);
        const basis = parseFloat(document.getElementById('adjusted-basis').value);
        const oldDebt = parseFloat(document.getElementById('old-mortgage').value);
        const purchasePrice = parseFloat(document.getElementById('purchase-price').value);
        const newDebt = parseFloat(document.getElementById('new-mortgage').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (basis > salePrice) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Adjusted basis exceeds sale price (No gain to defer).";
            return;
        }

        // Logic
        const potentialGain = salePrice - basis;

        // 1. Mortgage Boot (Debt relief)
        const mortgageBoot = Math.max(0, oldDebt - newDebt);

        // 2. Value Boot (Cash boot)
        const relinquishedEquity = salePrice - oldDebt;
        const replacementEquity = purchasePrice - newDebt;
        const cashBoot = Math.max(0, relinquishedEquity - replacementEquity);

        const totalBoot = Math.min(potentialGain, mortgageBoot + cashBoot);
        const deferredGain = potentialGain - totalBoot;

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('deferred-gain-display').textContent = currency.format(deferredGain);
        document.getElementById('taxable-boot-display').textContent = currency.format(totalBoot);

        // Requirement UI
        document.getElementById('req-value-target').textContent = currency.format(salePrice);
        document.getElementById('req-debt-target').textContent = currency.format(oldDebt);

        const vIcon = document.getElementById('value-status-icon');
        vIcon.className = purchasePrice >= salePrice ? "bi bi-check-circle-fill text-success" : "bi bi-exclamation-circle-fill text-danger";

        const dIcon = document.getElementById('debt-status-icon');
        dIcon.className = newDebt >= oldDebt ? "bi bi-check-circle-fill text-success" : "bi bi-exclamation-circle-fill text-danger";

        // Boot Explanation
        const alertBox = document.getElementById('boot-alert-box');
        if (totalBoot > 0) {
            alertBox.classList.remove('d-none');
            let reason = "";
            if (mortgageBoot > 0) reason += `You reduced your debt by ${currency.format(mortgageBoot)}. `;
            if (cashBoot > 0) reason += `You reinvested less equity than you received from the sale. `;
            document.getElementById('boot-explanation').innerText = reason + "This amount is considered taxable 'Boot'.";
        } else {
            alertBox.classList.add('d-none');
        }
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

