const form = document.getElementById('extra-payment-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: 2,
    });

    function formatTerm(totalMonths) {
        const years = Math.floor(totalMonths / 12);
        const months = totalMonths % 12;
        if (years === 0) return `${months} months`;
        return `${years} yrs, ${months} mos`;
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const P = parseFloat(document.getElementById('principal-input').value);
        const R = parseFloat(document.getElementById('rate-input').value);
        const N = parseFloat(document.getElementById('term-input').value);
        const extra = parseFloat(document.getElementById('extra-payment-input').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(P) || isNaN(R) || isNaN(N) || isNaN(extra)) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide valid numbers for all inputs.";
            return;
        }

        const monthlyR = (R / 100) / 12;
        const totalLoanMonths = N * 12;
        const baseMonthlyPI = P * (monthlyR * Math.pow(1 + monthlyR, totalLoanMonths)) / (Math.pow(1 + monthlyR, totalLoanMonths) - 1);

        // 1. Baseline Interest
        let originalInterest = 0;
        let tempBal = P;
        for (let m = 1; m <= totalLoanMonths; m++) {
            let int = tempBal * monthlyR;
            originalInterest += int;
            tempBal -= (baseMonthlyPI - int);
        }

        // 2. Extra Payment Calculation
        let balance = P;
        let totalInterestNew = 0;
        let newMonths = 0;
        let tableHtml = '';

        for (let month = 1; ; month++) {
            if (balance <= 0) break;

            let interestP = balance * monthlyR;
            let principalP = baseMonthlyPI - interestP;
            let totalPrincipalPaid = principalP + extra;

            if (totalPrincipalPaid >= balance) {
                totalPrincipalPaid = balance;
                balance = 0;
            } else {
                balance -= totalPrincipalPaid;
            }

            totalInterestNew += interestP;
            newMonths = month;

            if (month <= 12) {
                tableHtml += `
                    <tr>
                        <td class="fw-bold">${month}</td>
                        <td class="text-dark">${formatter.format(baseMonthlyPI + extra)}</td>
                        <td>${formatter.format(interestP)}</td>
                        <td>${formatter.format(principalP)} <span class="extra-tag">+${formatter.format(extra)}</span></td>
                        <td class="fw-bold text-dark">${formatter.format(Math.max(0, balance))}</td>
                    </tr>
                `;
            }
        }

        // Update UI
        resultsUi.classList.remove('d-none');
        document.getElementById('total-interest-saved').textContent = formatter.format(originalInterest - totalInterestNew);
        document.getElementById('new-term-display').textContent = formatTerm(newMonths);
        document.getElementById('time-saved-label').textContent = `Saves ${formatTerm(totalLoanMonths - newMonths)} in time`;
        document.getElementById('new-payment-display').textContent = formatter.format(baseMonthlyPI + extra);
        document.querySelector('#amortization-table tbody').innerHTML = tableHtml;
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

