    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });
    const currencyCents = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const val = parseFloat(document.getElementById('home-value').value);
        const bal = parseFloat(document.getElementById('mortgage-balance').value);
        const ltv = parseFloat(document.getElementById('max-cltv').value);
        const rate = parseFloat(document.getElementById('interest-rate').value);
        const drawAmt = parseFloat(document.getElementById('draw-amount').value);
        const dTerm = parseInt(document.getElementById('draw-term').value);
        const rTerm = parseInt(document.getElementById('repayment-term').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if ([val, bal, ltv, rate, drawAmt, dTerm, rTerm].some(isNaN)) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "All fields are required and must be numeric.";
            return;
        }

        // 1. Credit Limit
        const maxLimit = Math.max(0, (val * (ltv / 100)) - bal);

        // 2. Calculations
        const effectiveDraw = Math.min(drawAmt, maxLimit);
        const monthlyRate = (rate / 100) / 12;

        // Draw Payment (Interest Only)
        const drawPayment = effectiveDraw * monthlyRate;

        // Repayment Payment (Amortized P&I)
        const nRepay = rTerm * 12;
        const repayPayment = effectiveDraw * (monthlyRate * Math.pow(1 + monthlyRate, nRepay)) / (Math.pow(1 + monthlyRate, nRepay) - 1);

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('max-limit-display').textContent = currency.format(maxLimit);
        document.getElementById('cltv-val').textContent = ltv;
        document.getElementById('draw-payment-display').textContent = currencyCents.format(drawPayment);
        document.getElementById('repay-payment-display').textContent = currencyCents.format(repayPayment);
        document.getElementById('draw-term-text').textContent = `For ${dTerm} years`;
        document.getElementById('repay-term-text').textContent = `For ${rTerm} years`;

        const usageWarn = document.getElementById('usage-warning');
        if (drawAmt > maxLimit) {
            usageWarn.innerHTML = `<span class="text-danger fw-bold"><i class="bi bi-exclamation-circle"></i> Request exceeds limit of ${currency.format(maxLimit)}</span>`;
        } else {
            usageWarn.textContent = `Based on ${ltv}% CLTV Capacity`;
            usageWarn.classList.remove('text-danger');
        }
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

