const form = document.getElementById('appreciation-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');
    let growthChart = null;

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const initialValue = parseFloat(document.getElementById('initial-value').value);
        const rate = parseFloat(document.getElementById('appreciation-rate').value);
        const years = parseInt(document.getElementById('years').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(initialValue) || initialValue <= 0 || isNaN(rate) || isNaN(years) || years < 1) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide valid starting value, rate, and years.";
            return;
        }

        // Calculation
        const r = rate / 100;
        const labels = [];
        const data = [];
        for (let t = 0; t <= years; t++) {
            labels.push(`Year ${t}`);
            data.push(initialValue * Math.pow(1 + r, t));
        }

        const finalValue = data[data.length - 1];
        const totalGain = finalValue - initialValue;

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('final-value-display').textContent = currency.format(finalValue);
        document.getElementById('gain-text').textContent = `+${currency.format(totalGain)} Total appreciation over ${years} years`;

        // Charting
        const ctx = document.getElementById('appreciationChart').getContext('2d');
        if (growthChart) growthChart.destroy();

        growthChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Property Value',
                    data: data,
                    borderColor: '#ea580c',
                    backgroundColor: 'rgba(234, 88, 12, 0.1)',
                    borderWidth: 3,
                    fill: true,
                    tension: 0.3,
                    pointBackgroundColor: '#ea580c'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: {
                    y: { 
                        ticks: { callback: (val) => currency.format(val) },
                        grid: { color: 'var(--ag-bg)' }
                    },
                    x: { grid: { display: false } }
                }
            }
        });
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

