const form = document.getElementById('home-equity-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');
    const useMaxBtn = document.getElementById('use-max-btn');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });
    const currencyCents = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    let currentMaxEquity = 0;

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const val = parseFloat(document.getElementById('home-value').value);
        const bal = parseFloat(document.getElementById('mortgage-balance').value);
        const ltv = parseFloat(document.getElementById('max-ltv').value);
        const amount = parseFloat(document.getElementById('loan-amount').value);
        const rate = parseFloat(document.getElementById('interest-rate').value);
        const term = parseInt(document.getElementById('loan-term').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(val) || isNaN(bal) || isNaN(ltv) || isNaN(amount) || isNaN(rate) || isNaN(term)) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please ensure all fields are filled with valid numbers.";
            return;
        }

        // Logic
        currentMaxEquity = Math.max(0, (val * (ltv / 100)) - bal);

        const i = (rate / 100) / 12;
        const n = term * 12;
        const payment = amount * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
        const totalInterest = (payment * n) - amount;

        // UI Updates
        resultsUi.classList.remove('d-none');
        useMaxBtn.classList.remove('d-none');

        document.getElementById('max-equity-display').textContent = currency.format(currentMaxEquity);
        document.getElementById('ltv-ref-text').textContent = ltv;
        document.getElementById('payment-display').textContent = currencyCents.format(payment);
        document.getElementById('interest-display').textContent = currency.format(totalInterest);

        if (amount > currentMaxEquity) {
            document.getElementById('payment-display').classList.add('text-danger');
        } else {
            document.getElementById('payment-display').classList.remove('text-danger');
        }
    });

    useMaxBtn.addEventListener('click', () => {
        document.getElementById('loan-amount').value = Math.floor(currentMaxEquity);
        form.dispatchEvent(new Event('submit'));
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
        useMaxBtn.classList.add('d-none');
    });

