    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const initialRent = parseFloat(document.getElementById('initial-rent').value);
        const rate = parseFloat(document.getElementById('escalation-rate').value);
        const term = parseInt(document.getElementById('lease-term').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(initialRent) || initialRent <= 0 || isNaN(rate) || isNaN(term) || term < 1) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide a valid starting rent, escalation rate, and lease term.";
            return;
        }

        // Calculation (Compounding Loop)
        const r = rate / 100;
        let totalCost = 0;
        let currentYearRent = initialRent;
        let finalYearRent = 0;

        for (let year = 1; year <= term; year++) {
            totalCost += currentYearRent;
            if (year === term) finalYearRent = currentYearRent;
            currentYearRent *= (1 + r);
        }

        const totalEscalation = totalCost - (initialRent * term);
        const avgMonthly = (totalCost / term) / 12;

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('total-cost-display').textContent = currency.format(totalCost);
        document.getElementById('avg-monthly-text').textContent = `~${currency.format(avgMonthly)} / month average`;
        document.getElementById('final-rent-display').textContent = currency.format(finalYearRent);
        document.getElementById('total-escalation-display').textContent = currency.format(totalEscalation);
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

real_estate_calculator__ltv_ratio_calcul:
const form = document.getElementById('ltv-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });

    function getAnalysisData(ltv) {
        if (ltv <= 80) return {
            label: 'Excellent (Low Risk)',
            color: '#059669',
            bg: '#ecfdf5',
            pmi: 'No PMI Required',
            text: 'You have at least 20% equity. Most lenders will not require Private Mortgage Insurance (PMI) and you likely qualify for the most competitive interest rates.'
        };
        if (ltv <= 90) return {
            label: 'Good (Moderate Risk)',
            color: '#d97706',
            bg: '#fffbeb',
            pmi: 'PMI Required',
            text: 'Your equity is between 10% and 20%. You will likely be required to pay PMI, though your rates may be better than those with higher LTVs.'
        };
        return {
            label: 'High (Elevated Risk)',
            color: '#dc2626',
            bg: '#fef2f2',
            pmi: 'PMI Required',
            text: 'With an LTV above 90%, you are in a high-leverage position. Expect mandatory PMI and potentially higher mortgage insurance premiums.'
        };
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const loan = parseFloat(document.getElementById('loan-amount').value);
        const property = parseFloat(document.getElementById('property-value').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(loan) || isNaN(property) || loan <= 0 || property <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide valid positive numbers for both fields.";
            return;
        }

        if (loan > property) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Loan amount cannot exceed property value for a standard LTV calculation.";
            return;
        }

        const ltv = (loan / property) * 100;
        const equityAmount = property - loan;
        const equityPercent = 100 - ltv;

        // UI Updates
        resultsUi.classList.remove('d-none');

        const ltvDisp = document.getElementById('ltv-display');
        ltvDisp.textContent = ltv.toFixed(1) + '%';

        const info = getAnalysisData(ltv);

        const statusPill = document.getElementById('assessment-status');
        statusPill.textContent = info.label;
        statusPill.style.color = info.color;
        statusPill.style.backgroundColor = info.bg;
        ltvDisp.style.color = info.color;

        document.getElementById('equity-cash-display').textContent = formatter.format(equityAmount);
        document.getElementById('equity-percent-display').textContent = equityPercent.toFixed(1) + '% Equity';
        document.getElementById('pmi-status-display').textContent = info.pmi;
        document.getElementById('analysis-text').textContent = info.text;
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

real_estate_calculator__mortgage_afforda:
const form = document.getElementById('affordability-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    function formatCurrency(num, digits = 0) {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: digits,
            maximumFractionDigits: digits,
        }).format(num);
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const budget = parseFloat(document.getElementById('budget-input').value);
        const rate = parseFloat(document.getElementById('rate-input').value);
        const term = parseFloat(document.getElementById('term-input').value);
        const taxes = parseFloat(document.getElementById('taxes-input').value);
        const insurance = parseFloat(document.getElementById('insurance-input').value);

        // Reset views
        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(budget) || isNaN(rate) || isNaN(term)) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please provide your monthly budget, interest rate, and term.";
            return;
        }

        const monthlyEscrow = (taxes + insurance) / 12 || 0;
        const availablePI = budget - monthlyEscrow;

        if (availablePI <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-title').innerText = "Taxes/Insurance Too High";
            document.getElementById('error-msg').innerText = `Your monthly fixed costs ($${monthlyEscrow.toFixed(2)}) exceed your total budget.`;
            return;
        }

        // Calculation
        const i = (rate / 100) / 12;
        const n = term * 12;
