const form = document.getElementById('amortization-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: 2,
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const P = parseFloat(document.getElementById('p-input').value);
        const annualR = parseFloat(document.getElementById('r-input').value);
        const years = parseFloat(document.getElementById('t-input').value);
        const startVal = document.getElementById('date-input').value;

        // Reset
        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(P) || isNaN(annualR) || isNaN(years) || !startVal) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please complete all fields with valid numbers.";
            return;
        }

        const monthlyR = (annualR / 100) / 12;
        const totalMonths = years * 12;

        // Formula: M = P [ i(1 + i)^n ] / [ (1 + i)^n – 1]
        const monthlyPayment = P * (monthlyR * Math.pow(1 + monthlyR, totalMonths)) / (Math.pow(1 + monthlyR, totalMonths) - 1);

        let balance = P;
        let totalInterest = 0;
        let rowsHtml = '';
        let currentDate = new Date(startVal + "-02"); // Day 02 to avoid timezone jump

        for (let i = 1; i <= totalMonths; i++) {
            let interestM = balance * monthlyR;
            let principalM = monthlyPayment - interestM;

            if (i === totalMonths) principalM = balance; // Rounding correction

            balance -= principalM;
            totalInterest += interestM;

            const dateStr = currentDate.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });

            rowsHtml += `<tr>
                <td class="fw-bold">${dateStr}</td>
                <td>${formatter.format(principalM)}</td>
                <td class="text-danger">${formatter.format(interestM)}</td>
                <td class="text-dark fw-bold">${formatter.format(Math.max(0, balance))}</td>
            </tr>`;

            currentDate.setMonth(currentDate.getMonth() + 1);
        }

        // UI Injection
        resultsUi.classList.remove('d-none');
        document.getElementById('monthly-payment-display').textContent = formatter.format(monthlyPayment);
        document.getElementById('total-interest-display').textContent = formatter.format(totalInterest);

        // Decrement date by 1 month for the payoff date display
        let payoffDate = new Date(currentDate);
        payoffDate.setMonth(payoffDate.getMonth() - 1);
        document.getElementById('payoff-date-display').textContent = payoffDate.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });

        // Ratio Bar
        const principalPct = (P / (P + totalInterest)) * 100;
        document.getElementById('ratio-bar').style.width = principalPct + "%";
        document.getElementById('ratio-text').innerText = `${principalPct.toFixed(0)}% P / ${(100-principalPct).toFixed(0)}% I`;

        document.querySelector('#schedule-table tbody').innerHTML = rowsHtml;
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

