const form = document.getElementById('refi-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    function calculatePI(P, R_annual, N_years) {
        const i = (R_annual / 100) / 12;
        const n = N_years * 12;
        if (i === 0) return P / n;
        return P * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
    }

    function formatTerm(totalMonths) {
        if (totalMonths === Infinity) return "Never";
        const years = Math.floor(totalMonths / 12);
        const months = Math.ceil(totalMonths % 12);
        if (years === 0) return `${months} months`;
        if (months === 0) return `${years} years`;
        return `${years} yrs, ${months} mos`;
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const curBal = parseFloat(document.getElementById('current-balance').value);
        const curRate = parseFloat(document.getElementById('current-rate').value);
        const curTerm = parseFloat(document.getElementById('current-term').value);
        const cost = parseFloat(document.getElementById('refi-cost').value);
        const newRate = parseFloat(document.getElementById('new-rate').value);
        const newTerm = parseFloat(document.getElementById('new-term').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (isNaN(curBal) || isNaN(curRate) || isNaN(curTerm) || isNaN(cost) || isNaN(newRate) || isNaN(newTerm)) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please complete all fields with valid numbers.";
            return;
        }

        const currentP = calculatePI(curBal, curRate, curTerm);
        const newP = calculatePI(curBal, newRate, newTerm);
        const monthlySavings = currentP - newP;

        if (monthlySavings <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "New payment is higher than or equal to current. You will never break even.";
            return;
        }

        const breakevenMonths = cost / monthlySavings;

        // UI Injection
        resultsUi.classList.remove('d-none');
        document.getElementById('breakeven-display').textContent = Math.ceil(breakevenMonths);
        document.getElementById('monthly-savings-display').textContent = formatter.format(monthlySavings);
        document.getElementById('total-cost-display').textContent = formatter.format(cost);
        document.getElementById('breakeven-text-detail').textContent = `Full ROI in ${formatTerm(breakevenMonths)}`;

        // Table updates
        document.getElementById('cell-current-rate').textContent = curRate + "%";
        document.getElementById('cell-current-term').textContent = curTerm + " yrs";
        document.getElementById('cell-current-payment').textContent = formatter.format(currentP);
        document.getElementById('cell-new-rate').textContent = newRate + "%";
        document.getElementById('cell-new-term').textContent = newTerm + " yrs";
        document.getElementById('cell-new-payment').textContent = formatter.format(newP);
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

