const form = document.getElementById('rent-vs-buy-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');

    function fmt(num) {
        return new Intl.NumberFormat('en-US', { 
            style: 'currency', 
            currency: 'USD', 
            maximumFractionDigits: 0 
        }).format(num);
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // 1. Data Retrieval
        const years = parseInt(document.getElementById('time-horizon').value);
        const homePrice = parseFloat(document.getElementById('home-price').value);
        const dpPercent = parseFloat(document.getElementById('down-payment-percent').value) / 100;
        const mortgageRate = parseFloat(document.getElementById('mortgage-rate').value) / 100;
        const appRate = parseFloat(document.getElementById('appreciation-rate').value) / 100;
        const investRate = parseFloat(document.getElementById('investment-rate').value) / 100;
        const rentStart = parseFloat(document.getElementById('current-rent').value);
        const rentInc = parseFloat(document.getElementById('rent-increase-rate').value) / 100;
        const upfrontSavings = parseFloat(document.getElementById('upfront-savings').value);

        // 2. Buy Calculation
        const loanAmount = homePrice * (1 - dpPercent);
        const monthlyRate = mortgageRate / 12;
        const totalLoanMonths = 360; 
        const pAndI = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, totalLoanMonths)) / (Math.pow(1 + monthlyRate, totalLoanMonths) - 1);

        let totalBuyingOutlays = upfrontSavings; 
        let currentBalance = loanAmount;
        const monthlyTaxIns = (parseFloat(document.getElementById('annual-taxes').value) + parseFloat(document.getElementById('annual-insurance').value)) / 12;

        for (let i = 0; i < years * 12; i++) {
            const interest = currentBalance * monthlyRate;
            currentBalance -= (pAndI - interest);
            totalBuyingOutlays += (pAndI + monthlyTaxIns);
        }

        const finalValue = homePrice * Math.pow(1 + appRate, years);
        const equity = Math.max(0, finalValue - currentBalance);
        const buyNet = equity - totalBuyingOutlays;

        // 3. Rent Calculation
        let totalRentPaid = 0;
        let activeRent = rentStart;
        for (let i = 0; i < years; i++) {
            totalRentPaid += (activeRent * 12);
            activeRent *= (1 + rentInc);
        }
        const portfolio = upfrontSavings * Math.pow(1 + investRate, years);
        const rentNet = portfolio - totalRentPaid;

        // 4. Update UI
        placeholderUi.classList.add('d-none');
        resultsUi.classList.remove('d-none');

        const diff = Math.abs(buyNet - rentNet);
        const isBuyBetter = buyNet > rentNet;

        document.getElementById('verdict-text').textContent = isBuyBetter 
            ? `Buying is ${fmt(diff)} better than Renting` 
            : `Renting is ${fmt(diff)} better than Buying`;

        document.getElementById('res-buy-monthly').textContent = fmt(pAndI);
        document.getElementById('res-buy-total-paid').textContent = fmt(totalBuyingOutlays);
        document.getElementById('res-buy-equity').textContent = fmt(equity);
        document.getElementById('res-buy-net').textContent = fmt(buyNet);

        document.getElementById('res-rent-start').textContent = fmt(rentStart);
        document.getElementById('res-rent-total-paid').textContent = fmt(totalRentPaid);
        document.getElementById('res-rent-portfolio').textContent = fmt(portfolio);
        document.getElementById('res-rent-net').textContent = fmt(rentNet);

        window.scrollTo({ top: document.getElementById('result-container').offsetTop - 30, behavior: 'smooth' });
    });

