        const dpPct = parseFloat(document.getElementById('dp-pct').value) || 0;
        const rate = parseFloat(document.getElementById('rate').value) || 0;
        const upfront = parseFloat(document.getElementById('upfront-costs').value) || 0;
        const rent = parseFloat(document.getElementById('rent').value);
        const vacancyPct = parseFloat(document.getElementById('vacancy').value) || 0;
        const taxIns = parseFloat(document.getElementById('tax-ins').value) || 0;
        const maintenance = parseFloat(document.getElementById('maintenance').value) || 0;
        const mgmtPct = parseFloat(document.getElementById('mgmt').value) || 0;
        const otherExp = parseFloat(document.getElementById('other-exp').value) || 0;

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if (price <= 0 || rent <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Price and Rent must be greater than zero.";
            return;
        }

        // 2. Calculations
        const dpAmount = price * (dpPct / 100);
        const loanAmount = price - dpAmount;
        const totalInvested = dpAmount + upfront;

        // Monthly Mortgage (P&I)
        let monthlyPI = 0;
        if (loanAmount > 0 && rate > 0) {
            const i = (rate / 100) / 12;
            const n = 360; // 30 Years
            monthlyPI = loanAmount * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
        }

        // Income & OpEx
        const egi = rent * (1 - (vacancyPct / 100));
        const mgmtFee = egi * (mgmtPct / 100);
        const opex = taxIns + maintenance + mgmtFee + otherExp;
        const noi = egi - opex;
        const cashFlow = noi - monthlyPI;

        // Metrics
        const coc = totalInvested > 0 ? ((cashFlow * 12) / totalInvested) * 100 : 0;
        const capRate = (noi * 12 / price) * 100;

        // 3. UI Updates
        resultsUi.classList.remove('d-none');
        const cfEl = document.getElementById('cf-display');
        cfEl.textContent = currency.format(cashFlow);
        cfEl.style.color = cashFlow >= 0 ? "#059669" : "#dc2626";

