const form = document.getElementById('reverse-mortgage-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 0,
    });

    /**
     * Simplified PLF approximation based on HUD tables.
     * PLF increases with age and decreases with rate.
     */
    function calculatePLF(age, rate) {
        let base = 0.40; // Floor for younger seniors at higher rates
        const ageCredit = (age - 62) * 0.006;
        const rateDebit = (rate - 3.0) * 0.045;
        let plf = base + ageCredit - rateDebit;
        return Math.min(0.75, Math.max(0.10, plf));
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const val = parseFloat(document.getElementById('home-value').value);
        const age = parseInt(document.getElementById('borrower-age').value);
        const rate = parseFloat(document.getElementById('expected-rate').value);
        const debt = parseFloat(document.getElementById('current-debt').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        // Validation
        const hudLimit = 1215850; // Updated 2026 HUD Limit (Example)
        const claimAmt = Math.min(val, hudLimit);

        if (age < 62) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Youngest borrower must be at least 62 years old.";
            return;
        }

        const plf = calculatePLF(age, rate);
        const pl = claimAmt * plf;
        const mip = claimAmt * 0.02; // Initial MIP is typically 2% of Claim Amt
        const netCash = Math.max(0, pl - debt - mip);

        if (debt > pl) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Current debt exceeds the available Principal Limit. A HECM cannot close unless the gap is paid in cash.";
            return;
        }

        // UI Update
        resultsUi.classList.remove('d-none');
        document.getElementById('pl-display').textContent = currency.format(pl);
        document.getElementById('plf-text').textContent = `PLF: ${(plf * 100).toFixed(2)}%`;
        document.getElementById('net-cash-display').textContent = currency.format(netCash);
        document.getElementById('mip-display').textContent = currency.format(mip);
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });

