const form = document.getElementById('usda-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    function calculatePI(P, R, Y) {
        const i = (R / 100) / 12;
        const n = Y * 12;
        if (i === 0) return P / n;
        return P * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const price = parseFloat(document.getElementById('home-price').value);
        const rate = parseFloat(document.getElementById('interest-rate').value);
        const term = parseFloat(document.getElementById('loan-term').value);
        const upfrontPct = parseFloat(document.getElementById('upfront-rate').value);
        const annualPct = parseFloat(document.getElementById('annual-rate').value);

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if ([price, rate, term, upfrontPct, annualPct].some(isNaN) || price <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please ensure all values are valid. USDA loans require valid price and term entries.";
            return;
        }

        // USDA Logic: 0% down means Base Loan = Price
        const upfrontFee = price * (upfrontPct / 100);
        const totalLoan = price + upfrontFee;

        const monthlyPI = calculatePI(totalLoan, rate, term);
        const monthlyFee = (price * (annualPct / 100)) / 12;
        const totalMonthly = monthlyPI + monthlyFee;

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('monthly-payment-display').textContent = currency.format(totalMonthly);
        document.getElementById('upfront-fee-display').textContent = currency.format(upfrontFee).split('.')[0];
        document.getElementById('total-loan-display').textContent = currency.format(totalLoan).split('.')[0];
        document.getElementById('pi-breakdown').textContent = currency.format(monthlyPI);
