const form = document.getElementById('va-form');
    const resultsUi = document.getElementById('results-ui');
    const placeholderUi = document.getElementById('placeholder-ui');
    const errorUi = document.getElementById('error-ui');

    const currency = new Intl.NumberFormat('en-US', {
        style: 'currency', currency: 'USD', minimumFractionDigits: 2,
    });

    const VA_RATES = {
        first: { zero: 2.15, five: 1.5, ten: 1.25 },
        subsequent: { zero: 3.3, five: 1.5, ten: 1.25 }
    };

    function getFeeRate(usage, dp, exempt) {
        if (exempt) return 0;
        let bracket = 'zero';
        if (dp >= 10) bracket = 'ten';
        else if (dp >= 5) bracket = 'five';
        return VA_RATES[usage][bracket];
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const price = parseFloat(document.getElementById('home-price').value);
        const rate = parseFloat(document.getElementById('interest-rate').value);
        const term = parseFloat(document.getElementById('loan-term').value);
        const dp = parseFloat(document.getElementById('dp-percent').value);
        const usage = document.getElementById('usage-status').value;
        const exempt = document.getElementById('is-exempt').checked;

        placeholderUi.classList.add('d-none');
        resultsUi.classList.add('d-none');
        errorUi.classList.add('d-none');

        if ([price, rate, term, dp].some(isNaN) || price <= 0) {
            errorUi.classList.remove('d-none');
            document.getElementById('error-msg').innerText = "Please enter valid numbers for price, rate, and term.";
            return;
        }

        const feeRate = getFeeRate(usage, dp, exempt);
        const dpAmount = price * (dp / 100);
        const baseLoan = price - dpAmount;
        const feeAmount = baseLoan * (feeRate / 100);
        const totalLoan = baseLoan + feeAmount;

        // Amortization
        const i = (rate / 100) / 12;
        const n = term * 12;
        const monthlyPI = totalLoan * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);

        // UI Updates
        resultsUi.classList.remove('d-none');
        document.getElementById('monthly-payment-display').textContent = currency.format(monthlyPI);
        document.getElementById('fee-amount-display').textContent = currency.format(feeAmount).split('.')[0];
        document.getElementById('fee-rate-display').textContent = `Rate: ${feeRate.toFixed(2)}%`;
        document.getElementById('total-loan-display').textContent = currency.format(totalLoan).split('.')[0];
        document.getElementById('dp-cash-display').textContent = currency.format(dpAmount);
        document.getElementById('dp-percent-label').textContent = `${dp}% Down`;

        document.getElementById('exempt-badge-container').innerHTML = exempt ? '<span class="exempt-badge ms-2">EXEMPT</span>' : '';
    });

    form.addEventListener('reset', () => {
        resultsUi.classList.add('d-none');
        placeholderUi.classList.remove('d-none');
        errorUi.classList.add('d-none');
    });
